"use client"

import { useState, Suspense } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import Link from "next/link"
import Image from "next/image"
import { useAuth } from "@/hooks/useAuth"
import { t, UI_STRINGS } from "@/lib/i18n"
import { useLang } from "@/lib/lang-context"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { EmailInput } from "@/components/ui/email-input"
import { PasswordInput } from "@/components/ui/password-input"
import { Label } from "@/components/ui/label"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  getErrorMessage,
  requestPasswordReset,
} from "@/lib/pb"
import { getDashboardPath } from "@/lib/dashboard-routes"
import {
  EMAIL_INVALID_MESSAGE,
  isValidEmail,
  normalizeEmail,
} from "@/lib/validators"

function ExpertPendingNotice() {
  const searchParams = useSearchParams()
  const { lang } = useLang()
  if (searchParams.get("expert_pending") !== "1") return null
  const emailWarn = searchParams.get("warn") === "1"
  return (
    <>
      <div className="rounded-lg bg-green-50 p-3 text-sm text-green-700">
        {t(
          {
            en: "Your application has been submitted. You will receive an email once your account is approved.",
            ar: "تم تقديم طلبك. ستصلك رسالة بريد إلكتروني بمجرد اعتماد حسابك.",
          },
          lang
        )}
      </div>
      {emailWarn && (
        <div className="rounded-lg bg-amber-50 p-3 text-sm text-amber-700">
          {t(
            {
              en: "Your application was saved, but we couldn't send the notification email. Our team will still review your application.",
              ar: "تم حفظ طلبك، لكن تعذّر إرسال بريد الإشعار. سيقوم فريقنا بمراجعة طلبك على أي حال.",
            },
            lang
          )}
        </div>
      )}
    </>
  )
}

export default function LoginPage() {

  const router = useRouter()
  const { login } = useAuth()
  const { lang } = useLang()
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState("")

  const [forgotOpen, setForgotOpen] = useState(false)
  const [resetEmail, setResetEmail] = useState("")
  const [resetLoading, setResetLoading] = useState(false)
  const [resetSent, setResetSent] = useState(false)
  const [resetError, setResetError] = useState("")

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!email || !password) {
      setError(
        t(
          { en: "Please enter email and password", ar: "يرجى إدخال البريد الإلكتروني وكلمة المرور" },
          lang
        )
      )
      return
    }
    if (!isValidEmail(email)) {
      setError(t(EMAIL_INVALID_MESSAGE, lang))
      return
    }

    setIsLoading(true)
    setError("")

    const result = await login(normalizeEmail(email), password)

    if (result.success) {
      router.push(getDashboardPath(result.role))
    } else {
      setError(
        result.error ||
          t(
            { en: "Incorrect email or password.", ar: "البريد الإلكتروني أو كلمة المرور غير صحيحة." },
            lang
          )
      )
      setIsLoading(false)
    }
  }

  const handleForgotSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!resetEmail) {
      setResetError(
        t(
          { en: "Please enter your email", ar: "يرجى إدخال بريدك الإلكتروني" },
          lang
        )
      )
      return
    }
    if (!isValidEmail(resetEmail)) {
      setResetError(t(EMAIL_INVALID_MESSAGE, lang))
      return
    }

    setResetLoading(true)
    setResetError("")

    try {
      await requestPasswordReset(normalizeEmail(resetEmail))
      setResetSent(true)
    } catch (err: unknown) {
      const status = (err as { status?: number } | null)?.status
      if (status === 429) {
        setResetError(
          t(
            {
              en: "Too many attempts. Please try again later.",
              ar: "محاولات كثيرة. يرجى المحاولة لاحقًا.",
            },
            lang
          )
        )
      } else {
        setResetError(getErrorMessage(err, lang))
      }
    } finally {
      setResetLoading(false)
    }
  }

  return (
    <div className="relative flex min-h-screen items-center justify-center overflow-hidden bg-gradient-to-br from-primary/5 via-background to-accent/10 p-4">
      {/* Decorative background accents */}
      <div className="pointer-events-none absolute inset-0">
        <div className="animate-float absolute left-[8%] top-[18%] h-40 w-40 rounded-full bg-[#e6c200]/20 blur-3xl" />
        <div className="animate-float delay-500 absolute right-[6%] top-[24%] h-48 w-48 rounded-full bg-[#0a3d62]/15 blur-3xl" />
        <div className="absolute bottom-[12%] left-[30%] h-40 w-40 rounded-full bg-[#438b70]/15 blur-3xl" />
        <div className="animate-float delay-700 absolute right-[12%] bottom-[20%] h-8 w-8 rounded-full border border-[#c9a227]/30 bg-[#e6c200]/10" />
        <div className="animate-float delay-300 absolute left-[15%] bottom-[30%] h-6 w-6 rounded-full border border-[#0a3d62]/20 bg-white" />
      </div>

      <div className="relative z-10 w-full max-w-4xl grid grid-cols-1 lg:grid-cols-12 gap-24 items-stretch">
        <div className="lg:col-span-4 hidden lg:flex items-center justify-center">
          <div className="flex flex-col items-center gap-4 text-center lg:sticky lg:top-10">
            <div className="relative flex h-28 w-28 items-center justify-center">
              <div className="animate-pulse-ring absolute left-1/2 top-1/2 h-28 w-28 rounded-full border border-[#c9a227]/40" />
              <div className="animate-pulse-ring-delayed absolute left-1/2 top-1/2 h-28 w-28 rounded-full border border-[#e6c200]/30" />
              <div className="relative z-10 flex h-full w-full items-center justify-center rounded-full border-2 border-white bg-white/70 shadow-lg backdrop-blur-sm">
                <Image
                  src="/logo.svg"
                  alt="DSC Logo"
                  width={80}
                  height={80}
                  className="object-contain"
                />
              </div>
            </div>

            <p className="mt-2 text-2xl font-bold text-primary">DSC</p>
            <p>Development Secrets Consultancy</p>

            <p className="max-w-[220px] text-sm text-muted-foreground">
              {t(
                {
                  en: "Your data is safe and secure with us",
                  ar: "بياناتك آمنة ومحمية معنا",
                },
                lang
              )}
            </p>
          </div>
        </div>
        <div className="lg:col-span-8">
          <Card className="w-full max-w-lg mx-auto overflow-hidden rounded-2xl shadow-xl xl:max-w-xl">
            <CardHeader className="text-center">
              <h1 className="mt-5 text-2xl font-bold text-primary">
                {t({ en: "Login", ar: "تسجيل الدخول" }, lang)}
              </h1>
              <div className="mt-3 mx-auto h-1 w-12 rounded-full bg-gradient-to-r from-[#c9a227] to-[#e6c200]" />
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-4" noValidate>
                <Suspense fallback={null}>
                  <ExpertPendingNotice />
                </Suspense>
                {error && (
                  <div className="rounded-lg bg-red-50 p-3 text-sm text-red-600">
                    {error}
                  </div>
                )}
                <div className="space-y-2">
                  <Label htmlFor="email">
                    {t({ en: "Email", ar: "البريد الإلكتروني" }, lang)}
                  </Label>
                  <EmailInput
                    id="email"
                    placeholder="your@email.com"
                    value={email}
                    onChange={setEmail}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <Label htmlFor="password">
                      {t({ en: "Password", ar: "كلمة المرور" }, lang)}
                    </Label>
                    <button
                      type="button"
                      onClick={() => {
                        setForgotOpen(true)
                        setResetSent(false)
                        setResetError("")
                      }}
                      className="text-sm font-medium text-[#c9a227] hover:underline"
                    >
                      {t(
                        { en: "Forgot password?", ar: "هل نسيت كلمة المرور؟" },
                        lang
                      )}
                    </button>
                  </div>
                  <PasswordInput
                    id="password"
                    placeholder="••••••••"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    autoComplete="current-password"
                    required
                  />
                </div>
                <Button
                  type="submit"
                  className="group relative h-10 w-full overflow-hidden rounded-lg text-base font-semibold shadow-md transition-all duration-300 hover:scale-[1.02] hover:shadow-lg"
                  style={{ backgroundColor: "var(--dsc-gold)", color: "#fff" }}
                  disabled={isLoading}
                >
                  <span className="absolute inset-0 bg-gradient-to-r from-[#e6c200] to-[#c9a227] opacity-0 transition-opacity duration-300 group-hover:opacity-100" />
                  <span className="relative z-10">
                    {isLoading
                      ? t(
                          { en: "Signing in...", ar: "جارٍ تسجيل الدخول..." },
                          lang
                        )
                      : t({ en: "Sign In", ar: "تسجيل الدخول" }, lang)}
                  </span>
                </Button>
              </form>

              <div className="mt-6 border-t pt-6 text-center">
                <p className="text-sm text-muted-foreground">
                  {t(
                    { en: "Don't have an account?", ar: "ليس لديك حساب؟" },
                    lang
                  )}{" "}
                  <Link
                    href="/register"
                    className="font-medium text-[#c9a227] hover:underline"
                  >
                    {t({ en: "Register", ar: "التسجيل" }, lang)}
                  </Link>
                </p>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      <Dialog open={forgotOpen} onOpenChange={setForgotOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {t(
                { en: "Reset Password", ar: "إعادة تعيين كلمة المرور" },
                lang
              )}
            </DialogTitle>
            <DialogDescription>
              {resetSent
                ? t(
                    {
                      en: "If an account exists for this email, a reset link has been sent. Check your inbox (and spam folder).",
                      ar: "إذا كان هناك حساب مرتبط بهذا البريد، فقد تم إرسال رابط إعادة التعيين. تحقق من بريدك الوارد (ومجلد البريد غير المرغوب).",
                    },
                    lang
                  )
                : t(
                    {
                      en: "Enter your account email and we will send you a link to reset your password.",
                      ar: "أدخل بريد حسابك وسنرسل لك رابطاً لإعادة تعيين كلمة المرور.",
                    },
                    lang
                  )}
            </DialogDescription>
          </DialogHeader>

          {resetSent ? (
            <div className="flex justify-end">
              <Button variant="outline" onClick={() => setForgotOpen(false)}>
                {t(UI_STRINGS.close, lang)}
              </Button>
            </div>
          ) : (
            <form onSubmit={handleForgotSubmit} className="space-y-4" noValidate>
              {resetError && (
                <div className="rounded-lg bg-red-50 p-3 text-sm text-red-600">
                  {resetError}
                </div>
              )}
              <div className="space-y-2">
                <Label htmlFor="reset-email">
                  {t({ en: "Email", ar: "البريد الإلكتروني" }, lang)}
                </Label>
                <EmailInput
                  id="reset-email"
                  placeholder="your@email.com"
                  value={resetEmail}
                  onChange={setResetEmail}
                  autoFocus
                  required
                />
              </div>
              <div className="flex justify-end gap-2">
                <Button
                  variant="outline"
                  type="button"
                  onClick={() => setForgotOpen(false)}
                >
                  {t(UI_STRINGS.cancel, lang)}
                </Button>
                <Button type="submit" disabled={resetLoading}>
                  {resetLoading
                    ? t({ en: "Sending...", ar: "جارٍ الإرسال..." }, lang)
                    : t(
                        {
                          en: "Send Reset Link",
                          ar: "إرسال رابط إعادة التعيين",
                        },
                        lang
                      )}
                </Button>
              </div>
            </form>
          )}
        </DialogContent>
      </Dialog>
    </div>
  )
}

"use client"


import { boundedFullList } from "@/lib/bounded-records"
import { useEffect, useState, useCallback, useRef } from "react"
import { useParams, useRouter } from "next/navigation"
import Link from "next/link"
import Image from "next/image"
import { blogPagesCollection, blogCategoriesCollection } from "@/lib/pb-collections"
import { BlogPage, BlogCategory } from "@/types/cms"
import type { Lang } from "@/types/form"
import { RichTextEditor } from "@/components/cms/RichTextEditor"
import { CmsPreviewDialog } from "@/components/cms/CmsPreviewDialog"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs"
import { Card } from "@/components/ui/card"
import { Loader2, ArrowLeft, ArrowRight, Eye, Trash2, Copy } from "lucide-react"
import { toast } from "sonner"
import pb, { getErrorMessage } from "@/lib/pb"
import { t, UI_STRINGS } from "@/lib/i18n"
import { formatDate } from "@/lib/format-date"
import { useLang } from "@/lib/lang-context"

function extractThumbnail(record: Record<string, unknown>): string {
  const t = record.thumbnail
  if (!t) return ""
  if (Array.isArray(t)) return t[0] || ""
  return t as string
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/[\s_-]+/g, "-")
    .replace(/^-+|-+$/g, "")
}

export default function CmsBlogEditorPage() {
  const { lang } = useLang()
  const params = useParams()
  const router = useRouter()
  const slug = params.slug as string
  const [activeLang, setActiveLang] = useState<Lang>("en")
  const BackIcon = lang === "ar" ? ArrowRight : ArrowLeft

  const [page, setPage] = useState<BlogPage | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [publishing, setPublishing] = useState(false)
  const [deleting, setDeleting] = useState(false)

  // Form state
  const [enTitle, setEnTitle] = useState("")
  const [arTitle, setArTitle] = useState("")
  const [postSlug, setPostSlug] = useState("")
  const [category, setCategory] = useState("")
  const [enContent, setEnContent] = useState("")
  const [arContent, setArContent] = useState("")
  const [isPublished, setIsPublished] = useState(false)
  const [previewOpen, setPreviewOpen] = useState(false)
  const [authorName, setAuthorName] = useState("")
  const [thumbnailUrl, setThumbnailUrl] = useState<string | null>(null)
  const [uploadingThumbnail, setUploadingThumbnail] = useState(false)

  const [categories, setCategories] = useState<BlogCategory[]>([])

  const [resetKey, setResetKey] = useState(0)

  const isInitialMount = useRef(true)
  const pageRecordRef = useRef<Record<string, unknown> | null>(null)

  useEffect(() => {
    async function load() {
      const [rawRecords, cats] = await Promise.all([
        boundedFullList(pb.collection("blog_pages"), { filter: pb.filter("slug = {:value0}", { value0: slug }), limit: 1 }),
        blogCategoriesCollection.getAll(),
      ])
      const rawRecord = rawRecords[0] as Record<string, unknown> | undefined
      if (!rawRecord) {
        setLoading(false)
        return
      }
      pageRecordRef.current = rawRecord

      const thumbFile = extractThumbnail(rawRecord)
      setThumbnailUrl(thumbFile ? pb.files.getUrl(rawRecord, thumbFile) : null)

      const data: BlogPage = {
        id: rawRecord.id as string,
        slug: rawRecord.slug as string,
        title_en: rawRecord.title_en as string,
        title_ar: rawRecord.title_ar as string | undefined,
        category: rawRecord.category as string,
        content_en: rawRecord.content_en as string,
        content_ar: rawRecord.content_ar as string | undefined,
        is_published: rawRecord.is_published as boolean,
        media: (rawRecord.media as string[]) || [],
        thumbnail: thumbFile,
        author_name: (rawRecord.author_name as string) || "",
        created: rawRecord.created as string,
        updated: rawRecord.updated as string,
      }
      setPage(data)
      setEnTitle(data.title_en)
      setArTitle(data.title_ar || "")
      setPostSlug(data.slug)
      setCategory(data.category)
      setEnContent(data.content_en)
      setArContent(data.content_ar || "")
      setIsPublished(data.is_published)
      setAuthorName(data.author_name)
      setCategories(cats)
      setLoading(false)
    }
    load()
  }, [slug])

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false
      return
    }
    // Auto-generate slug from English title
    setPostSlug(slugify(enTitle))
  }, [enTitle])

  const handleSave = useCallback(
    async (overrideContent?: string) => {
      if (!page) return
      setSaving(true)
      try {
        const contentField = `content_${activeLang}` as const
        const contentValue = overrideContent !== undefined
          ? overrideContent
          : (activeLang === "en" ? enContent : arContent)
        const updated = await blogPagesCollection.update(page.id, {
          title_en: enTitle,
          title_ar: arTitle,
          slug: postSlug,
          category,
          author_name: authorName,
          [contentField]: contentValue,
        })
        setPage(updated)
        setEnTitle(updated.title_en)
        setArTitle(updated.title_ar || "")
        setEnContent(updated.content_en)
        setArContent(updated.content_ar || "")
        // If slug changed, redirect to new slug
        if (updated.slug !== slug) {
          router.push(`/cms/blog/${updated.slug}`)
        }
      } catch (err) {
        toast.error(
          t(
            { en: "Failed to save. Make sure the slug is unique.", ar: "فشل الحفظ. تأكد من أن المعرف (slug) فريد." },
            lang
          ),
          { description: getErrorMessage(err) }
        )
      } finally {
        setSaving(false)
      }
    },
    [page, enTitle, arTitle, postSlug, category, authorName, enContent, arContent, slug, router, activeLang, lang]
  )

  const handleContentChange = useCallback(
    (html: string) => {
      if (activeLang === "en") {
        setEnContent(html)
      } else {
        setArContent(html)
      }
    },
    [activeLang]
  )

  const handleContentSave = useCallback(
    async (html: string) => {
      if (activeLang === "en") {
        setEnContent(html)
      } else {
        setArContent(html)
      }
      await handleSave(html)
    },
    [handleSave, activeLang]
  )

  const copyFromEnglish = useCallback(() => {
    setArTitle(enTitle)
    setArContent(enContent)
    setResetKey(t => t + 1)
  }, [enTitle, enContent])

  const handleDiscard = useCallback(() => {
    if (!page) return
    setEnTitle(page.title_en)
    setArTitle(page.title_ar || "")
    setPostSlug(page.slug)
    setCategory(page.category)
    setEnContent(page.content_en)
    setArContent(page.content_ar || "")
    setIsPublished(page.is_published)
    setAuthorName(page.author_name)
    setThumbnailUrl(
      page.thumbnail && pageRecordRef.current
        ? pb.files.getUrl(pageRecordRef.current, page.thumbnail)
        : null
    )
    setResetKey(t => t + 1)
  }, [page])

  const togglePublish = useCallback(async () => {
    if (!page) return
    setPublishing(true)
    try {
      const updated = await blogPagesCollection.update(page.id, {
        is_published: !page.is_published,
      })
      setPage(updated)
      setIsPublished(updated.is_published)
    } finally {
      setPublishing(false)
    }
  }, [page])

  const handleImageUpload = useCallback(
    async (file: File): Promise<string> => {
      if (!page) throw new Error("No page loaded")
      const updated = await blogPagesCollection.updateWithFiles(
        page.id,
        {},
        [file]
      )
      const newMedia = updated.media
      const filename = newMedia[newMedia.length - 1]
      setPage((prev) => (prev ? { ...prev, media: newMedia } : null))
      return pb.files.getUrl(updated, filename)
    },
    [page]
  )

  const handleThumbnailUpload = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]
      if (!file || !page) return
      setUploadingThumbnail(true)
      try {
        const updated = await blogPagesCollection.updateThumbnail(page.id, file)
        setPage(updated)
        pageRecordRef.current = updated as unknown as Record<string, unknown>
        setThumbnailUrl(pb.files.getUrl(updated as never, updated.thumbnail))
      } catch (err) {
        toast.error(
          t(
            { en: "Failed to upload thumbnail.", ar: "فشل رفع الصورة المصغرة." },
            lang
          ),
          { description: getErrorMessage(err) }
        )
      } finally {
        setUploadingThumbnail(false)
      }
    },
    [page, lang]
  )

  const handleRemoveThumbnail = useCallback(async () => {
    if (!page) return
    try {
      const updated = await blogPagesCollection.removeThumbnail(page.id)
      setPage(updated)
      pageRecordRef.current = updated as unknown as Record<string, unknown>
      setThumbnailUrl(null)
    } catch (err) {
      toast.error(
        t(
          { en: "Failed to remove thumbnail.", ar: "فشل إزالة الصورة المصغرة." },
          lang
        ),
        { description: getErrorMessage(err) }
      )
    }
  }, [page, lang])

  const handleDelete = useCallback(async () => {
    if (!page) return
    if (
      !confirm(
        t(
          {
            en: `Delete "${page.title_en}"? This cannot be undone.`,
            ar: `حذف "${page.title_en}"؟ لا يمكن التراجع عن هذا.`,
          },
          lang
        )
      )
    )
      return
    setDeleting(true)
    try {
      await blogPagesCollection.delete(page.id)
      router.push("/cms/blog")
    } catch (err) {
      toast.error(getErrorMessage(err))
      setDeleting(false)
    }
  }, [page, router, lang])

  // Category label for the preview, resolved the same way the public
  // /blog/[slug] page resolves it.
  const previewCategoryLabel = (() => {
    const matched = categories.find((c) => c.key === category)
    if (!matched) return category
    return activeLang === "ar" && matched.label_ar ? matched.label_ar : matched.label_en
  })()

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    )
  }

  if (!page) {
    return (
      <div className="space-y-4">
        <Link
          href="/cms/blog"
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:underline"
        >
          <BackIcon className="h-4 w-4" />
          {t({ en: "Back", ar: "رجوع" }, lang)}
        </Link>
        <p>{t({ en: "Post not found.", ar: "المنشور غير موجود." }, lang)}</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link
          href="/cms/blog"
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:underline"
        >
          <BackIcon className="h-4 w-4" />
          {t({ en: "Back", ar: "رجوع" }, lang)}
        </Link>
      </div>

      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold">
            {t({ en: "Edit Post", ar: "تعديل المنشور" }, lang)}
          </h1>
          <p className="text-muted-foreground">
            {t({ en: "Manage blog post details", ar: "إدارة تفاصيل منشور المدونة" }, lang)}
          </p>
        </div>

        <div className="flex items-center gap-3">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setPreviewOpen(true)}
          >
            <Eye className="me-2 h-4 w-4" />
            {t(UI_STRINGS.preview, lang)}
          </Button>
          <div className="flex items-center gap-2">
            <Switch
              id="publish"
              checked={isPublished}
              onCheckedChange={togglePublish}
              disabled={publishing}
            />
            <Label htmlFor="publish" className="font-medium">
              {isPublished ? t(UI_STRINGS.published, lang) : t(UI_STRINGS.draft, lang)}
            </Label>
          </div>
        </div>
      </div>

      <Card className="space-y-4 p-4">
        <div className="space-y-2">
          <Label htmlFor="category">
            {t({ en: "Category", ar: "التصنيف" }, lang)}
          </Label>
          <Select value={category} onValueChange={setCategory}>
            <SelectTrigger id="category" className="w-72">
              <SelectValue placeholder={t({ en: "Select category", ar: "اختر التصنيف" }, lang)} />
            </SelectTrigger>
            <SelectContent position="popper" className="w-[var(--radix-select-trigger-width)] min-w-[160px]">
              {categories.map((cat) => (
                <SelectItem key={cat.id} value={cat.key}>
                  {activeLang === "ar" && cat.label_ar ? cat.label_ar : cat.label_en}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <Label htmlFor="author">
            {t({ en: "Author", ar: "المؤلف" }, lang)}
          </Label>
          <Input
            id="author"
            value={authorName}
            onChange={(e) => setAuthorName(e.target.value)}
            placeholder={t({ en: "Author name", ar: "اسم المؤلف" }, lang)}
            className="max-w-xs w-72"
          />
        </div>

        <div className="space-y-2">
          <Label>{t({ en: "Thumbnail", ar: "الصورة المصغرة" }, lang)}</Label>
          {thumbnailUrl && (
            <div className="relative mb-2 w-48 overflow-hidden rounded-lg border">
              <Image
                src={thumbnailUrl}
                alt={t({ en: "Thumbnail", ar: "الصورة المصغرة" }, lang)}
                width={192}
                height={108}
                className="h-auto w-full object-cover"
              />
              <Button
                variant="destructive"
                size="sm"
                className="absolute right-1 top-1"
                onClick={handleRemoveThumbnail}
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          )}
          <div className="flex items-center gap-2">
            <Input
              type="file"
              accept="image/*"
              onChange={handleThumbnailUpload}
              disabled={uploadingThumbnail}
              className="w-72"
            />
            {uploadingThumbnail && <Loader2 className="h-4 w-4 animate-spin" />}
          </div>
        </div>
      </Card>

      <Tabs value={activeLang} onValueChange={(v) => setActiveLang(v as Lang)}>
        <TabsList>
          <TabsTrigger value="en">English</TabsTrigger>
          <TabsTrigger value="ar">العربية</TabsTrigger>
        </TabsList>
      </Tabs>

      {activeLang === "en" ? (
        <div className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="en-title">
              {t({ en: "Title (English)", ar: "العنوان (إنجليزي)" }, lang)}
            </Label>
            <Input
              id="en-title"
              value={enTitle}
              onChange={(e) => setEnTitle(e.target.value)}
              placeholder={t({ en: "Post title", ar: "عنوان المنشور" }, lang)}
            />
          </div>
          <RichTextEditor
            key={`${resetKey}-en`}
            title={t({ en: "English Content", ar: "المحتوى (إنجليزي)" }, lang)}
            initialContent={enContent}
            onSave={handleContentSave}
            isSaving={saving}
            onImageUpload={handleImageUpload}
            onDiscard={handleDiscard}
            onChange={handleContentChange}
          />
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <Label htmlFor="ar-title">
              {t({ en: "Title (Arabic)", ar: "العنوان (عربي)" }, lang)}
            </Label>
            <Button variant="outline" size="sm" onClick={copyFromEnglish}>
              <Copy className="mr-2 h-4 w-4" />
              {t({ en: "Copy from English", ar: "نسخ من الإنجليزية" }, lang)}
            </Button>
          </div>
          <Input
            id="ar-title"
            value={arTitle}
            onChange={(e) => setArTitle(e.target.value)}
            placeholder="عنوان المقال"
          />
          <RichTextEditor
            key={`${resetKey}-ar`}
            title={t({ en: "Arabic Content", ar: "المحتوى (عربي)" }, lang)}
            initialContent={arContent}
            onSave={handleContentSave}
            isSaving={saving}
            onImageUpload={handleImageUpload}
            onDiscard={handleDiscard}
            onChange={handleContentChange}
            direction="rtl"
          />
        </div>
      )}

      <CmsPreviewDialog
        open={previewOpen}
        onOpenChange={setPreviewOpen}
        title={activeLang === "ar" && arTitle ? arTitle : enTitle}
        html={activeLang === "en" ? enContent : arContent}
        lang={activeLang}
        path={`/blog/${postSlug}`}
      >
        <div className="mb-8 space-y-2">
          <div className="flex items-center gap-3 text-sm text-muted-foreground">
            {previewCategoryLabel && (
              <>
                <span className="rounded-md bg-gray-100 px-2 py-0.5 capitalize">
                  {previewCategoryLabel}
                </span>
                <span>&middot;</span>
              </>
            )}
            {page.created && <span>{formatDate(page.created)}</span>}
            {authorName && (
              <>
                <span>&middot;</span>
                <span>
                  {t({ en: "By", ar: "بقلم" }, lang)} {authorName}
                </span>
              </>
            )}
          </div>
        </div>
      </CmsPreviewDialog>
    </div>
  )
}

"use client"

import { useEffect, useState, useCallback, useRef } from "react"
import { useParams, useRouter } from "next/navigation"
import Link from "next/link"
import { usePortals } from "@/hooks/usePortals"
import { infoPagesCollection } from "@/lib/pb-collections"
import pb, { getErrorMessage } from "@/lib/pb"
import type { InfoPage } from "@/types/cms"
import type { Lang } from "@/types/form"
import { RichTextEditor } from "@/components/cms/RichTextEditor"
import { CmsPreviewDialog } from "@/components/cms/CmsPreviewDialog"
import { Switch } from "@/components/ui/switch"
import { Label } from "@/components/ui/label"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Card } from "@/components/ui/card"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { ArrowLeft, ArrowRight, Eye, Loader2, Copy, Trash2 } from "lucide-react"
import { toast } from "sonner"
import { t, UI_STRINGS } from "@/lib/i18n"
import { useLang } from "@/lib/lang-context"

function extractIcon(record: Record<string, unknown>): string {
  const icon = record.icon
  if (!icon) return ""
  if (Array.isArray(icon)) return icon[0] || ""
  return icon as string
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/[\s_-]+/g, "-")
    .replace(/^-+|-+$/g, "")
}

async function loadImage(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file)
    const img = new Image()
    img.onload = () => {
      URL.revokeObjectURL(url)
      resolve(img)
    }
    img.onerror = () => {
      URL.revokeObjectURL(url)
      reject(new Error("Invalid image"))
    }
    img.src = url
  })
}

async function resizeIconToSquare(file: File, size = 256): Promise<File> {
  const img = await loadImage(file)
  const canvas = document.createElement("canvas")
  canvas.width = size
  canvas.height = size
  const ctx = canvas.getContext("2d")
  if (!ctx) throw new Error("Canvas not supported")

  const side = Math.min(img.naturalWidth, img.naturalHeight)
  const sx = (img.naturalWidth - side) / 2
  const sy = (img.naturalHeight - side) / 2
  ctx.drawImage(img, sx, sy, side, side, 0, 0, size, size)

  const blob = await new Promise<Blob>((resolve, reject) => {
    canvas.toBlob(
      (b) => (b ? resolve(b) : reject(new Error("Failed to process image"))),
      "image/png"
    )
  })
  return new File([blob], "icon.png", { type: "image/png" })
}

export default function CmsServiceEditorPage() {
  const { lang } = useLang()
  const { portals: PORTALS } = usePortals()
  const getPortalById = (id: string) => PORTALS.find((portal) => portal.id === id)
  const BackIcon = lang === "ar" ? ArrowRight : ArrowLeft
  const params = useParams()
  const router = useRouter()
  const portalId = params.portalId as string
  const slug = params.slug as string
  const portal = getPortalById(portalId)
  const [activeLang, setActiveLang] = useState<Lang>("en")

  const [page, setPage] = useState<InfoPage | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [publishing, setPublishing] = useState(false)
  const [deleting, setDeleting] = useState(false)
  const [uploadingIcon, setUploadingIcon] = useState(false)
  const [previewOpen, setPreviewOpen] = useState(false)

  const [pageSlug, setPageSlug] = useState(slug)
  const [enTitle, setEnTitle] = useState("")
  const [arTitle, setArTitle] = useState("")
  const [enContent, setEnContent] = useState("")
  const [arContent, setArContent] = useState("")
  const [isPublished, setIsPublished] = useState(false)
  const [iconUrl, setIconUrl] = useState<string | null>(null)

  const [resetKey, setResetKey] = useState(0)

  const isInitialMount = useRef(true)
  const pageRecordRef = useRef<Record<string, unknown> | null>(null)

  useEffect(() => {
    async function load() {
      const data = await infoPagesCollection.getBySlug(slug)
      if (!data) {
        setLoading(false)
        return
      }
      pageRecordRef.current = data as unknown as Record<string, unknown>
      const iconFile = extractIcon(pageRecordRef.current)
      setIconUrl(
        iconFile && pageRecordRef.current
          ? pb.files.getUrl(pageRecordRef.current, iconFile)
          : null
      )
      setPage(data)
      setPageSlug(data.slug)
      setEnTitle(data.title_en)
      setArTitle(data.title_ar || "")
      setEnContent(data.content_en)
      setArContent(data.content_ar || "")
      setIsPublished(data.is_published)
      setLoading(false)
    }
    load()
  }, [slug, portalId])

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false
      return
    }
    setPageSlug(slugify(enTitle))
  }, [enTitle])

  const handleSave = useCallback(
    async (overrideContent?: string) => {
      if (!page) return
      setSaving(true)
      try {
        const contentField = `content_${activeLang}` as const
        const contentValue =
          overrideContent !== undefined
            ? overrideContent
            : activeLang === "en"
              ? enContent
              : arContent
        const updated = await infoPagesCollection.update(page.id, {
          portal_name: page.portal_name || portalId,
          slug: pageSlug,
          title_en: enTitle,
          title_ar: arTitle,
          is_published: isPublished,
          [contentField]: contentValue,
        })
        setPage(updated)
        setEnTitle(updated.title_en)
        setArTitle(updated.title_ar || "")
        setEnContent(updated.content_en)
        setArContent(updated.content_ar || "")
        if (updated.slug !== pageSlug) {
          router.push(`/cms/info/${portalId}/${updated.slug}`)
        }
      } catch (err) {
        toast.error(
          t(
            { en: "Failed to save. Make sure the slug is unique.", ar: "فشل الحفظ. تأكد من أن المعرف (slug) فريد." },
            lang
          ),
          { description: getErrorMessage(err) }
        )
      } finally {
        setSaving(false)
      }
    },
    [
      page,
      pageSlug,
      enTitle,
      arTitle,
      enContent,
      arContent,
      isPublished,
      activeLang,
      portalId,
      router,
      lang,
    ]
  )

  const handleContentChange = useCallback(
    (html: string) => {
      if (activeLang === "en") {
        setEnContent(html)
      } else {
        setArContent(html)
      }
    },
    [activeLang]
  )

  const handleContentSave = useCallback(
    async (html: string) => {
      if (activeLang === "en") {
        setEnContent(html)
      } else {
        setArContent(html)
      }
      await handleSave(html)
    },
    [handleSave, activeLang]
  )

  const copyFromEnglish = useCallback(() => {
    setArTitle(enTitle)
    setArContent(enContent)
    setResetKey(t => t + 1)
  }, [enTitle, enContent])

  const handleDiscard = useCallback(async () => {
    const data = await infoPagesCollection.getBySlug(slug)
    if (!data) return
    pageRecordRef.current = data as unknown as Record<string, unknown>
    setPage(data)
    setPageSlug(data.slug)
    setEnTitle(data.title_en)
    setArTitle(data.title_ar || "")
    setEnContent(data.content_en)
    setArContent(data.content_ar || "")
    setIsPublished(data.is_published)
    const iconFile = extractIcon(pageRecordRef.current)
    setIconUrl(iconFile ? pb.files.getUrl(pageRecordRef.current, iconFile) : null)
    setResetKey(t => t + 1)
  }, [slug])

  const togglePublish = useCallback(async () => {
    if (!page) return
    setPublishing(true)
    try {
      const updated = await infoPagesCollection.update(page.id, {
        is_published: !page.is_published,
      })
      setPage(updated)
      setIsPublished(updated.is_published)
    } finally {
      setPublishing(false)
    }
  }, [page])

  const handleImageUpload = useCallback(
    async (file: File): Promise<string> => {
      if (!page) throw new Error("No page loaded")
      const updated = await infoPagesCollection.updateWithFiles(page.id, {}, [file])
      const newMedia = updated.media as string[]
      const filename = newMedia[newMedia.length - 1]
      setPage((prev) => (prev ? { ...prev, media: newMedia } : null))
      return pb.files.getUrl(updated, filename)
    },
    [page]
  )

  const handleIconUpload = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]
      if (!file || !page) return
      setUploadingIcon(true)
      try {
        const resized = await resizeIconToSquare(file)
        const updated = await infoPagesCollection.updateIcon(page.id, resized)
        setPage(updated)
        pageRecordRef.current = updated as unknown as Record<string, unknown>
        const iconFile = extractIcon(pageRecordRef.current)
        setIconUrl(
          iconFile ? pb.files.getUrl(pageRecordRef.current, iconFile) : null
        )
      } catch (err) {
        toast.error(
          t(
            { en: "Please upload a valid image.", ar: "يرجى رفع صورة صالحة." },
            lang
          ),
          { description: getErrorMessage(err) }
        )
      } finally {
        e.target.value = ""
        setUploadingIcon(false)
      }
    },
    [page, lang]
  )

  const handleRemoveIcon = useCallback(async () => {
    if (!page) return
    try {
      const updated = await infoPagesCollection.removeIcon(page.id)
      setPage(updated)
      pageRecordRef.current = updated as unknown as Record<string, unknown>
      setIconUrl(null)
    } catch (err) {
      toast.error(
        t(
          { en: "Failed to remove icon.", ar: "فشل إزالة الأيقونة." },
          lang
        ),
        { description: getErrorMessage(err) }
      )
    }
  }, [page, lang])

  const handleDelete = useCallback(async () => {
    if (!page) return
    if (
      !confirm(
        t(
          {
            en: `Delete "${page.title_en}"? This cannot be undone.`,
            ar: `حذف "${page.title_en}"؟ لا يمكن التراجع عن هذا.`,
          },
          lang
        )
      )
    )
      return
    setDeleting(true)
    try {
      await infoPagesCollection.delete(page.id)
      router.push(`/cms/info/${portalId}`)
    } catch (err) {
      toast.error(getErrorMessage(err))
      setDeleting(false)
    }
  }, [page, portalId, router, lang])

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    )
  }

  if (!page) {
    return (
      <div className="space-y-4">
        <Link
          href={`/cms/info/${portalId}`}
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:underline"
        >
          <BackIcon className="h-4 w-4" />
          {t({ en: "Back", ar: "رجوع" }, lang)}
        </Link>
        <p>{t({ en: "Page not found.", ar: "الصفحة غير موجودة." }, lang)}</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link
          href={`/cms/info/${portalId}`}
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:underline"
        >
          <BackIcon className="h-4 w-4" />
          {t({ en: "Back", ar: "رجوع" }, lang)}
        </Link>
      </div>

      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold">
            {t({ en: "Edit Page", ar: "تعديل الصفحة" }, lang)}
          </h1>
          <p className="text-muted-foreground">
            {t({ en: "Manage info page details", ar: "إدارة تفاصيل صفحة المعلومات" }, lang)}
          </p>
        </div>

        <div className="flex items-center gap-3">
          {/* <Button variant="destructive" size="sm" onClick={handleDelete} disabled={deleting}>
            {deleting ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <Trash2 className="mr-2 h-4 w-4" />
            )}
            Delete
          </Button> */}
          <Button
            variant="outline"
            size="sm"
            onClick={() => setPreviewOpen(true)}
          >
            <Eye className="me-2 h-4 w-4" />
            {t(UI_STRINGS.preview, lang)}
          </Button>
          <div className="flex items-center gap-2">
            <Switch
              id="publish"
              checked={isPublished}
              onCheckedChange={togglePublish}
              disabled={publishing}
            />
            <Label htmlFor="publish" className="font-medium">
              {isPublished ? t(UI_STRINGS.published, lang) : t(UI_STRINGS.draft, lang)}
            </Label>
          </div>
        </div>
      </div>

      <Card className="space-y-4 p-4">
        <div className="space-y-2">
          <Label>{t({ en: "Portal", ar: "البوابة" }, lang)}</Label>
          <p className="text-sm text-muted-foreground">
            {portal ? t(portal.title, lang) : portalId}
          </p>
        </div>

        {/* <div className="space-y-2">
          <Label htmlFor="slug">Slug</Label>
          <Input
            id="slug"
            value={pageSlug}
            onChange={(e) => setPageSlug(e.target.value)}
            placeholder="page-slug"
            className="max-w-xs w-72"
          />
        </div> */}

        <div className="space-y-2">
          <Label>{t({ en: "Icon", ar: "الأيقونة" }, lang)}</Label>
          {iconUrl && (
            <div className="relative mb-2 w-24 overflow-hidden rounded-lg border">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={iconUrl}
                alt={t({ en: "Icon", ar: "الأيقونة" }, lang)}
                className="h-auto w-full object-contain"
              />
              <Button
                variant="destructive"
                size="sm"
                className="absolute right-1 top-1"
                onClick={handleRemoveIcon}
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          )}
          <div className="flex items-center gap-2">
            <Input
              type="file"
              accept="image/*"
              onChange={handleIconUpload}
              disabled={uploadingIcon}
              className="w-72"
            />
            {uploadingIcon && <Loader2 className="h-4 w-4 animate-spin" />}
          </div>
        </div>
      </Card>

      <Tabs value={activeLang} onValueChange={(v) => setActiveLang(v as Lang)}>
        <TabsList>
          <TabsTrigger value="en">English</TabsTrigger>
          <TabsTrigger value="ar">العربية</TabsTrigger>
        </TabsList>
      </Tabs>

      {activeLang === "en" ? (
        <div className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="en-title">
              {t({ en: "Title (English)", ar: "العنوان (إنجليزي)" }, lang)}
            </Label>
            <Input
              id="en-title"
              value={enTitle}
              onChange={(e) => setEnTitle(e.target.value)}
              placeholder={t({ en: "Page title", ar: "عنوان الصفحة" }, lang)}
            />
          </div>
          <RichTextEditor
            key={`${resetKey}-en`}
            title={t({ en: "English Content", ar: "المحتوى (إنجليزي)" }, lang)}
            initialContent={enContent}
            onSave={handleContentSave}
            isSaving={saving}
            onImageUpload={handleImageUpload}
            onDiscard={handleDiscard}
            onChange={handleContentChange}
          />
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <Label htmlFor="ar-title">
              {t({ en: "Title (Arabic)", ar: "العنوان (عربي)" }, lang)}
            </Label>
            <Button variant="outline" size="sm" onClick={copyFromEnglish}>
              <Copy className="mr-2 h-4 w-4" />
              {t({ en: "Copy from English", ar: "نسخ من الإنجليزية" }, lang)}
            </Button>
          </div>
          <Input
            id="ar-title"
            value={arTitle}
            onChange={(e) => setArTitle(e.target.value)}
            placeholder="عنوان الصفحة"
          />
          <RichTextEditor
            key={`${resetKey}-ar`}
            title={t({ en: "Arabic Content", ar: "المحتوى (عربي)" }, lang)}
            initialContent={arContent}
            onSave={handleContentSave}
            isSaving={saving}
            onImageUpload={handleImageUpload}
            onDiscard={handleDiscard}
            onChange={handleContentChange}
            direction="rtl"
          />
        </div>
      )}

      <CmsPreviewDialog
        open={previewOpen}
        onOpenChange={setPreviewOpen}
        title={activeLang === "ar" && arTitle ? arTitle : enTitle}
        html={activeLang === "en" ? enContent : arContent}
        lang={activeLang}
        path={`/info/${pageSlug}`}
      >
        {iconUrl && (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={iconUrl}
            alt=""
            className="mb-6 h-16 w-16 rounded-xl object-contain"
          />
        )}
      </CmsPreviewDialog>
    </div>
  )
}

"use client"


import { boundedFullList } from "@/lib/bounded-records"
import { useEffect, useState, useCallback } from "react"
import Link from "next/link"
import { useParams, useRouter } from "next/navigation"
import { toast } from "sonner"
import { PageLoader } from "@/components/ui/page-loader"
import { DataError } from "@/components/ui/data-error"
import { usePortals } from "@/hooks/usePortals"
import { infoPagesCollection } from "@/lib/pb-collections"
import pb, { getErrorMessage } from "@/lib/pb"
import { Card } from "@/components/ui/card"
import { DragList } from "@/components/ui/drag-list"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  ArrowLeft,
  ArrowRight,
  Loader2,
  Plus,
  FileText,
  Trash2,
  Pencil,
} from "lucide-react"
import { t, UI_STRINGS } from "@/lib/i18n"
import { useLang } from "@/lib/lang-context"

interface InfoPageRecord {
  id: string
  slug: string
  title_en: string
  icon?: string
  is_published: boolean
  order: number
}

export default function CmsPortalServicesPage() {
  const { lang } = useLang()
  const { portals: PORTALS, isLoading: portalsLoading, error: portalsError, reload: reloadPortals } = usePortals()
  const getPortalById = (id: string) => PORTALS.find((portal) => portal.id === id)
  const BackIcon = lang === "ar" ? ArrowRight : ArrowLeft
  const params = useParams()
  const router = useRouter()
  const portalId = params.portalId as string
  const portal = getPortalById(portalId)

  const [pages, setPages] = useState<InfoPageRecord[]>([])
  const [loading, setLoading] = useState(true)
  const [creating, setCreating] = useState(false)
  const [deleting, setDeleting] = useState<string | null>(null)
  const [savingOrder, setSavingOrder] = useState(false)

  const loadPages = useCallback(async () => {
    const data = await boundedFullList(pb.collection("info_pages"), {
      filter: pb.filter("portal_name = {:value0}", { value0: portalId }),
      sort: "order",
    })
    setPages(data as unknown as InfoPageRecord[])
  }, [portalId])

  useEffect(() => {
    if (!portal) return
    const timer = window.setTimeout(() => { void loadPages().finally(() => setLoading(false)) }, 0)
    return () => window.clearTimeout(timer)
  }, [portal, loadPages])

  const handleNewPage = async () => {
    setCreating(true)
    try {
      const newPage = await infoPagesCollection.create({
        slug: `new-page-${Date.now()}`,
        title_en: "New Page",
        portal_name: portalId,
      })
      router.push(`/cms/info/${portalId}/${newPage.slug}`)
    } catch (err) {
      toast.error(getErrorMessage(err))
      setCreating(false)
    }
  }

  const handleDelete = async (id: string, title: string) => {
    if (
      !confirm(
        t(
          {
            en: `Delete "${title}"? This cannot be undone.`,
            ar: `حذف "${title}"؟ لا يمكن التراجع عن هذا.`,
          },
          lang
        )
      )
    )
      return
    setDeleting(id)
    try {
      await infoPagesCollection.delete(id)
      setPages((prev) => prev.filter((p) => p.id !== id))
    } finally {
      setDeleting(null)
    }
  }

  const handleReorder = useCallback(async (items: InfoPageRecord[]) => {
    setSavingOrder(true)
    try {
      await Promise.all(
        items.map((item) =>
          infoPagesCollection.update(item.id, { order: item.order })
        )
      )
      setPages(items)
    } 

    catch (err) {
      toast.error(
        t(
          { en: "Failed to save order.", ar: "فشل حفظ الترتيب." },
          lang
        ),
        { description: getErrorMessage(err) }
      )
    } 

    finally {
      setSavingOrder(false)
    }
  }, [lang])

  if (portalsLoading) return <PageLoader />
  if (portalsError) return <DataError message={lang === "ar" ? "تعذر تحميل البوابات." : "Unable to load portals."} onRetry={() => void reloadPortals()} />
  if (!portal) {
    return (
      <div className="space-y-4">
        <Link
          href="/cms/info"
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:underline"
        >
          <BackIcon className="h-4 w-4" />
          {t({ en: "Back", ar: "رجوع" }, lang)}
        </Link>
        <p>{t({ en: "Portal not found", ar: "البوابة غير موجودة" }, lang)}</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link
          href="/cms/info"
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:underline"
        >
          <BackIcon className="h-4 w-4" />
          {t({ en: "Back", ar: "رجوع" }, lang)}
        </Link>
      </div>

      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold">{t(portal.title, lang)}</h1>
          <p className="text-muted-foreground">
            {t(
              { en: "Manage info pages for this portal", ar: "إدارة صفحات المعلومات لهذه البوابة" },
              lang
            )}
          </p>
        </div>

        {/* <Button onClick={handleNewPage} disabled={creating}>
          {creating ? (
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
          ) : (
            <Plus className="mr-2 h-4 w-4" />
          )}
          New Page
        </Button> */}
      </div>

      {loading ? (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {Array.from({ length: 5 }).map((_, i) => (
            <Card key={i} className="h-24 animate-pulse bg-gray-100" />
          ))}
        </div>
      ) : pages.length === 0 ? (
        <div className="flex flex-col items-center justify-center rounded-lg border border-dashed py-12 text-center">
          <p className="text-muted-foreground">
            {t({ en: "No pages yet.", ar: "لا توجد صفحات بعد." }, lang)}
          </p>
          <Button onClick={handleNewPage} className="mt-4" disabled={creating}>
            {creating ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <Plus className="mr-2 h-4 w-4" />
            )}
            {t({ en: "Create your first page", ar: "أنشئ صفحتك الأولى" }, lang)}
          </Button>
        </div>
        ) : (
          <DragList
            items={pages}
            onReorder={handleReorder}
            keyExtractor={(p) => p.id}
            containerClassName="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3"
            renderItem={(p) => {
              const iconUrl = p.icon ? pb.files.getUrl(p as never, p.icon) : null
              return (
                <>
                  <div
                    className="flex h-12 w-12 shrink-0 items-center justify-center rounded-lg"
                    style={{ backgroundColor: `${portal.accent}15` }}
                  >
                    {iconUrl ? (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img src={iconUrl} alt="" className="h-6 w-6 object-contain" />
                    ) : (
                      <FileText className="h-6 w-6" style={{ color: portal.accent }} />
                    )}
                  </div>
                  <div className="min-w-0 flex-1">
                    <h3 className="font-medium">{p.title_en}</h3>
                    <div className="mt-1 flex items-center gap-2">
                      {p.is_published ? (
                        <Badge variant="default" className="text-xs" style={{ backgroundColor: portal.accent, color: "#fff" }}>
                          {t(UI_STRINGS.published, lang)}
                        </Badge>
                      ) : (
                        <Badge variant="secondary" className="text-xs">{t(UI_STRINGS.draft, lang)}</Badge>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-1">
                    <Link href={`/cms/info/${portalId}/${p.slug}`}>
                      <Button variant="ghost" size="sm">
                        <Pencil className="h-4 w-4" />
                      </Button>
                    </Link>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleDelete(p.id, p.title_en)}
                      disabled={deleting === p.id}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </>
              )
            }}
          />
        )}
    </div>
  )
}

"use client"
import { useState, useEffect } from "react"
import Link from "next/link"
import { Plus, Pencil, Trash2, RotateCcw } from "lucide-react"
import pb, { getErrorMessage } from "@/lib/pb"
import { usePortals } from "@/hooks/usePortals"
import { useLang } from "@/lib/lang-context"
import type { Portal } from "@/lib/portals"
import { PortalIcon, portalIcons } from "@/components/portal/PortalIcon"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"
import { PageLoader } from "@/components/ui/page-loader"
import { DataError } from "@/components/ui/data-error"
type Draft = {
  key: string
  en: string
  ar: string
  descriptionEn: string
  descriptionAr: string
  icon: string
  registration: string
  accent: string
  order: number
}
const iconLabels: Record<string, [string, string]> = {
  heartHandshake: ["Support", "الدعم"],
  brain: ["Mind", "العقل"],
  graduationCap: ["Education", "التعليم"],
  building2: ["Organization", "المؤسسة"],
  heart: ["Wellbeing", "العافية"],
  users: ["Community", "المجتمع"],
  bookOpen: ["Learning", "التعلم"],
  lightbulb: ["Ideas", "الأفكار"],
  briefcase: ["Work", "العمل"],
  globe: ["Global", "العالم"],
}
const empty: Draft = {
  key: "",
  en: "",
  ar: "",
  descriptionEn: "",
  descriptionAr: "",
  icon: "globe",
  registration: "individual",
  accent: "#0b3d60",
  order: 0,
}
export default function CmsPortalsPage() {
  const { lang } = useLang()
  const ar = lang === "ar"
  const text = (en: string, arabic: string) => (ar ? arabic : en)
  const { portals, isLoading, error, reload } = usePortals(true)
  const [editing, setEditing] = useState<Portal | null | undefined>(undefined),
    [draft, setDraft] = useState<Draft>(empty),
    [picture, setPicture] = useState<File | null>(null),
    [preview, setPreview] = useState(""),
    [removePicture, setRemovePicture] = useState(false),
    [saving, setSaving] = useState(false),
    [notice, setNotice] = useState(""),
    [failure, setFailure] = useState(""),
    [pictureError, setPictureError] = useState(""),
    [showRemoved, setShowRemoved] = useState(false)
  useEffect(() => {
    const url = picture ? URL.createObjectURL(picture) : ""
    const timer = window.setTimeout(() => setPreview(url), 0)
    return () => {
      window.clearTimeout(timer)
      if (url) URL.revokeObjectURL(url)
    }
  }, [picture])
  const start = (p: Portal | null) => {
    setEditing(p)
    setDraft(
      p
        ? {
            key: p.id,
            en: p.title.en,
            ar: p.title.ar,
            descriptionEn: p.tagline.en,
            descriptionAr: p.tagline.ar,
            icon: p.icon || "globe",
            registration: p.registrationType || "individual",
            accent: p.accent,
            order: p.order || 0,
          }
        : { ...empty, order: portals.length }
    )
    setPicture(null)
    setPictureError("")
    setRemovePicture(false)
    setFailure("")
    setNotice("")
  }
  const update = (field: keyof Draft, value: string | number) =>
    setDraft({ ...draft, [field]: value })
  const changed = async () => {
    await reload()
    window.dispatchEvent(new Event("portals-updated"))
  }
  const save = async (e: React.FormEvent) => {
    e.preventDefault()
    setFailure("")
    setNotice("")
    if (!/^[a-z0-9-]{1,80}$/.test(draft.key)) {
      setFailure(
        text(
          "Use lowercase letters, numbers and hyphens for the portal address.",
          "استخدم الحروف الإنجليزية الصغيرة والأرقام والشرطات لعنوان البوابة."
        )
      )
      return
    }
    if (
      [draft.en, draft.ar].some((s) => s.trim().length < 2) ||
      [draft.descriptionEn, draft.descriptionAr].some((s) => !s.trim())
    ) {
      setFailure(
        text(
          "Enter both titles and descriptions.",
          "أدخل العنوان والوصف باللغتين."
        )
      )
      return
    }
    setSaving(true)
    try {
      const data = new FormData()
      Object.entries({
        portal_key: draft.key,
        title_en: draft.en.trim(),
        title_ar: draft.ar.trim(),
        description_en: draft.descriptionEn.trim(),
        description_ar: draft.descriptionAr.trim(),
        icon: draft.icon,
        registration_type: draft.registration,
        accent: draft.accent,
        order: draft.order,
      }).forEach(([key, value]) => data.append(key, String(value)))
      if (picture) data.append("picture", picture)
      else if (removePicture) data.append("picture", "")
      if (editing?.recordId)
        await pb.collection("portals").update(editing.recordId, data)
      else await pb.collection("portals").create(data)
      await changed()
      setEditing(undefined)
      setNotice(text("Portal saved.", "تم حفظ البوابة."))
    } catch (e) {
      setFailure(getErrorMessage(e))
    } finally {
      setSaving(false)
    }
  }
  const archive = async (p: Portal) => {
    setSaving(true)
    setFailure("")
    try {
      await pb
        .collection("portals")
        .update(p.recordId!, { is_deleted: !p.isDeleted })
      await changed()
      setNotice(
        p.isDeleted
          ? text("Portal restored.", "تمت استعادة البوابة.")
          : text(
              "Portal removed. You can restore it below.",
              "تم حذف البوابة. يمكنك استعادتها أدناه."
            )
      )
    } catch (e) {
      setFailure(getErrorMessage(e))
    } finally {
      setSaving(false)
    }
  }
  const image = preview || (!removePicture && editing?.picture) || ""
  return (
    <div className="mx-auto max-w-6xl space-y-6" dir={ar ? "rtl" : "ltr"}>
      <header className="flex flex-wrap items-start justify-between gap-4 border-b pb-5">
        <div>
          <p className="mb-2 text-xs font-semibold tracking-widest text-[#9b7621]">
            CMS
          </p>
          <h1 className="text-3xl font-bold text-[#0b3d60]">
            {text("Portals", "البوابات")}
          </h1>
          <p className="mt-2 max-w-xl text-sm text-slate-600">
            {text(
              "Manage the support areas displayed on your website. Edit their names, descriptions and visual identity.",
              "إدارة مجالات الدعم المعروضة على موقعك. عدّل الأسماء والأوصاف والصورة أو الأيقونة."
            )}
          </p>
        </div>
        <Button onClick={() => start(null)} disabled={saving}>
          <Plus size={16} />
          {text("Add portal", "إضافة بوابة")}
        </Button>
      </header>
      {notice && (
        <p
          role="status"
          className="rounded-md bg-emerald-50 p-3 text-sm text-emerald-800"
        >
          {notice}
        </p>
      )}
      {failure && (
        <p
          role="alert"
          className="rounded-md bg-red-50 p-3 text-sm text-red-800"
        >
          {failure}
        </p>
      )}
      {editing === undefined && isLoading ? (
        <PageLoader />
      ) : editing === undefined && error ? (
        <DataError
          message={text("Unable to load portals.", "تعذر تحميل البوابات.")}
          onRetry={() => void reload()}
        />
      ) : editing !== undefined ? (
        <form
          onSubmit={save}
          className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_280px]"
        >
          <div className="min-w-0 space-y-6 rounded-xl border bg-white p-4 sm:p-6">
            <h2 className="text-xl font-semibold">
              {editing
                ? text("Edit portal", "تعديل البوابة")
                : text("New portal", "بوابة جديدة")}
            </h2>
            <div className="space-y-2">
              <Label htmlFor="portal-key">
                {text("Portal address", "عنوان البوابة")}
              </Label>
              <Input
                id="portal-key"
                dir="ltr"
                value={draft.key}
                readOnly={!!editing}
                maxLength={80}
                onChange={(e) => update("key", e.target.value)}
                placeholder="family-support"
                required
              />
              <p className="text-xs text-slate-500" dir="ltr">
                /portal/{draft.key || "family-support"}
              </p>
            </div>
            <div className="grid gap-5 sm:grid-cols-2">
              {(["en", "ar"] as const).map((language) => (
                <fieldset
                  key={language}
                  className="min-w-0 space-y-4"
                  dir={language === "ar" ? "rtl" : "ltr"}
                >
                  <legend className="mb-3 text-sm font-semibold text-[#0b3d60]">
                    {language === "en" ? "English" : "العربية"}
                  </legend>
                  <div className="space-y-2">
                    <Label htmlFor={`title-${language}`}>
                      {language === "en" ? "Title" : "العنوان"}
                    </Label>
                    <Input
                      id={`title-${language}`}
                      value={draft[language]}
                      onChange={(e) => update(language, e.target.value)}
                      required
                      minLength={2}
                      maxLength={120}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor={`description-${language}`}>
                      {language === "en" ? "Description" : "الوصف"}
                    </Label>
                    <Textarea
                      id={`description-${language}`}
                      value={
                        language === "en"
                          ? draft.descriptionEn
                          : draft.descriptionAr
                      }
                      onChange={(e) =>
                        update(
                          language === "en" ? "descriptionEn" : "descriptionAr",
                          e.target.value
                        )
                      }
                      required
                      maxLength={600}
                      rows={5}
                    />
                    <p className="text-xs text-slate-500">
                      {
                        (language === "en"
                          ? draft.descriptionEn
                          : draft.descriptionAr
                        ).length
                      }
                      /600
                    </p>
                  </div>
                </fieldset>
              ))}
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="portal-icon">{text("Icon", "الأيقونة")}</Label>
                <select
                  id="portal-icon"
                  className="h-11 w-full rounded-md border px-3"
                  value={draft.icon}
                  onChange={(e) => update("icon", e.target.value)}
                >
                  {Object.keys(portalIcons).map((name) => (
                    <option key={name} value={name}>
                      {text(...iconLabels[name])}
                    </option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="portal-color">
                  {text("Accent color", "لون البوابة")}
                </Label>
                <Input
                  id="portal-color"
                  type="color"
                  value={draft.accent}
                  onChange={(e) => update("accent", e.target.value)}
                  className="h-11"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="portal-picture">
                {text("Picture (optional)", "الصورة (اختياري)")}
              </Label>
              <Input
                id="portal-picture"
                type="file"
                aria-invalid={!!pictureError}
                aria-describedby="portal-picture-help portal-picture-error"
                accept="image/png,image/jpeg,image/webp,image/gif"
                onChange={(e) => {
                  const file = e.target.files?.[0] || null
                  if (
                    file &&
                    (file.size > 5 * 1024 * 1024 ||
                      ![
                        "image/jpeg",
                        "image/png",
                        "image/webp",
                        "image/gif",
                      ].includes(file.type))
                  ) {
                    setPictureError(
                      text(
                        "Choose a JPG, PNG, WebP or GIF up to 5 MB.",
                        "اختر صورة JPG أو PNG أو WebP أو GIF بحجم لا يتجاوز 5 ميجابايت."
                      )
                    )
                    e.target.value = ""
                    return
                  }
                  setPictureError("")
                  setPicture(file)
                  setRemovePicture(false)
                }}
              />
              {pictureError && (
                <p id="portal-picture-error" role="alert" className="text-sm text-red-700">
                  {pictureError}
                </p>
              )}
              {picture && (
                <p role="status" className="text-sm text-emerald-700">
                  {picture.name} — {text("Selected. Click Save portal to upload.", "تم اختيار الصورة. اضغط حفظ البوابة لرفعها.")}
                </p>
              )}
              <p id="portal-picture-help" className="text-xs text-slate-500">
                {text(
                  "Maximum 5 MB. A picture replaces the icon and appears on the portal page.",
                  "الحد الأقصى 5 ميجابايت. تحل الصورة محل الأيقونة وتظهر في صفحة البوابة."
                )}
              </p>
              {(editing?.picture || picture) && (
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    setPicture(null)
                    setRemovePicture(true)
                  }}
                >
                  {text("Remove picture", "حذف الصورة")}
                </Button>
              )}
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="portal-registration">
                  {text("Registration account type", "نوع حساب التسجيل")}
                </Label>
                <select
                  id="portal-registration"
                  className="h-11 w-full rounded-md border px-3"
                  value={draft.registration}
                  onChange={(e) => update("registration", e.target.value)}
                >
                  {[
                    ["parent", "Parent", "ولي أمر"],
                    ["individual", "Individual", "فرد"],
                    ["organization", "Organization", "مؤسسة"],
                    ["expert", "Expert", "خبير"],
                  ].map(([key, en, arabic]) => (
                    <option key={key} value={key}>
                      {text(en, arabic)}
                    </option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="portal-order">
                  {text("Display order", "ترتيب العرض")}
                </Label>
                <Input
                  id="portal-order"
                  type="number"
                  min={0}
                  step={1}
                  value={draft.order}
                  onChange={(e) => update("order", Number(e.target.value))}
                  required
                />
              </div>
            </div>
            <div className="flex flex-wrap gap-3 border-t pt-5">
              <Button disabled={saving}>
                {saving
                  ? text("Saving…", "جارٍ الحفظ…")
                  : text("Save portal", "حفظ البوابة")}
              </Button>
              <Button
                type="button"
                variant="outline"
                disabled={saving}
                onClick={() => setEditing(undefined)}
              >
                {text("Cancel", "إلغاء")}
              </Button>
            </div>
          </div>
          <aside className="space-y-3">
            <h3 className="text-sm font-semibold text-slate-600">
              {text("Card preview", "معاينة البطاقة")}
            </h3>
            <div
              className={`min-w-0 overflow-hidden rounded-xl border bg-white p-6 ${image ? "min-h-[432px]" : ""}`}
              style={{ borderTop: `4px solid ${draft.accent}` }}
            >
              <div
                className={image
                  ? "-mx-6 -mt-6 mb-5 h-54 overflow-hidden bg-slate-50"
                  : "mb-6 flex h-16 w-16 items-center justify-center overflow-hidden rounded-lg bg-slate-50"}
                style={{ color: draft.accent }}
              >
                {image ? (
                  <img
                    src={image}
                    alt=""
                    className="h-full w-full object-cover"
                  />
                ) : (
                  <PortalIcon name={draft.icon} size={32} />
                )}
              </div>
              <h3 className="text-lg font-bold break-words text-[#0b3d60]">
                {(ar ? draft.ar : draft.en) ||
                  text("Portal title", "عنوان البوابة")}
              </h3>
              <p className="mt-3 text-sm leading-relaxed break-words text-slate-600">
                {(ar ? draft.descriptionAr : draft.descriptionEn) ||
                  text(
                    "Your description appears here.",
                    "يظهر وصف البوابة هنا."
                  )}
              </p>
              <div
                className="mt-8 flex flex-wrap items-center justify-between gap-3 text-xs font-semibold"
                style={{ color: draft.accent }}
              >
                <span>{text("Explore support →", "استكشف المجال ←")}</span>
              </div>
            </div>
          </aside>
        </form>
      ) : (
        <>
          <div className="space-y-3">
            {portals
              .filter((p) => !p.isDeleted)
              .map((p) => (
                <article
                  key={p.id}
                  className="flex flex-wrap items-center gap-4 rounded-xl border bg-white p-4 sm:p-5"
                >
                  <div
                    className="flex h-14 w-14 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-slate-50"
                    style={{ color: p.accent }}
                  >
                    {p.picture ? (
                      <img
                        src={p.picture}
                        alt=""
                        className="h-full w-full object-cover"
                      />
                    ) : (
                      <PortalIcon name={p.icon} />
                    )}
                  </div>
                  <div className="min-w-0 flex-1 basis-40">
                    <h2 className="text-lg font-semibold break-words text-[#0b3d60]">
                      {p.title[lang]}
                    </h2>
                    <p className="mt-1 text-sm break-words text-slate-600">
                      {p.tagline[lang]}
                    </p>
                    <p className="mt-2 text-xs text-slate-500" dir="ltr">
                      /portal/{p.id}
                    </p>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <Button
                      variant="outline"
                      onClick={() => start(p)}
                      disabled={saving}
                    >
                      <Pencil size={15} />
                      {text("Edit", "تعديل")}
                    </Button>
                    <Button variant="outline" asChild>
                      <Link href={`/portal/${p.id}`} target="_blank">
                        {text("View", "عرض")}
                      </Link>
                    </Button>
                    <Button
                      variant="ghost"
                      onClick={() => void archive(p)}
                      disabled={saving}
                    >
                      <Trash2 size={15} />
                      {text("Remove", "حذف")}
                    </Button>
                  </div>
                </article>
              ))}
          </div>
          {!portals.some((p) => !p.isDeleted) && (
            <div className="rounded-xl border border-dashed p-8 text-center">
              <h2 className="font-semibold">
                {text("No active portals", "لا توجد بوابات نشطة")}
              </h2>
              <p className="mt-2 text-sm text-slate-600">
                {text(
                  "Add your first portal or restore a removed one.",
                  "أضف بوابة جديدة أو استعد إحدى البوابات المحذوفة."
                )}
              </p>
            </div>
          )}
          {portals.some((p) => p.isDeleted) && (
            <section className="border-t pt-5">
              <Button
                variant="outline"
                onClick={() => setShowRemoved(!showRemoved)}
              >
                {text("Removed portals", "البوابات المحذوفة")} (
                {portals.filter((p) => p.isDeleted).length})
              </Button>
              {showRemoved && (
                <div className="mt-4 space-y-3">
                  {portals
                    .filter((p) => p.isDeleted)
                    .map((p) => (
                      <article
                        key={p.id}
                        className="flex flex-wrap items-center justify-between gap-3 rounded-lg border bg-slate-50 p-4"
                      >
                        <h3 className="min-w-0 font-medium break-words">
                          {p.title[lang]}
                        </h3>
                        <Button
                          variant="outline"
                          onClick={() => void archive(p)}
                          disabled={saving}
                        >
                          <RotateCcw size={15} />
                          {text("Restore", "استعادة")}
                        </Button>
                      </article>
                    ))}
                </div>
              )}
            </section>
          )}
        </>
      )}
    </div>
  )
}

