interface AllocationRow {
  id?: string
  expert_id: string
  /** Matches `role_name_en` of a roles_management record */
  role: string
}

function ExpertCombobox({
  value,
  onChange,
  experts,
  placeholder,
}: {
  value: string
  onChange: (value: string) => void
  experts: Array<{ id: string; name: string; email: string }>
  placeholder?: string
}) {
  const [open, setOpen] = useState(false)
  const { lang } = useLang()
  const selectedExpert = experts.find((e) => e.id === value)

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className="w-full justify-between"
        >
          {selectedExpert
            ? selectedExpert.name
            : placeholder ||
              (lang === "ar" ? "اختر خبير..." : "Select expert...")}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[300px] p-0">
        <Command>
          <CommandInput
            placeholder={
              lang === "ar" ? "البحث عن الخبراء..." : "Search experts..."
            }
          />
          <CommandList>
            <CommandEmpty>
              {lang === "ar" ? "لم يتم العثور على خبراء." : "No experts found."}
            </CommandEmpty>
            <CommandGroup>
              {experts.map((expert) => (
                <CommandItem
                  key={expert.id}
                  value={expert.id + " " + expert.name + " " + expert.email}
                  onSelect={() => {
                    onChange(expert.id === value ? "" : expert.id)
                    setOpen(false)
                  }}
                >
                  <Check
                    className={cn(
                      "mr-2 h-4 w-4",
                      value === expert.id ? "opacity-100" : "opacity-0"
                    )}
                  />
                  <div className="flex flex-col">
                    <span>{expert.name}</span>
                    <span className="text-xs text-muted-foreground">
                      {expert.email}
                    </span>
                  </div>
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

export default function AllocationsPage() {
  const router = useRouter()
  const { lang } = useLang()
  const { users, isLoading: isUsersLoading } = useUsers()
  const {
    allocations,
    loadError: allocationsError,
    isLoading: isAllocationsLoading,
    refresh: refreshAllocations,
  } = useAllocations()

  const [expertProfiles, setExpertProfiles] = useState<ExpertProfile[]>([])
  const [countryFilter, setCountryFilter] = useState("")
  const [cityFilter, setCityFilter] = useState("")
  const [specialtyFilter, setSpecialtyFilter] = useState("")
  useEffect(() => {
    boundedFullList(pb.collection("expert_profiles"))
      .then((data) => setExpertProfiles(data as unknown as ExpertProfile[]))
      .catch((error) => toast.error(getErrorMessage(error)))
  }, [])
  const [selectedCase, setSelectedCase] = useState<string>("")
  const [rows, setRows] = useState<AllocationRow[]>([])
  const [originalRows, setOriginalRows] = useState<AllocationRow[]>([])
  const [isSaving, setIsSaving] = useState(false)

  const {
    roles: roleMgmtRoles,
    isLoading: isRolesLoading,
    updateRoleToolTypes,
    updateRole,
    addRole,
    removeRole,
  } = useRolesManagement()
  const {
    toolTypes: allToolTypes,
    isLoading: isToolTypesLoading,
    fetchToolTypes,
  } = useToolTypes()

  const [roleToolTypesMap, setRoleToolTypesMap] = useState<
    Record<string, string[]>
  >({})
  const [isSavingAll, setIsSavingAll] = useState(false)
  const [roleDialogOpen, setRoleDialogOpen] = useState(false)
  const [newRoleNameEn, setNewRoleNameEn] = useState("")
  const [newRoleNameAr, setNewRoleNameAr] = useState("")
  const [isAddingRole, setIsAddingRole] = useState(false)

  const [editRoleDialogOpen, setEditRoleDialogOpen] = useState(false)
  const [editingRole, setEditingRole] = useState<RolesManagement | null>(null)
  const [editRoleNameEn, setEditRoleNameEn] = useState("")
  const [editRoleNameAr, setEditRoleNameAr] = useState("")
  const [isUpdatingRole, setIsUpdatingRole] = useState(false)

  useEffect(() => {
    fetchToolTypes()
  }, [fetchToolTypes])

  useEffect(() => {
    if (
      roleMgmtRoles.length > 0 &&
      Object.keys(roleToolTypesMap).length === 0
    ) {
      const map: Record<string, string[]> = {}
      roleMgmtRoles.forEach((r) => {
        map[r.id] = [...(r.tool_types || [])]
      })
      // Synchronize the editable permission map after roles load from the server.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setRoleToolTypesMap(map)
    }
  }, [roleMgmtRoles, roleToolTypesMap])

  const handleRoleToolTypesChange = (roleId: string, toolTypeIds: string[]) => {
    setRoleToolTypesMap((prev) => ({ ...prev, [roleId]: toolTypeIds }))
  }

  /** Localized role label, falling back to the other language when empty. */
  const getRoleLabel = (role: RolesManagement) =>
    (lang === "ar" ? role.role_name_ar : role.role_name_en) ||
    (lang === "ar" ? role.role_name_en : role.role_name_ar) ||
    ""

  const handleSaveAllRoles = async () => {
    const changed = roleMgmtRoles.filter(
      (role) =>
        JSON.stringify(roleToolTypesMap[role.id]?.sort()) !==
        JSON.stringify([...(role.tool_types || [])].sort())
    )
    if (changed.length === 0) return

    setIsSavingAll(true)
    try {
      await Promise.all(
        changed.map((role) =>
          updateRoleToolTypes(role.id, roleToolTypesMap[role.id])
        )
      )
    } catch (error) {
      console.error("Failed to save role tool types:", error)
      toast.error(
        lang === "ar"
          ? "فشل الحفظ. يرجى المحاولة مرة أخرى."
          : "Failed to save. Please try again.",
        { description: getErrorMessage(error) }
      )
    } finally {
      setIsSavingAll(false)
    }
  }

  const handleAddRole = async () => {
    const roleNameEn = newRoleNameEn.trim()
    const roleNameAr = newRoleNameAr.trim()
    if (!roleNameEn || !roleNameAr) return

    setIsAddingRole(true)
    try {
      const created = await addRole(roleNameEn, roleNameAr)
      setRoleToolTypesMap((prev) => ({
        ...prev,
        [created.id]: created.tool_types || [],
      }))
      setRoleDialogOpen(false)
      setNewRoleNameEn("")
      setNewRoleNameAr("")
    } catch (error) {
      console.error("Failed to add role:", error)
      toast.error(
        lang === "ar"
          ? "فشل إضافة الدور. يرجى المحاولة مرة أخرى."
          : "Failed to add role. Please try again.",
        { description: getErrorMessage(error) }
      )
    } finally {
      setIsAddingRole(false)
    }
  }

  const openEditRole = (role: RolesManagement) => {
    setEditingRole(role)
    setEditRoleNameEn(role.role_name_en)
    setEditRoleNameAr(role.role_name_ar)
    setEditRoleDialogOpen(true)
  }

  const handleUpdateRole = async () => {
    if (!editingRole) return
    const roleNameEn = editRoleNameEn.trim()
    const roleNameAr = editRoleNameAr.trim()
    if (!roleNameEn || !roleNameAr) return

    setIsUpdatingRole(true)
    try {
      await updateRole(
        editingRole.id,
        roleNameEn,
        roleNameAr,
        editingRole.role_name_en
      )
      await refreshAllocations()
      toast.success(
        lang === "ar" ? "تم حفظ الإسنادات" : "Case allocations saved"
      )
      setEditRoleDialogOpen(false)
      setEditingRole(null)
    } catch (error) {
      console.error("Failed to update role:", error)
      toast.error(
        lang === "ar"
          ? "فشل تحديث الدور. يرجى المحاولة مرة أخرى."
          : "Failed to update role. Please try again.",
        { description: getErrorMessage(error) }
      )
    } finally {
      setIsUpdatingRole(false)
    }
  }

  const handleDeleteRole = async (roleId: string, roleName: string) => {
    if (
      !window.confirm(
        lang === "ar"
          ? `هل تريد حذف الدور "${roleName}"؟`
          : `Delete role "${roleName}"?`
      )
    ) {
      return
    }

    try {
      await removeRole(roleId)
      setRoleToolTypesMap((prev) => {
        const next = { ...prev }
        delete next[roleId]
        return next
      })
    } catch (error) {
      console.error("Failed to delete role:", error)
      toast.error(
        lang === "ar"
          ? "فشل حذف الدور. يرجى المحاولة مرة أخرى."
          : "Failed to delete role. Please try again.",
        { description: getErrorMessage(error) }
      )
    }
  }

  // Filter only expert users
  const experts = useMemo(
    () =>
      users
        .filter((u) => u.role === "expert" && u.is_active)
        .filter((u) => {
          const profile = expertProfiles.find((p) => p.user === u.id)
          return (
            (!countryFilter ||
              ((profile?.country_of_residence || "") + " " + countryLabel(profile?.country_of_residence || "", lang))
                .toLowerCase()
                .includes(countryFilter.toLowerCase())) &&
            (!cityFilter ||
              (profile?.city || "")
                .toLowerCase()
                .includes(cityFilter.toLowerCase())) &&
            (!specialtyFilter ||
              toStringList(profile?.specialization_type).some((v) =>
                (v + " " + specializationLabel(v, lang))
                  .toLowerCase()
                  .includes(specialtyFilter.toLowerCase())
              ))
          )
        })
        .map((u) => ({ id: u.id, name: u.name, email: u.email })),
    [users, expertProfiles, countryFilter, cityFilter, specialtyFilter, lang]
  )

  // Load existing allocations when case is selected
  const loadAllocationsForCase = useCallback(
    (caseId: string) => {
      const caseAllocations = allocations.filter((a) => a.case_id === caseId)
      const loadedRows: AllocationRow[] = caseAllocations.map((a) => ({
        id: a.id,
        expert_id: a.expert_id,
        role: a.role,
      }))
      setRows(loadedRows)
      setOriginalRows(loadedRows)
    },
    [allocations]
  )

  useEffect(() => {
    if (isSaving) return
    if (selectedCase) {
      // Synchronize rows when the selected case or its saved allocations change.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      loadAllocationsForCase(selectedCase)
    } else {
      setRows([])
      setOriginalRows([])
    }
  }, [selectedCase, loadAllocationsForCase, isSaving])

  const addRow = () => {
    setRows((prev) => [
      ...prev,
      { expert_id: "", role: roleMgmtRoles[0]?.role_name_en ?? "" },
    ])
  }

  const removeRow = (index: number) => {
    setRows((prev) => prev.filter((_, i) => i !== index))
  }

  const updateRow = (index: number, updates: Partial<AllocationRow>) => {
    setRows((prev) =>
      prev.map((row, i) => (i === index ? { ...row, ...updates } : row))
    )
  }

  const handleSave = async () => {
    if (!selectedCase) return

    // Validate rows
    const invalidRows = rows.filter((r) => !r.expert_id || !r.role)
    if (invalidRows.length > 0) {
      toast.error(
        lang === "ar"
          ? "يرجى اختيار خبير ودور لكل صف."
          : "Please select an expert and role for each row."
      )
      return
    }

    setIsSaving(true)
    try {
      await pb.send(`/api/dsc/cases/${selectedCase}/allocations`, {
        method: "POST",
        body: { rows },
      })
      await refreshAllocations()
    } catch (error) {
      console.error("Failed to save allocations:", error)
      toast.error(
        lang === "ar"
          ? "فشل حفظ التخصيصات. يرجى المحاولة مرة أخرى."
          : "Failed to save allocations. Please try again.",
        { description: getErrorMessage(error) }
      )
    } finally {
      setIsSaving(false)
    }
  }

  const isLoading =
    isUsersLoading ||
    isAllocationsLoading ||
    isRolesLoading ||
    isToolTypesLoading

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Button variant="ghost" size="icon" onClick={() => router.back()}>
              <ArrowLeft className="h-5 w-5" />
            </Button>
            <div>
              <h1 className="text-2xl font-bold text-primary">
                {lang === "ar" ? "نموذج التخصيص" : "Allocation Form"}
              </h1>
              <p className="text-muted-foreground">
                {lang === "ar"
                  ? "تخصيص القضايا للخبراء"
                  : "Allocate cases to experts"}
              </p>
            </div>
          </div>
        </div>
        <SkeletonTable rows={4} />
      </div>
    )
  }

  const hasChanges = JSON.stringify(rows) !== JSON.stringify(originalRows)

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-primary">
              {lang === "ar" ? "نموذج التخصيص" : "Allocation Form"}
            </h1>
            <p className="text-muted-foreground">
              {lang === "ar"
                ? "تخصيص القضايا للخبراء"
                : "Allocate cases to experts"}
            </p>
          </div>
        </div>
      </div>

      {allocationsError && (
        <DataError message={allocationsError} onRetry={refreshAllocations} />
      )}
      <Tabs defaultValue="allocations">
        <TabsList>
          <TabsTrigger value="allocations">
            {lang === "ar" ? "التخصيصات" : "Allocations"}
          </TabsTrigger>
          <TabsTrigger value="roles">
            {lang === "ar" ? "الأدوار" : "Roles"}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="allocations" className="space-y-6">
          <div className="grid gap-3 sm:grid-cols-3">
            <Input
              aria-label={
                lang === "ar" ? "بلد الإقامة" : "Country of Residence"
              }
              placeholder={
                lang === "ar"
                  ? "البحث حسب بلد الإقامة"
                  : "Filter by country of residence"
              }
              value={countryFilter}
              onChange={(e) => setCountryFilter(e.target.value)}
            />
            <Input
              aria-label={lang === "ar" ? "مدينة الإقامة" : "City of Residence"}
              placeholder={
                lang === "ar"
                  ? "البحث حسب مدينة الإقامة"
                  : "Filter by city of residence"
              }
              value={cityFilter}
              onChange={(e) => setCityFilter(e.target.value)}
            />
            <Input
              aria-label={lang === "ar" ? "التخصص" : "Specialization"}
              placeholder={
                lang === "ar" ? "البحث حسب التخصص" : "Filter by specialization"
              }
              value={specialtyFilter}
              onChange={(e) => setSpecialtyFilter(e.target.value)}
            />
          </div>
          <div className="flex justify-end">
            <Button
              onClick={handleSave}
              disabled={!selectedCase || isSaving || !hasChanges}
            >
              <Save className="me-2 h-4 w-4" />
              {isSaving
                ? lang === "ar"
                  ? "جاري الحفظ..."
                  : "Saving..."
                : lang === "ar"
                  ? "حفظ التخصيصات"
                  : "Save Allocations"}
            </Button>
          </div>

          {/* Case Selector */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "اختيار القضية" : "Select Case"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "اختر القضية التي تريد تخصيص الخبراء لها"
                  : "Choose the case you want to allocate experts to"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="max-w-md">
                <CaseSearchCombobox
                  value={selectedCase}
                  onChange={setSelectedCase}
                  placeholder={
                    lang === "ar" ? "اختر قضية..." : "Select a case..."
                  }
                />
              </div>
            </CardContent>
          </Card>

          {/* Allocations Grid */}
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle>
                    {lang === "ar" ? "الخبراء المخصصون" : "Assigned Experts"}
                  </CardTitle>
                  <CardDescription>
                    {rows.length}{" "}
                    {lang === "ar" ? "خبير(ين) مخصص" : "expert(s) assigned"}
                  </CardDescription>
                </div>
                {selectedCase && (
                  <Button
                    variant="outline"
                    onClick={addRow}
                    disabled={isSaving}
                  >
                    <Plus className="me-2 h-4 w-4" />
                    {lang === "ar" ? "إضافة خبير" : "Add Expert"}
                  </Button>
                )}
              </div>
            </CardHeader>
            <CardContent>
              {!selectedCase ? (
                <div className="py-12 text-center">
                  <Users className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar" ? "لم يتم اختيار قضية" : "No case selected"}
                  </h3>
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? "يرجى اختيار قضية أولاً لعرض الخبراء المخصصين"
                      : "Please select a case first to view assigned experts"}
                  </p>
                </div>
              ) : rows.length === 0 ? (
                <div className="py-12 text-center">
                  <UserCheck className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar"
                      ? "لم يتم تخصيص خبراء"
                      : "No experts assigned"}
                  </h3>
                  <p className="mb-4 text-muted-foreground">
                    {lang === "ar"
                      ? "لم يتم تخصيص خبراء لهذه القضية بعد"
                      : "No experts have been assigned to this case yet"}
                  </p>
                  <Button onClick={addRow}>
                    <Plus className="me-2 h-4 w-4" />
                    {lang === "ar" ? "إضافة خبير" : "Add Expert"}
                  </Button>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-[300px]">
                        {lang === "ar" ? "الخبير" : "Expert"}
                      </TableHead>
                      <TableHead className="w-[250px]">
                        {lang === "ar" ? "الدور" : "Role"}
                      </TableHead>
                      <TableHead className="text-right">
                        {lang === "ar" ? "إجراءات" : "Actions"}
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {rows.map((row, index) => (
                      <TableRow key={`${row.id || "new"}-${index}`}>
                        <TableCell>
                          <ExpertCombobox
                            value={row.expert_id}
                            onChange={(value) =>
                              updateRow(index, { expert_id: value })
                            }
                            experts={experts}
                            placeholder={
                              lang === "ar"
                                ? "اختر خبير..."
                                : "Select expert..."
                            }
                          />
                        </TableCell>
                        <TableCell>
                          <Select
                            value={row.role}
                            onValueChange={(value) =>
                              updateRow(index, { role: value })
                            }
                          >
                            <SelectTrigger>
                              <SelectValue
                                placeholder={
                                  lang === "ar"
                                    ? "اختر دوراً..."
                                    : "Select role..."
                                }
                              />
                            </SelectTrigger>
                            <SelectContent>
                              {roleMgmtRoles.map((role) => (
                                <SelectItem
                                  key={role.id}
                                  value={role.role_name_en}
                                >
                                  {getRoleLabel(role)}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </TableCell>
                        <TableCell className="text-right">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => removeRow(index)}
                            disabled={isSaving}
                          >
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="roles">
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle>
                    {lang === "ar"
                      ? "إدارة أدوار الخبراء"
                      : "Expert Role Management"}
                  </CardTitle>
                  <CardDescription>
                    {lang === "ar"
                      ? "تحديد أنواع الأدوات المتاحة لكل دور"
                      : "Assign which tool types each role can access"}
                  </CardDescription>
                </div>
                <Button onClick={() => setRoleDialogOpen(true)}>
                  <Plus className="me-2 h-4 w-4" />
                  {lang === "ar" ? "إضافة دور" : "Add Role"}
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              {isRolesLoading || isToolTypesLoading ? (
                <SkeletonTable rows={4} />
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>{lang === "ar" ? "الدور" : "Role"}</TableHead>
                      <TableHead>
                        {lang === "ar"
                          ? "أنواع الأدوات المخصصة"
                          : "Assigned Tool Types"}
                      </TableHead>
                      <TableHead className="text-right">
                        {lang === "ar" ? "إجراءات" : "Actions"}
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {roleMgmtRoles.map((role) => {
                      const hasAssignments = allocations.some(
                        (a) => a.role === role.role_name_en
                      )
                      return (
                        <TableRow key={role.id}>
                          <TableCell className="font-medium">
                            {getRoleLabel(role)}
                          </TableCell>
                          <TableCell>
                            <ToolTypeMultiSelect
                              value={
                                roleToolTypesMap[role.id] ||
                                role.tool_types ||
                                []
                              }
                              onChange={(toolTypeIds) =>
                                handleRoleToolTypesChange(role.id, toolTypeIds)
                              }
                              toolTypes={allToolTypes}
                              lang={lang}
                              placeholder={
                                lang === "ar"
                                  ? "اختر أنواع الأدوات..."
                                  : "Select tool types..."
                              }
                              emptyMessage={
                                lang === "ar"
                                  ? "لا توجد أنواع أدوات"
                                  : "No tool types found"
                              }
                            />
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="flex items-center justify-end gap-1">
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => openEditRole(role)}
                                title={
                                  lang === "ar"
                                    ? "تعديل اسم الدور"
                                    : "Edit role name"
                                }
                              >
                                <Pencil className="h-4 w-4" />
                              </Button>
                              <Button
                                variant="ghost"
                                size="sm"
                                disabled={hasAssignments || isSavingAll}
                                onClick={() =>
                                  handleDeleteRole(role.id, getRoleLabel(role))
                                }
                                title={
                                  hasAssignments
                                    ? lang === "ar"
                                      ? "لا يمكن حذف دور معين لخبراء"
                                      : "Cannot delete a role assigned to experts"
                                    : undefined
                                }
                              >
                                <Trash2 className="h-4 w-4 text-destructive" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      )
                    })}
                  </TableBody>
                </Table>
              )}
              <div className="mt-4 flex justify-end">
                <Button onClick={handleSaveAllRoles} disabled={isSavingAll}>
                  {isSavingAll
                    ? lang === "ar"
                      ? "جاري الحفظ..."
                      : "Saving..."
                    : lang === "ar"
                      ? "حفظ الكل"
                      : "Save"}
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      <Dialog open={roleDialogOpen} onOpenChange={setRoleDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>
              {lang === "ar" ? "إضافة دور جديد" : "Add New Role"}
            </DialogTitle>
            <DialogDescription>
              {lang === "ar"
                ? "أدخل اسمي الدور الجديد (بالإنجليزية والعربية) ثم قم بتحديد أنواع الأدوات المتاحة له"
                : "Enter the new role name in English and Arabic, then assign the tool types it can access"}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <label className="mb-1.5 block text-sm font-medium">
                  {lang === "ar" ? "اسم الدور (إنجليزي)" : "Role Name (EN)"}
                </label>
                <Input
                  value={newRoleNameEn}
                  onChange={(e) => setNewRoleNameEn(e.target.value)}
                  placeholder="e.g., Lawyer"
                />
              </div>
              <div>
                <label className="mb-1.5 block text-sm font-medium">
                  {lang === "ar" ? "اسم الدور (عربي)" : "Role Name (AR)"}
                </label>
                <Input
                  dir="rtl"
                  value={newRoleNameAr}
                  onChange={(e) => setNewRoleNameAr(e.target.value)}
                  placeholder="مثال: محامٍ"
                />
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setRoleDialogOpen(false)
                setNewRoleNameEn("")
                setNewRoleNameAr("")
              }}
              disabled={isAddingRole}
            >
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleAddRole}
              disabled={
                isAddingRole || !newRoleNameEn.trim() || !newRoleNameAr.trim()
              }
            >
              {isAddingRole
                ? lang === "ar"
                  ? "جارٍ الإضافة..."
                  : "Adding..."
                : lang === "ar"
                  ? "إضافة"
                  : "Add"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog
        open={editRoleDialogOpen}
        onOpenChange={(open) => {
          setEditRoleDialogOpen(open)
          if (!open) setEditingRole(null)
        }}
      >
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>
              {lang === "ar" ? "تعديل الدور" : "Edit Role"}
            </DialogTitle>
            <DialogDescription>
              {lang === "ar"
                ? "تعديل اسم الدور (بالإنجليزية والعربية). تحديث الاسم الإنجليزي سيحدّثه أيضاً في توزيعات الخبراء."
                : "Edit the role name in English and Arabic. Changing the English name also updates it in existing expert allocations."}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <label className="mb-1.5 block text-sm font-medium">
                  {lang === "ar" ? "اسم الدور (إنجليزي)" : "Role Name (EN)"}
                </label>
                <Input
                  value={editRoleNameEn}
                  onChange={(e) => setEditRoleNameEn(e.target.value)}
                  placeholder="e.g., Lawyer"
                />
              </div>
              <div>
                <label className="mb-1.5 block text-sm font-medium">
                  {lang === "ar" ? "اسم الدور (عربي)" : "Role Name (AR)"}
                </label>
                <Input
                  dir="rtl"
                  value={editRoleNameAr}
                  onChange={(e) => setEditRoleNameAr(e.target.value)}
                  placeholder="مثال: محامٍ"
                />
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setEditRoleDialogOpen(false)
                setEditingRole(null)
              }}
              disabled={isUpdatingRole}
            >
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleUpdateRole}
              disabled={
                isUpdatingRole ||
                !editRoleNameEn.trim() ||
                !editRoleNameAr.trim()
              }
            >
              {isUpdatingRole
                ? lang === "ar"
                  ? "جارٍ الحفظ..."
                  : "Saving..."
                : lang === "ar"
                  ? "حفظ"
                  : "Save"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

"use client"

import { use, useEffect } from "react"
import { useRouter } from "next/navigation"
import { DataError } from "@/components/ui/data-error"
import { ExpertTaskAssignment } from "@/components/dashboard/ExpertTaskAssignment"
import { PageLoader } from "@/components/ui/page-loader"
import { useAuth } from "@/hooks/useAuth"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useLang } from "@/lib/lang-context"
import { formatDate } from "@/lib/format-date"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { SurveyPreview } from "@/components/tool-renderers/SurveyPreview"
import { MultipleChoicePreview } from "@/components/tool-renderers/MultipleChoicePreview"
import { MediaPreview } from "@/components/tool-renderers/MediaPreview"
import { PlanPreview } from "@/components/tool-renderers/PlanPreview"
import { ReportPreview } from "@/components/tool-renderers/ReportPreview"
import { ArrowLeft, FileText, Download, Edit } from "lucide-react"
import Link from "next/link"
import type {
  SurveyConfig,
  MultipleChoiceConfig,
  MediaConfig,
  PlanConfig,
  ReportConfig,
} from "@/types/tool"
import type { AssignmentStatus } from "@/types/assignment"
import { getToolTypeLabel, getToolTypeMeta } from "@/lib/tool-types"

const statusColors: Record<AssignmentStatus, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  assigned: "bg-blue-100 text-blue-800",
  in_progress: "bg-purple-100 text-purple-800",
  completed: "bg-green-100 text-green-800",
}

const statusLabels: Record<AssignmentStatus, { en: string; ar: string }> = {
  pending: { en: "Pending", ar: "قيد الانتظار" },
  assigned: { en: "Assigned", ar: "تم التعيين" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
}

interface AssignmentDetailPageProps {
  params: Promise<{ id: string }>
}

export default function AssignmentDetailPage({
  params,
}: AssignmentDetailPageProps) {
  const { id: assignmentId } = use(params)
  const router = useRouter()
  const { lang } = useLang()
  const {
    assignments,
    updateAssignment,
    loadError: assignmentsError,
    refresh: refreshAssignments,
    isLoading: assignmentsLoading,
  } = useAssignments()
  const { currentUser } = useAuth()
  const { profiles, isLoading: profilesLoading } = useProfiles()
  const {
    toolTypes,
    isLoading: toolTypesLoading,
    fetchToolTypes,
    getToolTypeById,
  } = useToolTypes()

  const assignment = assignments.find((a) => a.id === assignmentId)
  const profile = assignment
    ? profiles.find((p) => p.id === assignment.case)
    : undefined

  useEffect(() => {
    fetchToolTypes()
  }, [fetchToolTypes])

  const toolType = assignment?.type
    ? getToolTypeById(assignment.type)
    : undefined
  const typeName = toolType?.key || "Unknown"

  const config = assignment?.config

  const isLoading = assignmentsLoading || toolTypesLoading || profilesLoading

  if (isLoading) {
    return <PageLoader />
  }

  if (assignmentsError)
    return <DataError message={assignmentsError} onRetry={refreshAssignments} />

  if (!assignment) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "لم يتم العثور على المهمة" : "Assignment not found"}
        </h2>
        <Button onClick={() => router.push("/dashboard/admin/assignments")}>
          {lang === "ar" ? "العودة إلى المهام" : "Back to Assignments"}
        </Button>
      </div>
    )
  }

  if (!profile) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "لم يتم العثور على الحالة" : "Case not found"}
        </h2>
        <p className="mb-4 text-muted-foreground">
          {lang === "ar"
            ? "تم حذف الحالة المرتبطة بهذه المهمة."
            : "The linked case for this assignment was deleted."}
        </p>
        <Button onClick={() => router.push("/dashboard/admin/assignments")}>
          {lang === "ar" ? "العودة إلى المهام" : "Back to Assignments"}
        </Button>
      </div>
    )
  }

  const Icon = getToolTypeMeta(typeName)?.icon || FileText
  const canEdit = typeName === "plan" || typeName === "report"

  const renderToolPreview = () => {
    if (!config) return null

    switch (typeName) {
      case "survey":
        return <SurveyPreview config={config as SurveyConfig} />
      case "multiple_answer":
        return <MultipleChoicePreview config={config as MultipleChoiceConfig} />
      case "media_question":
        return <MediaPreview config={config as MediaConfig} />
      case "attachment_request":
        return (
          <div className="rounded-lg border bg-muted/30 p-6">
            <h3 className="text-lg font-semibold">
              {(config as { title?: { en: string; ar: string } }).title?.[
                lang
              ] || (lang === "ar" ? "طلب إرفاق ملف" : "Request for Attachment")}
            </h3>
            <p className="mt-2 text-muted-foreground">
              {lang === "ar"
                ? "سيظهر طلب رفع الملف هنا"
                : "File upload request will appear here"}
            </p>
          </div>
        )
      case "plan":
        return <PlanPreview config={config as PlanConfig} />
      case "report":
        return <ReportPreview config={config as ReportConfig} />
      default:
        return (
          <div className="rounded-lg border bg-muted/30 p-6">
            <p className="text-muted-foreground">
              {lang === "ar"
                ? "المعاينة غير متاحة لهذا النوع من الأدوات"
                : "Preview not available for this tool type"}
            </p>
          </div>
        )
    }
  }

  const renderSurveyResponse = (surveyConfig: SurveyConfig) => {
    const responses = assignment.responses || {}
    const questions = surveyConfig.questions || []

    if (questions.length === 0) {
      return (
        <p className="text-muted-foreground">
          {lang === "ar"
            ? "لا توجد أسئلة في هذا الاستبيان."
            : "No questions in this survey."}
        </p>
      )
    }

    return (
      <div className="space-y-4">
        {questions.map((question, idx) => {
          const answer = responses[question.id]
          return (
            <div key={question.id} className="rounded-lg border p-4">
              <div className="flex items-start gap-2">
                <Badge variant="outline" className="mt-0.5">
                  {idx + 1}
                </Badge>
                <div className="flex-1">
                  <p className="font-medium">{question.text}</p>
                  <div className="mt-2 rounded bg-muted/30 p-3">
                    {answer !== undefined &&
                    answer !== null &&
                    answer !== "" ? (
                      <p className="text-sm">{String(answer)}</p>
                    ) : (
                      <p className="text-sm text-muted-foreground">
                        {lang === "ar" ? "لا إجابة" : "No answer"}
                      </p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )
        })}
      </div>
    )
  }

  const renderMultipleChoiceResponse = (mcConfig: MultipleChoiceConfig) => {
    const responses = assignment.responses || {}
    const questions = mcConfig.questions || []

    if (questions.length === 0) {
      return (
        <p className="text-muted-foreground">
          {lang === "ar"
            ? "لا توجد أسئلة في هذا الاستبيان."
            : "No questions in this survey."}
        </p>
      )
    }

    return (
      <div className="space-y-4">
        {questions.map((question, idx) => {
          const answer = responses[question.id]
          return (
            <div key={question.id} className="rounded-lg border p-4">
              <div className="flex items-start gap-2">
                <Badge variant="outline" className="mt-0.5">
                  {idx + 1}
                </Badge>
                <div className="flex-1">
                  <p className="font-medium">{question.text}</p>
                  <div className="mt-2 space-y-1">
                    {answer !== undefined && answer !== null ? (
                      Array.isArray(answer) ? (
                        answer.map((val, i) => (
                          <p key={i} className="text-sm">
                            {question.options?.find((o) => o.value === val)
                              ?.label || val}
                          </p>
                        ))
                      ) : (
                        <p className="text-sm">
                          {question.options?.find((o) => o.value === answer)
                            ?.label || String(answer)}
                        </p>
                      )
                    ) : (
                      <p className="text-sm text-muted-foreground">
                        {lang === "ar" ? "لا إجابة" : "No answer"}
                      </p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )
        })}
      </div>
    )
  }

  const renderMediaResponse = (mediaConfig: MediaConfig) => {
    const responses = assignment.responses || {}
    const items = mediaConfig.items || []

    if (items.length === 0) {
      return (
        <p className="text-muted-foreground">
          {lang === "ar"
            ? "لا توجد عناصر وسائط في هذه المهمة."
            : "No media items in this assignment."}
        </p>
      )
    }

    return (
      <div className="space-y-4">
        {items.map((item, idx) => {
          const answer = responses[item.id]
          return (
            <div key={item.id} className="rounded-lg border p-4">
              <div className="flex items-start gap-2">
                <Badge variant="outline" className="mt-0.5">
                  {idx + 1}
                </Badge>
                <div className="flex-1">
                  <p className="font-medium">{item.question}</p>
                  <div className="mt-2 rounded bg-muted/30 p-3">
                    {item.responseType === "text" ? (
                      answer ? (
                        <p className="text-sm">{String(answer)}</p>
                      ) : (
                        <p className="text-sm text-muted-foreground">
                          {lang === "ar" ? "لا إجابة" : "No answer"}
                        </p>
                      )
                    ) : (
                      <p className="text-sm text-muted-foreground">
                        {answer
                          ? `${lang === "ar" ? "ملف" : "File"}: ${answer}`
                          : lang === "ar"
                            ? "لم يتم رفع ملف"
                            : "No file uploaded"}
                      </p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )
        })}
      </div>
    )
  }

  const renderAttachmentResponse = () => {
    const responses = assignment.responses || {}
    const responseKeys = Object.keys(responses)

    if (
      responseKeys.length === 0 &&
      (!assignment.media || assignment.media.length === 0)
    ) {
      return (
        <p className="text-muted-foreground">
          {lang === "ar"
            ? "لم يتم رفع أي ملفات بعد."
            : "No files uploaded yet."}
        </p>
      )
    }

    return (
      <div className="space-y-4">
        {responseKeys.length > 0 && (
          <div className="rounded-lg border p-4">
            <h4 className="mb-2 font-medium">
              {lang === "ar" ? "استجابات الملفات" : "File Responses"}
            </h4>
            <ul className="space-y-2">
              {responseKeys.map((key) => (
                <li key={key} className="flex items-center gap-2">
                  <span className="text-sm">{key}:</span>
                  <span className="text-sm text-muted-foreground">
                    {String(responses[key])}
                  </span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {assignment.media && assignment.media.length > 0 && (
          <div className="rounded-lg border p-4">
            <h4 className="mb-2 font-medium">
              {lang === "ar" ? "الملفات المرفوعة" : "Uploaded Files"}
            </h4>
            <ul className="space-y-2">
              {assignment.media.map((file, idx) => (
                <li key={idx}>
                  <a
                    href={file}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-primary hover:underline"
                  >
                    <Download className="h-4 w-4" />
                    {lang === "ar" ? "ملف" : "File"} {idx + 1}
                  </a>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    )
  }

  const renderGenericResponse = () => {
    return (
      <div className="space-y-4">
        {assignment.media && assignment.media.length > 0 && (
          <div className="rounded-lg border p-4">
            <h4 className="mb-2 font-medium">
              {lang === "ar" ? "الملفات المرفوعة" : "Uploaded Files"}
            </h4>
            <ul className="space-y-2">
              {assignment.media.map((file, idx) => (
                <li key={idx}>
                  <a
                    href={file}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-primary hover:underline"
                  >
                    <Download className="h-4 w-4" />
                    {lang === "ar" ? "ملف" : "File"} {idx + 1}
                  </a>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    )
  }

  const renderResponseView = () => {
    if (assignment.status !== "completed") {
      return (
        <div className="flex flex-col items-center justify-center py-12">
          <FileText className="mb-4 h-12 w-12 text-muted-foreground" />
          <h3 className="mb-2 text-lg font-medium">
            {lang === "ar" ? "لم تكتمل بعد" : "Not Yet Completed"}
          </h3>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? "هذه المهمة لا تزال قيد الانتظار. ستظهر الردود هنا بمجرد اكتمال الحالة لها."
              : "This assignment is still pending. Responses will appear here once the case completes it."}
          </p>
        </div>
      )
    }

    if (
      !assignment.responses ||
      Object.keys(assignment.responses).length === 0
    ) {
      if (!assignment.media || assignment.media.length === 0) {
        return (
          <div className="flex flex-col items-center justify-center py-12">
            <FileText className="mb-4 h-12 w-12 text-muted-foreground" />
            <h3 className="mb-2 text-lg font-medium">
              {lang === "ar" ? "لا توجد ردود" : "No Responses"}
            </h3>
            <p className="text-muted-foreground">
              {lang === "ar"
                ? "لا توجد بيانات استجابة متاحة لهذه المهمة."
                : "No response data available for this assignment."}
            </p>
          </div>
        )
      }
    }

    switch (typeName) {
      case "survey":
        return (
          <SurveyPreview
            config={config as SurveyConfig}
            responses={assignment.responses}
            readOnly
          />
        )
      case "multiple_answer":
        return (
          <MultipleChoicePreview
            config={config as MultipleChoiceConfig}
            responses={assignment.responses}
            readOnly
          />
        )
      case "media_question":
        return (
          <MediaPreview
            config={config as MediaConfig}
            responses={assignment.responses as Record<string, string>}
            readOnly
          />
        )
      case "attachment_request":
        return renderAttachmentResponse()
      default:
        return renderGenericResponse()
    }
  }

  return (
    <div className="space-y-6">
      {(currentUser?.role === "admin" ||
        currentUser?.role === "super_admin") && (
        <ExpertTaskAssignment
          key={assignment.id}
          task={assignment}
          onSaved={updateAssignment}
        />
      )}
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => router.push("/dashboard/admin/assignments")}
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-primary">
              {lang === "ar" ? "تفاصيل المهمة" : "Assignment Details"}
            </h1>
            <p className="text-muted-foreground">
              {lang === "ar"
                ? "عرض المهمة والردود"
                : "View assignment and responses"}
            </p>
          </div>
        </div>
        {canEdit && (
          <Link
            href={`/dashboard/admin/tools/${typeName}/edit/${assignmentId}`}
          >
            <Button variant="outline">
              <Edit className="mr-2 h-4 w-4" />
              {lang === "ar" ? "تعديل" : "Edit"}
            </Button>
          </Link>
        )}
      </div>

      {/* Assignment Info Card */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Icon className="h-5 w-5 text-primary" />
            <CardTitle className="text-lg">
              {lang === "ar" ? "معلومات المهمة" : "Assignment Information"}
            </CardTitle>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            <div>
              <span className="text-sm font-medium text-muted-foreground">
                {lang === "ar" ? "الحالة" : "Case"}
              </span>
              <p>
                <Link
                  href={`/dashboard/cases/${profile.id}`}
                  className="hover:text-primary hover:underline"
                >
                  {profile.name}
                </Link>
              </p>
            </div>
            <div>
              <span className="text-sm font-medium text-muted-foreground">
                {lang === "ar" ? "المهمة" : "Assignment"}
              </span>
              <p>
                {assignment.name_en ||
                  (lang === "ar" ? "مهمة بدون اسم" : "Unnamed Assignment")}
              </p>
            </div>
            <div>
              <span className="text-sm font-medium text-muted-foreground">
                {lang === "ar" ? "النوع" : "Type"}
              </span>
              <div>
                <Badge variant="outline">
                  {getToolTypeLabel(toolType, lang)}
                </Badge>
              </div>
            </div>
            <div>
              <span className="text-sm font-medium text-muted-foreground">
                {lang === "ar" ? "الحالة" : "Status"}
              </span>
              <div>
                <Badge className={statusColors[assignment.status]}>
                  {statusLabels[assignment.status][lang]}
                </Badge>
              </div>
            </div>
          </div>
          <div className="mt-4 border-t pt-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <span className="text-sm font-medium text-muted-foreground">
                  {lang === "ar" ? "تاريخ التعيين" : "Assigned Date"}
                </span>
                <p>
                  {formatDate(assignment.assigned_at || assignment.created)}
                </p>
              </div>
              <div>
                <span className="text-sm font-medium text-muted-foreground">
                  {lang === "ar" ? "مرئي للمستخدم" : "Visible to User"}
                </span>
                <p>
                  {assignment.is_visible_to_user
                    ? lang === "ar"
                      ? "نعم"
                      : "Yes"
                    : lang === "ar"
                      ? "لا"
                      : "No"}
                </p>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Tabs */}
      <Tabs defaultValue="view" className="space-y-4">
        <TabsList>
          <TabsTrigger value="view">
            {lang === "ar" ? "عرض" : "View"}
          </TabsTrigger>
          <TabsTrigger value="response">
            {lang === "ar" ? "الرد" : "Response"}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="view">
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "معاينة الأداة" : "Tool Preview"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "كيف تظهر الأداة للحالة (باستخدام لقطة الإعدادات)"
                  : "How the tool appears to the case (using config snapshot)"}
              </CardDescription>
            </CardHeader>
            <CardContent>{renderToolPreview()}</CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="response">
          <Card>
            <CardHeader>
              <CardTitle>{lang === "ar" ? "الرد" : "Response"}</CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "الردود المقدمة والملفات المرفوعة"
                  : "Submitted responses and uploaded files"}
              </CardDescription>
            </CardHeader>
            <CardContent>{renderResponseView()}</CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  )
}

"use client"

import { useState, useEffect, useRef } from "react"
import { useRouter } from "next/navigation"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useLang } from "@/lib/lang-context"
import { useAuth } from "@/hooks/useAuth"
import { formatDate } from "@/lib/format-date"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Input } from "@/components/ui/input"
import { PageLoader } from "@/components/ui/page-loader"
import { SkeletonTable } from "@/components/ui/skeleton"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  ArrowLeft,
  Trash2,
  FileText,
  ClipboardList,
  Search,
  Eye,
} from "lucide-react"
import { Switch } from "@/components/ui/switch"
import { SmartLink } from "@/components/smart-link"
import { CaseSearchCombobox } from "@/components/case-search-combobox"
import type { AssignmentStatus } from "@/types/assignment"
import { getToolTypeLabel, getToolTypeMeta } from "@/lib/tool-types"

const statusColors: Record<AssignmentStatus, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  assigned: "bg-blue-100 text-blue-800",
  in_progress: "bg-purple-100 text-purple-800",
  completed: "bg-green-100 text-green-800",
}

const statusLabels: Record<AssignmentStatus, { en: string; ar: string }> = {
  pending: { en: "Pending", ar: "قيد الانتظار" },
  assigned: { en: "Assigned", ar: "تم التعيين" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
}

export default function AssignmentsPage() {
  const router = useRouter()
  const { lang } = useLang()
  const {
    assignments,
    deleteAssignment,
    updateAssignment,
    isLoading: isAssignmentsLoading,
  } = useAssignments()
  const { profiles, isLoading: isProfilesLoading } = useProfiles()
  const {
    toolTypes,
    isLoading: isToolTypesLoading,
    fetchToolTypes,
    getToolTypeById,
  } = useToolTypes()
  const hasFetched = useRef(false)

  const { currentUser } = useAuth()
  const isExpert = currentUser?.role === "expert"

  const [searchQuery, setSearchQuery] = useState("")
  const [filterCase, setFilterCase] = useState("")
  const [filterType, setFilterType] = useState<string>("all")
  const [filterStatus, setFilterStatus] = useState<AssignmentStatus | "all">(
    "all"
  )

  useEffect(() => {
    if (hasFetched.current) return
    hasFetched.current = true
    fetchToolTypes()
  }, [fetchToolTypes])

  const getCaseName = (caseId: string) => {
    const profile = profiles.find((p) => p.id === caseId)
    return profile?.name || (lang === "ar" ? "حالة غير معروفة" : "Unknown Case")
  }

  const getToolTypeName = (typeId: string) => {
    const toolType = getToolTypeById(typeId)
    return toolType?.key || "Unknown"
  }

  const expertCaseIds = isExpert ? profiles.map((p) => p.id) : []

  const filteredAssignments = assignments.filter((assignment) => {
    // Filter by expert's assigned cases
    if (isExpert && !expertCaseIds.includes(assignment.case)) return false

    // Filter by search query
    if (searchQuery) {
      const caseName = getCaseName(assignment.case).toLowerCase()
      const assignmentName = (assignment.name_en || "").toLowerCase()
      if (
        !caseName.includes(searchQuery.toLowerCase()) &&
        !assignmentName.includes(searchQuery.toLowerCase())
      ) {
        return false
      }
    }

    // Filter by case
    if (filterCase && assignment.case !== filterCase) {
      return false
    }

    // Filter by type
    if (filterType !== "all" && assignment.type !== filterType) {
      return false
    }

    // Filter by status
    if (filterStatus !== "all" && assignment.status !== filterStatus) {
      return false
    }

    return true
  })

  // Get unique tool types for filter dropdown
  const uniqueToolTypes = Array.from(
    new Set(assignments.map((a) => a.type))
  ).filter(Boolean)

  const isLoading =
    isAssignmentsLoading || isProfilesLoading || isToolTypesLoading

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Button variant="ghost" size="icon" onClick={() => router.back()}>
              <ArrowLeft className="h-5 w-5" />
            </Button>
            <div>
              <h1 className="text-2xl font-bold text-primary">
                {lang === "ar" ? "التعيينات" : "Assignments"}
              </h1>
              <p className="text-muted-foreground">
                {lang === "ar"
                  ? "إدارة تعيينات الأدوات للحالات"
                  : "Manage tool assignments to cases"}
              </p>
            </div>
          </div>
        </div>
        <SkeletonTable rows={6} />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-primary">
              {lang === "ar" ? "التعيينات" : "Assignments"}
            </h1>
            <p className="text-muted-foreground">
              {lang === "ar"
                ? "إدارة تعيينات الأدوات للحالات"
                : "Manage tool assignments to cases"}
            </p>
          </div>
        </div>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-col gap-4 sm:flex-row">
            <div className="relative flex-1">
              <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder={
                  lang === "ar"
                    ? "ابحث باسم التعيين..."
                    : "Search by assignment name..."
                }
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
            <CaseSearchCombobox
              value={filterCase}
              onChange={setFilterCase}
              placeholder={lang === "ar" ? "تصفية حسب الحالة..." : "Filter by case..."}
              className="w-[250px]"
            />
            <Select value={filterType} onValueChange={setFilterType}>
              <SelectTrigger className="w-[200px]">
                <SelectValue
                  placeholder={lang === "ar" ? "تصفية حسب النوع" : "Filter by Type"}
                />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">
                  {lang === "ar" ? "جميع الأنواع" : "All Types"}
                </SelectItem>
                {uniqueToolTypes.map((typeId) => {
                  const toolType = getToolTypeById(typeId)
                  return (
                    <SelectItem key={typeId} value={typeId}>
                      {getToolTypeLabel(toolType, lang)}
                    </SelectItem>
                  )
                })}
              </SelectContent>
            </Select>
            <Select
              value={filterStatus}
              onValueChange={(v) =>
                setFilterStatus(v as AssignmentStatus | "all")
              }
            >
              <SelectTrigger className="w-[180px]">
                <SelectValue
                  placeholder={lang === "ar" ? "تصفية حسب الحالة" : "Filter by Status"}
                />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">
                  {lang === "ar" ? "جميع الحالات" : "All Status"}
                </SelectItem>
                <SelectItem value="pending">
                  {lang === "ar" ? "قيد الانتظار" : "Pending"}
                </SelectItem>
                <SelectItem value="assigned">
                  {lang === "ar" ? "تم التعيين" : "Assigned"}
                </SelectItem>
                <SelectItem value="in_progress">
                  {lang === "ar" ? "قيد التنفيذ" : "In Progress"}
                </SelectItem>
                <SelectItem value="completed">
                  {lang === "ar" ? "مكتمل" : "Completed"}
                </SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {/* Assignments Table */}
      <Card>
        <CardHeader>
          <CardTitle>
            {lang === "ar" ? "جميع التعيينات" : "All Assignments"}
          </CardTitle>
          <CardDescription>
            {lang === "ar"
              ? `تم العثور على ${filteredAssignments.length} تعيين`
              : `${filteredAssignments.length} assignment(s) found`}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {filteredAssignments.length === 0 ? (
            <div className="py-12 text-center">
              <ClipboardList className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
              <h3 className="mb-2 text-lg font-medium">
                {lang === "ar" ? "لا توجد تعيينات" : "No assignments found"}
              </h3>
              <p className="text-muted-foreground">
                {assignments.length === 0
                  ? lang === "ar"
                    ? "لم يتم تعيين أي أدوات للحالات بعد. انتقل إلى إحدى الأدوات واستخدم التعيين السريع."
                    : "No tools have been assigned to cases yet. Go to a tool and use Quick Assign."
                  : lang === "ar"
                    ? "لا توجد تعيينات تطابق عوامل التصفية."
                    : "No assignments match your filters."}
              </p>
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>{lang === "ar" ? "الحالة" : "Case"}</TableHead>
                  <TableHead>
                    {lang === "ar" ? "التعيين" : "Assignment"}
                  </TableHead>
                  <TableHead>{lang === "ar" ? "النوع" : "Type"}</TableHead>
                  <TableHead>{lang === "ar" ? "الحالة" : "Status"}</TableHead>
                  <TableHead>
                    {lang === "ar" ? "مرئي للمستخدم" : "Visible to User"}
                  </TableHead>
                  <TableHead>
                    {lang === "ar" ? "تاريخ التعيين" : "Assigned Date"}
                  </TableHead>
                  <TableHead className="text-right">
                    {lang === "ar" ? "الإجراءات" : "Actions"}
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredAssignments.map((assignment) => {
                  const toolType = getToolTypeById(assignment.type)
                  const typeName = getToolTypeName(assignment.type)
                  const Icon = getToolTypeMeta(typeName)?.icon || FileText
                  return (
                    <TableRow key={assignment.id}>
                      <TableCell className="font-medium">
                        <SmartLink
                          href={`/dashboard/cases/${assignment.case}`}
                          className="hover:text-primary hover:underline"
                        >
                          {getCaseName(assignment.case)}
                        </SmartLink>
                      </TableCell>
                      <TableCell>
                        <SmartLink
                          href={`/dashboard/admin/assignments/${assignment.id}`}
                          className="hover:text-primary hover:underline"
                        >
                          {assignment.name_en ||
                            (lang === "ar"
                              ? "تعيين بدون اسم"
                              : "Unnamed Assignment")}
                        </SmartLink>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-1 text-muted-foreground">
                          <Icon className="h-3 w-3" />
                          <span className="text-xs">
                            {getToolTypeLabel(toolType, lang)}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <Badge className={statusColors[assignment.status]}>
                          {statusLabels[assignment.status][lang]}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <Switch
                          checked={assignment.is_visible_to_user}
                          onCheckedChange={(checked) =>
                            updateAssignment(assignment.id, {
                              is_visible_to_user: checked,
                            })
                          }
                        />
                      </TableCell>
                      <TableCell>
                        {formatDate(assignment.assigned_at || assignment.created)}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-2">
                          <SmartLink
                            href={`/dashboard/admin/assignments/${assignment.id}`}
                          >
                            <Button variant="ghost" size="sm">
                              <Eye className="h-4 w-4" />
                            </Button>
                          </SmartLink>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => deleteAssignment(assignment.id)}
                          >
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

