import { Badge } from "@/components/ui/badge"
import { Input } from "@/components/ui/input"
import { EmailInput } from "@/components/ui/email-input"
import { PasswordInput } from "@/components/ui/password-input"
import { Label } from "@/components/ui/label"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  ArrowLeft,
  User,
  Calendar,
  Mail,
  Phone,
  ClipboardList,
  History,
  Eye,
  Pencil,
  Trash2,
  FileText,
  Plus,
  Link2,
  UserX,
  UserPlus,
  KeyRound,
  Wallet,
  Save,
  CheckCircle2,
  XCircle,
  Loader2,
} from "lucide-react"
import Link from "next/link"
import type { AssignmentStatus } from "@/types/assignment"
import type { Tool, ToolType, ToolConfig } from "@/types/tool"
import {
  getToolTypeLabel,
  getToolTypeMeta,
  toolTypeOrder,
} from "@/lib/tool-types"
import {
  getAllowedToolTypesForCase,
  getAllowedToolTypesForRole,
  caseExpertsCollection,
} from "@/lib/pb-collections"

const statusColors: Record<AssignmentStatus, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  assigned: "bg-blue-100 text-blue-800",
  in_progress: "bg-purple-100 text-purple-800",
  completed: "bg-green-100 text-green-800",
}

const statusLabels: Record<AssignmentStatus, { en: string; ar: string }> = {
  pending: { en: "Pending", ar: "قيد الانتظار" },
  assigned: { en: "Assigned", ar: "تم التعيين" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
}

export default function AdminCaseDetailPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id: caseId } = use(params)
  const router = useRouter()
  const { lang } = useLang()
  const { currentUser, isAdmin } = useAuth()
  const { getProfileById, updateProfile, setPaymentAmount, approveCase, rejectPayment } =
    useProfiles()
  const { assignments, assignTool, deleteAssignment } = useAssignments()
  const { tools } = useTools()
  const { toolTypes, fetchToolTypes } = useToolTypes()
  const { users } = useUsers()
  const { bankDetails } = usePaymentSettings()

  const [showAssignModal, setShowAssignModal] = useState(false)
  const [selectedToolId, setSelectedToolId] = useState<string>("")
  const [isAssigning, setIsAssigning] = useState(false)
  const [assignTab, setAssignTab] = useState<"templates" | "caseSpecific">(
    "templates"
  )
  const [toolTypeFilter, setToolTypeFilter] = useState<string>("all")
  const [confirmToolType, setConfirmToolType] = useState<string | null>(null)
  const [allowedToolTypeIds, setAllowedToolTypeIds] = useState<string[]>([])
  const [linkMode, setLinkMode] = useState<"existing" | "new">("existing")
  const [linkUserId, setLinkUserId] = useState("")
  const [newUser, setNewUser] = useState({ name: "", email: "", password: "" })
  const [isLinking, setIsLinking] = useState(false)
  const [linkError, setLinkError] = useState<string | null>(null)
  const [linkSuccess, setLinkSuccess] = useState<string | null>(null)
  const [amountInput, setAmountInput] = useState<string | null>(null)
  const [rejectInput, setRejectInput] = useState("")
  const [isPaymentBusy, setIsPaymentBusy] = useState(false)
  const [paymentError, setPaymentError] = useState<string | null>(null)
  const [paymentSuccess, setPaymentSuccess] = useState<string | null>(null)

  const profile = getProfileById(caseId)
  const caseAssignments = assignments.filter((a) => a.case === caseId)
  const isExpert = currentUser?.role === "expert"
  const owner = profile ? users.find((u) => u.id === profile.user) : undefined
  const linkableUsers = users.filter(
    (u) => !["admin", "super_admin", "expert"].includes(u.role)
  )

  const handleLinkExisting = async () => {
    if (!linkUserId) return
    setIsLinking(true)
    setLinkError(null)
    setLinkSuccess(null)
    try {
      await updateProfile(caseId, { user: linkUserId })
      setLinkSuccess(
        lang === "ar" ? "تم ربط الحالة بالمستخدم." : "Case linked to user."
      )
      setLinkUserId("")
    } catch (error) {
      setLinkError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل ربط المستخدم." : "Failed to link user.")
      )
    } finally {
      setIsLinking(false)
    }
  }

  const handleCreateAndLink = async () => {
    if (!newUser.name || !newUser.email || !newUser.password) {
      setLinkError(
        lang === "ar"
          ? "يرجى ملء جميع الحقول المطلوبة."
          : "Please fill in all required fields."
      )
      return
    }
    if (!isValidEmail(newUser.email)) {
      setLinkError(t(EMAIL_INVALID_MESSAGE, lang))
      return
    }
    if (newUser.password.length < 8) {
      setLinkError(
        lang === "ar"
          ? "يجب أن تكون كلمة المرور 8 أحرف على الأقل."
          : "Password must be at least 8 characters."
      )
      return
    }
    setIsLinking(true)
    setLinkError(null)
    setLinkSuccess(null)
    try {
      const cleanName = newUser.name.trim()
      const cleanEmail = normalizeEmail(newUser.email)

      const record = await pb.collection("users").create({
        email: cleanEmail,
        password: newUser.password,
        passwordConfirm: newUser.password,
        name: cleanName,
        role: "individual",
        contact_number: "",
        is_active: true,
        emailVisibility: true,
      })
      await updateProfile(caseId, { user: record.id })
      try {
        await sendCredentialsEmail({
          email: cleanEmail,
          name: cleanName,
          password: newUser.password,
          caseName: profile?.name,
          caseUrl: `${window.location.origin}/dashboard/cases/${caseId}`,
        })
        setLinkSuccess(
          lang === "ar"
            ? "تم إنشاء المستخدم وربط الحالة وإرسال بيانات الدخول بالبريد."
            : "User created, case linked, and credentials emailed."
        )
      } catch (err) {
        setLinkSuccess(
          lang === "ar"
            ? "تم إنشاء المستخدم وربط الحالة، لكن تعذر إرسال البريد الإلكتروني."
            : "User created and case linked, but the credentials email could not be sent."
        )
        toast.error(getErrorMessage(err))
      }
      setNewUser({ name: "", email: "", password: "" })
    } catch (error) {
      setLinkError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل إنشاء المستخدم." : "Failed to create user.")
      )
    } finally {
      setIsLinking(false)
    }
  }

  const handleUnlink = async () => {
    setIsLinking(true)
    setLinkError(null)
    setLinkSuccess(null)
    try {
      await updateProfile(caseId, { user: "" })
      setLinkSuccess(lang === "ar" ? "تم فك ربط الحالة." : "Case unlinked.")
    } catch (error) {
      setLinkError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل فك ربط المستخدم." : "Failed to unlink user.")
      )
    } finally {
      setIsLinking(false)
    }
  }

  const handleSetAmount = async () => {
    if (amountInput === null || !amountInput.trim() || !Number.isFinite(Number(amountInput)) || Number(amountInput) <= 0) return
    setIsPaymentBusy(true)
    setPaymentError(null)
    setPaymentSuccess(null)
    try {
      if (profile?.status === "pending") await setPaymentAmount(caseId, Number(amountInput))
      else await updateProfile(caseId, { payment_amount: Number(amountInput) })
      setPaymentSuccess(
        lang === "ar"
          ? "تم حفظ رسوم الحالة."
          : "Case fee saved."
      )
      setAmountInput(null)
    } catch (error) {
      setPaymentError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل تحديد المبلغ." : "Failed to set amount.")
      )
    } finally {
      setIsPaymentBusy(false)
    }
  }

  const handleApprove = async () => {
    setIsPaymentBusy(true)
    setPaymentError(null)
    setPaymentSuccess(null)
    try {
      await approveCase(caseId)
      setPaymentSuccess(
        lang === "ar"
          ? "تم تفعيل الحالة. يمكن للمستخدم الوصول إليها الآن."
          : "Case enabled. The user can now access it."
      )
    } catch (error) {
      setPaymentError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل تفعيل الحالة." : "Failed to enable case.")
      )
    } finally {
      setIsPaymentBusy(false)
    }
  }

  const handleReject = async () => {
    setIsPaymentBusy(true)
    setPaymentError(null)
    setPaymentSuccess(null)
    try {
      await rejectPayment(caseId, rejectInput)
      setPaymentSuccess(
        lang === "ar"
          ? "تم رفض الإيصال. سيعاد طلب الدفع للمستخدم."
          : "Receipt rejected. The user will be asked to pay again."
      )
      setRejectInput("")
    } catch (error) {
      setPaymentError(
        getErrorMessage(error) ||
          (lang === "ar" ? "فشل رفض الدفع." : "Failed to reject payment.")
      )
    } finally {
      setIsPaymentBusy(false)
    }
  }

  useEffect(() => {
    fetchToolTypes()
  }, [fetchToolTypes])

  useEffect(() => {
    async function fetchAllowedToolTypes() {
      if (!caseId || !currentUser) return
      try {
        if (isExpert) {
          const caseExpert =
            await caseExpertsCollection.getByCaseAndExpert(
              caseId,
              currentUser.id
            )
          const allowed = caseExpert?.role
            ? await getAllowedToolTypesForRole(caseExpert.role)
            : []
          setAllowedToolTypeIds(allowed)
        } else {
          const allowed = await getAllowedToolTypesForCase(caseId)
          setAllowedToolTypeIds(allowed)
        }
      } catch (error) {
        console.error("Failed to fetch allowed tool types for case:", error)
        toast.error(getErrorMessage(error))
      }
    }
    fetchAllowedToolTypes()
  }, [caseId, currentUser, isExpert])

  const handleAssignTool = async () => {
    if (!selectedToolId) return
    setIsAssigning(true)
    try {
      const tool = tools.find((t) => t.id === selectedToolId)
      if (tool) {
        const toolTypeObj = toolTypes.find((tt) => tt.id === tool.type)
        await assignTool({
          case: caseId,
          type: toolTypeObj?.id || tool.type,
          name_en: tool.name.en,
          name_ar: tool.name.ar,
          is_not_template: false,
          config: tool.config as ToolConfig,
          status: "pending",
          is_visible_to_user: true,
        })
        setShowAssignModal(false)
        setSelectedToolId("")
      }
    } finally {
      setIsAssigning(false)
    }
  }

  if (!profile) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الحالة غير موجودة" : "Case not found"}
        </h2>
        <Link href="/dashboard/admin/cases">
          <Button>
            {lang === "ar" ? "العودة إلى الحالات" : "Back to Cases"}
          </Button>
        </Link>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-primary">{profile.name}</h1>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? `أنشئت في ${formatDate(profile.created)}`
              : `Created ${formatDate(profile.created)}`}
          </p>
        </div>
      </div>

      <Tabs defaultValue="overview" className="space-y-4">
        <TabsList>
          <TabsTrigger value="overview">
            {lang === "ar" ? "نظرة عامة" : "Overview"}
          </TabsTrigger>
          <TabsTrigger value="assigned">
            {lang === "ar" ? "المكلف بها" : "Assigned"}
            <Badge variant="secondary" className="ms-2">
              {caseAssignments.length}
            </Badge>
          </TabsTrigger>
          <TabsTrigger value="case-file">
            {lang === "ar" ? "ملف الحالة" : "Case File"}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="overview">
          {isAdmin && (
            <Card className="mb-6">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Link2 className="h-5 w-5" />
                  {lang === "ar" ? "المستخدم المرتبط" : "Linked User"}
                </CardTitle>
                <CardDescription>
                  {lang === "ar"
                    ? "اربط هذه الحالة بمستخدم ليتمكن من الوصول إليها"
                    : "Link this case to a user so they can access it"}
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                {linkError && (
                  <div className="rounded-lg bg-red-50 p-3 text-sm text-red-700">
                    {linkError}
                  </div>
                )}
                {linkSuccess && (
                  <div className="rounded-lg bg-green-50 p-3 text-sm text-green-700">
                    {linkSuccess}
                  </div>
                )}

                {owner ? (
                  <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border p-4">
                    <div className="flex items-center gap-3">
                      <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10">
                        <User className="h-5 w-5 text-primary" />
                      </div>
                      <div>
                        <p className="font-medium">{owner.name}</p>
                        <p className="text-sm text-muted-foreground">
                          {owner.email}
                        </p>
                      </div>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={handleUnlink}
                      disabled={isLinking}
                    >
                      <UserX className="me-1 h-4 w-4" />
                      {lang === "ar" ? "فك الربط" : "Unlink"}
                    </Button>
                  </div>
                ) : (
                  <div className="rounded-lg border p-4">
                    <p className="mb-3 text-sm text-muted-foreground">
                      {lang === "ar"
                        ? "لا يوجد مستخدم مرتبط بهذه الحالة بعد."
                        : "No user linked to this case yet."}
                    </p>
                    <div className="grid grid-cols-2 gap-3">
                      <Button
                        type="button"
                        variant={
                          linkMode === "existing" ? "default" : "outline"
                        }
                        size="sm"
                        onClick={() => setLinkMode("existing")}
                      >
                        <Link2 className="me-1 h-4 w-4" />
                        {lang === "ar" ? "مستخدم مسجل" : "Existing User"}
                      </Button>
                      <Button
                        type="button"
                        variant={linkMode === "new" ? "default" : "outline"}
                        size="sm"
                        onClick={() => setLinkMode("new")}
                      >
                        <UserPlus className="me-1 h-4 w-4" />
                        {lang === "ar" ? "مستخدم جديد" : "New User"}
                      </Button>
                    </div>

                    {linkMode === "existing" ? (
                      <div className="mt-4 flex flex-col gap-3 sm:flex-row sm:items-end">
                        <div className="flex-1 space-y-2">
                          <Label>
                            {lang === "ar" ? "المستخدم" : "User"}
                          </Label>
                          <Select
                            value={linkUserId}
                            onValueChange={setLinkUserId}
                          >
                            <SelectTrigger>
                              <SelectValue
                                placeholder={
                                  lang === "ar"
                                    ? "اختر مستخدمًا"
                                    : "Select a user"
                                }
                              />
                            </SelectTrigger>
                            <SelectContent>
                              {linkableUsers.length === 0 ? (
                                <SelectItem value="__none__" disabled>
                                  {lang === "ar"
                                    ? "لا يوجد مستخدمون"
                                    : "No users available"}
                                </SelectItem>
                              ) : (
                                linkableUsers.map((user) => (
                                  <SelectItem key={user.id} value={user.id}>
                                    {user.name} ({user.email})
                                  </SelectItem>
                                ))
                              )}
                            </SelectContent>
                          </Select>
                        </div>
                        <Button
                          onClick={handleLinkExisting}
                          disabled={isLinking || !linkUserId}
                        >
                          <Link2 className="me-1 h-4 w-4" />
                          {lang === "ar" ? "ربط" : "Link"}
                        </Button>
                      </div>
                    ) : (
                      <div className="mt-4 space-y-3 rounded-lg bg-muted/50 p-4">
                        <div className="space-y-2">
                          <Label htmlFor="link_user_name">
                            {lang === "ar" ? "الاسم الكامل" : "Full Name"}
                          </Label>
                          <Input
                            id="link_user_name"
                            value={newUser.name}
                            onChange={(e) =>
                              setNewUser({ ...newUser, name: e.target.value })
                            }
                            placeholder={
                              lang === "ar"
                                ? "أدخل الاسم الكامل"
                                : "Enter full name"
                            }
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="link_user_email">
                            {lang === "ar" ? "البريد الإلكتروني" : "Email"}
                          </Label>
                          <EmailInput
                            id="link_user_email"
                            value={newUser.email}
                            onChange={(value) =>
                              setNewUser({ ...newUser, email: value })
                            }
                            placeholder={
                              lang === "ar"
                                ? "أدخل عنوان البريد الإلكتروني"
                                : "Enter email address"
                            }
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="link_user_password">
                            {lang === "ar" ? "كلمة المرور" : "Password"}
                          </Label>
                          <PasswordInput
                            id="link_user_password"
                            value={newUser.password}
                            onChange={(e) =>
                              setNewUser({
                                ...newUser,
                                password: e.target.value,
                              })
                            }
                            placeholder={
                              lang === "ar"
                                ? "8 أحرف على الأقل"
                                : "Min 8 characters"
                            }
                          />
                        </div>
                        <Button
                          onClick={handleCreateAndLink}
                          disabled={isLinking}
                          className="w-full"
                        >
                          <KeyRound className="me-1 h-4 w-4" />
                          {isLinking
                            ? lang === "ar"
                              ? "جارٍ الإنشاء..."
                              : "Creating..."
                            : lang === "ar"
                              ? "إنشاء مستخدم وربط"
                              : "Create User & Link"}
                        </Button>
                        <p className="text-xs text-muted-foreground">
                          {lang === "ar"
                            ? "سيتم إنشاء حساب جديد وسيتم إرسال بيانات الدخول إلى بريد المستخدم."
                            : "A new account will be created and the login credentials will be emailed to the user."}
                        </p>
                      </div>
                    )}
                  </div>
                )}
              </CardContent>
            </Card>
          )}
          {isAdmin && (
            <Card className="mb-6">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Wallet className="h-5 w-5" />
                  {lang === "ar" ? "الدفع" : "Payment"}
                  <CaseStatusBadge status={profile.status} />
                </CardTitle>
                <CardDescription>
                  {lang === "ar"
                    ? "حدد المبلغ، راجع الإيصال، وفعّل الحالة"
                    : "Set the amount, review the receipt, and enable the case"}
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                {paymentError && (
                  <div className="rounded-lg bg-red-50 p-3 text-sm text-red-700">
                    {paymentError}
                  </div>
                )}
                {paymentSuccess && (
                  <div className="rounded-lg bg-green-50 p-3 text-sm text-green-700">
                    {paymentSuccess}
                  </div>
                )}

                <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border p-4">
                  <div className="flex flex-col gap-3 sm:flex-row sm:items-end">
                    <div className="flex-1 space-y-2">
                      <Label htmlFor="payment_amount">
                        {lang === "ar"
                          ? "رسوم الحالة"
                          : "Case fee"}
                      </Label>
                      <Input
                        id="payment_amount"
                        type="number"
                        min="0"
                        step="0.01"
                        aria-describedby="case-fee-help"
                        value={amountInput ?? String(profile.payment_amount ?? 0)}
                        onChange={(e) => setAmountInput(e.target.value)}
                        placeholder={
                          lang === "ar" ? "أدخل المبلغ" : "Enter amount"
                        }
                      />
                      <p id="case-fee-help" className="text-xs text-muted-foreground">
                        {lang === "ar"
                          ? `الرسوم الحالية بعملة ${bankDetails.currency}. عدّل القيمة ثم اضغط حفظ الرسوم.`
                          : `Current fee in ${bankDetails.currency}. Edit the value, then click Save fee.`}
                      </p>
                    </div>
                    <Button
                      onClick={handleSetAmount}
                      disabled={
                        isPaymentBusy || amountInput === null || !amountInput.trim() || !Number.isFinite(Number(amountInput)) || Number(amountInput) <= 0 || Number(amountInput) === Number(profile.payment_amount ?? 0)
                      }
                    >
                      {isPaymentBusy ? (
                        <Loader2 className="me-1 h-4 w-4 animate-spin" />
                      ) : (
                        <Save className="me-1 h-4 w-4" />
                      )}
                      {lang === "ar"
                        ? "حفظ الرسوم"
                        : "Save fee"}
                    </Button>
                  </div>
                  {profile.payment_slip && (
                    <a
                      href={pb.files.getURL(
                        { collectionId: "cases", id: caseId },
                        profile.payment_slip
                      )}
                      target="_blank"
                      rel="noreferrer"
                    >
                      <Button variant="outline" size="sm">
                        <FileText className="me-1 h-4 w-4" />
                        {lang === "ar" ? "عرض الإيصال" : "View Receipt"}
                      </Button>
                    </a>
                  )}
                </div>


                {profile.status === "awaiting_payment" && (
                  <p className="text-sm text-muted-foreground">
                    {lang === "ar"
                      ? "بانتظار رفع إيصال التحويل من المستخدم."
                      : "Waiting for the user to upload the transfer receipt."}
                    {profile.payment_reject_reason && (
                      <span className="ms-1 text-red-600">
                        {lang === "ar" ? `الرفض: ${profile.payment_reject_reason}` : `Rejected: ${profile.payment_reject_reason}`}
                      </span>
                    )}
                  </p>
                )}

                {profile.status === "under_review" && (
                  <div className="flex flex-col gap-3 sm:flex-row sm:items-end">
                    <div className="flex-1 space-y-2">
                      <Label htmlFor="reject_reason">
                        {lang === "ar"
                          ? "سبب الرفض (اختياري)"
                          : "Reject reason (optional)"}
                      </Label>
                      <Input
                        id="reject_reason"
                        value={rejectInput}
                        onChange={(e) => setRejectInput(e.target.value)}
                        placeholder={
                          lang === "ar"
                            ? "مثال: المبلغ غير مطابق"
                            : "e.g. Amount does not match"
                        }
                      />
                    </div>
                    <Button
                      onClick={handleApprove}
                      disabled={isPaymentBusy}
                    >
                      {isPaymentBusy ? (
                        <Loader2 className="me-1 h-4 w-4 animate-spin" />
                      ) : (
                        <CheckCircle2 className="me-1 h-4 w-4" />
                      )}
                      {lang === "ar" ? "تفعيل الحالة" : "Enable Case"}
                    </Button>
                    <Button
                      variant="destructive"
                      onClick={handleReject}
                      disabled={isPaymentBusy}
                    >
                      <XCircle className="me-1 h-4 w-4" />
                      {lang === "ar" ? "رفض" : "Reject"}
                    </Button>
                  </div>
                )}

                {profile.status === "active" && (
                  <p className="text-sm text-green-700">
                    {lang === "ar"
                      ? "الحالة مفعلة والدفع مكتمل."
                      : "Case is active and paid."}
                  </p>
                )}
              </CardContent>
            </Card>
          )}
          <div className="grid gap-6 lg:grid-cols-2">
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <User className="h-5 w-5" />
                  {lang === "ar" ? "معلومات الطفل" : "Child Information"}
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ الميلاد" : "Date of Birth"}
                  </span>
                  <span className="font-medium">
                    {profile.date_of_birth ? formatDate(profile.date_of_birth) : "—"}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">
                    {lang === "ar" ? "الجنس" : "Gender"}
                  </span>
                  <span className="font-medium capitalize">
                    {profile.gender === "male"
                      ? lang === "ar"
                        ? "ذكر"
                        : "male"
                      : profile.gender === "female"
                        ? lang === "ar"
                          ? "أنثى"
                          : "female"
                        : profile.gender}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">
                    {lang === "ar" ? "الصف الدراسي" : "Grade"}
                  </span>
                  <span className="font-medium capitalize">
                    {profile.grade}
                  </span>
                </div>
                {profile.notes && (
                  <div className="pt-2">
                    <span className="mb-2 block text-muted-foreground">
                      {lang === "ar" ? "ملاحظات" : "Notes"}
                    </span>
                    <p className="text-sm text-muted-foreground">{profile.notes}</p>
                  </div>
                )}
              </CardContent>
            </Card>

            {profile.notes && (
              <Card className="lg:col-span-2">
                <CardHeader>
                  <CardTitle>{lang === "ar" ? "ملاحظات" : "Notes"}</CardTitle>
                </CardHeader>
                <CardContent>
                  <p className="text-muted-foreground">{profile.notes}</p>
                </CardContent>
              </Card>
            )}
          </div>
        </TabsContent>

        <TabsContent value="assigned">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle className="flex items-center gap-2">
                  <ClipboardList className="h-5 w-5" />
                  {lang === "ar" ? "المهام المكلف بها" : "Assigned Tasks"}
                </CardTitle>
                <CardDescription>
                  {lang === "ar"
                    ? "إدارة التعيينات لهذه الحالة"
                    : "Manage assignments for this case"}
                </CardDescription>
              </div>
              <Button onClick={() => setShowAssignModal(true)}>
                <Plus className="me-2 h-4 w-4" />
                {lang === "ar" ? "تعيين أداة" : "Assign Tool"}
              </Button>
            </CardHeader>
            <CardContent>
              {caseAssignments.length === 0 ? (
                <div className="py-8 text-center">
                  <ClipboardList className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar" ? "لا توجد مهام مكلف بها" : "No tasks assigned"}
                  </h3>
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? 'انقر على "تعيين أداة" لإضافة مهمة لهذه الحالة'
                      : 'Click "Assign Tool" to add a task for this case'}
                  </p>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>
                        {lang === "ar" ? "التعيين" : "Assignment"}
                      </TableHead>
                      <TableHead>{lang === "ar" ? "النوع" : "Type"}</TableHead>
                      <TableHead>{lang === "ar" ? "الحالة" : "Status"}</TableHead>
                      <TableHead>
                        {lang === "ar" ? "مرئي للمستخدم" : "Visible to User"}
                      </TableHead>
                      <TableHead>
                        {lang === "ar" ? "تاريخ التعيين" : "Assigned Date"}
                      </TableHead>
                      <TableHead className="text-right">
                        {lang === "ar" ? "الإجراءات" : "Actions"}
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {caseAssignments.map((assignment) => {
                      const toolType = toolTypes.find(
                        (t) => t.id === assignment.type
                      )
                      const toolTypeName = toolType?.key || "custom"
                      const Icon =
                        getToolTypeMeta(toolTypeName)?.icon || FileText

                      return (
                        <TableRow key={assignment.id}>
                          <TableCell className="font-medium">
                            {assignment.name_en ||
                              (lang === "ar" ? "تعيين بدون اسم" : "Unnamed Assignment")}
                          </TableCell>
                          <TableCell>
                            <div className="flex items-center gap-1">
                              <Icon className="h-3 w-3 text-muted-foreground" />
                              <span className="text-xs">
                                {getToolTypeLabel(toolType, lang)}
                              </span>
                            </div>
                          </TableCell>
                          <TableCell>
                            <Badge className={statusColors[assignment.status]}>
                              {statusLabels[assignment.status][lang]}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            {assignment.is_visible_to_user
                              ? lang === "ar"
                                ? "نعم"
                                : "Yes"
                              : lang === "ar"
                                ? "لا"
                                : "No"}
                          </TableCell>
                          <TableCell>
                            {formatDate(
                              assignment.assigned_at || assignment.created
                            )}
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="flex items-center justify-end gap-1">
                              <Link
                                href={`/dashboard/admin/assignments/${assignment.id}`}
                              >
                                <Button variant="ghost" size="sm">
                                  <Eye className="h-4 w-4" />
                                </Button>
                              </Link>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => deleteAssignment(assignment.id)}
                              >
                                <Trash2 className="h-4 w-4 text-destructive" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      )
                    })}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="case-file">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <History className="h-5 w-5" />
                {lang === "ar" ? "ملف الحالة" : "Case File"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "سجل جميع التفاعلات بين الحالة والخبير"
                  : "History of all interactions between the case and the expert"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {caseAssignments.filter((a) => a.status === "completed")
                .length === 0 ? (
                <div className="py-8 text-center">
                  <History className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar" ? "لا يوجد سجل بعد" : "No history yet"}
                  </h3>
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? "ستظهر المهام المكتملة هنا"
                      : "Completed tasks will appear here"}
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {caseAssignments
                    .filter((a) => a.status === "completed")
                    .map((assignment) => (
                      <div
                        key={assignment.id}
                        className="flex items-center justify-between rounded-lg border p-4"
                      >
                        <div>
                          <p className="font-medium">
                            {lang === "ar"
                              ? assignment.name_ar || assignment.name_en
                              : assignment.name_en}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            {lang === "ar" ? "أكملت في" : "Completed"}{" "}
                            {assignment.updated &&
                              formatDate(assignment.updated)}
                          </p>
                        </div>
                        <Badge variant="default">
                          {lang === "ar" ? "مكتمل" : "Completed"}
                        </Badge>
                      </div>
                    ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {showAssignModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <Card className="mx-4 w-full max-w-2xl">
            <CardHeader>
              <CardTitle>{lang === "ar" ? "تعيين أداة" : "Assign Tool"}</CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "اختر أداة أو أنشئ أداة جديدة لهذه الحالة"
                  : "Choose a tool or create a new tool for this case"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 gap-4 md:grid-cols-3">
                {/* Case-specific tools - direct create */}
                {toolTypeOrder
                  .filter((key) =>
                    ["plan", "report", "attachment_request"].includes(key)
                  )
                  .filter((key) => {
                    const toolType = toolTypes.find((item) => item.key === key)
                    if (!toolType) return false
                    if (isExpert) return allowedToolTypeIds.includes(toolType.id)
                    return (
                      allowedToolTypeIds.length === 0 ||
                      allowedToolTypeIds.includes(toolType.id)
                    )
                  })
                  .map((key) => {
                    const toolType = toolTypes.find((item) => item.key === key)
                    const meta = getToolTypeMeta(key)
                    if (!toolType || !meta) return null

                    return (
                      <div
                        key={toolType.id}
                        className="flex flex-col items-center gap-3 rounded-lg border p-4"
                      >
                        <meta.icon className="h-8 w-8 text-muted-foreground" />
                        <span className="font-medium">
                          {getToolTypeLabel(toolType, lang)}
                        </span>
                        <Button
                          size="sm"
                          onClick={() => {
                            router.push(
                              `/dashboard/admin/tools/${meta.route}/new?caseId=${caseId}`
                            )
                            setShowAssignModal(false)
                          }}
                        >
                          {lang === "ar" ? "إنشاء" : "Create"}
                        </Button>
                      </div>
                    )
                  })}

                {/* Template-based tools - show template list or create new */}
                {toolTypeOrder
                  .filter((key) =>
                    ["survey", "multiple_answer"].includes(
                      key
                    )
                  )
                  .filter((key) => {
                    const toolType = toolTypes.find((item) => item.key === key)
                    if (!toolType) return false
                    if (isExpert) return allowedToolTypeIds.includes(toolType.id)
                    return (
                      allowedToolTypeIds.length === 0 ||
                      allowedToolTypeIds.includes(toolType.id)
                    )
                  })
                  .map((key) => {
                    const toolType = toolTypes.find((item) => item.key === key)
                    const meta = getToolTypeMeta(key)
                    if (!toolType || !meta) return null

                    const typeTools = tools.filter((t) => {
                      const toolTypeObj = toolTypes.find(
                        (tt) => tt.id === t.type
                      )
                      return toolTypeObj?.key === key
                    })

                    return (
                      <div
                        key={toolType.id}
                        className="flex flex-col items-center gap-3 rounded-lg border p-4"
                      >
                        <meta.icon className="h-8 w-8 text-muted-foreground" />
                        <span className="font-medium">
                          {getToolTypeLabel(toolType, lang)}
                        </span>
                        <div className="flex gap-2">
                          {typeTools.length > 0 && (
                            <Select
                              onValueChange={(toolId) => {
                                setSelectedToolId(toolId)
                                setConfirmToolType(key)
                              }}
                            >
                              <SelectTrigger className="h-8 text-xs">
                                <SelectValue
                                  placeholder={
                                    lang === "ar" ? "قوالب" : "Templates"
                                  }
                                />
                              </SelectTrigger>
                              <SelectContent>
                                {typeTools.map((tool) => (
                                  <SelectItem key={tool.id} value={tool.id}>
                                    {tool.name.en}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          )}
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => {
                              router.push(
                                `/dashboard/admin/tools/${meta.route}/new?caseId=${caseId}`
                              )
                              setShowAssignModal(false)
                            }}
                          >
                            {lang === "ar" ? "جديد" : "New"}
                          </Button>
                        </div>
                      </div>
                    )
                  })}</div>

              {allowedToolTypeIds.length > 0 && (
                <p className="text-sm text-muted-foreground mt-4">
                  {lang === "ar"
                    ? "يتم عرض أنواع الأدوات بناءً على أدوار الخبراء المخصصين لهذه القضية."
                    : "Tool types shown are based on the assigned experts' roles for this case."}
                </p>
              )}
            </CardContent>
            <CardContent className="flex justify-end pt-0">
              <Button
                variant="outline"
                onClick={() => {
                  setShowAssignModal(false)
                  setSelectedToolId("")
                }}
              >
                {lang === "ar" ? "إلغاء" : "Cancel"}
              </Button>
            </CardContent>
          </Card>
        </div>
      )}

      {confirmToolType && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <Card className="mx-4 w-full max-w-sm">
            <CardHeader>
              <CardTitle>{lang === "ar" ? "تأكيد" : "Confirm"}</CardTitle>
            </CardHeader>
            <CardContent>
              {selectedToolId ? (
                <p>
                  {lang === "ar"
                    ? `هل تريد تعيين هذا القالب لهذه الحالة؟`
                    : `Assign this template to this case?`}
                </p>
              ) : (
                <p>
                  {lang === "ar"
                    ? `إنشاء ${getToolTypeLabel(
                        toolTypes.find((item) => item.key === confirmToolType),
                        lang
                      )} جديد لهذه الحالة؟`
                    : `Create new ${getToolTypeLabel(
                        toolTypes.find((item) => item.key === confirmToolType),
                        lang
                      )} for this case?`}
                </p>
              )}
            </CardContent>
            <CardContent className="flex justify-end gap-2">
              <Button
                variant="outline"
                onClick={() => {
                  setConfirmToolType(null)
                  setSelectedToolId("")
                }}
              >
                {lang === "ar" ? "إلغاء" : "Cancel"}
              </Button>
              {selectedToolId ? (
                <Button onClick={handleAssignTool} disabled={isAssigning}>
                  {isAssigning
                    ? lang === "ar"
                      ? "جاري التعيين..."
                      : "Assigning..."
                    : lang === "ar"
                      ? "تعيين"
                      : "Assign"}
                </Button>
              ) : (
                <Button
                  onClick={() => {
                    const route =
                      getToolTypeMeta(confirmToolType)?.route || confirmToolType
                    router.push(
                      `/dashboard/admin/tools/${route}/new?caseId=${caseId}`
                    )
                    setShowAssignModal(false)
                    setConfirmToolType(null)
                    setSelectedToolId("")
                  }}
                >
                  {lang === "ar" ? "إنشاء" : "Create"}
                </Button>
              )}
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  )
}

"use client"

import { useState, useMemo } from "react"
import Link from "next/link"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useLang } from "@/lib/lang-context"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Input } from "@/components/ui/input"
import { PageLoader } from "@/components/ui/page-loader"
import { SkeletonTable } from "@/components/ui/skeleton"
import { SmartLink } from "@/components/smart-link"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  Plus,
  FolderKanban,
  User,
  Eye,
  Search,
  ArrowUp,
  ArrowDown,
} from "lucide-react"

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

import { formatDate, formatDateTime } from "@/lib/format-date"
import { CaseStatusBadge } from "@/components/cases/status-badge"
import type { Profile } from "@/types/profile"

type CaseSortField = "name" | "date_of_birth" | "gender" | "grade" | "created"

const DATE_SORT_FIELDS: ReadonlySet<CaseSortField> = new Set([
  "date_of_birth",
  "created",
])

interface AssignmentCount {
  total: number
  pending: number
  assigned: number
  in_progress: number
  completed: number
}

export default function AdminCasesPage() {
  const { lang } = useLang()
  const { profiles, isLoading: isProfilesLoading } = useProfiles()
  const { assignments, isLoading: isAssignmentsLoading } = useAssignments()

  const [searchQuery, setSearchQuery] = useState("")
  const [sortField, setSortField] = useState<CaseSortField>("name")
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("asc")

  const assignmentCounts = useMemo(() => {
    const counts: Record<string, AssignmentCount> = {}
    assignments.forEach((a) => {
      if (!counts[a.case]) {
        counts[a.case] = {
          total: 0,
          pending: 0,
          assigned: 0,
          in_progress: 0,
          completed: 0,
        }
      }
      counts[a.case].total++
      if (a.status === "pending") counts[a.case].pending++
      else if (a.status === "assigned") counts[a.case].assigned++
      else if (a.status === "in_progress") counts[a.case].in_progress++
      else if (a.status === "completed") counts[a.case].completed++
    })
    return counts
  }, [assignments])

  const isLoading = isProfilesLoading || isAssignmentsLoading

  const filteredProfiles = profiles.filter((profile) => {
    if (!searchQuery) return true
    const q = searchQuery.toLowerCase()
    return (
      profile.name?.toLowerCase().includes(q) ||
      profile.gender?.toLowerCase().includes(q) ||
      profile.grade?.toLowerCase().includes(q)
    )
  })

  const sortedProfiles = [...filteredProfiles].sort((a, b) => {
    const getVal = (p: Profile) => String(p[sortField] ?? "")

    if (DATE_SORT_FIELDS.has(sortField)) {
      const timeA = Date.parse(getVal(a))
      const timeB = Date.parse(getVal(b))
      const invalidA = Number.isNaN(timeA)
      const invalidB = Number.isNaN(timeB)
      // Keep records with missing/invalid dates at the end in both directions
      if (invalidA || invalidB) {
        if (invalidA && invalidB) return 0
        return invalidA ? 1 : -1
      }
      const cmp = timeA - timeB
      return sortDirection === "asc" ? cmp : -cmp
    }

    const cmp = getVal(a).toLowerCase().localeCompare(getVal(b).toLowerCase())
    return sortDirection === "asc" ? cmp : -cmp
  })

  const handleSortFieldChange = (value: string) => {
    const next = value as CaseSortField
    setSortField(next)
    // Newest (or latest) first is the useful default for date fields
    if (DATE_SORT_FIELDS.has(next)) {
      setSortDirection("desc")
    }
  }

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-primary">
              {lang === "ar" ? "الحالات" : "Cases"}
            </h1>
            <p className="text-muted-foreground">
              {lang === "ar" ? "إدارة جميع الحالات" : "Manage all cases"}
            </p>
          </div>
          <Link href="/dashboard/admin/cases/new">
            <Button>
              <Plus className="me-2 h-4 w-4" />
              {lang === "ar" ? "حالة جديدة" : "New Case"}
            </Button>
          </Link>
        </div>
        <SkeletonTable rows={6} />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {lang === "ar" ? "الحالات" : "Cases"}
          </h1>
          <p className="text-muted-foreground">
            {lang === "ar" ? "إدارة جميع الحالات" : "Manage all cases"}
          </p>
        </div>
        <Link href="/dashboard/admin/cases/new">
          <Button>
            <Plus className="me-2 h-4 w-4" />
            {lang === "ar" ? "حالة جديدة" : "New Case"}
          </Button>
        </Link>
      </div>

      {/* Search & Sort */}
      <div className="flex flex-col gap-4 sm:flex-row">
        <div className="relative flex-1">
          <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder={
              lang === "ar"
                ? "ابحث بالاسم أو الجنس أو الصف..."
                : "Search by name, gender, or grade..."
            }
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10"
          />
        </div>
        <div className="flex items-center gap-2">
          <span className="text-sm whitespace-nowrap text-muted-foreground">
            {lang === "ar" ? "ترتيب حسب" : "Sort by"}
          </span>
          <Select value={sortField} onValueChange={handleSortFieldChange}>
            <SelectTrigger className="w-[160px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="name">
                {lang === "ar" ? "اسم الحالة" : "Case Name"}
              </SelectItem>
              <SelectItem value="date_of_birth">
                {lang === "ar" ? "تاريخ الميلاد" : "Date of Birth"}
              </SelectItem>
              <SelectItem value="created">
                {lang === "ar" ? "تاريخ الإضافة" : "Date Added"}
              </SelectItem>
              <SelectItem value="gender">
                {lang === "ar" ? "الجنس" : "Gender"}
              </SelectItem>
              <SelectItem value="grade">
                {lang === "ar" ? "الصف الدراسي" : "Grade"}
              </SelectItem>
            </SelectContent>
          </Select>
          <Button
            variant="outline"
            size="icon"
            className="h-8 w-8"
            onClick={() =>
              setSortDirection((prev) => (prev === "asc" ? "desc" : "asc"))
            }
          >
            {sortDirection === "asc" ? (
              <ArrowUp className="h-3 w-3" />
            ) : (
              <ArrowDown className="h-3 w-3" />
            )}
          </Button>
        </div>
      </div>

      {sortedProfiles.length === 0 ? (
        <Card>
          <CardContent className="flex flex-col items-center justify-center py-12">
            <FolderKanban className="mb-4 h-12 w-12 text-muted-foreground" />
            <h3 className="mb-2 text-lg font-medium">
              {profiles.length === 0
                ? lang === "ar"
                  ? "لا توجد حالات بعد"
                  : "No cases yet"
                : lang === "ar"
                  ? "لا توجد حالات مطابقة لبحثك"
                  : "No cases match your search"}
            </h3>
            <p className="mb-4 text-center text-muted-foreground">
              {profiles.length === 0
                ? lang === "ar"
                  ? "أنشئ حالتك الأولى للبدء"
                  : "Create your first case to get started"
                : lang === "ar"
                  ? "حاول تعديل استعلام البحث"
                  : "Try adjusting your search query"}
            </p>
            {profiles.length === 0 && (
              <Link href="/dashboard/admin/cases/new">
                <Button>
                  {lang === "ar" ? "إنشاء الحالة" : "Create Case"}
                </Button>
              </Link>
            )}
          </CardContent>
        </Card>
      ) : (
        <Card>
          <CardHeader>
            <CardTitle>
              {lang === "ar" ? "جميع الحالات" : "All Cases"}
            </CardTitle>
            <CardDescription>
              {lang === "ar"
                ? `تم العثور على ${sortedProfiles.length} حالة`
                : `${sortedProfiles.length} case(s) found`}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-[250px]">
                    {lang === "ar" ? "اسم الحالة" : "Case Name"}
                  </TableHead>
                  <TableHead>
                    {lang === "ar" ? "تاريخ الميلاد" : "Date of Birth"}
                  </TableHead>
                  <TableHead className="whitespace-nowrap">
                    {lang === "ar" ? "تاريخ الإضافة" : "Date Added"}
                  </TableHead>
                  <TableHead>{lang === "ar" ? "الجنس" : "Gender"}</TableHead>
                  <TableHead>
                    {lang === "ar" ? "الصف الدراسي" : "Grade"}
                  </TableHead>
                  <TableHead>{lang === "ar" ? "المستخدم" : "User"}</TableHead>
                  <TableHead>{lang === "ar" ? "الحالة" : "Status"}</TableHead>
                  <TableHead>
                    {lang === "ar" ? "التعيينات" : "Assignments"}
                  </TableHead>
                  <TableHead className="text-right">
                    {lang === "ar" ? "الإجراءات" : "Actions"}
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {sortedProfiles.map((profile) => {
                  const counts = assignmentCounts[profile.id] || {
                    total: 0,
                    pending: 0,
                    assigned: 0,
                    in_progress: 0,
                    completed: 0,
                  }
                  return (
                    <TableRow key={profile.id}>
                      <TableCell className="font-medium">
                        <div className="flex items-center gap-2">
                          <User className="h-4 w-4 text-muted-foreground" />
                          {profile.name}
                        </div>
                      </TableCell>
                      <TableCell>
                        {formatDate(profile.date_of_birth || "")}
                      </TableCell>
                      <TableCell className="whitespace-nowrap text-muted-foreground">
                        {formatDateTime(profile.created)}
                      </TableCell>
                      <TableCell className="capitalize">
                        {profile.gender === "male"
                          ? lang === "ar"
                            ? "ذكر"
                            : "male"
                          : profile.gender === "female"
                            ? lang === "ar"
                              ? "أنثى"
                              : "female"
                            : profile.gender}
                      </TableCell>
                      <TableCell className="capitalize">
                        {profile.grade}
                      </TableCell>
                      <TableCell>
                        <span className="text-sm text-muted-foreground">
                          {profile.expand?.user
                            ? `${profile.expand.user.name} (${profile.expand.user.email})`
                            : "—"}
                        </span>
                      </TableCell>
                      <TableCell>
                        <CaseStatusBadge status={profile.status} />
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-wrap items-center gap-1">
                          {counts.total === 0 ? (
                            <span className="text-sm text-muted-foreground">
                              {lang === "ar"
                                ? "لا توجد تعيينات"
                                : "No assignments"}
                            </span>
                          ) : (
                            <>
                              {counts.pending > 0 && (
                                <Badge
                                  key="pending"
                                  variant="outline"
                                  className="bg-yellow-50 text-yellow-700"
                                >
                                  {counts.pending}{" "}
                                  {lang === "ar" ? "قيد الانتظار" : "pending"}
                                </Badge>
                              )}
                              {counts.assigned > 0 && (
                                <Badge
                                  key="assigned"
                                  variant="outline"
                                  className="bg-blue-50 text-blue-700"
                                >
                                  {counts.assigned}{" "}
                                  {lang === "ar" ? "تم التعيين" : "assigned"}
                                </Badge>
                              )}
                              {counts.in_progress > 0 && (
                                <Badge
                                  key="in_progress"
                                  variant="outline"
                                  className="bg-purple-50 text-purple-700"
                                >
                                  {counts.in_progress}{" "}
                                  {lang === "ar"
                                    ? "قيد التنفيذ"
                                    : "in progress"}
                                </Badge>
                              )}
                              {counts.completed > 0 && (
                                <Badge
                                  key="completed"
                                  variant="outline"
                                  className="bg-green-50 text-green-700"
                                >
                                  {counts.completed}{" "}
                                  {lang === "ar" ? "مكتمل" : "completed"}
                                </Badge>
                              )}
                            </>
                          )}
                        </div>
                      </TableCell>
                      <TableCell className="text-right">
                        <SmartLink
                          href={`/dashboard/admin/cases/${profile.id}`}
                        >
                          <Button variant="ghost" size="sm">
                            <Eye className="me-1 h-4 w-4" />
                            {lang === "ar" ? "عرض" : "View"}
                          </Button>
                        </SmartLink>
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

"use client"

import { useEffect, useState, useRef } from "react"
import { useRouter } from "next/navigation"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { useLookups, type LookupType } from "@/hooks/useLookups"
import { formatDate } from "@/lib/format-date"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { ArrowLeft, Pencil, Plus, Trash2, List } from "lucide-react"

const LOOKUP_TYPES: { value: LookupType; label: { en: string; ar: string } }[] = [
  { value: "tool_types", label: { en: "Tool Types", ar: "أنواع الأدوات" } },
  { value: "case_types", label: { en: "Case Types", ar: "أنواع الحالات" } },
  { value: "user_types", label: { en: "User Types", ar: "أنواع المستخدمين" } },
]

export default function LookupsPage() {
  const router = useRouter()
  const { isSuperAdmin, isLoading: isAuthLoading } = useAuth()
  const { lang } = useLang()
  const {
    lookups,
    isLoading,
    error,
    fetchLookups,
    createLookup,
    updateLookup,
    deleteLookup,
  } = useLookups()

  const [filterType, setFilterType] = useState<LookupType>("tool_types")
  const [dialogOpen, setDialogOpen] = useState(false)
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)
  const [editingLookup, setEditingLookup] = useState<string | null>(null)
  const [deletingLookupId, setDeletingLookupId] = useState<string | null>(null)
  const [formData, setFormData] = useState({
    key: "",
    label_en: "",
    label_ar: "",
  })
  const [formType, setFormType] = useState<LookupType>("tool_types")
  const hasFetched = useRef(false)

  useEffect(() => {
    if (!isAuthLoading && !isSuperAdmin) {
      router.push("/dashboard")
    }
  }, [isAuthLoading, isSuperAdmin, router])

  useEffect(() => {
    if (!hasFetched.current) {
      hasFetched.current = true
    }
    fetchLookups(filterType)
  }, [filterType, fetchLookups])

  const resetForm = () => {
    setFormData({ key: "", label_en: "", label_ar: "" })
    setFormType("tool_types")
    setEditingLookup(null)
  }

  const openCreateDialog = () => {
    resetForm()
    setDialogOpen(true)
  }

  const openEditDialog = (id: string) => {
    const item = lookups.find((l) => l.id === id)
    if (!item) return
    setFormData({
      key: item.key,
      label_en: item.label_en,
      label_ar: item.label_ar,
    })
    setFormType(item.type as LookupType)
    setEditingLookup(id)
    setDialogOpen(true)
  }

  const handleSave = async () => {
    if (!formData.key || !formData.label_en || !formData.label_ar) return

    if (editingLookup) {
      await updateLookup(editingLookup, {
        key: formData.key,
        label_en: formData.label_en,
        label_ar: formData.label_ar,
      })
    } else {
      await createLookup({
        type: formType,
        key: formData.key,
        label_en: formData.label_en,
        label_ar: formData.label_ar,
      })
    }
    setDialogOpen(false)
    resetForm()
    fetchLookups(filterType)
  }

  const handleDelete = async () => {
    if (!deletingLookupId) return
    const success = await deleteLookup(deletingLookupId)
    if (success) {
      setDeleteDialogOpen(false)
      setDeletingLookupId(null)
      fetchLookups(filterType)
    }
  }

  if (isAuthLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جاري التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  if (!isSuperAdmin) {
    return null
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button
          variant="ghost"
          size="icon"
          onClick={() => router.push("/dashboard/admin/settings")}
        >
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {lang === "ar" ? "القوائم المرجعية" : "Lookups"}
          </h1>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? "إدارة جداول القوائم المرجعية"
              : "Manage lookup tables"}
          </p>
        </div>
      </div>

      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <div className="flex items-center gap-4">
            <div>
              <Label className="text-xs tracking-wider text-muted-foreground uppercase">
                {lang === "ar" ? "تصفية حسب النوع" : "Filter by Type"}
              </Label>
              <Select
                value={filterType}
                onValueChange={(v) => setFilterType(v as LookupType)}
              >
                <SelectTrigger className="w-[200px]">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {LOOKUP_TYPES.map((t) => (
                    <SelectItem key={t.value} value={t.value}>
                      {t.label[lang]}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <Button onClick={openCreateDialog}>
            <Plus className="me-2 h-4 w-4" />
            {lang === "ar" ? "إضافة قيمة" : "Add Lookup"}
          </Button>
        </CardHeader>
        <CardContent>
          {error && (
            <div className="mb-4 rounded border border-destructive/50 bg-destructive/10 p-3 text-sm text-destructive">
              {error}
            </div>
          )}

          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>{lang === "ar" ? "المفتاح" : "Key"}</TableHead>
                <TableHead>{lang === "ar" ? "التسمية (إنجليزي)" : "Label (EN)"}</TableHead>
                <TableHead>{lang === "ar" ? "التسمية (عربي)" : "Label (AR)"}</TableHead>
                <TableHead>{lang === "ar" ? "تاريخ الإنشاء" : "Created"}</TableHead>
                <TableHead className="text-right">
                  {lang === "ar" ? "إجراءات" : "Actions"}
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell colSpan={5} className="py-8 text-center">
                    {lang === "ar" ? "جاري التحميل..." : "Loading..."}
                  </TableCell>
                </TableRow>
              ) : lookups.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={5} className="py-8 text-center">
                    <div className="flex flex-col items-center gap-2">
                      <List className="h-8 w-8 text-muted-foreground" />
                      <p className="text-muted-foreground">
                        {lang === "ar" ? "لا توجد قيم" : "No lookups found"}
                      </p>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={openCreateDialog}
                      >
                        {lang === "ar"
                          ? "أضف أول قيمة"
                          : "Add your first lookup"}
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ) : (
                lookups.map((lookup) => (
                  <TableRow key={lookup.id}>
                    <TableCell className="font-mono text-sm">
                      {lookup.key}
                    </TableCell>
                    <TableCell>{lookup.label_en}</TableCell>
                    <TableCell dir="rtl">{lookup.label_ar}</TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      {formatDate(lookup.created)}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-1">
                        <Button
                          variant="ghost"
                          size="icon-sm"
                          onClick={() => openEditDialog(lookup.id)}
                        >
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon-sm"
                          onClick={() => {
                            setDeletingLookupId(lookup.id)
                            setDeleteDialogOpen(true)
                          }}
                        >
                          <Trash2 className="h-4 w-4 text-destructive" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Create / Edit Dialog */}
      <Dialog
        open={dialogOpen}
        onOpenChange={(open) => {
          setDialogOpen(open)
          if (!open) resetForm()
        }}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {editingLookup
                ? lang === "ar"
                  ? "تعديل القيمة"
                  : "Edit Lookup"
                : lang === "ar"
                  ? "إضافة قيمة"
                  : "Add Lookup"}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            {!editingLookup && (
              <div className="space-y-2">
                <Label>{lang === "ar" ? "النوع" : "Type"}</Label>
                <Select
                  value={formType}
                  onValueChange={(v) => setFormType(v as LookupType)}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {LOOKUP_TYPES.map((t) => (
                      <SelectItem key={t.value} value={t.value}>
                        {t.label[lang]}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            <div className="space-y-2">
              <Label>{lang === "ar" ? "المفتاح" : "Key"}</Label>
              <Input
                placeholder="e.g. survey"
                value={formData.key}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, key: e.target.value }))
                }
                disabled={!!editingLookup}
              />
            </div>
            <div className="space-y-2">
              <Label>
                {lang === "ar" ? "التسمية (إنجليزي)" : "Label (English)"}
              </Label>
              <Input
                placeholder="e.g. Survey"
                value={formData.label_en}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, label_en: e.target.value }))
                }
              />
            </div>
            <div className="space-y-2">
              <Label>
                {lang === "ar" ? "التسمية (عربي)" : "Label (Arabic)"}
              </Label>
              <Input
                placeholder="e.g. استبيان"
                value={formData.label_ar}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, label_ar: e.target.value }))
                }
                dir="rtl"
              />
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setDialogOpen(false)
                resetForm()
              }}
            >
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleSave}
              disabled={
                !formData.key || !formData.label_en || !formData.label_ar
              }
            >
              {editingLookup
                ? lang === "ar"
                  ? "حفظ التغييرات"
                  : "Save Changes"
                : lang === "ar"
                  ? "إنشاء"
                  : "Create"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog
        open={deleteDialogOpen}
        onOpenChange={(open) => {
          setDeleteDialogOpen(open)
          if (!open) setDeletingLookupId(null)
        }}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {lang === "ar" ? "حذف القيمة" : "Delete Lookup"}
            </DialogTitle>
          </DialogHeader>
          <p className="py-2">
            {lang === "ar"
              ? "هل أنت متأكد من حذف هذه القيمة؟ لا يمكن التراجع عن هذا الإجراء."
              : "Are you sure you want to delete this lookup? This action cannot be undone."}
          </p>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setDeleteDialogOpen(false)
                setDeletingLookupId(null)
              }}
            >
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button variant="destructive" onClick={handleDelete}>
              {lang === "ar" ? "حذف" : "Delete"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

