"use client"

import { use, useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { useTools } from "@/hooks/useTools"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { useLang } from "@/lib/lang-context"
import { caseToolsCollection } from "@/lib/pb-collections"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { DragList } from "@/components/ui/drag-list"
import { MultipleChoicePreview } from "@/components/tool-renderers/MultipleChoicePreview"
import { MediaUpload } from "@/components/ui/media-upload"
import {
  ArrowLeft,
  Plus,
  Trash2,
  Eye,
  EyeOff,
  CheckCircle,
  Image,
  Video,
  Music,
  X,
} from "lucide-react"
import type {
  MultipleChoiceConfig,
  MCQuestion,
  MCAnswerType,
  MediaType,
  ResponseType,
} from "@/types/tool"
import { useToolTypes } from "@/hooks/useToolTypes"
import pb from "@/lib/pb"

function generateId(): string {
  return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
}

const ANSWER_TYPES: {
  value: MCAnswerType
  label: { en: string; ar: string }
}[] = [
  { value: "text", label: { en: "Text", ar: "نص" } },
  { value: "number", label: { en: "Number", ar: "رقم" } },
  {
    value: "single_choice",
    label: {
      en: "Single Choice (mark correct)",
      ar: "اختيار واحد (حدد الصحيح)",
    },
  },
  {
    value: "multiple_choice",
    label: {
      en: "Multiple Choice (mark correct)",
      ar: "اختيار من متعدد (حدد الصحيح)",
    },
  },
  {
    value: "media",
    label: { en: "Media (image/video/audio)", ar: "وسائط (صورة/فيديو/صوت)" },
  },
]

const DEFAULT_OPTIONS = [
  { value: "opt1", label: "Option 1", isCorrect: false },
  { value: "opt2", label: "Option 2", isCorrect: false },
  { value: "opt3", label: "Option 3", isCorrect: false },
  { value: "opt4", label: "Option 4", isCorrect: false },
  { value: "opt5", label: "Option 5", isCorrect: false },
]

interface MultipleChoiceBuilderPageProps {
  params?: Promise<{ id?: string }>
  searchParams?: Promise<{ caseId?: string }>
}

export default function MultipleChoiceBuilderPage({
  params,
  searchParams,
}: MultipleChoiceBuilderPageProps = {}) {
  const router = useRouter()
  const { lang } = useLang()
  const { updateTool, getToolById, isLoading: isToolsLoading } = useTools()
  const { assignTool } = useAssignments()
  const { getProfileById } = useProfiles()
  const { toolTypes, fetchToolTypes } = useToolTypes()
  const [showPreview, setShowPreview] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isLoading, setIsLoading] = useState(false)

  // Edit mode detection
  const resolvedParams = params ? use(params) : undefined
  const resolvedSearchParams = searchParams ? use(searchParams) : undefined
  const editId = resolvedParams?.id
  const caseId = resolvedSearchParams?.caseId
  const isEditMode = !!editId

  const [isTemplate, setIsTemplate] = useState(true)
  const selectedCase = caseId ? getProfileById(caseId) : null

  const [formData, setFormData] = useState({
    nameEn: "",
    nameAr: "",
  })

  const [questions, setQuestions] = useState<MCQuestion[]>([])
  const [pendingFiles, setPendingFiles] = useState<Map<string, File>>(new Map())
  const [uploadOpen, setUploadOpen] = useState(false)
  const [currentMediaQuestionId, setCurrentMediaQuestionId] = useState<
    string | null
  >(null)

  // Load existing data in edit mode
  useEffect(() => {
    if (isEditMode && editId && !isToolsLoading) {
      // Initialize the editable draft once the asynchronous tool data is available.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setIsLoading(true)
      const tool = getToolById(editId)
      if (tool && tool.config) {
        const config = tool.config as MultipleChoiceConfig
        setFormData({
          nameEn: tool.name.en,
          nameAr: tool.name.ar,
        })
        setQuestions(config.questions || [])
      }
      setIsLoading(false)
    }
  }, [isEditMode, editId, isToolsLoading])

  const addQuestion = () => {
    const newQuestion: MCQuestion = {
      id: generateId(),
      text: "",
      answerType: "single_choice",
      options: [...DEFAULT_OPTIONS],
      required: false,
      order: questions.length,
    }
    setQuestions([...questions, newQuestion])
  }

  const updateQuestion = (id: string, updates: Partial<MCQuestion>) => {
    setQuestions(questions.map((q) => (q.id === id ? { ...q, ...updates } : q)))
  }

  const removeQuestion = (id: string) => {
    setQuestions(questions.filter((q) => q.id !== id))
  }

  const handleReorder = (reordered: MCQuestion[]) => {
    setQuestions(reordered)
  }

  const handleSubmit = async () => {
    if (!formData.nameEn || questions.length === 0) return
    setIsSubmitting(true)

    const toolTypes = await fetchToolTypes()
    const type = toolTypes.find((t) => t.key === "multiple_answer")?.id
    if (!type) {
      setIsSubmitting(false)
      return
    }

    const baseQuestions = questions.map((q, idx) => ({ ...q, order: idx }))
    const pendingEntries = Array.from(pendingFiles.entries())

    const baseConfig: MultipleChoiceConfig = {
      title: { en: formData.nameEn, ar: formData.nameAr },
      questions: baseQuestions,
      media: [],
    }

    let finalConfig: MultipleChoiceConfig

    // Helper: build finalConfig from uploaded URLs
    const buildFinalConfig = (uploadedUrls: string[]): MultipleChoiceConfig => {
      const finalQuestions = baseQuestions.map((q) => {
        const pendingIndex = pendingEntries.findIndex(([id]) => id === q.id)
        if (pendingIndex >= 0 && uploadedUrls[pendingIndex]) {
          return { ...q, mediaUrl: uploadedUrls[pendingIndex] }
        }
        return q
      })
      return {
        title: { en: formData.nameEn, ar: formData.nameAr },
        questions: finalQuestions,
        media: uploadedUrls,
      }
    }

    if (isEditMode && editId) {
      const mediaFormData = new FormData()
      for (const [, file] of pendingEntries) {
        mediaFormData.append("media", file)
      }
      mediaFormData.append("config", JSON.stringify(baseConfig))

      const record = await pb.collection("tools").update(editId, mediaFormData)
      const uploadedUrls = (record.media as string[]).map((filename) =>
        pb.files.getUrl(record, filename)
      )

      finalConfig = buildFinalConfig(uploadedUrls)

      await updateTool(editId, {
        name: { en: formData.nameEn, ar: formData.nameAr },
        config: finalConfig,
      })
      router.push(`/dashboard/admin/tools/multiple-choice/${editId}`)
      return
    }

    // Create mode: only 2 paths
    if (!isTemplate && caseId) {
      // Assignment: create in case_tools, upload media there
      const assignment = await caseToolsCollection.create({
        case: caseId,
        type: type,
        name_en: formData.nameEn,
        name_ar: formData.nameAr,
        is_not_template: true,
        config: baseConfig,
        status: "pending",
        is_visible_to_user: true,
        responses: {},
        media: [],
      })

      if (pendingEntries.length > 0) {
        const files = pendingEntries.map(([, file]) => file)
        const updated = await caseToolsCollection.updateWithFiles(
          assignment.id,
          {},
          files
        )
        const uploadedUrls = (updated.media as string[]).map((filename) =>
          pb.files.getUrl(updated, filename)
        )
        finalConfig = buildFinalConfig(uploadedUrls)
        await caseToolsCollection.update(assignment.id, { config: finalConfig })
      } else {
        finalConfig = baseConfig
      }

      router.push(`/dashboard/admin/cases/${caseId}`)
    } else {
      // Template (with or without case): create in tools, upload media there
      const mediaFormData = new FormData()
      mediaFormData.append("name_en", formData.nameEn)
      mediaFormData.append("name_ar", formData.nameAr)
      mediaFormData.append("type", type)
      mediaFormData.append("serviceType", "individual")
      mediaFormData.append("status", "active")
      mediaFormData.append("config", JSON.stringify(baseConfig))
      for (const [, file] of pendingEntries) {
        mediaFormData.append("media", file)
      }

      const record = await pb.collection("tools").create(mediaFormData)
      const uploadedUrls = (record.media as string[]).map((filename) =>
        pb.files.getUrl(record, filename)
      )

      finalConfig = buildFinalConfig(uploadedUrls)

      await updateTool(record.id, {
        name: { en: formData.nameEn, ar: formData.nameAr },
        config: finalConfig,
      })

      if (caseId) {
        await caseToolsCollection.create({
          case: caseId,
          type: type,
          name_en: formData.nameEn,
          name_ar: formData.nameAr,
          is_not_template: false,
          config: finalConfig,
          is_visible_to_user: true,
          status: "pending",
          responses: {},
          media: [],
        })
      }

      router.push(`/dashboard/admin/tools`)
    }
  }

  const getMediaIcon = (type?: MediaType) => {
    switch (type) {
      case "image":
        return Image
      case "video":
        return Video
      case "audio":
        return Music
      default:
        return Image
    }
  }

  const handleMediaUpload = (data: {
    file: File
    mediaType: MediaType
    responseType: ResponseType
  }) => {
    if (!currentMediaQuestionId) return
    updateQuestion(currentMediaQuestionId, {
      mediaType: data.mediaType,
      mediaUrl: "",
      responseType: data.responseType,
    })
    setPendingFiles((prev) =>
      new Map(prev).set(currentMediaQuestionId, data.file)
    )
    setCurrentMediaQuestionId(null)
  }

  const handleRemoveMedia = (questionId: string) => {
    updateQuestion(questionId, {
      mediaType: undefined,
      mediaUrl: undefined,
      responseType: undefined,
    })
    setPendingFiles((prev) => {
      const next = new Map(prev)
      next.delete(questionId)
      return next
    })
  }

  const renderQuestionItem = (question: MCQuestion, index: number) => {
    const showOptions =
      question.answerType === "single_choice" ||
      question.answerType === "multiple_choice"
    const showCorrect = showOptions
    const isMedia = question.answerType === "media"
    const pendingFile = pendingFiles.get(question.id)
    const mediaPreviewSrc = pendingFile
      ? URL.createObjectURL(pendingFile)
      : question.mediaUrl

    return (
      <div className="flex-1 space-y-3">
        <div className="flex items-center justify-between">
          <span className="text-sm font-medium">
            {lang === "ar" ? "سؤال" : "Question"} {index + 1}
          </span>
          <div className="flex items-center gap-2">
            <Checkbox
              id={`req-${question.id}`}
              checked={question.required}
              onCheckedChange={(checked) =>
                updateQuestion(question.id, { required: !!checked })
              }
            />
            <Label htmlFor={`req-${question.id}`} className="text-xs">
              {lang === "ar" ? "إجباري" : "Required"}
            </Label>
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={() => {
                removeQuestion(question.id)
                setPendingFiles((prev) => {
                  const next = new Map(prev)
                  next.delete(question.id)
                  return next
                })
              }}
            >
              <Trash2 className="h-4 w-4 text-destructive" />
            </Button>
          </div>
        </div>

        <Input
          placeholder={lang === "ar" ? "سؤال" : "Question"}
          value={question.text}
          onChange={(e) =>
            updateQuestion(question.id, { text: e.target.value })
          }
        />

        <Select
          value={question.answerType}
          onValueChange={(v) =>
            updateQuestion(question.id, { answerType: v as MCAnswerType })
          }
        >
          <SelectTrigger className="w-56">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {ANSWER_TYPES.map((type) => (
              <SelectItem key={type.value} value={type.value}>
                {type.label[lang]}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        {isMedia && (
          <div className="space-y-3 rounded-md border p-3">
            <Label className="text-xs">
              {lang === "ar" ? "وسائط السؤال" : "Media Prompt"}
            </Label>
            {!question.mediaType ? (
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => {
                  setCurrentMediaQuestionId(question.id)
                  setUploadOpen(true)
                }}
              >
                <Plus className="me-1 h-3 w-3" />
                {lang === "ar" ? "اختر الوسائط" : "Select Media"}
              </Button>
            ) : (
              <div className="space-y-3">
                <div className="rounded-lg border bg-muted/30 p-2">
                  {question.mediaType === "image" && mediaPreviewSrc && (
                    <img
                      src={mediaPreviewSrc}
                      alt={lang === "ar" ? "معاينة" : "Preview"}
                      className="h-32 w-full rounded object-cover"
                    />
                  )}
                  {question.mediaType === "video" && mediaPreviewSrc && (
                    <video
                      src={mediaPreviewSrc}
                      className="h-32 w-full rounded object-cover"
                    />
                  )}
                  {question.mediaType === "audio" && (
                    <div className="flex h-12 items-center justify-center rounded bg-muted">
                      <Music className="h-6 w-6" />
                    </div>
                  )}
                  {question.mediaType === "audio" && mediaPreviewSrc && (
                    <audio
                      src={mediaPreviewSrc}
                      controls
                      className="mt-2 w-full"
                    />
                  )}
                  {!mediaPreviewSrc && (
                    <div className="flex h-32 items-center justify-center text-muted-foreground">
                      {lang === "ar" ? "لا توجد معاينة" : "No preview"}
                    </div>
                  )}
                </div>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    {(() => {
                      const Icon = getMediaIcon(question.mediaType)
                      return <Icon className="h-4 w-4" />
                    })()}
                    <span className="capitalize">{question.mediaType}</span>
                    <span className="text-muted-foreground">•</span>
                    <span className="capitalize">
                      {question.responseType}{" "}
                      {lang === "ar" ? "استجابة" : "response"}
                    </span>
                  </div>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveMedia(question.id)}
                  >
                    <X className="me-1 h-3 w-3" />
                    {lang === "ar" ? "إزالة" : "Remove"}
                  </Button>
                </div>
              </div>
            )}
          </div>
        )}

        {showOptions && (
          <div className="space-y-2 rounded-md border p-3">
            <Label className="text-xs">
              {lang === "ar"
                ? "الخيارات - حدد الإجابة الصحيحة"
                : "Options - check correct answer(s)"}
            </Label>
            {question.options.map((opt, optIdx) => (
              <div key={opt.value} className="flex items-center gap-2">
                <Checkbox
                  id={`correct-${question.id}-${optIdx}`}
                  checked={opt.isCorrect}
                  onCheckedChange={(checked) => {
                    const newOptions = question.options.map((o, i) =>
                      i === optIdx ? { ...o, isCorrect: !!checked } : o
                    )
                    updateQuestion(question.id, { options: newOptions })
                  }}
                />
                <Input
                  placeholder={lang === "ar" ? "خيار" : "Option"}
                  value={opt.label}
                  onChange={(e) => {
                    const newOptions = question.options.map((o, i) =>
                      i === optIdx ? { ...o, label: e.target.value } : o
                    )
                    updateQuestion(question.id, { options: newOptions })
                  }}
                  className="flex-1"
                />
                {opt.isCorrect && (
                  <CheckCircle className="h-4 w-4 text-green-600" />
                )}
              </div>
            ))}
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => {
                const newOptions = [
                  ...question.options,
                  {
                    value: generateId(),
                    label: `Option ${question.options.length + 1}`,
                    isCorrect: false,
                  },
                ]
                updateQuestion(question.id, { options: newOptions })
              }}
            >
              <Plus className="me-1 h-3 w-3" />
              {lang === "ar" ? "إضافة خيار" : "Add Option"}
            </Button>
          </div>
        )}
      </div>
    )
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جارٍ التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-primary">
              {isEditMode
                ? lang === "ar"
                  ? "تعديل"
                  : "Edit"
                : lang === "ar"
                  ? "إنشاء"
                  : "Create"}{" "}
              {lang === "ar"
                ? "منشئ الإجابة المتعددة"
                : "Multiple Answer Builder"}
            </h1>
            <p className="text-muted-foreground">
              {isEditMode
                ? lang === "ar"
                  ? "تحديث أسئلة وإجابات الاختبار"
                  : "Update quiz questions and answers"
                : lang === "ar"
                  ? "أنشئ اختباراً بالإجابات الصحيحة"
                  : "Build quiz with correct answer(s)"}
            </p>
          </div>
        </div>
        <Button
          variant={showPreview ? "default" : "outline"}
          onClick={() => setShowPreview(!showPreview)}
        >
          {showPreview ? (
            <EyeOff className="me-2 h-4 w-4" />
          ) : (
            <Eye className="me-2 h-4 w-4" />
          )}
          {showPreview
            ? lang === "ar"
              ? "إخفاء المعاينة"
              : "Hide Preview"
            : lang === "ar"
              ? "معاينة"
              : "Preview"}
        </Button>
      </div>

      <div
        className={`grid gap-6 ${showPreview ? "lg:grid-cols-2" : "grid-cols-1"}`}
      >
        <div className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "معلومات أساسية" : "Basic Info"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>
                    {lang === "ar" ? "الاسم (إنجليزي)" : "Name (EN)"}
                  </Label>
                  <Input
                    value={formData.nameEn}
                    onChange={(e) =>
                      setFormData({ ...formData, nameEn: e.target.value })
                    }
                    placeholder={
                      lang === "ar" ? "عنوان الاختبار" : "Quiz title"
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "الاسم (عربي)" : "Name (AR)"}</Label>
                  <Input
                    value={formData.nameAr}
                    onChange={(e) =>
                      setFormData({ ...formData, nameAr: e.target.value })
                    }
                    placeholder="عنوان الاختبار"
                  />
                </div>
              </div>
            </CardContent>
          </Card>

          {caseId && selectedCase && (
            <Card>
              <CardHeader>
                <CardTitle>
                  {lang === "ar" ? "معلومات الحالة" : "Case Information"}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex items-center gap-2 text-sm">
                  <span className="font-medium">
                    {lang === "ar" ? "الحالة:" : "Case:"}
                  </span>
                  <span>{selectedCase.name}</span>
                </div>
              </CardContent>
            </Card>
          )}

          {(caseId || !isEditMode) && (
            <Card>
              <CardContent className="pt-6">
                <div className="flex items-center space-x-2">
                  <Checkbox
                    id="isTemplate"
                    checked={isTemplate}
                    onCheckedChange={(checked) =>
                      setIsTemplate(checked === true)
                    }
                  />
                  <label
                    htmlFor="isTemplate"
                    className="text-sm leading-none font-medium peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
                  >
                    {lang === "ar"
                      ? "حفظ كقالب (متاح للاستخدام المستقبلي)"
                      : "Save as template (available for future use)"}
                  </label>
                </div>
              </CardContent>
            </Card>
          )}

          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{lang === "ar" ? "الأسئلة" : "Questions"}</CardTitle>
              <Button size="sm" onClick={addQuestion}>
                <Plus className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة سؤال" : "Add Question"}
              </Button>
            </CardHeader>
            <CardContent>
              {questions.length === 0 ? (
                <p className="py-4 text-center text-muted-foreground">
                  {lang === "ar" ? "لا توجد أسئلة بعد." : "No questions yet."}
                </p>
              ) : (
                <DragList
                  items={questions}
                  onReorder={handleReorder}
                  renderItem={renderQuestionItem}
                  keyExtractor={(q) => q.id}
                />
              )}
            </CardContent>
          </Card>

          <div className="flex justify-end gap-4">
            <Button variant="outline" onClick={() => router.back()}>
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={
                !formData.nameEn || questions.length === 0 || isSubmitting
              }
            >
              {isSubmitting
                ? isEditMode
                  ? lang === "ar"
                    ? "جارٍ الحفظ..."
                    : "Saving..."
                  : lang === "ar"
                    ? "جارٍ الإنشاء..."
                    : "Creating..."
                : isEditMode
                  ? lang === "ar"
                    ? "حفظ التغييرات"
                    : "Save Changes"
                  : lang === "ar"
                    ? "إنشاء"
                    : "Create"}
            </Button>
          </div>
        </div>

        {showPreview && (
          <div className="sticky top-6 max-h-[calc(100vh-12rem)] overflow-auto rounded-lg border bg-card p-4">
            <p className="mb-4 text-sm font-semibold tracking-wider text-muted-foreground uppercase">
              {lang === "ar" ? "معاينة مباشرة" : "Live Preview"}
            </p>
            <MultipleChoicePreview
              config={{
                title: { en: formData.nameEn, ar: formData.nameAr },
                questions,
                media: [],
              }}
            />
          </div>
        )}
      </div>

      <MediaUpload
        open={uploadOpen}
        onOpenChange={setUploadOpen}
        onUpload={handleMediaUpload}
      />
    </div>
  )
}

"use client"

import { useEffect, useRef } from "react"
import { useRouter } from "next/navigation"
import { useLang } from "@/lib/lang-context"
import { useToolTypes } from "@/hooks/useToolTypes"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import Link from "next/link"
import {
  getToolTypeLabel,
  getToolTypeMeta,
  toolTypeOrder,
} from "@/lib/tool-types"

export default function NewToolPage() {
  const router = useRouter()
  const { lang } = useLang()
  const { toolTypes, fetchToolTypes } = useToolTypes()
  const hasFetched = useRef(false)

  useEffect(() => {
    if (hasFetched.current) return
    hasFetched.current = true
    fetchToolTypes()
  }, [fetchToolTypes])

  const visibleToolTypes = toolTypeOrder.flatMap((key) => {
    const toolType = toolTypes.find((item) => item.key === key)
    const meta = getToolTypeMeta(key)
    if (!toolType || !meta) return []

    return [
      {
        ...toolType,
        icon: meta.icon,
        href: `/dashboard/admin/tools/${meta.route}/new`,
      },
    ]
  })

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          ←
        </Button>
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {lang === "ar" ? "إنشاء أداة" : "Create Tool"}
          </h1>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? "اختر نوع الأداة لإنشائها"
              : "Select a tool type to create"}
          </p>
        </div>
      </div>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {visibleToolTypes.map((tool) => (
          <Link key={tool.id} href={tool.href}>
            <Card className="h-full cursor-pointer transition-all hover:shadow-md">
              <CardHeader>
                <div className="flex items-center gap-2">
                  <tool.icon className="h-5 w-5 text-primary" />
                  <CardTitle>{getToolTypeLabel(tool, lang)}</CardTitle>
                </div>
                {/* <CardDescription>
                  {tool.key.replaceAll("_", " ")}
                </CardDescription> */}
              </CardHeader>
            </Card>
          </Link>
        ))}
      </div>
    </div>
  )
}

"use client"

import { useState, useEffect, useRef, useCallback } from "react"
import { useRouter } from "next/navigation"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { toolTypesCollection } from "@/lib/pb-collections"
import { getErrorMessage } from "@/lib/pb"
import { toast } from "sonner"
import { formatDate } from "@/lib/format-date"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { DateInput } from "@/components/ui/date-input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Switch } from "@/components/ui/switch"
import { CaseSearchCombobox } from "@/components/case-search-combobox"
import { Calendar, Eye, EyeOff, Loader2 } from "lucide-react"
import { useLang } from "@/lib/lang-context"
import type { OneToOneMeetingConfig } from "@/types/tool"

export default function OneToOneMeetingNewPage({
  searchParams,
}: {
  searchParams: Promise<{ caseId?: string; edit?: string }>
}) {
  const router = useRouter()
  const { lang } = useLang()
  const { assignTool, updateAssignment, assignments, isLoading: isAssignmentsLoading } = useAssignments()
  const { getProfileById } = useProfiles()
  const [showPreview, setShowPreview] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [meetingTypeId, setMeetingTypeId] = useState<string>("")
  const [typeError, setTypeError] = useState<string>("")
  const [editAssignmentId, setEditAssignmentId] = useState<string>("")

  const [selectedCaseId, setSelectedCaseId] = useState("")
  const [isInitializing, setIsInitializing] = useState(true)
  const hasInitialized = useRef(false)

  const [toolName, setToolName] = useState({ en: "", ar: "" })

  const [meetingDate, setMeetingDate] = useState("")
  const [meetingTime, setMeetingTime] = useState("")
  const [meetingType, setMeetingType] = useState<"online" | "face_to_face">("online")
  const [meetingLink, setMeetingLink] = useState("")
  const [meetingLocation, setMeetingLocation] = useState("")
  const [adminNotes, setAdminNotes] = useState("")
  const [notesVisible, setNotesVisible] = useState(false)

  useEffect(() => {
    const fetchType = async () => {
      try {
        const meetingType = await toolTypesCollection.getByName("one_to_one_meeting")
        setMeetingTypeId(meetingType.id)
        setTypeError("")
      } catch (error) {
        setTypeError(
          getErrorMessage(error) ||
            (lang === "ar"
              ? 'نوع الأداة "one_to_one_meeting" غير موجود. يرجى الاتصال بالمسؤول.'
              : 'Tool type "one_to_one_meeting" not found. Please contact admin.')
        )
        console.error("Failed to fetch meeting type:", error)
      }
    }
    fetchType()
  }, [])

  const handleCaseSelect = useCallback((caseId: string) => {
    setSelectedCaseId(caseId)
    if (caseId) {
      const caseProfile = getProfileById(caseId)
      if (caseProfile) {
        setToolName({
          en: `${caseProfile.name} - One to One Meeting`,
          ar: `${caseProfile.name} - اجتماع فردي`,
        })
      }
    } else {
      setToolName({ en: "", ar: "" })
    }
  }, [getProfileById])

  useEffect(() => {
    if (isAssignmentsLoading) return
    if (hasInitialized.current) return

    const initFromUrl = async () => {
      try {
        const params = await searchParams
        const editId = params?.edit
        const caseIdFromUrl = params?.caseId

        if (editId) {
          setEditAssignmentId(editId)
          const existingAssignment = assignments.find((a) => a.id === editId)
          if (existingAssignment) {
            const config = existingAssignment.config as OneToOneMeetingConfig
            setSelectedCaseId(existingAssignment.case)
            setToolName({
              en: existingAssignment.name_en || "",
              ar: existingAssignment.name_ar || "",
            })
            setMeetingDate(config?.date || "")
            setMeetingTime(config?.time || "")
            setMeetingType(config?.meetingType || "online")
            setMeetingLink(config?.meetingLink || "")
            setMeetingLocation(config?.location || "")
            setAdminNotes(config?.notes || "")
            setNotesVisible(config?.notesVisibleToUser || false)
          }
        } else if (caseIdFromUrl) {
          handleCaseSelect(caseIdFromUrl)
        }
      } catch (e) {
        console.error("Failed to read searchParams:", e)
        toast.error(getErrorMessage(e))
      } finally {
        setIsInitializing(false)
        hasInitialized.current = true
      }
    }
    initFromUrl()
  }, [isAssignmentsLoading, assignments, searchParams, handleCaseSelect])

  const handleSubmit = async () => {
    if (!selectedCaseId || !toolName.en || !meetingDate || !meetingTime || !meetingTypeId) return
    setIsSubmitting(true)

    try {
      const config: OneToOneMeetingConfig = {
        date: meetingDate,
        time: meetingTime,
        meetingType,
        meetingLink: meetingType === "online" ? meetingLink : undefined,
        location: meetingType === "face_to_face" ? meetingLocation || undefined : undefined,
        notes: adminNotes || undefined,
        notesVisibleToUser: notesVisible,
        media: [],
      }

      if (editAssignmentId) {
        await updateAssignment(editAssignmentId, {
          name_en: toolName.en,
          name_ar: toolName.ar,
          config,
        })
        router.push(`/dashboard/admin/assignments/${editAssignmentId}`)
      } else {
        await assignTool({
          case: selectedCaseId,
          type: meetingTypeId,
          name_en: toolName.en,
          name_ar: toolName.ar,
          is_not_template: true,
          config,
          is_visible_to_user: true,
          status: "pending",
        })
        router.push("/dashboard/admin/assignments")
      }
    } catch (error) {
      console.error(editAssignmentId ? "Failed to update meeting:" : "Failed to create meeting:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleCancel = () => {
    if (editAssignmentId) {
      router.push(`/dashboard/admin/assignments/${editAssignmentId}`)
    } else {
      setSelectedCaseId("")
      setToolName({ en: "", ar: "" })
      setMeetingDate("")
      setMeetingTime("")
      setMeetingType("online")
      setMeetingLink("")
      setMeetingLocation("")
      setAdminNotes("")
      setNotesVisible(false)
      setShowPreview(false)
    }
  }

  const isFormValid = selectedCaseId && toolName.en && meetingDate && meetingTime && meetingTypeId

  if (typeError) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-destructive">{typeError}</p>
      </div>
    )
  }

  if (isInitializing) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جارٍ التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {editAssignmentId
              ? lang === "ar"
                ? "تعديل اجتماع فردي"
                : "Edit One to One Meeting"
              : lang === "ar"
                ? "إنشاء اجتماع فردي"
                : "Create One to One Meeting"}
          </h1>
          <p className="text-muted-foreground">
            {editAssignmentId
              ? lang === "ar"
                ? "تحديث الاجتماع لقضية محددة"
                : "Update the meeting for a specific case"
              : lang === "ar"
                ? "إنشاء اجتماع لقضية محددة"
                : "Create a meeting for a specific case"}
          </p>
        </div>
        <Button
          variant={showPreview ? "default" : "outline"}
          onClick={() => setShowPreview(!showPreview)}
        >
          {showPreview ? (
            <EyeOff className="me-2 h-4 w-4" />
          ) : (
            <Eye className="me-2 h-4 w-4" />
          )}
          {showPreview
            ? lang === "ar"
              ? "إخفاء المعاينة"
              : "Hide Preview"
            : lang === "ar"
              ? "معاينة"
              : "Preview"}
        </Button>
      </div>

      {typeError && (
        <div className="rounded-lg border border-destructive bg-destructive/10 p-4 text-destructive">
          {typeError}
        </div>
      )}

      <div className={`grid gap-6 ${showPreview ? "lg:grid-cols-2" : "grid-cols-1"}`}>
        <div className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "اختر قضية *" : "Select Case *"}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <CaseSearchCombobox
                value={selectedCaseId}
                onChange={handleCaseSelect}
                placeholder={lang === "ar" ? "اختر قضية..." : "Select a case..."}
                disabled={!!editAssignmentId}
              />
              {!selectedCaseId && (
                <p className="mt-2 text-sm text-destructive">
                  {lang === "ar"
                    ? "يرجى اختيار قضية للمتابعة"
                    : "Please select a case to continue"}
                </p>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "اسم الاجتماع *" : "Meeting Name *"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "الاسم (إنجليزي)" : "Name (EN)"}</Label>
                  <Input
                    value={toolName.en}
                    onChange={(e) => setToolName({ ...toolName, en: e.target.value })}
                    placeholder={
                      lang === "ar"
                        ? "مثال: اجتماع التقييم الأولي"
                        : "e.g., Initial Assessment Meeting"
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "الاسم (عربي)" : "Name (AR)"}</Label>
                  <Input
                    value={toolName.ar}
                    onChange={(e) => setToolName({ ...toolName, ar: e.target.value })}
                    placeholder="مثال: اجتماع التقييم الأولي"
                  />
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "جدول الاجتماع *" : "Meeting Schedule *"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "التاريخ *" : "Date *"}</Label>
                  <DateInput
                    required
                    value={meetingDate}
                    onChange={setMeetingDate}
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "الوقت *" : "Time *"}</Label>
                  <Input
                    type="time"
                    required
                    value={meetingTime}
                    onChange={(e) => setMeetingTime(e.target.value)}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label>{lang === "ar" ? "نوع الاجتماع *" : "Meeting Type *"}</Label>
                <RadioGroup
                  value={meetingType}
                  onValueChange={(val) => setMeetingType(val as "online" | "face_to_face")}
                  className="flex gap-4"
                >
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="online" id="online" />
                    <Label htmlFor="online">
                      {lang === "ar" ? "عن بعد" : "Online"}
                    </Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="face_to_face" id="face_to_face" />
                    <Label htmlFor="face_to_face">
                      {lang === "ar" ? "حضوري" : "Face to Face"}
                    </Label>
                  </div>
                </RadioGroup>
              </div>

              {meetingType === "online" ? (
                <div className="space-y-2">
                  <Label>
                    {lang === "ar" ? "رابط الاجتماع *" : "Meeting Link *"}
                  </Label>
                  <Input
                    value={meetingLink}
                    onChange={(e) => setMeetingLink(e.target.value)}
                    placeholder="https://meet.google.com/..."
                  />
                </div>
              ) : (
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "الموقع" : "Location"}</Label>
                  <Input
                    value={meetingLocation}
                    onChange={(e) => setMeetingLocation(e.target.value)}
                    placeholder={
                      lang === "ar"
                        ? "مثال: غرفة 201، المبنى الرئيسي"
                        : "e.g., Room 201, Main Building"
                    }
                  />
                </div>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "ملاحظات إدارية" : "Admin Notes"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <Textarea
                value={adminNotes}
                onChange={(e) => setAdminNotes(e.target.value)}
                placeholder={
                  lang === "ar"
                    ? "أضف ملاحظات داخلية حول هذا الاجتماع..."
                    : "Add internal notes about this meeting..."
                }
                rows={3}
              />
              <div className="flex items-center gap-2">
                <Switch
                  id="notes-visible"
                  checked={notesVisible}
                  onCheckedChange={setNotesVisible}
                />
                <Label htmlFor="notes-visible" className="text-sm text-muted-foreground">
                  {lang === "ar" ? "إظهار الملاحظات للمستخدم" : "Show notes to user"}
                </Label>
              </div>
            </CardContent>
          </Card>

          <div className="flex justify-end gap-4">
            <Button variant="outline" onClick={handleCancel}>
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={!isFormValid || isSubmitting}
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  {editAssignmentId
                    ? lang === "ar"
                      ? "جارٍ الحفظ..."
                      : "Saving..."
                    : lang === "ar"
                      ? "جارٍ الإنشاء..."
                      : "Creating..."}
                </>
              ) : editAssignmentId ? (
                lang === "ar" ? "حفظ التغييرات" : "Save Changes"
              ) : lang === "ar" ? (
                "إنشاء اجتماع"
              ) : (
                "Create Meeting"
              )}
            </Button>
          </div>
        </div>

        {showPreview && (
          <div className="sticky top-6 max-h-[calc(100vh-12rem)] overflow-auto rounded-lg border bg-card p-4">
            <p className="mb-4 text-sm font-semibold tracking-wider text-muted-foreground uppercase">
              {lang === "ar" ? "معاينة مباشرة" : "Live Preview"}
            </p>
            <div className="space-y-4">
              <div className="flex items-center gap-2 text-lg font-semibold">
                <Calendar className="h-5 w-5 text-primary" />
                {toolName.en ||
                  (lang === "ar" ? "اجتماع فردي" : "One to One Meeting")}
              </div>
              <div className="rounded-lg border bg-muted/30 p-4 space-y-3">
                <div className="grid grid-cols-2 gap-2 text-sm">
                  <span className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ:" : "Date:"}
                  </span>
                  <span>{meetingDate ? formatDate(meetingDate) : "—"}</span>
                  <span className="text-muted-foreground">
                    {lang === "ar" ? "الوقت:" : "Time:"}
                  </span>
                  <span>{meetingTime || "—"}</span>
                  <span className="text-muted-foreground">
                    {lang === "ar" ? "النوع:" : "Type:"}
                  </span>
                  <span>
                    {meetingType === "online"
                      ? lang === "ar"
                        ? "عن بعد"
                        : "Online"
                      : lang === "ar"
                        ? "حضوري"
                        : "Face to Face"}
                  </span>
                  {meetingType === "online" && (
                    <>
                      <span className="text-muted-foreground">
                        {lang === "ar" ? "الرابط:" : "Link:"}
                      </span>
                      <span className="truncate">{meetingLink || "—"}</span>
                    </>
                  )}
                  {meetingType === "face_to_face" && (
                    <>
                      <span className="text-muted-foreground">
                        {lang === "ar" ? "الموقع:" : "Location:"}
                      </span>
                      <span>{meetingLocation || "—"}</span>
                    </>
                  )}
                </div>
                {adminNotes && (
                  <div className="pt-2 border-t text-sm">
                    <span className="text-muted-foreground">
                      {lang === "ar" ? "الملاحظات:" : "Notes:"}
                    </span>
                    <p className="mt-1 whitespace-pre-wrap">{adminNotes}</p>
                    <p className="mt-1 text-xs text-muted-foreground">
                      {notesVisible
                        ? lang === "ar"
                          ? "مرئية للمستخدم"
                          : "Visible to user"
                        : lang === "ar"
                          ? "للمسؤول فقط"
                          : "Admin only"}
                    </p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import { useEffect, useState, useRef, useCallback } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { useAuth } from "@/hooks/useAuth"
import { toolTypesCollection } from "@/lib/pb-collections"
import { getErrorMessage } from "@/lib/pb"
import { toast } from "sonner"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { DateInput } from "@/components/ui/date-input"
import { Label } from "@/components/ui/label"
import { Checkbox } from "@/components/ui/checkbox"
import { DragList } from "@/components/ui/drag-list"
import { CaseSearchCombobox } from "@/components/case-search-combobox"
import { PlanPreview } from "@/components/tool-renderers/PlanPreview"
import { Plus, Trash2, Eye, EyeOff, GripVertical } from "lucide-react"
import { useLang } from "@/lib/lang-context"
import type { PlanConfig } from "@/types/tool"

function generateId(): string {
  return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
}

// Simple interfaces for admin form (non-bilingual except plan name)
interface SimplePlanGoal {
  id: string
  title: string
  description: string
  order: number
}

interface SimplePlanStep {
  id: string
  goalId?: string
  title: string
  description: string
  notes: string
  comments: string
  dateOfAchievement: string
  evaluation: string
  completed: boolean
  order: number
}

export default function PlanBuilderPage({
  searchParams,
}: {
  searchParams: Promise<{ caseId?: string; edit?: string }>
}) {
  const router = useRouter()
  const { lang } = useLang()
  const { assignTool, updateAssignment, assignments, isLoading: isAssignmentsLoading } = useAssignments()
  const { getProfileById } = useProfiles()
  const { currentUser } = useAuth()
  const [editAssignmentId, setEditAssignmentId] = useState<string>("")
  const [showPreview, setShowPreview] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [planTypeId, setPlanTypeId] = useState<string>("")
  const [typeError, setTypeError] = useState<string>("")

  const [selectedCaseId, setSelectedCaseId] = useState("")
  const [isInitializing, setIsInitializing] = useState(true)
  const hasInitialized = useRef(false)

  // Tool name for this specific plan instance (only bilingual field)
  const [toolName, setToolName] = useState({
    en: "",
    ar: "",
  })

  const [formData, setFormData] = useState({
    childName: "",
    expertName: "",
    startDate: "",
    endDate: "",
  })

  const [goals, setGoals] = useState<SimplePlanGoal[]>([])
  const [steps, setSteps] = useState<SimplePlanStep[]>([])

  // Fetch plan type ID on mount
  useEffect(() => {
    const fetchPlanType = async () => {
      try {
        const planType = await toolTypesCollection.getByName("plan")
        setPlanTypeId(planType.id)
        setTypeError("")
      } catch (error) {
        setTypeError(
          getErrorMessage(error) ||
            (lang === "ar"
              ? 'نوع الأداة "plan" غير موجود. يرجى الاتصال بالمسؤول.'
              : 'Tool type "plan" not found. Please contact admin.')
        )
        console.error("Failed to fetch plan type:", error)
      }
    }
    fetchPlanType()
  }, [])

  // Update expert name when currentUser loads
  useEffect(() => {
    if (currentUser?.name) {
      setFormData((prev) => ({
        ...prev,
        expertName: currentUser.name,
      }))
    }
  }, [currentUser])

  const handleCaseSelect = useCallback((caseId: string) => {
    setSelectedCaseId(caseId)
    if (caseId) {
      const caseProfile = getProfileById(caseId)
      if (caseProfile) {
        setFormData((prev) => ({
          ...prev,
          childName: caseProfile.name,
        }))
        // Auto-generate tool name if empty
        setToolName((prev) => ({
          en: prev.en || `${caseProfile.name} - Plan`,
          ar: prev.ar || `${caseProfile.name} - خطة`,
        }))
      }
    } else {
      // Reset fields when case is cleared
      setFormData((prev) => ({
        ...prev,
        childName: "",
      }))
    }
  }, [getProfileById])

  // Initialize from URL caseId - runs once after assignments load
  useEffect(() => {
    if (isAssignmentsLoading) return
    if (hasInitialized.current) return

    const initFromUrl = async () => {
      try {
        const params = await searchParams
        const editId = params?.edit
        const caseIdFromUrl = params?.caseId

        // Edit mode - load existing assignment
        if (editId) {
          setEditAssignmentId(editId)
          const existingAssignment = assignments.find((a) => a.id === editId)
          if (existingAssignment) {
            const config = existingAssignment.config as PlanConfig
            setSelectedCaseId(existingAssignment.case)
            setToolName({
              en: existingAssignment.name_en || "",
              ar: existingAssignment.name_ar || "",
            })
            setFormData({
              childName: config?.childName || "",
              expertName: config?.expertName || "",
              startDate: config?.startDate || "",
              endDate: config?.endDate || "",
            })
            setGoals(
              (config?.goals || []).map((g) => ({
                id: g.id,
                title: g.title,
                description: g.description || "",
                order: g.order,
              }))
            )
            setSteps(
              (config?.steps || []).map((s, idx) => ({
                id: s.id,
                title: s.title,
                description: s.description || "",
                notes: s.notes || "",
                comments: s.comments || "",
                dateOfAchievement: s.dateOfAchievement || "",
                evaluation: s.evaluation || "",
                completed: s.completed,
                order: idx,
              }))
            )
          }
        } else if (caseIdFromUrl) {
          handleCaseSelect(caseIdFromUrl)
        }
      } catch (e) {
        console.error("Failed to read searchParams:", e)
        toast.error(getErrorMessage(e))
      } finally {
        setIsInitializing(false)
        hasInitialized.current = true
      }
    }
    initFromUrl()
  }, [isAssignmentsLoading, assignments, searchParams, handleCaseSelect])

  const addGoal = () => {
    setGoals([
      ...goals,
      {
        id: generateId(),
        title: "",
        description: "",
        order: goals.length,
      },
    ])
  }

  const updateGoal = (id: string, updates: Partial<SimplePlanGoal>) => {
    setGoals(goals.map((g) => (g.id === id ? { ...g, ...updates } : g)))
  }

  const removeGoal = (id: string) => {
    setGoals(goals.filter((g) => g.id !== id))
  }

  const handleGoalReorder = (reordered: SimplePlanGoal[]) => {
    setGoals(reordered.map((g, idx) => ({ ...g, order: idx })))
  }

  const addStep = () => {
    setSteps([
      ...steps,
      {
        id: generateId(),
        title: "",
        description: "",
        notes: "",
        comments: "",
        dateOfAchievement: "",
        evaluation: "",
        completed: false,
        order: steps.length,
      },
    ])
  }

  const updateStep = (id: string, updates: Partial<SimplePlanStep>) => {
    setSteps(steps.map((s) => (s.id === id ? { ...s, ...updates } : s)))
  }

  const removeStep = (id: string) => {
    setSteps(steps.filter((s) => s.id !== id))
  }

  const handleStepReorder = (reordered: SimplePlanStep[]) => {
    setSteps(reordered.map((s, idx) => ({ ...s, order: idx })))
  }

  const handleSubmit = async () => {
    if (
      !toolName.en ||
      !formData.childName ||
      !formData.expertName ||
      !formData.startDate ||
      !formData.endDate ||
      !selectedCaseId ||
      !planTypeId
    )
      return
    setIsSubmitting(true)

    try {
      // Convert simple form data to bilingual config for storage
      const config: PlanConfig = {
        childName: formData.childName,
        expertName: formData.expertName,
        startDate: formData.startDate,
        endDate: formData.endDate,
        goals: goals.map((g, idx) => ({
          id: g.id,
          title: g.title,
          description: g.description,
          order: idx,
        })),
        steps: steps.map((s) => ({
          id: s.id,
          title: s.title,
          description: s.description,
          notes: s.notes,
          comments: s.comments,
          dateOfAchievement: s.dateOfAchievement || undefined,
          evaluation: s.evaluation,
          completed: s.completed,
        })),
        media: [],
      }

      // Edit mode - update existing assignment
      if (editAssignmentId) {
        await updateAssignment(editAssignmentId, {
          name_en: toolName.en,
          name_ar: toolName.ar,
          config,
        })
        router.push(`/dashboard/admin/assignments/${editAssignmentId}`)
      } else {
        // Create case document directly in case_tools (no tool template)
        await assignTool({
          case: selectedCaseId,
          type: planTypeId,
          name_en: toolName.en,
          name_ar: toolName.ar,
          is_not_template: true,
          config,
          is_visible_to_user: true,
          status: "pending",
        })

        router.push("/dashboard/admin/assignments")
      }
    } catch (error) {
      console.error(editAssignmentId ? "Failed to update plan:" : "Failed to create plan:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleCancel = () => {
    if (editAssignmentId) {
      router.push(`/dashboard/admin/assignments/${editAssignmentId}`)
    } else {
      // Reset form
      setSelectedCaseId("")
      setToolName({ en: "", ar: "" })
      setFormData({
        childName: "",
        expertName: currentUser?.name || "",
        startDate: "",
        endDate: "",
      })
      setGoals([])
      setSteps([])
      setShowPreview(false)
    }
  }

  const renderGoalItem = (goal: SimplePlanGoal, index: number) => (
    <div className="flex-1 space-y-3">
      <div className="flex items-center justify-between">
        <span className="text-sm font-medium">
          {lang === "ar" ? "هدف" : "Goal"} {index + 1}
        </span>
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={() => removeGoal(goal.id)}
        >
          <Trash2 className="h-4 w-4 text-destructive" />
        </Button>
      </div>
      <div className="space-y-2">
        <Input
          placeholder={lang === "ar" ? "عنوان الهدف" : "Goal Title"}
          value={goal.title}
          onChange={(e) => updateGoal(goal.id, { title: e.target.value })}
        />
        <Input
          placeholder={lang === "ar" ? "الوصف" : "Description"}
          value={goal.description}
          onChange={(e) => updateGoal(goal.id, { description: e.target.value })}
        />
      </div>
    </div>
  )

  const renderStepItem = (step: SimplePlanStep, index: number) => (
    <div className="flex-1 space-y-3 rounded border p-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Checkbox
            checked={step.completed}
            onCheckedChange={(checked) =>
              updateStep(step.id, { completed: !!checked })
            }
          />
          <span className="font-medium">
            {lang === "ar" ? "خطوة" : "Step"} {index + 1}
          </span>
        </div>
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={() => removeStep(step.id)}
        >
          <Trash2 className="h-4 w-4 text-destructive" />
        </Button>
      </div>

      <div className="space-y-3">
        <Input
          placeholder={lang === "ar" ? "عنوان الخطوة" : "Step Title"}
          value={step.title}
          onChange={(e) => updateStep(step.id, { title: e.target.value })}
        />
        <Input
          placeholder={lang === "ar" ? "الوصف" : "Description"}
          value={step.description}
          onChange={(e) => updateStep(step.id, { description: e.target.value })}
        />

        {/* Fields matching preview layout */}
        <div className="grid gap-2 sm:grid-cols-2">
          <Input
            placeholder={lang === "ar" ? "ملاحظات" : "Notes"}
            value={step.notes}
            onChange={(e) => updateStep(step.id, { notes: e.target.value })}
          />
          <Input
            placeholder={lang === "ar" ? "تعليقات" : "Comments"}
            value={step.comments}
            onChange={(e) => updateStep(step.id, { comments: e.target.value })}
          />
        </div>
        <div className="grid gap-2 sm:grid-cols-2">
          <DateInput
            placeholder={
              lang === "ar" ? "تاريخ الإنجاز" : "Date of Achievement"
            }
            value={step.dateOfAchievement}
            onChange={(v) =>
              updateStep(step.id, { dateOfAchievement: v })
            }
          />
          <Input
            placeholder={lang === "ar" ? "التقييم" : "Evaluation"}
            value={step.evaluation}
            onChange={(e) =>
              updateStep(step.id, { evaluation: e.target.value })
            }
          />
        </div>
      </div>
    </div>
  )

  if (typeError) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-destructive">{typeError}</p>
      </div>
    )
  }

  if (isInitializing) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جارٍ التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {editAssignmentId
              ? lang === "ar"
                ? "تعديل الخطة"
                : "Edit Plan"
              : lang === "ar"
                ? "إنشاء خطة"
                : "Create Plan"}
          </h1>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? "إنشاء خطة لقضية محددة"
              : "Create a plan for a specific case"}
          </p>
        </div>
        <Button
          variant={showPreview ? "default" : "outline"}
          onClick={() => setShowPreview(!showPreview)}
        >
          {showPreview ? (
            <EyeOff className="me-2 h-4 w-4" />
          ) : (
            <Eye className="me-2 h-4 w-4" />
          )}
          {showPreview
            ? lang === "ar"
              ? "إخفاء المعاينة"
              : "Hide Preview"
            : lang === "ar"
              ? "معاينة"
              : "Preview"}
        </Button>
      </div>

      {typeError && (
        <div className="rounded-lg border border-destructive bg-destructive/10 p-4 text-destructive">
          {typeError}
        </div>
      )}

      <div
        className={`grid gap-6 ${showPreview ? "lg:grid-cols-2" : "grid-cols-1"}`}
      >
        <div className="space-y-6">
          {/* Case Selection */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "اختيار القضية *" : "Case Selection *"}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <CaseSearchCombobox
                value={selectedCaseId}
                onChange={handleCaseSelect}
                placeholder={lang === "ar" ? "اختر قضية..." : "Select a case..."}
                disabled={!!editAssignmentId}
              />
            </CardContent>
          </Card>

          {/* Plan Name - Only bilingual field */}
          <Card>
            <CardHeader>
              <CardTitle>{lang === "ar" ? "اسم الخطة *" : "Plan Name *"}</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "الاسم (إنجليزي)" : "Name (EN)"}</Label>
                  <Input
                    value={toolName.en}
                    onChange={(e) =>
                      setToolName({ ...toolName, en: e.target.value })
                    }
                    placeholder={
                      lang === "ar"
                        ? "مثال: خطة تطوير جون"
                        : "e.g., John's Development Plan"
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "الاسم (عربي)" : "Name (AR)"}</Label>
                  <Input
                    value={toolName.ar}
                    onChange={(e) =>
                      setToolName({ ...toolName, ar: e.target.value })
                    }
                    placeholder="مثال: خطة تطوير جون"
                  />
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Child & Expert Info - Single fields */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar"
                  ? "معلومات الطفل والخبير"
                  : "Child & Expert Information"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "اسم الطفل" : "Child Name"}</Label>
                  <Input
                    value={formData.childName}
                    onChange={(e) =>
                      setFormData({ ...formData, childName: e.target.value })
                    }
                    placeholder={lang === "ar" ? "اسم الطفل" : "Child name"}
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "اسم الخبير" : "Expert Name"}</Label>
                  <Input
                    value={formData.expertName}
                    onChange={(e) =>
                      setFormData({ ...formData, expertName: e.target.value })
                    }
                    placeholder={lang === "ar" ? "اسم الخبير" : "Expert name"}
                  />
                </div>
              </div>
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "تاريخ البداية" : "Start Date"}</Label>
                  <DateInput
                    value={formData.startDate}
                    onChange={(v) =>
                      setFormData({ ...formData, startDate: v })
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "تاريخ النهاية" : "End Date"}</Label>
                  <DateInput
                    value={formData.endDate}
                    onChange={(v) =>
                      setFormData({ ...formData, endDate: v })
                    }
                  />
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Goals - Single fields */}
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{lang === "ar" ? "الأهداف" : "Goals"}</CardTitle>
              <Button size="sm" onClick={addGoal}>
                <Plus className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة هدف" : "Add Goal"}
              </Button>
            </CardHeader>
            <CardContent>
              {goals.length === 0 ? (
                <p className="py-4 text-center text-muted-foreground">
                  {lang === "ar"
                    ? "لا توجد أهداف بعد. انقر على إضافة هدف لإنشاء واحد."
                    : "No goals yet. Click Add Goal to create one."}
                </p>
              ) : (
                <DragList
                  items={goals}
                  onReorder={handleGoalReorder}
                  renderItem={renderGoalItem}
                  keyExtractor={(g) => g.id}
                />
              )}
            </CardContent>
          </Card>

          {/* Steps - With all fields matching preview */}
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{lang === "ar" ? "الخطوات" : "Steps"}</CardTitle>
              <Button size="sm" onClick={addStep}>
                <Plus className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة خطوة" : "Add Step"}
              </Button>
            </CardHeader>
            <CardContent>
              {steps.length === 0 ? (
                <p className="py-4 text-center text-muted-foreground">
                  {lang === "ar"
                    ? "لا توجد خطوات بعد. انقر على إضافة خطوة لإنشاء واحدة."
                    : "No steps yet. Click Add Step to create one."}
                </p>
              ) : (
                <DragList
                  items={steps}
                  onReorder={handleStepReorder}
                  renderItem={renderStepItem}
                  keyExtractor={(s) => s.id}
                />
              )}
            </CardContent>
          </Card>

          <div className="flex justify-end gap-4">
            <Button variant="outline" onClick={handleCancel}>
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={
                !toolName.en ||
                !formData.childName ||
                !formData.startDate ||
                !formData.endDate ||
                !selectedCaseId ||
                !planTypeId ||
                isSubmitting
              }
            >
              {isSubmitting
                ? editAssignmentId
                  ? lang === "ar"
                    ? "جارٍ الحفظ..."
                    : "Saving..."
                  : lang === "ar"
                    ? "جارٍ الإنشاء..."
                    : "Creating..."
                : editAssignmentId
                  ? lang === "ar"
                    ? "حفظ التغييرات"
                    : "Save Changes"
                  : lang === "ar"
                    ? "إنشاء خطة"
                    : "Create Plan"}
            </Button>
          </div>
        </div>

        {showPreview && (
          <div className="sticky top-6 max-h-[calc(100vh-12rem)] overflow-auto rounded-lg border bg-card p-4">
            <p className="mb-4 text-sm font-semibold tracking-wider text-muted-foreground uppercase">
              {lang === "ar" ? "معاينة مباشرة" : "Live Preview"}
            </p>
            <PlanPreview
              config={{
                childName: formData.childName,
                expertName: formData.expertName,
                startDate: formData.startDate,
                endDate: formData.endDate,
                goals: goals.map((g) => ({
                  id: g.id,
                  title: g.title,
                  description: g.description,
                  order: g.order,
                })),
                steps: steps.map((s) => ({
                  id: s.id,
                  title: s.title,
                  description: s.description,
                  notes: s.notes,
                  comments: s.comments,
                  dateOfAchievement: s.dateOfAchievement || undefined,
                  evaluation: s.evaluation,
                  completed: s.completed,
                })),
                media: [],
              }}
            />
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import { useState, useEffect, useRef, useCallback } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { useAssignments } from "@/hooks/useAssignments"
import { useProfiles } from "@/hooks/useProfiles"
import { useAuth } from "@/hooks/useAuth"
import { toolTypesCollection } from "@/lib/pb-collections"
import { getErrorMessage } from "@/lib/pb"
import { toast } from "sonner"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { DateInput } from "@/components/ui/date-input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { CaseSearchCombobox } from "@/components/case-search-combobox"
import { ReportPreview } from "@/components/tool-renderers/ReportPreview"
import { Eye, EyeOff } from "lucide-react"
import { useLang } from "@/lib/lang-context"
import type { ReportConfig } from "@/types/tool"

export default function ReportBuilderPage({
  searchParams,
}: {
  searchParams: Promise<{ caseId?: string; edit?: string }>
}) {
  const router = useRouter()
  const { lang } = useLang()
  const { assignTool, updateAssignment, assignments, isLoading: isAssignmentsLoading } = useAssignments()
  const { getProfileById } = useProfiles()
  const { currentUser } = useAuth()
  const [showPreview, setShowPreview] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [reportTypeId, setReportTypeId] = useState<string>("")
  const [typeError, setTypeError] = useState<string>("")
  const [editAssignmentId, setEditAssignmentId] = useState<string>("")

  const [selectedCaseId, setSelectedCaseId] = useState("")
  const [isInitializing, setIsInitializing] = useState(true)
  const hasInitialized = useRef(false)

  // Child name - from case selection
  const [childName, setChildName] = useState("")

  // Report name (bilingual) - goes directly to name_en/name_ar
  const [reportName, setReportName] = useState({
    en: "",
    ar: "",
  })

  // Expert name - single field, auto-filled from auth
  const [expertName, setExpertName] = useState("")

  // Fixed fields - stored in config
  const [fixedFields, setFixedFields] = useState({
    date: "",
    assessment: "",
    suggestions: "",
  })

  // Fetch report type ID on mount
  useEffect(() => {
    const fetchReportType = async () => {
      try {
        const reportType = await toolTypesCollection.getByName("report")
        setReportTypeId(reportType.id)
        setTypeError("")
      } catch (error) {
        setTypeError(
          getErrorMessage(error) ||
            (lang === "ar"
              ? 'نوع الأداة "report" غير موجود. يرجى الاتصال بالمسؤول.'
              : 'Tool type "report" not found. Please contact admin.')
        )
        console.error("Failed to fetch report type:", error)
      }
    }
    fetchReportType()
  }, [])

  // Auto-fill expert name when currentUser loads
  useEffect(() => {
    if (currentUser?.name) {
      setExpertName(currentUser.name)
    }
  }, [currentUser])

  const handleCaseSelect = useCallback((caseId: string) => {
    setSelectedCaseId(caseId)
    if (caseId) {
      const caseProfile = getProfileById(caseId)
      if (caseProfile) {
        // Auto-populate child name and report name
        setChildName(caseProfile.name)
        setReportName({
          en: `${caseProfile.name} - Report`,
          ar: `${caseProfile.name} - تقرير`,
        })
      }
    } else {
      // Reset name fields when case is cleared
      setChildName("")
      setReportName({ en: "", ar: "" })
    }
  }, [getProfileById])

  // Initialize from URL caseId - runs once after assignments load
  useEffect(() => {
    if (isAssignmentsLoading) return
    if (hasInitialized.current) return

    const initFromUrl = async () => {
      try {
        const params = await searchParams
        const editId = params?.edit
        const caseIdFromUrl = params?.caseId

        // Edit mode - load existing assignment
        if (editId) {
          setEditAssignmentId(editId)
          const existingAssignment = assignments.find((a) => a.id === editId)
          if (existingAssignment) {
            const config = existingAssignment.config as ReportConfig
            setSelectedCaseId(existingAssignment.case)
            setReportName({
              en: existingAssignment.name_en || "",
              ar: existingAssignment.name_ar || "",
            })
            setChildName(config?.childName || "")
            setExpertName(config?.expertName || "")
            setFixedFields({
              date: config?.date || "",
              assessment: config?.assessment || "",
              suggestions: config?.suggestions || "",
            })
          }
        } else if (caseIdFromUrl) {
          handleCaseSelect(caseIdFromUrl)
        }
      } catch (e) {
        console.error("Failed to read searchParams:", e)
        toast.error(getErrorMessage(e))
      } finally {
        setIsInitializing(false)
        hasInitialized.current = true
      }
    }
    initFromUrl()
  }, [isAssignmentsLoading, assignments, searchParams, handleCaseSelect])

  const handleSubmit = async () => {
    if (!selectedCaseId || !reportName.en || !expertName || !reportTypeId)
      return
    setIsSubmitting(true)

    try {
      // Store fixed fields in config
      const config: ReportConfig = {
        title: { en: reportName.en, ar: reportName.ar },
        childName: childName,
        expertName: expertName,
        customFields: [],
        media: [],
        date: fixedFields.date || undefined,
        assessment: fixedFields.assessment,
        suggestions: fixedFields.suggestions,
      }

      // Edit mode - update existing assignment
      if (editAssignmentId) {
        await updateAssignment(editAssignmentId, {
          name_en: reportName.en,
          name_ar: reportName.ar,
          config,
        })
        router.push(`/dashboard/admin/assignments/${editAssignmentId}`)
      } else {
        // Create case document directly in case_tools (no tool template)
        await assignTool({
          case: selectedCaseId,
          type: reportTypeId,
          name_en: reportName.en,
          name_ar: reportName.ar,
          is_not_template: true,
          config,
          is_visible_to_user: true,
          status: "completed",
        })

        // Redirect to assignments page
        router.push(`/dashboard/admin/assignments`)
      }
    } catch (error) {
      console.error(editAssignmentId ? "Failed to update report:" : "Failed to create report:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleCancel = () => {
    if (editAssignmentId) {
      router.push(`/dashboard/admin/assignments/${editAssignmentId}`)
    } else {
      // Reset form
      setSelectedCaseId("")
      setReportName({ en: "", ar: "" })
      setExpertName(currentUser?.name || "")
      setChildName("")
      setFixedFields({
        date: "",
        assessment: "",
        suggestions: "",
      })
      setShowPreview(false)
    }
  }

  const isFormValid =
    selectedCaseId && reportName.en && expertName && reportTypeId

  if (typeError) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-destructive">{typeError}</p>
      </div>
    )
  }

  if (isInitializing) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جارٍ التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {editAssignmentId
              ? lang === "ar"
                ? "تعديل التقرير"
                : "Edit Report"
              : lang === "ar"
                ? "إنشاء تقرير"
                : "Create Report"}
          </h1>
          <p className="text-muted-foreground">
            {lang === "ar"
              ? "إنشاء تقرير لقضية محددة"
              : "Create a report for a specific case"}
          </p>
        </div>
        <Button
          variant={showPreview ? "default" : "outline"}
          onClick={() => setShowPreview(!showPreview)}
        >
          {showPreview ? (
            <EyeOff className="me-2 h-4 w-4" />
          ) : (
            <Eye className="me-2 h-4 w-4" />
          )}
          {showPreview
            ? lang === "ar"
              ? "إخفاء المعاينة"
              : "Hide Preview"
            : lang === "ar"
              ? "معاينة"
              : "Preview"}
        </Button>
      </div>

      {typeError && (
        <div className="rounded-lg border border-destructive bg-destructive/10 p-4 text-destructive">
          {typeError}
        </div>
      )}

      <div
        className={`grid gap-6 ${showPreview ? "lg:grid-cols-2" : "grid-cols-1"}`}
      >
        <div className="space-y-6">
          {/* Case Selection */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "اختر قضية *" : "Select Case *"}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <CaseSearchCombobox
                value={selectedCaseId}
                onChange={handleCaseSelect}
                placeholder={lang === "ar" ? "اختر قضية..." : "Select a case..."}
                disabled={!!editAssignmentId}
              />
              {!selectedCaseId && (
                <p className="mt-2 text-sm text-destructive">
                  {lang === "ar"
                    ? "يرجى اختيار قضية للمتابعة"
                    : "Please select a case to continue"}
                </p>
              )}
            </CardContent>
          </Card>

          {/* Report Name - Bilingual (goes to name_en/name_ar) */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "اسم التقرير *" : "Report Name *"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "الاسم (إنجليزي)" : "Name (EN)"}</Label>
                  <Input
                    value={reportName.en}
                    onChange={(e) =>
                      setReportName({ ...reportName, en: e.target.value })
                    }
                    placeholder={
                      lang === "ar" ? "عنوان التقرير" : "Report title"
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "الاسم (عربي)" : "Name (AR)"}</Label>
                  <Input
                    value={reportName.ar}
                    onChange={(e) =>
                      setReportName({ ...reportName, ar: e.target.value })
                    }
                    placeholder="عنوان التقرير"
                  />
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Basic Info - Child Name from Case + Expert Name */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "معلومات أساسية" : "Basic Information"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "اسم الطفل" : "Child Name"}</Label>
                  <Input
                    value={childName}
                    onChange={(e) => setChildName(e.target.value)}
                    placeholder={lang === "ar" ? "اسم الطفل" : "Child name"}
                  />
                </div>
                <div className="space-y-2">
                  <Label>{lang === "ar" ? "اسم الخبير" : "Expert Name"}</Label>
                  <Input
                    value={expertName}
                    onChange={(e) => setExpertName(e.target.value)}
                    placeholder={lang === "ar" ? "اسم الخبير" : "Expert name"}
                  />
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Fixed Fields - Date, Assessment, Suggestions */}
          <Card>
            <CardHeader>
              <CardTitle>
                {lang === "ar" ? "تفاصيل التقرير" : "Report Details"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label>{lang === "ar" ? "التاريخ" : "Date"}</Label>
                <DateInput
                  value={fixedFields.date}
                  onChange={(v) =>
                    setFixedFields({ ...fixedFields, date: v })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>{lang === "ar" ? "التقييم" : "Assessment"}</Label>
                <Textarea
                  value={fixedFields.assessment}
                  onChange={(e) =>
                    setFixedFields({
                      ...fixedFields,
                      assessment: e.target.value,
                    })
                  }
                  placeholder={
                    lang === "ar" ? "أدخل التقييم..." : "Enter assessment..."
                  }
                  rows={4}
                />
              </div>
              <div className="space-y-2">
                <Label>{lang === "ar" ? "الاقتراحات" : "Suggestions"}</Label>
                <Textarea
                  value={fixedFields.suggestions}
                  onChange={(e) =>
                    setFixedFields({
                      ...fixedFields,
                      suggestions: e.target.value,
                    })
                  }
                  placeholder={
                    lang === "ar"
                      ? "أدخل الاقتراحات..."
                      : "Enter suggestions..."
                  }
                  rows={4}
                />
              </div>
            </CardContent>
          </Card>

          <div className="flex justify-end gap-4">
            <Button variant="outline" onClick={handleCancel}>
              {lang === "ar" ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={!isFormValid || isSubmitting}
            >
              {isSubmitting
                ? editAssignmentId
                  ? lang === "ar"
                    ? "جارٍ الحفظ..."
                    : "Saving..."
                  : lang === "ar"
                    ? "جارٍ الإنشاء..."
                    : "Creating..."
                : editAssignmentId
                  ? lang === "ar"
                    ? "حفظ التغييرات"
                    : "Save Changes"
                  : lang === "ar"
                    ? "إنشاء تقرير"
                    : "Create Report"}
            </Button>
          </div>
        </div>

        {showPreview && (
          <div className="sticky top-6 max-h-[calc(100vh-12rem)] overflow-auto rounded-lg border bg-card p-4">
            <p className="mb-4 text-sm font-semibold tracking-wider text-muted-foreground uppercase">
              {lang === "ar" ? "معاينة مباشرة" : "Live Preview"}
            </p>
            <ReportPreview
              config={{
                title: { en: reportName.en, ar: reportName.ar },
                childName: childName,
                expertName: expertName,
                customFields: [],
                media: [],
                date: fixedFields.date,
                assessment: fixedFields.assessment,
                suggestions: fixedFields.suggestions,
              }}
            />
          </div>
        )}
      </div>
    </div>
  )
}

