                    <h4 className="mb-2 font-medium">
                      {lang === "ar" ? "الإحصائيات" : "Analytics"}
                    </h4>
                    <ul className="space-y-2 text-sm">
                      <li className="flex justify-between">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "إجمالي التسجيلات:" : "Total registrations:"}
                        </span>
                        <span className="font-medium">
                          {stats?.totalRegistered ?? 0}
                        </span>
                      </li>
                      <li className="flex justify-between">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "المكتملون:" : "Total completed:"}
                        </span>
                        <span className="font-medium">
                          {stats?.totalCompleted ?? 0}
                        </span>
                      </li>
                      <li className="flex justify-between">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "نسبة الإكمال:" : "Completion rate:"}
                        </span>
                        <span className="font-medium">
                          {stats?.attendanceRate ?? 0}%
                        </span>
                      </li>
                      <li className="flex justify-between">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "عدد الجلسات:" : "Sessions:"}
                        </span>
                        <span className="font-medium">
                          {program.schedule.sessions.length}
                        </span>
                      </li>
                      <li className="flex justify-between">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "الحد الأقصى:" : "Max participants:"}
                        </span>
                        <span className="font-medium">
                          {program.maxParticipants ?? "—"}
                        </span>
                      </li>
                    </ul>
                  </div>
                  <div>
                    <h4 className="mb-2 font-medium">
                      {lang === "ar" ? "معلومات البرنامج" : "Program Info"}
                    </h4>
                    <ul className="space-y-2 text-sm">
                      <li className="flex justify-between">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "العنوان:" : "Title:"}
                        </span>
                        <span className="font-medium">
                          {program.title[lang]}
                        </span>
                      </li>
                      <li className="flex justify-between">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "المدرب:" : "Trainer:"}
                        </span>
                        <span className="font-medium">
                          {program.trainer.name[lang]}
                        </span>
                      </li>
                      <li className="flex justify-between">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "تاريخ البدء:" : "Start date:"}
                        </span>
                        <span className="font-medium">
                          {formatDate(program.schedule.startDate)}
                        </span>
                      </li>
                      <li className="flex justify-between">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "المدة:" : "Duration:"}
                        </span>
                        <span className="font-medium">
                          {program.duration}{" "}
                          {lang === "ar" ? "أيام" : "days"}
                        </span>
                      </li>
                      <li className="flex justify-between">
                        <span className="text-muted-foreground">
                          {lang === "ar" ? "الموقع:" : "Location:"}
                        </span>
                        <span className="font-medium">{program.location}</span>
                      </li>
                    </ul>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  )
}

"use client"

import { use, useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { getToolTypeLabel } from "@/lib/tool-types"
import { formatDate } from "@/lib/format-date"
import { caseExpertsCollection } from "@/lib/pb-collections"
import { getAllowedToolTypesForRole } from "@/lib/pb-collections"
import { PaymentGate } from "@/components/cases/PaymentGate"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  ArrowLeft,
  Calendar,
  Mail,
  Phone,
  User,
  ClipboardList,
  History,
  Eye,
  Pencil,
  Send,
} from "lucide-react"
import Link from "next/link"
import { toast } from "sonner"
import { getErrorMessage } from "@/lib/pb"

const assignmentStatusLabels: Record<
  string,
  { en: string; ar: string }
> = {
  pending: { en: "Pending", ar: "قيد الانتظار" },
  assigned: { en: "Assigned", ar: "تم التعيين" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
}

export default function ProfileDetailPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = use(params)
  const router = useRouter()
  const { lang } = useLang()
  const { getProfileById } = useProfiles()
  const { getAssignmentsByCase, getVisibleAssignments } = useAssignments(id)
  const { toolTypes, fetchToolTypes } = useToolTypes()
  const { currentUser } = useAuth()

  const [expertRole, setExpertRole] = useState<string | null>(null)
  const [allowedToolTypeIds, setAllowedToolTypeIds] = useState<string[]>([])

  const profile = getProfileById(id)
  const assignments = getAssignmentsByCase(id)
  const visibleAssignments = getVisibleAssignments(id)

  // Filter visible assignments by role-based tool type permissions
  const roleFilteredAssignments =
    expertRole && allowedToolTypeIds.length > 0
      ? visibleAssignments.filter((a) => allowedToolTypeIds.includes(a.type))
      : visibleAssignments

  useEffect(() => {
    fetchToolTypes()
  }, [fetchToolTypes])

  useEffect(() => {
    async function fetchExpertRole() {
      if (!currentUser || !id) return
      try {
        const caseExpert = await caseExpertsCollection.getByCaseAndExpert(
          id,
          currentUser.id
        )
        if (caseExpert?.role) {
          setExpertRole(caseExpert.role)
          const allowed = await getAllowedToolTypesForRole(caseExpert.role)
          setAllowedToolTypeIds(allowed)
        }
      } catch (error) {
        console.error("Failed to fetch expert role:", error)
        toast.error(getErrorMessage(error))
      }
    }
    fetchExpertRole()
  }, [currentUser, id])

  if (!profile) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الحالة غير موجودة" : "Case not found"}
        </h2>
        <Link href="/dashboard/cases">
          <Button>{lang === "ar" ? "العودة إلى الحالات" : "Back to Cases"}</Button>
        </Link>
      </div>
    )
  }

  return (
    <PaymentGate profile={profile}>
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-primary">{profile.name}</h1>
          <p className="text-muted-foreground">
            {lang === "ar" ? `أنشئت في ${formatDate(profile.created)}` : `Created ${formatDate(profile.created)}`}
          </p>
        </div>
      </div>

      <Tabs defaultValue="overview" className="space-y-4">
        <TabsList>
          <TabsTrigger value="overview">
            {lang === "ar" ? "نظرة عامة" : "Overview"}
          </TabsTrigger>
          <TabsTrigger value="tasks">
            {lang === "ar" ? "المهام" : "Tasks"}
            {roleFilteredAssignments.length > 0 && (
              <Badge variant="secondary" className="ms-2">
                {roleFilteredAssignments.length}
              </Badge>
            )}
          </TabsTrigger>
          <TabsTrigger value="case-file">
            {lang === "ar" ? "السجل" : "History"}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="overview">
          <div className="grid gap-6 lg:grid-cols-2">
            {profile.portal_type === "Attending Training" ? (
              <Card>
                <CardHeader>
                  <CardTitle>
                    {lang === "ar" ? "التسجيل في التدريب" : "Training Enrollment"}
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">
                      {lang === "ar" ? "نوع الخدمة" : "Service Type"}
                    </span>
                    <span className="font-medium">
                      {lang === "ar" ? "حضور تدريب" : "Attending Training"}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">
                      {lang === "ar" ? "نوع المشكلة" : "Issue Type"}
                    </span>
                    <span className="font-medium">
                      {profile.service_type ||
                        profile.sub_category ||
                        (lang === "ar" ? "حضور تدريب" : "Attending Training")}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">
                      {lang === "ar" ? "الحالة" : "Status"}
                    </span>
                    <Badge variant="secondary">
                      {profile.program_status === "enrolled"
                        ? lang === "ar"
                          ? "مسجل"
                          : "enrolled"
                        : profile.program_status}
                    </Badge>
                  </div>
                  {profile.training_link && (
                    <Link
                      href={profile.training_link}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="mt-2 block"
                    >
                      <Button variant="default" className="w-full">
                        {lang === "ar" ? "الانضمام للاجتماع" : "Join Meeting"}
                      </Button>
                    </Link>
                  )}
                  {profile.program_id && (
                    <Link
                      href={`/programmes/training_programmes/${profile.program_id}`}
                      className="mt-2 block"
                    >
                      <Button variant="outline" className="w-full">
                        {lang === "ar"
                          ? "عرض البرنامج التدريبي"
                          : "View Training Program"}
                      </Button>
                    </Link>
                  )}
                </CardContent>
              </Card>
            ) : (
              <>
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                      <User className="h-5 w-5" />
                      {lang === "ar" ? "معلومات الحالة" : "Case Information"}
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">
                        {lang === "ar" ? "تاريخ الميلاد" : "Date of Birth"}
                      </span>
                      <span className="font-medium">
                        {profile.date_of_birth
                          ? formatDate(profile.date_of_birth)
                          : "—"}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">
                        {lang === "ar" ? "الجنس" : "Gender"}
                      </span>
                      <span className="font-medium capitalize">
                        {profile.gender === "male"
                          ? lang === "ar"
                            ? "ذكر"
                            : "male"
                          : profile.gender === "female"
                            ? lang === "ar"
                              ? "أنثى"
                              : "female"
                            : "—"}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">
                        {lang === "ar" ? "الصف الدراسي" : "Grade"}
                      </span>
                      <span className="font-medium capitalize">
                        {profile.grade || "—"}
                      </span>
                    </div>
                  </CardContent>
                </Card>

                {profile.notes && (
                  <Card className="lg:col-span-2">
                    <CardHeader>
                      <CardTitle>{lang === "ar" ? "ملاحظات" : "Notes"}</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <p className="text-muted-foreground">{profile.notes}</p>
                    </CardContent>
                  </Card>
                )}
              </>
            )}
          </div>
        </TabsContent>

        <TabsContent value="tasks">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <ClipboardList className="h-5 w-5" />
                {lang === "ar" ? "المهام المكلف بها" : "Assigned Tasks"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "المهام المكلف بها لهذه الحالة"
                  : "Tasks assigned to this profile"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {roleFilteredAssignments.length === 0 ? (
                <div className="py-8 text-center">
                  <ClipboardList className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar" ? "لا توجد مهام مكلف بها" : "No tasks assigned"}
                  </h3>
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? "ستظهر المهام هنا بمجرد تكليفها من قبل المشرف"
                      : "Tasks will appear here once assigned by an admin"}
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {roleFilteredAssignments.map((assignment) => {
                    const toolType = toolTypes.find(
                      (t) => t.id === assignment.type
                    )
                    const toolTypeName = getToolTypeLabel(toolType, lang)
                    return (
                      <div
                        key={assignment.id}
                        className="flex items-center justify-between rounded-lg border p-4 transition-colors hover:bg-muted/50"
                      >
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <p className="font-medium">
                              {lang === "ar"
                                ? assignment.name_ar || assignment.name_en
                                : assignment.name_en}
                            </p>
                            <Badge
                              variant="outline"
                              className="text-xs capitalize"
                            >
                              {toolTypeName}
                            </Badge>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          {!assignment.is_not_template ? (
                            <Link
                              href={`/dashboard/cases/${id}/tasks/${assignment.id}`}
                            >
                              <Button
                                variant="outline"
                                size="sm"
                                title={lang === "ar" ? "الإجابة" : "Respond"}
                              >
                                <Pencil className="h-4 w-4" />
                              </Button>
                            </Link>
                          ) : (
                            <Link
                              href={`/dashboard/cases/${id}/tasks/${assignment.id}`}
                            >
                              <Button
                                variant="outline"
                                size="sm"
                                title={lang === "ar" ? "عرض" : "View"}
                              >
                                <Eye className="h-4 w-4" />
                              </Button>
                            </Link>
                          )}
                          {assignment.status === "completed" && !assignment.is_not_template && (
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => {
                                const responses = assignment.responses
                                if (
                                  responses &&
                                  Object.keys(responses).length > 0
                                ) {
                                  const printWindow = window.open(
                                    "",
                                    "_blank",
                                    "width=800,height=600"
                                  )
                                  if (printWindow) {
                                    printWindow.document.write(`
                                    <html>
                                      <head>
                                        <title>${assignment.name_en || (lang === "ar" ? "الردود" : "Responses")}</title>
                                        <style>
                                          body { font-family: system-ui, sans-serif; padding: 20px; }
                                          h1 { margin-bottom: 10px; }
                                          .meta { color: #666; margin-bottom: 20px; }
                                          .response { margin-bottom: 15px; padding: 10px; background: #f5f5f5; border-radius: 4px; }
                                          .question { font-weight: bold; margin-bottom: 5px; }
                                          @media print { .no-print { display: none; } }
                                        </style>
                                      </head>
                                      <body>
                                        <h1>${assignment.name_en || (lang === "ar" ? "الردود" : "Responses")}</h1>
                                        <p class="meta">${lang === "ar" ? "الحالة" : "Profile"}: ${profile.name} | ${lang === "ar" ? "التاريخ" : "Date"}: ${formatDate(assignment.updated)}</p>
                                        <pre style="white-space: pre-wrap; background: #f5f5f5; padding: 15px; border-radius: 4px;">${JSON.stringify(responses, null, 2)}</pre>
                                        <button class="no-print" onclick="window.print()" style="margin-top: 20px; padding: 10px 20px; cursor: pointer;">${lang === "ar" ? "طباعة / حفظ كـ PDF" : "Print / Save as PDF"}</button>
                                      </body>
                                    </html>
                                  `)
                                    printWindow.document.close()
                                  }
                                }
                              }}
                            >
                              <Eye className="h-4 w-4" />
                            </Button>
                          )}
                          <Badge
                            variant={
                              assignment.status === "completed"
                                ? "default"
                                : "secondary"
                            }
                          >
                            {assignmentStatusLabels[assignment.status]?.[lang] || assignment.status}
                          </Badge>
                        </div>
                      </div>
                    )
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="case-file">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <History className="h-5 w-5" />
                {lang === "ar" ? "السجل" : "History"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "ستكون المهام المكتملة هنا"
                  : "Completed Tasks will be here"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {assignments.filter((a) => a.status === "completed").length ===
              0 ? (
                <div className="py-8 text-center">
                  <History className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar" ? "لا يوجد سجل بعد" : "No history yet"}
                  </h3>
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? "ستظهر المهام المكتملة هنا"
                      : "Completed tasks will appear here"}
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {assignments
                    .filter((a) => a.status === "completed")
                    .map((assignment) => (
                      <div
                        key={assignment.id}
                        className="flex items-center justify-between rounded-lg border p-4"
                      >
                        <div>
                          <p className="font-medium">
                            {lang === "ar"
                              ? assignment.name_ar || assignment.name_en
                              : assignment.name_en}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            {lang === "ar" ? "أكملت في" : "Completed"}{" "}
                            {assignment.updated &&
                              formatDate(assignment.updated)}
                          </p>
                        </div>
                        <Badge variant="default">
                          {lang === "ar" ? "مكتمل" : "Completed"}
                        </Badge>
                      </div>
                    ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
    </PaymentGate>
  )
}

"use client"

import { use, useState, useEffect, useMemo, useRef } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { formatDate } from "@/lib/format-date"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { Input } from "@/components/ui/input"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Checkbox } from "@/components/ui/checkbox"
import {
  ArrowLeft,
  CheckCircle,
  AlertCircle,
  Upload,
  X,
  FileText,
  Image,
  Video,
  Music,
  Play,
  Trash2,
  File,
} from "lucide-react"
import Link from "next/link"
import type {
  SurveyConfig,
  SurveyQuestion,
  MultipleChoiceConfig,
  MCQuestion,
  MediaConfig,
  MediaItem,
  AttachmentRequestConfig,
  AttachmentFileType,
  OneToOneMeetingConfig,
  ReportConfig,
  PlanConfig,
} from "@/types/tool"
import { cn } from "@/lib/utils"
import { toast } from "sonner"
import pb, { getErrorMessage } from "@/lib/pb"
import { PaymentGate } from "@/components/cases/PaymentGate"

const RATING_LABELS: Record<number, { en: string; ar: string }> = {
  1: { en: "Very Low", ar: "منخفض جداً" },
  2: { en: "Low", ar: "منخفض" },
  3: { en: "Medium", ar: "متوسط" },
  4: { en: "High", ar: "عالٍ" },
  5: { en: "Very High", ar: "عالٍ جداً" },
}

export default function TakeSurveyToolPage({
  params,
}: {
  params: Promise<{ id: string; toolId: string }>
}) {
  const params2 = use(params)
  const caseId = params2.id
  const assignmentId = params2.toolId
  const router = useRouter()
  const { lang } = useLang()
  const { getProfileById } = useProfiles()
  const {
    assignments,
    updateAssignment,
    updateAssignmentWithFiles,
    isLoading: isAssignmentsLoading,
  } = useAssignments(caseId)
  const { getToolTypeById, fetchToolTypes } = useToolTypes()
  const { currentUser } = useAuth()

  const assignment = assignments.find((a) => a.id === assignmentId) // Find by toolId
  const profile = getProfileById(caseId) // Get profile by case ID
  const toolType = assignment ? getToolTypeById(assignment.type) : undefined
  const toolTypeName = toolType?.key || "unknown"

  const isAdminOrExpert = currentUser?.role === "admin" || currentUser?.role === "super_admin" || currentUser?.role === "expert"

  const isSurveyTool = toolTypeName === "survey"
  const isMultipleChoiceTool = toolTypeName === "multiple_answer"
  const isMediaTool = toolTypeName === "media_question"
  const isAttachmentTool = toolTypeName === "attachment_request"
  const isMeetingTool = toolTypeName === "one_to_one_meeting"
  const isReportTool = toolTypeName === "report"
  const isPlanTool = toolTypeName === "plan"

  const surveyConfig = isSurveyTool
    ? (assignment?.config as SurveyConfig | undefined)
    : undefined
  const mcConfig = isMultipleChoiceTool
    ? (assignment?.config as MultipleChoiceConfig | undefined)
    : undefined
  const mediaConfig = isMediaTool
    ? (assignment?.config as MediaConfig | undefined)
    : undefined
  const attachmentConfig = isAttachmentTool
    ? (assignment?.config as AttachmentRequestConfig | undefined)
    : undefined
  const meetingConfig = isMeetingTool
    ? (assignment?.config as OneToOneMeetingConfig | undefined)
    : undefined
  const reportConfig = isReportTool
    ? (assignment?.config as ReportConfig | undefined)
    : undefined
  const planConfig = isPlanTool
    ? (assignment?.config as PlanConfig | undefined)
    : undefined

  const config = surveyConfig || mcConfig || mediaConfig || attachmentConfig || meetingConfig || reportConfig || planConfig

  const existingResponses = assignment?.responses as
    | Record<string, unknown>
    | undefined
  const [answers, setAnswers] = useState<Record<string, unknown>>({})
  const [mediaResponses, setMediaResponses] = useState<Record<string, string>>(
    {}
  )
  const [errors, setErrors] = useState<string[]>([])
  const [isSubmitting, setIsSubmitting] = useState(false)
  const isCompleted = assignment?.status === "completed"

  const [localNotes, setLocalNotes] = useState("")
  const [localNotesVisible, setLocalNotesVisible] = useState(false)
  const [isSavingNotes, setIsSavingNotes] = useState(false)

  useEffect(() => {
    if (meetingConfig) {
      setLocalNotes(meetingConfig.notes || "")
      setLocalNotesVisible(meetingConfig.notesVisibleToUser || false)
    }
  }, [meetingConfig])

  // File upload state for media and attachment tools
  const [uploadedFiles, setUploadedFiles] = useState<
    Record<string, { file: File; preview?: string }>
  >({})
  const [existingFiles, setExistingFiles] = useState<Record<string, string[]>>(
    {}
  )
  const [filesToRemove, setFilesToRemove] = useState<string[]>([])

  const hasFetchedToolTypes = useRef(false)
  const hasInitializedAnswers = useRef(false)
  const hasInitializedFiles = useRef(false)

  useEffect(() => {
    if (hasFetchedToolTypes.current) return
    hasFetchedToolTypes.current = true
    fetchToolTypes()
  }, [fetchToolTypes])

  // Initialize answers from existing responses - only once
  useEffect(() => {
    if (hasInitializedAnswers.current) return
    if (existingResponses && Object.keys(existingResponses).length > 0) {
      setAnswers(existingResponses)
      hasInitializedAnswers.current = true
    }
  }, [existingResponses])

  // Initialize existing files from assignment media - only once
  useEffect(() => {
    if (hasInitializedFiles.current) return
    if (assignment?.media && assignment.media.length > 0) {
      // Group files by response key from responses data
      const filesByKey: Record<string, string[]> = {}

      if (assignment.responses) {
        Object.entries(assignment.responses).forEach(([key, value]) => {
          if (typeof value === "string" && assignment.media?.includes(value)) {
            if (!filesByKey[key]) filesByKey[key] = []
            filesByKey[key].push(value)
          }
        })
      }

      // Also add files not yet mapped to any key (for attachment tool)
      const unmappedFiles = assignment.media.filter(
        (file) =>
          !Object.values(filesByKey).some((files) => files.includes(file))
      )
      if (unmappedFiles.length > 0) {
        filesByKey["_unmapped"] = unmappedFiles
      }

      setExistingFiles(filesByKey)
      hasInitializedFiles.current = true
    }
  }, [assignment?.media, assignment?.responses])

  if (isAssignmentsLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جاري التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  if (!assignment || !profile || !config) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الأداة غير موجودة" : "Tool not found"}
        </h2>
        <Link href="/dashboard/cases">
          <Button>
            {lang === "ar" ? "العودة إلى الحالات" : "Back to Cases"}
          </Button>
        </Link>
      </div>
    )
  }

  if (profile.status && profile.status !== "active" && !isAdminOrExpert) {
    return <PaymentGate profile={profile} />
  }

  const handleAnswer = (questionId: string, value: unknown) => {
    setAnswers((prev) => ({ ...prev, [questionId]: value }))
    setErrors((prev) => prev.filter((e) => e !== questionId))
  }

  const validateRequired = (): boolean => {
    const missing: string[] = []

    if (isSurveyTool && surveyConfig) {
      surveyConfig.questions.forEach((q) => {
        if (q.required) {
          const answer = answers[q.id]
          if (
            answer === undefined ||
            answer === null ||
            (typeof answer === "string" && answer.trim() === "") ||
            (Array.isArray(answer) && answer.length === 0)
          ) {
            missing.push(q.id)
          }
        }
      })
    }

    if (isMultipleChoiceTool && mcConfig) {
      mcConfig.questions.forEach((q) => {
        if (q.required) {
          if (q.answerType === "media") {
            if (q.responseType === "text") {
              const answer = answers[q.id]
              if (
                !answer ||
                (typeof answer === "string" && answer.trim() === "")
              ) {
                missing.push(q.id)
              }
            } else if (
              q.responseType === "video" ||
              q.responseType === "audio"
            ) {
              const hasNewFile = uploadedFiles[q.id]
              const hasExistingFile =
                existingFiles[q.id] && existingFiles[q.id].length > 0
              if (!hasNewFile && !hasExistingFile) {
                missing.push(q.id)
              }
            }
          } else {
            const answer = answers[q.id]
            if (
              answer === undefined ||
              answer === null ||
              (typeof answer === "string" && answer.trim() === "") ||
              (typeof answer === "number" && isNaN(answer)) ||
              (Array.isArray(answer) && answer.length === 0)
            ) {
              missing.push(q.id)
            }
          }
        }
      })
    }

    if (isMediaTool && mediaConfig) {
      mediaConfig.items.forEach((item) => {
        if (item.responseType === "text") {
          const answer = mediaResponses[item.id]
          if (!answer || answer.trim() === "") {
            missing.push(item.id)
          }
        } else if (
          item.responseType === "video" ||
          item.responseType === "audio"
        ) {
          // Check if a file is uploaded for this media item
          const hasNewFile = uploadedFiles[item.id]
          const hasExistingFile =
            existingFiles[item.id] && existingFiles[item.id].length > 0
          if (!hasNewFile && !hasExistingFile) {
            missing.push(item.id)
          }
        }
      })
    }

    if (isAttachmentTool && attachmentConfig) {
      const totalFiles = Object.keys(uploadedFiles).length
      const totalExisting = existingFiles["_unmapped"]
        ? existingFiles["_unmapped"].filter((f) => !filesToRemove.includes(f))
            .length
        : 0

      if (attachmentConfig.required && totalFiles + totalExisting === 0) {
        missing.push("attachment")
      }
    }

    setErrors(missing)
    return missing.length === 0
  }

  const saveNotes = async () => {
    if (!assignment || !meetingConfig) return
    setIsSavingNotes(true)
    try {
      const updatedConfig = {
        ...meetingConfig,
        notes: localNotes || undefined,
        notesVisibleToUser: localNotesVisible,
      }
      await updateAssignment(assignmentId, {
        config: updatedConfig as OneToOneMeetingConfig,
      })
    } catch (error) {
      console.error("Failed to save notes:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSavingNotes(false)
    }
  }

  const handleSubmit = async () => {
    if (!validateRequired()) return

    setIsSubmitting(true)
    try {
      // Build responses with file references for media/attachment tools
      const finalResponses: Record<string, unknown> = { ...answers }

      if (isMediaTool && mediaConfig) {
        mediaConfig.items.forEach((item) => {
          if (item.responseType === "text") {
            finalResponses[item.id] = mediaResponses[item.id] || ""
          } else if (uploadedFiles[item.id]) {
            // File will be uploaded, reference will be added after upload
            finalResponses[item.id] = uploadedFiles[item.id].file.name
          }
        })
      }

      if (isMultipleChoiceTool && mcConfig) {
        mcConfig.questions.forEach((q) => {
          if (
            q.answerType === "media" &&
            (q.responseType === "video" || q.responseType === "audio")
          ) {
            if (uploadedFiles[q.id]) {
              finalResponses[q.id] = uploadedFiles[q.id].file.name
            }
          }
        })
      }

      if (isAttachmentTool) {
        // Add references for uploaded files
        Object.entries(uploadedFiles).forEach(([key, data]) => {
          finalResponses[key] = data.file.name
        })
      }

      // Upload files if any
      const filesToUpload = Object.values(uploadedFiles).map(
        (data) => data.file
      )

      if (filesToUpload.length > 0 || filesToRemove.length > 0) {
        await updateAssignmentWithFiles(
          assignmentId,
          {
            status: "completed",
            responses: finalResponses,
          },
          filesToUpload,
          filesToRemove.length > 0 ? filesToRemove : undefined
        )
      } else {
        await updateAssignment(assignmentId, {
          status: "completed",
          responses: finalResponses,
        })
      }

      router.push(`/dashboard/cases/${profile.id}`)
    } catch (error) {
      console.error("Failed to submit:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleStart = async () => {
    if (assignment.status === "pending") {
      await updateAssignment(assignmentId, {
        status: "in_progress",
      })
    }
  }

  // File handling helpers
  const handleFileSelect = (
    key: string,
    e: React.ChangeEvent<HTMLInputElement>,
    allowedTypes?: AttachmentFileType[]
  ) => {
    const file = e.target.files?.[0]
    if (!file) return

    // Validate file type
    if (allowedTypes && allowedTypes.length > 0) {
      const isValidType = validateFileType(file, allowedTypes)
      if (!isValidType) {
        alert(
          lang === "ar" ? "نوع الملف غير مسموح به" : "File type not allowed"
        )
        return
      }
    }

    // Validate file size (default 20MB)
    const maxSize = attachmentConfig?.maxFileSize || 20
    if (file.size > maxSize * 1024 * 1024) {
      alert(
        lang === "ar"
          ? `حجم الملف كبير جداً. الحد الأقصى ${maxSize} ميجابايت`
          : `File too large. Max size is ${maxSize}MB`
      )
      return
    }

    // Create preview for media files
    let preview: string | undefined
    if (file.type.startsWith("image/") || file.type.startsWith("video/")) {
      preview = URL.createObjectURL(file)
    }

    setUploadedFiles((prev) => ({
      ...prev,
      [key]: { file, preview },
    }))
    setErrors((prev) => prev.filter((e) => e !== key))
  }

  const validateFileType = (
    file: File,
    allowedTypes: AttachmentFileType[]
  ): boolean => {
    if (allowedTypes.includes("any")) return true

    const typeMap: Record<AttachmentFileType, string[]> = {
      image: ["image/"],
      document: [
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument",
        "text/",
      ],
      video: ["video/"],
      audio: ["audio/"],
      any: [],
    }

    return allowedTypes.some((type) =>
      typeMap[type]?.some((prefix) => file.type.startsWith(prefix))
    )
  }

  const handleRemoveFile = (key: string) => {
    setUploadedFiles((prev) => {
      const newFiles = { ...prev }
      if (newFiles[key]?.preview) {
        URL.revokeObjectURL(newFiles[key].preview!)
      }
      delete newFiles[key]
      return newFiles
    })
  }

  const handleRemoveExistingFile = (filename: string) => {
    setFilesToRemove((prev) => [...prev, filename])
  }

  const getFileIcon = (filename: string) => {
    const ext = filename.split(".").pop()?.toLowerCase()
    if (["jpg", "jpeg", "png", "gif", "webp"].includes(ext || ""))
      return <Image className="h-5 w-5" />
    if (["mp4", "webm", "mov", "avi"].includes(ext || ""))
      return <Video className="h-5 w-5" />
    if (["mp3", "wav", "ogg", "m4a"].includes(ext || ""))
      return <Music className="h-5 w-5" />
    return <FileText className="h-5 w-5" />
  }

  const getFileUrl = (filename: string) => {
    return pb.files.getUrl(
      { collectionId: "case_tools", id: assignmentId },
      filename
    )
  }

  const renderQuestion = (question: SurveyQuestion) => {
    const value = answers[question.id] as string | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMultiple = surveyConfig?.answerType === "multiple_choice"
    const sortedOptions = [...(surveyConfig?.options || [])].sort(
      (a, b) => a.order - b.order
    )

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>
        {isMultiple ? (
          <div className="space-y-2">
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <Checkbox
                  id={`${question.id}-${opt.id}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{opt.label}</Label>
              </div>
            ))}
          </div>
        ) : (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`${question.id}-${opt.id}`}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{opt.label}</Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMCQuestion = (question: MCQuestion) => {
    const value = answers[question.id] as string | number | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMedia = question.answerType === "media"

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>

        {/* Media prompt */}
        {isMedia && question.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
            {question.mediaType === "image" && (
              <img
                src={question.mediaUrl}
                alt={lang === "ar" ? "الوسائط" : "Media"}
                className="h-full w-full object-contain"
              />
            )}
            {question.mediaType === "video" && (
              <video
                src={question.mediaUrl}
                controls
                className="h-full w-full object-contain"
              />
            )}
            {question.mediaType === "audio" && (
              <div className="p-4">
                <audio src={question.mediaUrl} controls className="w-full" />
              </div>
            )}
          </div>
        )}

        {question.answerType === "text" && (
          <Input
            placeholder={
              lang === "ar" ? "أدخل إجابتك..." : "Enter your answer..."
            }
            value={(value as string) || ""}
            onChange={(e) => handleAnswer(question.id, e.target.value)}
          />
        )}
        {question.answerType === "number" && (
          <Input
            type="number"
            placeholder="0"
            value={value as string | number | undefined}
            onChange={(e) => handleAnswer(question.id, Number(e.target.value))}
          />
        )}
        {question.answerType === "single_choice" && (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {question.options?.map((opt) => (
              <div key={opt.value} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`mc-${question.id}-${opt.value}`}
                />
                <Label htmlFor={`mc-${question.id}-${opt.value}`}>
                  {opt.label}
                </Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {question.answerType === "multiple_choice" && (
          <div className="space-y-2">
            {question.options?.map((opt) => (
              <div key={opt.value} className="flex items-center gap-2">
                <Checkbox
                  id={`mc-${question.id}-${opt.value}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`mc-${question.id}-${opt.value}`}>
                  {opt.label}
                </Label>
              </div>
            ))}
          </div>
        )}

        {/* Media question response */}
        {isMedia && question.responseType === "text" && (
          <Input
            placeholder={
              lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
            }
            value={(value as string) || ""}
            onChange={(e) => handleAnswer(question.id, e.target.value)}
          />
        )}
        {isMedia &&
          (question.responseType === "video" ||
            question.responseType === "audio") && (
            <div className="space-y-3">
              {(() => {
                const hasNewUpload = uploadedFiles[question.id]
                const hasExistingFile =
                  existingFiles[question.id] &&
                  existingFiles[question.id].length > 0 &&
                  !filesToRemove.includes(existingFiles[question.id][0])

                return (
                  <>
                    {/* Show existing uploaded file */}
                    {hasExistingFile && !hasNewUpload && (
                      <div className="rounded-lg border bg-muted/30 p-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {question.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="text-sm">
                              {existingFiles[question.id][0].split("_").pop()}
                            </span>
                          </div>
                          <div className="flex items-center gap-2">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(existingFiles[question.id][0]),
                                  "_blank"
                                )
                              }
                            >
                              <Play className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                handleRemoveExistingFile(
                                  existingFiles[question.id][0]
                                )
                              }
                            >
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          </div>
                        </div>
                        <div className="mt-2">
                          {question.responseType === "video" ? (
                            <video
                              src={getFileUrl(existingFiles[question.id][0])}
                              controls
                              className="w-full rounded"
                              style={{ maxHeight: "200px" }}
                            />
                          ) : (
                            <audio
                              src={getFileUrl(existingFiles[question.id][0])}
                              controls
                              className="w-full"
                            />
                          )}
                        </div>
                      </div>
                    )}

                    {/* Show new file being uploaded */}
                    {hasNewUpload && (
                      <div className="rounded-lg border bg-muted/30 p-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {question.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="text-sm">
                              {uploadedFiles[question.id].file.name}
                            </span>
                          </div>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleRemoveFile(question.id)}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        </div>
                        {uploadedFiles[question.id].preview && (
                          <div className="mt-2">
                            {question.responseType === "video" ? (
                              <video
                                src={uploadedFiles[question.id].preview}
                                controls
                                className="w-full rounded"
                                style={{ maxHeight: "200px" }}
                              />
                            ) : (
                              <audio
                                src={uploadedFiles[question.id].preview}
                                controls
                                className="w-full"
                              />
                            )}
                          </div>
                        )}
                      </div>
                    )}

                    {/* Upload button */}
                    {!hasExistingFile && !hasNewUpload && (
                      <div className="flex items-center gap-2">
                        <Input
                          type="file"
                          accept={
                            question.responseType === "video"
                              ? "video/*"
                              : "audio/*"
                          }
                          onChange={(e) => handleFileSelect(question.id, e)}
                          className="hidden"
                          id={`media-upload-${question.id}`}
                        />
                        <Button
                          variant="outline"
                          onClick={() =>
                            document
                              .getElementById(`media-upload-${question.id}`)
                              ?.click()
                          }
                        >
                          <Upload className="me-2 h-4 w-4" />
                          {lang === "ar" ? "اختيار ملف" : "Choose File"}
                        </Button>
                      </div>
                    )}
                  </>
                )
              })()}
            </div>
          )}

        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMediaItem = (item: MediaItem) => {
    const hasNewUpload = uploadedFiles[item.id]
    const hasExistingFile =
      existingFiles[item.id] &&
      existingFiles[item.id].length > 0 &&
      !filesToRemove.includes(existingFiles[item.id][0])
    const hasError = errors.includes(item.id)

    return (
      <div key={item.id} className="space-y-3 rounded-lg border bg-card p-4">
        <Label className="text-base font-medium">{item.question}</Label>

        {/* Display existing media (question media) */}
        {item.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
            {item.mediaType === "image" && (
              <img
                src={item.mediaUrl}
                alt={lang === "ar" ? "الوسائط" : "Media"}
                className="h-full w-full object-contain"
              />
            )}
            {item.mediaType === "video" && (
              <video
                src={item.mediaUrl}
                controls
                className="h-full w-full object-contain"
              />
            )}
            {item.mediaType === "audio" && (
              <div className="p-4">
                <audio src={item.mediaUrl} controls className="w-full" />
              </div>
            )}
          </div>
        )}

        {/* Response section */}
        {item.responseType === "text" && (
          <div>
            <Label className="text-sm text-muted-foreground">
              {lang === "ar" ? "إجابتك:" : "Your response:"}
            </Label>
            <Input
              placeholder={
                lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
              }
              value={mediaResponses[item.id] || ""}
              onChange={(e) => {
                setMediaResponses((prev) => ({
                  ...prev,
                  [item.id]: e.target.value,
                }))
                setErrors((prev) => prev.filter((e) => e !== item.id))
              }}
              className="mt-2"
            />
            {hasError && (
              <div className="flex items-center gap-1 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
              </div>
            )}
          </div>
        )}

        {/* Video/Audio response upload */}
        {(item.responseType === "video" || item.responseType === "audio") && (
          <div className="space-y-3">
            <Label className="text-sm text-muted-foreground">
              {lang === "ar"
                ? item.responseType === "video"
                  ? "رفع فيديو الرد:"
                  : "رفع صوت الرد:"
                : item.responseType === "video"
                  ? "Upload video response:"
                  : "Upload audio response:"}
            </Label>

            {/* Show existing uploaded file */}
            {hasExistingFile && !hasNewUpload && (
              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {item.responseType === "video" ? (
                      <Video className="h-5 w-5" />
                    ) : (
                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {existingFiles[item.id][0].split("_").pop()}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(
                          getFileUrl(existingFiles[item.id][0]),
                          "_blank"
                        )
                      }
                    >
                      <Play className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        handleRemoveExistingFile(existingFiles[item.id][0])
                      }
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
                {/* Preview player */}
                <div className="mt-2">
                  {item.responseType === "video" ? (
                    <video
                      src={getFileUrl(existingFiles[item.id][0])}
                      controls
                      className="w-full rounded"
                      style={{ maxHeight: "200px" }}
                    />
                  ) : (
                    <audio
                      src={getFileUrl(existingFiles[item.id][0])}
                      controls
                      className="w-full"
                    />
                  )}
                </div>
              </div>
            )}

            {/* Show new file being uploaded */}
            {hasNewUpload && (
              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {item.responseType === "video" ? (
                      <Video className="h-5 w-5" />
                    ) : (
                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {uploadedFiles[item.id].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(item.id)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
                {/* Preview player for new upload */}
                {uploadedFiles[item.id].preview && (
                  <div className="mt-2">
                    {item.responseType === "video" ? (
                      <video
                        src={uploadedFiles[item.id].preview}
                        controls
                        className="w-full rounded"
                        style={{ maxHeight: "200px" }}
                      />
                    ) : (
                      <audio
                        src={uploadedFiles[item.id].preview}
                        controls
                        className="w-full"
                      />
                    )}
                  </div>
                )}
              </div>
            )}

            {/* Upload button */}
            {!hasExistingFile && !hasNewUpload && (
              <div className="flex items-center gap-2">
                <Input
                  type="file"
                  accept={item.responseType === "video" ? "video/*" : "audio/*"}
                  onChange={(e) => handleFileSelect(item.id, e)}
                  className="hidden"
                  id={`media-upload-${item.id}`}
                />
                <Button
                  variant="outline"
                  onClick={() =>
                    document.getElementById(`media-upload-${item.id}`)?.click()
                  }
                >
                  <Upload className="me-2 h-4 w-4" />
                  {lang === "ar" ? "اختيار ملف" : "Choose File"}
                </Button>
              </div>
            )}

            {hasError && (
              <div className="flex items-center gap-1 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {lang === "ar" ? "الرد مطلوب" : "Response is required"}
              </div>
            )}
          </div>
        )}
      </div>
    )
  }

  const renderAttachment = () => {
    if (!attachmentConfig) return null

    const existingUnmapped = existingFiles["_unmapped"] || []
    const filteredExisting = existingUnmapped.filter(
      (f) => !filesToRemove.includes(f)
    )
    const newUploadKeys = Object.keys(uploadedFiles).filter((k) =>
      k.startsWith("attachment_")
    )
    const totalFiles = newUploadKeys.length + filteredExisting.length
    const hasError = errors.includes("attachment")

    return (
      <div className="space-y-4">
        <div className="rounded-lg border bg-card p-4">
          <h3 className="mb-2 text-lg font-semibold">
            {
              (attachmentConfig.title as unknown as { en: string; ar: string })[
                lang
              ]
            }
          </h3>
          <p className="text-sm text-muted-foreground">
            {lang === "ar"
              ? `الحد الأقصى: ${attachmentConfig.maxFiles} ملف(ات), ${attachmentConfig.maxFileSize}MB لكل ملف`
              : `Max files: ${attachmentConfig.maxFiles}, ${attachmentConfig.maxFileSize}MB each`}
          </p>
          <p className="text-sm text-muted-foreground">
            {lang === "ar" ? "أنواع الملفات المسموح بها: " : "Allowed types: "}
            {attachmentConfig.allowedTypes.join(", ")}
          </p>

          {/* Existing files */}
          {filteredExisting.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "الملفات المرفقة:" : "Attached files:"}
              </Label>
              {filteredExisting.map((filename, idx) => (
                <div
                  key={`existing-${idx}`}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(filename)}
                    <span className="text-sm">{filename.split("_").pop()}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(getFileUrl(filename), "_blank")
                      }
                    >
                      {lang === "ar" ? "عرض" : "View"}
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleRemoveExistingFile(filename)}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* New uploads */}
          {newUploadKeys.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "ملفات جديدة:" : "New files:"}
              </Label>
              {newUploadKeys.map((key) => (
                <div
                  key={key}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(uploadedFiles[key].file.name)}
                    <span className="text-sm">
                      {uploadedFiles[key].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(key)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          {/* Upload button */}
          {totalFiles < attachmentConfig.maxFiles && (
            <div className="mt-4">
              <Input
                type="file"
                accept={getAcceptTypes(attachmentConfig.allowedTypes)}
                onChange={(e) => {
                  const newKey = `attachment_${Date.now()}`
                  handleFileSelect(newKey, e, attachmentConfig.allowedTypes)
                }}
                className="hidden"
                id="attachment-upload"
              />
              <Button
                variant="outline"
                onClick={() =>
                  document.getElementById("attachment-upload")?.click()
                }
              >
                <Upload className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة ملف" : "Add File"}
              </Button>
            </div>
          )}

          {hasError && (
            <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
              <AlertCircle className="h-4 w-4" />
              {lang === "ar" ? "الملفات مطلوبة" : "Files are required"}
            </div>
          )}
        </div>
      </div>
    )
  }

  const getAcceptTypes = (allowedTypes: AttachmentFileType[]): string => {
    const typeMap: Record<AttachmentFileType, string> = {
      image: "image/*",
      document: ".pdf,.doc,.docx,.txt",
      video: "video/*",
      audio: "audio/*",
      any: "*/*",
    }
    return allowedTypes.map((t) => typeMap[t]).join(",")
  }

  const displayName =
    lang === "ar"
      ? assignment.name_ar || assignment.name_en
      : assignment.name_en

  if (isCompleted) {
    return (
      <div className="mx-auto max-w-2xl space-y-6">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="flex-1">
            <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
            <p className="text-muted-foreground">{profile.name}</p>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>{assignment.name_en}</CardTitle>
            <CardDescription>
              {lang === "ar" ? "تمت الإجابة" : "Completed"}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {isSurveyTool &&
              (() => {
                const sortedOptions = [...(surveyConfig?.options || [])].sort(
                  (a, b) => a.order - b.order
                )
                const isMultiple =
                  surveyConfig?.answerType === "multiple_choice"
                return (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                          <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                            {lang === "ar" ? "الأسئلة" : "Questions"}
                          </th>
                          {sortedOptions.map((opt) => (
                            <th
                              key={opt.id}
                              className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                            >
                              {opt.label}
                            </th>
                          ))}
                        </tr>
                      </thead>
                      <tbody className="divide-y">
                        {surveyConfig?.questions.map((question) => {
                          const value = answers[question.id] as
                            | string
                            | string[]
                            | undefined
                          return (
                            <tr
                              key={question.id}
                              className="text-muted-foreground"
                            >
                              <td className="py-3 pe-4 align-top font-medium">
                                {question.text}
                              </td>
                              {sortedOptions.map((opt) => (
                                <td
                                  key={opt.id}
                                  className="px-2 py-3 text-center"
                                >
                                  {isMultiple ? (
                                    ((value as string[]) || []).includes(
                                      opt.value
                                    ) ? (
                                      <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                    ) : null
                                  ) : (value as string) === opt.value ? (
                                    <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                  ) : null}
                                </td>
                              ))}
                            </tr>
                          )
                        })}
                      </tbody>
                    </table>
                  </div>
                )
              })()}

            {isMultipleChoiceTool &&
              mcConfig?.questions.map((question, idx) => (
                <div key={question.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {idx + 1}. {question.text}
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {question.answerType === "text" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "number" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "single_choice" && (
                      <span className="font-medium">
                        {question.options?.find(
                          (o) => o.value === answers[question.id]
                        )?.label || "-"}
                      </span>
                    )}
                    {question.answerType === "multiple_choice" && (
                      <div className="flex flex-wrap gap-2">
                        {((answers[question.id] as string[]) || []).map((v) => (
                          <span
                            key={v}
                            className="rounded-full bg-primary/10 px-3 py-1 text-sm"
                          >
                            {
                              question.options?.find((o) => o.value === v)
                                ?.label
                            }
                          </span>
                        ))}
                      </div>
                    )}
                    {question.answerType === "media" && (
                      <div>
                        {question.responseType === "text" ? (
                          <span className="font-medium">
                            {String(answers[question.id] || "-")}
                          </span>
                        ) : (
                          <div>
                            {assignment.responses?.[question.id] ? (
                              <div className="flex items-center gap-2">
                                {question.responseType === "video" ? (
                                  <Video className="h-5 w-5" />
                                ) : (
                                  <Music className="h-5 w-5" />
                                )}
                                <span className="font-medium">
                                  {(assignment.responses[question.id] as string)
                                    .split("_")
                                    .pop()}
                                </span>
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() =>
                                    window.open(
                                      getFileUrl(
                                        assignment.responses[
                                          question.id
                                        ] as string
                                      ),
                                      "_blank"
                                    )
                                  }
                                >
                                  {lang === "ar" ? "تشغيل" : "Play"}
                                </Button>
                              </div>
                            ) : (
                              <span className="text-muted-foreground">-</span>
                            )}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isMediaTool &&
              mediaConfig?.items.map((item) => (
                <div key={item.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {
                      (item.question as unknown as { en: string; ar: string })[
                        lang
                      ]
                    }
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {item.responseType === "text" ? (
                      <span className="font-medium">
                        {String(
                          answers[item.id] || mediaResponses[item.id] || "-"
                        )}
                      </span>
                    ) : (
                      <div>
                        {assignment.responses?.[item.id] ? (
                          <div className="flex items-center gap-2">
                            {item.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="font-medium">
                              {(assignment.responses[item.id] as string)
                                .split("_")
                                .pop()}
                            </span>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(
                                    assignment.responses[item.id] as string
                                  ),
                                  "_blank"
                                )
                              }
                            >
                              {lang === "ar" ? "تشغيل" : "Play"}
                            </Button>
                          </div>
                        ) : (
                          <span className="text-muted-foreground">-</span>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isAttachmentTool && (
              <div className="space-y-2">
                <Label className="text-base font-medium text-muted-foreground">
                  {(
                    attachmentConfig?.title as unknown as {
                      en: string
                      ar: string
                    }
                  )?.[lang] || (lang === "ar" ? "المرفقات" : "Attachments")}
                </Label>
                <div className="space-y-2">
                  {assignment.media && assignment.media.length > 0 ? (
                    assignment.media.map((file, idx) => (
                      <div
                        key={idx}
                        className="flex items-center justify-between rounded-lg bg-muted/30 p-3"
                      >
                        <div className="flex items-center gap-2">
                          {getFileIcon(file)}
                          <span className="font-medium">
                            {file.split("_").pop()}
                          </span>
                        </div>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() =>
                            window.open(getFileUrl(file), "_blank")
                          }
                        >
                          {lang === "ar" ? "عرض" : "View"}
                        </Button>
                      </div>
                    ))
                  ) : (
                    <p className="text-muted-foreground">
                      {lang === "ar" ? "لا توجد ملفات" : "No files"}
                    </p>
                  )}
                </div>
              </div>
            )}

            {isMeetingTool && meetingConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الوقت" : "Time"}
                    </Label>
                    <p className="font-medium">{meetingConfig.time || "—"}</p>
                  </div>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">
                    {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                  </Label>
                  <p className="font-medium">
                    {meetingConfig.meetingType === "online"
                      ? lang === "ar" ? "عن بُعد" : "Online"
                      : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                  </p>
                </div>
                {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الرابط" : "Meeting Link"}
                    </Label>
                    <div className="mt-1">
                      <a
                        href={meetingConfig.meetingLink}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <Button variant="default" size="sm">
                          {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                        </Button>
                      </a>
                    </div>
                  </div>
                )}
                {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الموقع" : "Location"}
                    </Label>
                    <p className="font-medium">{meetingConfig.location}</p>
                  </div>
                )}

                {isAdminOrExpert ? (
                  <div className="space-y-2 rounded-lg border p-3">
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                    </Label>
                    <textarea
                      value={localNotes}
                      onChange={(e) => setLocalNotes(e.target.value)}
                      placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                      className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                      rows={3}
                    />
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <input
                          type="checkbox"
                          id="notes-visible-completed"
                          checked={localNotesVisible}
                          onChange={(e) => setLocalNotesVisible(e.target.checked)}
                          className="h-4 w-4 rounded border-gray-300"
                        />
                        <Label htmlFor="notes-visible-completed" className="text-sm text-muted-foreground">
                          {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                        </Label>
                      </div>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={saveNotes}
                        disabled={isSavingNotes}
                      >
                        {isSavingNotes
                          ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                          : lang === "ar" ? "حفظ" : "Save"}
                      </Button>
                    </div>
                  </div>
                ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "ملاحظات" : "Notes"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                  </div>
                ) : null}
              </div>
            )}

            {isReportTool && reportConfig && (
              <div className="space-y-3">
                {reportConfig.date && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{formatDate(reportConfig.date)}</p>
                  </div>
                )}
                {reportConfig.assessment && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التقييم" : "Assessment"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                  </div>
                )}
                {reportConfig.suggestions && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                  </div>
                )}
              </div>
            )}

            {isPlanTool && planConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                    </Label>
                    <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                    </Label>
                    <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                  </div>
                </div>
                {planConfig.goals?.length > 0 && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الأهداف" : "Goals"}
                    </Label>
                    <div className="mt-1 space-y-2">
                      {planConfig.goals.map((goal) => (
                        <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                          <p className="font-medium">{goal.title}</p>
                          {goal.description && (
                            <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                {planConfig.steps?.length > 0 && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الخطوات" : "Steps"}
                    </Label>
                    <div className="mt-1 space-y-2">
                      {planConfig.steps.map((step) => (
                        <div key={step.id} className="rounded-lg border p-3">
                          <div className="flex items-start gap-2">
                            <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                            <div className="flex-1">
                              <p className="font-medium">{step.title}</p>
                              {step.description && (
                                <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                              )}
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {(isMeetingTool || isReportTool || isPlanTool) && (
              <div className="flex gap-2 pt-4">
                <Button
                  onClick={() => router.push(`/dashboard/cases/${profile.id}`)}
                >
                  {lang === "ar" ? "العودة" : "Back"}
                </Button>
              </div>
            )}

            {!isMeetingTool && !isReportTool && !isPlanTool && (
            <div className="flex gap-2 pt-4">
              <Button
                variant="outline"
                onClick={() =>
                  updateAssignment(assignmentId, { status: "in_progress" })
                }
              >
                {lang === "ar" ? "تعديل الإجابات" : "Edit Answers"}
              </Button>
              <Button
                onClick={() => router.push(`/dashboard/cases/${profile.id}`)}
              >
                {lang === "ar" ? "العودة" : "Back"}
              </Button>
            </div>
            )}
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
          <p className="text-muted-foreground">{profile.name}</p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>{assignment.name_en}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {isSurveyTool &&
            (() => {
              const sortedOptions = [...(surveyConfig?.options || [])].sort(
                (a, b) => a.order - b.order
              )
              const isMultiple = surveyConfig?.answerType === "multiple_choice"
              return (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                        <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                          {lang === "ar" ? "الأسئلة" : "Questions"}
                        </th>
                        {sortedOptions.map((opt) => (
                          <th
                            key={opt.id}
                            className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                          >
                            {opt.label}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {surveyConfig?.questions.map((question) => {
                        const value = answers[question.id] as
                          | string
                          | string[]
                          | undefined
                        const hasError = errors.includes(question.id)
                        return (
                          <tr key={question.id}>
                            <td className="py-3 pe-4 align-top">
                              <Label className="text-base font-medium">
                                {question.text}
                                {question.required && (
                                  <span className="ms-1 text-destructive">
                                    *
                                  </span>
                                )}
                              </Label>
                            </td>
                            {sortedOptions.map((opt) => (
                              <td
                                key={opt.id}
                                className="px-2 py-3 text-center"
                              >
                                {isMultiple ? (
                                  <Checkbox
                                    id={`${question.id}-${opt.id}`}
                                    checked={(
                                      (value as string[]) || []
                                    ).includes(opt.value)}
                                    onCheckedChange={(checked) => {
                                      if (checked) {
                                        handleAnswer(question.id, [
                                          ...((value as string[]) || []),
                                          opt.value,
                                        ])
                                      } else {
                                        handleAnswer(
                                          question.id,
                                          ((value as string[]) || []).filter(
                                            (v) => v !== opt.value
                                          )
                                        )
                                      }
                                    }}
                                    className="mx-auto"
                                  />
                                ) : (
                                  <button
                                    type="button"
                                    onClick={() =>
                                      handleAnswer(question.id, opt.value)
                                    }
                                    className={`mx-auto h-5 w-5 rounded-full border-2 transition-colors ${
                                      (value as string) === opt.value
                                        ? "border-primary bg-primary"
                                        : "border-muted-foreground hover:border-primary"
                                    }`}
                                  />
                                )}
                              </td>
                            ))}
                          </tr>
                        )
                      })}
                    </tbody>
                  </table>
                  {errors.some((errId) =>
                    surveyConfig?.questions.find((q) => q.id === errId)
                  ) && (
                    <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
                      <AlertCircle className="h-4 w-4" />
                      {lang === "ar"
                        ? "يرجى الإجابة على جميع الأسئلة المطلوبة"
                        : "Please answer all required questions"}
                    </div>
                  )}
                </div>
              )
            })()}

          {isMultipleChoiceTool &&
            mcConfig?.questions.map((question) => (
              <div key={question.id}>{renderMCQuestion(question)}</div>
            ))}

          {isMediaTool &&
            mediaConfig?.items.map((item) => renderMediaItem(item))}

          {isAttachmentTool && renderAttachment()}

          {isMeetingTool && meetingConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الوقت" : "Time"}
                  </Label>
                  <p className="font-medium">{meetingConfig.time || "—"}</p>
                </div>
              </div>
              <div className="space-y-1">
                <Label className="text-muted-foreground">
                  {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                </Label>
                <p className="font-medium">
                  {meetingConfig.meetingType === "online"
                    ? lang === "ar" ? "عن بُعد" : "Online"
                    : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                </p>
              </div>
              {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الرابط" : "Meeting Link"}
                  </Label>
                  <a
                    href={meetingConfig.meetingLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block"
                  >
                    <Button variant="default" className="w-full">
                      {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                    </Button>
                  </a>
                </div>
              )}
              {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الموقع" : "Location"}
                  </Label>
                  <p className="font-medium">{meetingConfig.location}</p>
                </div>
              )}

              {isAdminOrExpert ? (
                <div className="space-y-3 rounded-lg border p-4">
                  <Label className="text-sm font-medium">
                    {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                  </Label>
                  <textarea
                    value={localNotes}
                    onChange={(e) => setLocalNotes(e.target.value)}
                    placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                    className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                    rows={3}
                  />
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <input
                        type="checkbox"
                        id="notes-visible-task"
                        checked={localNotesVisible}
                        onChange={(e) => setLocalNotesVisible(e.target.checked)}
                        className="h-4 w-4 rounded border-gray-300"
                      />
                      <Label htmlFor="notes-visible-task" className="text-sm text-muted-foreground">
                        {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                      </Label>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={saveNotes}
                      disabled={isSavingNotes}
                    >
                      {isSavingNotes
                        ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                        : lang === "ar" ? "حفظ" : "Save"}
                    </Button>
                  </div>
                </div>
              ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "ملاحظات" : "Notes"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                </div>
              ) : null}
            </div>
          )}

          {isReportTool && reportConfig && (
            <div className="space-y-4">
              {reportConfig.date && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{formatDate(reportConfig.date)}</p>
                </div>
              )}
              {reportConfig.assessment && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التقييم" : "Assessment"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                </div>
              )}
              {reportConfig.suggestions && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                </div>
              )}
            </div>
          )}

          {isPlanTool && planConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                  </Label>
                  <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                  </Label>
                  <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                </div>
              </div>
              {planConfig.goals?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الأهداف" : "Goals"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.goals.map((goal) => (
                      <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                        <p className="font-medium">{goal.title}</p>
                        {goal.description && (
                          <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
              {planConfig.steps?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الخطوات" : "Steps"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.steps.map((step) => (
                      <div key={step.id} className="rounded-lg border p-3">
                        <div className="flex items-start gap-2">
                          <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                          <div className="flex-1">
                            <p className="font-medium">{step.title}</p>
                            {step.description && (
                              <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {(isMeetingTool || isReportTool || isPlanTool) ? (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الحفظ..."
                  : "Saving..."
                : lang === "ar"
                  ? "تأكيد الإتمام"
                  : "Mark as Completed"}
            </Button>
          ) : (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الإرسال..."
                  : "Submitting..."
                : lang === "ar"
                  ? "إرسال"
                  : "Submit"}
            </Button>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { use, useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { getToolTypeLabel } from "@/lib/tool-types"
import { formatDate } from "@/lib/format-date"
import { caseExpertsCollection } from "@/lib/pb-collections"
import { getAllowedToolTypesForRole } from "@/lib/pb-collections"
import { PaymentGate } from "@/components/cases/PaymentGate"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  ArrowLeft,
  Calendar,
  Mail,
  Phone,
  User,
  ClipboardList,
  History,
  Eye,
  Pencil,
  Send,
} from "lucide-react"
import Link from "next/link"
import { toast } from "sonner"
import { getErrorMessage } from "@/lib/pb"

const assignmentStatusLabels: Record<
  string,
  { en: string; ar: string }
> = {
  pending: { en: "Pending", ar: "قيد الانتظار" },
  assigned: { en: "Assigned", ar: "تم التعيين" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
}

export default function ProfileDetailPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = use(params)
  const router = useRouter()
  const { lang } = useLang()
  const { getProfileById } = useProfiles()
  const { getAssignmentsByCase, getVisibleAssignments } = useAssignments(id)
  const { toolTypes, fetchToolTypes } = useToolTypes()
  const { currentUser } = useAuth()

  const [expertRole, setExpertRole] = useState<string | null>(null)
  const [allowedToolTypeIds, setAllowedToolTypeIds] = useState<string[]>([])

  const profile = getProfileById(id)
  const assignments = getAssignmentsByCase(id)
  const visibleAssignments = getVisibleAssignments(id)

  // Filter visible assignments by role-based tool type permissions
  const roleFilteredAssignments =
    expertRole && allowedToolTypeIds.length > 0
      ? visibleAssignments.filter((a) => allowedToolTypeIds.includes(a.type))
      : visibleAssignments

  useEffect(() => {
    fetchToolTypes()
  }, [fetchToolTypes])

  useEffect(() => {
    async function fetchExpertRole() {
      if (!currentUser || !id) return
      try {
        const caseExpert = await caseExpertsCollection.getByCaseAndExpert(
          id,
          currentUser.id
        )
        if (caseExpert?.role) {
          setExpertRole(caseExpert.role)
          const allowed = await getAllowedToolTypesForRole(caseExpert.role)
          setAllowedToolTypeIds(allowed)
        }
      } catch (error) {
        console.error("Failed to fetch expert role:", error)
        toast.error(getErrorMessage(error))
      }
    }
    fetchExpertRole()
  }, [currentUser, id])

  if (!profile) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الحالة غير موجودة" : "Case not found"}
        </h2>
        <Link href="/dashboard/individual/cases">
          <Button>{lang === "ar" ? "العودة إلى الحالات" : "Back to Cases"}</Button>
        </Link>
      </div>
    )
  }

  return (
    <PaymentGate profile={profile}>
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-primary">{profile.name}</h1>
          <p className="text-muted-foreground">
            {lang === "ar" ? `أنشئت في ${formatDate(profile.created)}` : `Created ${formatDate(profile.created)}`}
          </p>
        </div>
      </div>

      <Tabs defaultValue="overview" className="space-y-4">
        <TabsList>
          <TabsTrigger value="overview">
            {lang === "ar" ? "نظرة عامة" : "Overview"}
          </TabsTrigger>
          <TabsTrigger value="tasks">
            {lang === "ar" ? "المهام" : "Tasks"}
            {roleFilteredAssignments.length > 0 && (
              <Badge variant="secondary" className="ms-2">
                {roleFilteredAssignments.length}
              </Badge>
            )}
          </TabsTrigger>
          <TabsTrigger value="case-file">
            {lang === "ar" ? "السجل" : "History"}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="overview">
          <div className="grid gap-6 lg:grid-cols-2">
            {profile.portal_type === "Attending Training" ? (
              <Card>
                <CardHeader>
                  <CardTitle>
                    {lang === "ar" ? "التسجيل في التدريب" : "Training Enrollment"}
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">
                      {lang === "ar" ? "نوع الخدمة" : "Service Type"}
                    </span>
                    <span className="font-medium">
                      {lang === "ar" ? "حضور تدريب" : "Attending Training"}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">
                      {lang === "ar" ? "نوع المشكلة" : "Issue Type"}
                    </span>
                    <span className="font-medium">
                      {profile.service_type ||
                        profile.sub_category ||
                        (lang === "ar" ? "حضور تدريب" : "Attending Training")}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">
                      {lang === "ar" ? "الحالة" : "Status"}
                    </span>
                    <Badge variant="secondary">
                      {profile.program_status === "enrolled"
                        ? lang === "ar"
                          ? "مسجل"
                          : "enrolled"
                        : profile.program_status}
                    </Badge>
                  </div>
                  {profile.training_link && (
                    <Link
                      href={profile.training_link}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="mt-2 block"
                    >
                      <Button variant="default" className="w-full">
                        {lang === "ar" ? "الانضمام للاجتماع" : "Join Meeting"}
                      </Button>
                    </Link>
                  )}
                  {profile.program_id && (
                    <Link
                      href={`/programmes/training_programmes/${profile.program_id}`}
                      className="mt-2 block"
                    >
                      <Button variant="outline" className="w-full">
                        {lang === "ar"
                          ? "عرض البرنامج التدريبي"
                          : "View Training Program"}
                      </Button>
                    </Link>
                  )}
                </CardContent>
              </Card>
            ) : (
              <>
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                      <User className="h-5 w-5" />
                      {lang === "ar" ? "معلومات الحالة" : "Case Information"}
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">
                        {lang === "ar" ? "تاريخ الميلاد" : "Date of Birth"}
                      </span>
                      <span className="font-medium">
                        {profile.date_of_birth
                          ? formatDate(profile.date_of_birth)
                          : "—"}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">
                        {lang === "ar" ? "الجنس" : "Gender"}
                      </span>
                      <span className="font-medium capitalize">
                        {profile.gender === "male"
                          ? lang === "ar"
                            ? "ذكر"
                            : "male"
                          : profile.gender === "female"
                            ? lang === "ar"
                              ? "أنثى"
                              : "female"
                            : "—"}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">
                        {lang === "ar" ? "الصف الدراسي" : "Grade"}
                      </span>
                      <span className="font-medium capitalize">
                        {profile.grade || "—"}
                      </span>
                    </div>
                  </CardContent>
                </Card>

                {profile.notes && (
                  <Card className="lg:col-span-2">
                    <CardHeader>
                      <CardTitle>{lang === "ar" ? "ملاحظات" : "Notes"}</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <p className="text-muted-foreground">{profile.notes}</p>
                    </CardContent>
                  </Card>
                )}
              </>
            )}
          </div>
        </TabsContent>

        <TabsContent value="tasks">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <ClipboardList className="h-5 w-5" />
                {lang === "ar" ? "المهام المكلف بها" : "Assigned Tasks"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "المهام المكلف بها لهذه الحالة"
                  : "Tasks assigned to this profile"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {roleFilteredAssignments.length === 0 ? (
                <div className="py-8 text-center">
                  <ClipboardList className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar" ? "لا توجد مهام مكلف بها" : "No tasks assigned"}
                  </h3>
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? "ستظهر المهام هنا بمجرد تكليفها من قبل المشرف"
                      : "Tasks will appear here once assigned by an admin"}
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {roleFilteredAssignments.map((assignment) => {
                    const toolType = toolTypes.find(
                      (t) => t.id === assignment.type
                    )
                    const toolTypeName = getToolTypeLabel(toolType, lang)
                    return (
                      <div
                        key={assignment.id}
                        className="flex items-center justify-between rounded-lg border p-4 transition-colors hover:bg-muted/50"
                      >
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <p className="font-medium">
                              {lang === "ar"
                                ? assignment.name_ar || assignment.name_en
                                : assignment.name_en}
                            </p>
                            <Badge
                              variant="outline"
                              className="text-xs capitalize"
                            >
                              {toolTypeName}
                            </Badge>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          {!assignment.is_not_template ? (
                            <Link
                              href={`/dashboard/individual/cases/${id}/tasks/${assignment.id}`}
                            >
                              <Button
                                variant="outline"
                                size="sm"
                                title={lang === "ar" ? "الإجابة" : "Respond"}
                              >
                                <Pencil className="h-4 w-4" />
                              </Button>
                            </Link>
                          ) : (
                            <Link
                              href={`/dashboard/individual/cases/${id}/tasks/${assignment.id}`}
                            >
                              <Button
                                variant="outline"
                                size="sm"
                                title={lang === "ar" ? "عرض" : "View"}
                              >
                                <Eye className="h-4 w-4" />
                              </Button>
                            </Link>
                          )}
                          {assignment.status === "completed" && !assignment.is_not_template && (
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => {
                                const responses = assignment.responses
                                if (
                                  responses &&
                                  Object.keys(responses).length > 0
                                ) {
                                  const printWindow = window.open(
                                    "",
                                    "_blank",
                                    "width=800,height=600"
                                  )
                                  if (printWindow) {
                                    printWindow.document.write(`
                                    <html>
                                      <head>
                                        <title>${assignment.name_en || (lang === "ar" ? "الردود" : "Responses")}</title>
                                        <style>
                                          body { font-family: system-ui, sans-serif; padding: 20px; }
                                          h1 { margin-bottom: 10px; }
                                          .meta { color: #666; margin-bottom: 20px; }
                                          .response { margin-bottom: 15px; padding: 10px; background: #f5f5f5; border-radius: 4px; }
                                          .question { font-weight: bold; margin-bottom: 5px; }
                                          @media print { .no-print { display: none; } }
                                        </style>
                                      </head>
                                      <body>
                                        <h1>${assignment.name_en || (lang === "ar" ? "الردود" : "Responses")}</h1>
                                        <p class="meta">${lang === "ar" ? "الحالة" : "Profile"}: ${profile.name} | ${lang === "ar" ? "التاريخ" : "Date"}: ${formatDate(assignment.updated)}</p>
                                        <pre style="white-space: pre-wrap; background: #f5f5f5; padding: 15px; border-radius: 4px;">${JSON.stringify(responses, null, 2)}</pre>
                                        <button class="no-print" onclick="window.print()" style="margin-top: 20px; padding: 10px 20px; cursor: pointer;">${lang === "ar" ? "طباعة / حفظ كـ PDF" : "Print / Save as PDF"}</button>
                                      </body>
                                    </html>
                                  `)
                                    printWindow.document.close()
                                  }
                                }
                              }}
                            >
                              <Eye className="h-4 w-4" />
                            </Button>
                          )}
                          <Badge
                            variant={
                              assignment.status === "completed"
                                ? "default"
                                : "secondary"
                            }
                          >
                            {assignmentStatusLabels[assignment.status]?.[lang] || assignment.status}
                          </Badge>
                        </div>
                      </div>
                    )
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="case-file">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <History className="h-5 w-5" />
                {lang === "ar" ? "السجل" : "History"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "ستكون المهام المكتملة هنا"
                  : "Completed Tasks will be here"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {assignments.filter((a) => a.status === "completed").length ===
              0 ? (
                <div className="py-8 text-center">
                  <History className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar" ? "لا يوجد سجل بعد" : "No history yet"}
                  </h3>
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? "ستظهر المهام المكتملة هنا"
                      : "Completed tasks will appear here"}
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {assignments
                    .filter((a) => a.status === "completed")
                    .map((assignment) => (
                      <div
                        key={assignment.id}
                        className="flex items-center justify-between rounded-lg border p-4"
                      >
                        <div>
                          <p className="font-medium">
                            {lang === "ar"
                              ? assignment.name_ar || assignment.name_en
                              : assignment.name_en}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            {lang === "ar" ? "أكملت في" : "Completed"}{" "}
                            {assignment.updated &&
                              formatDate(assignment.updated)}
                          </p>
                        </div>
                        <Badge variant="default">
                          {lang === "ar" ? "مكتمل" : "Completed"}
                        </Badge>
                      </div>
                    ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
    </PaymentGate>
  )
}

"use client"

import { use, useState, useEffect, useMemo, useRef } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { formatDate } from "@/lib/format-date"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { Input } from "@/components/ui/input"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Checkbox } from "@/components/ui/checkbox"
import {
  ArrowLeft,
  CheckCircle,
  AlertCircle,
  Upload,
  X,
  FileText,
  Image,
  Video,
  Music,
  Play,
  Trash2,
  File,
} from "lucide-react"
import Link from "next/link"
import type {
  SurveyConfig,
  SurveyQuestion,
  MultipleChoiceConfig,
  MCQuestion,
  MediaConfig,
  MediaItem,
  AttachmentRequestConfig,
  AttachmentFileType,
  OneToOneMeetingConfig,
  ReportConfig,
  PlanConfig,
} from "@/types/tool"
import { cn } from "@/lib/utils"
import { toast } from "sonner"
import pb, { getErrorMessage } from "@/lib/pb"
import { PaymentGate } from "@/components/cases/PaymentGate"

const RATING_LABELS: Record<number, { en: string; ar: string }> = {
  1: { en: "Very Low", ar: "منخفض جداً" },
  2: { en: "Low", ar: "منخفض" },
  3: { en: "Medium", ar: "متوسط" },
  4: { en: "High", ar: "عالٍ" },
  5: { en: "Very High", ar: "عالٍ جداً" },
}

export default function TakeSurveyToolPage({
  params,
}: {
  params: Promise<{ id: string; toolId: string }>
}) {
  const params2 = use(params)
  const caseId = params2.id
  const assignmentId = params2.toolId
  const router = useRouter()
  const { lang } = useLang()
  const { getProfileById } = useProfiles()
  const {
    assignments,
    updateAssignment,
    updateAssignmentWithFiles,
    isLoading: isAssignmentsLoading,
  } = useAssignments(caseId)
  const { getToolTypeById, fetchToolTypes } = useToolTypes()
  const { currentUser } = useAuth()

  const assignment = assignments.find((a) => a.id === assignmentId) // Find by toolId
  const profile = getProfileById(caseId) // Get profile by case ID
  const toolType = assignment ? getToolTypeById(assignment.type) : undefined
  const toolTypeName = toolType?.key || "unknown"

  const isAdminOrExpert = currentUser?.role === "admin" || currentUser?.role === "super_admin" || currentUser?.role === "expert"

  const isSurveyTool = toolTypeName === "survey"
  const isMultipleChoiceTool = toolTypeName === "multiple_answer"
  const isMediaTool = toolTypeName === "media_question"
  const isAttachmentTool = toolTypeName === "attachment_request"
  const isMeetingTool = toolTypeName === "one_to_one_meeting"
  const isReportTool = toolTypeName === "report"
  const isPlanTool = toolTypeName === "plan"

  const surveyConfig = isSurveyTool
    ? (assignment?.config as SurveyConfig | undefined)
    : undefined
  const mcConfig = isMultipleChoiceTool
    ? (assignment?.config as MultipleChoiceConfig | undefined)
    : undefined
  const mediaConfig = isMediaTool
    ? (assignment?.config as MediaConfig | undefined)
    : undefined
  const attachmentConfig = isAttachmentTool
    ? (assignment?.config as AttachmentRequestConfig | undefined)
    : undefined
  const meetingConfig = isMeetingTool
    ? (assignment?.config as OneToOneMeetingConfig | undefined)
    : undefined
  const reportConfig = isReportTool
    ? (assignment?.config as ReportConfig | undefined)
    : undefined
  const planConfig = isPlanTool
    ? (assignment?.config as PlanConfig | undefined)
    : undefined

  const config = surveyConfig || mcConfig || mediaConfig || attachmentConfig || meetingConfig || reportConfig || planConfig

  const existingResponses = assignment?.responses as
    | Record<string, unknown>
    | undefined
  const [answers, setAnswers] = useState<Record<string, unknown>>({})
  const [mediaResponses, setMediaResponses] = useState<Record<string, string>>(
    {}
  )
  const [errors, setErrors] = useState<string[]>([])
  const [isSubmitting, setIsSubmitting] = useState(false)
  const isCompleted = assignment?.status === "completed"

  const [localNotes, setLocalNotes] = useState("")
  const [localNotesVisible, setLocalNotesVisible] = useState(false)
  const [isSavingNotes, setIsSavingNotes] = useState(false)

  useEffect(() => {
    if (meetingConfig) {
      setLocalNotes(meetingConfig.notes || "")
      setLocalNotesVisible(meetingConfig.notesVisibleToUser || false)
    }
  }, [meetingConfig])

  // File upload state for media and attachment tools
  const [uploadedFiles, setUploadedFiles] = useState<
    Record<string, { file: File; preview?: string }>
  >({})
  const [existingFiles, setExistingFiles] = useState<Record<string, string[]>>(
    {}
  )
  const [filesToRemove, setFilesToRemove] = useState<string[]>([])

  const hasFetchedToolTypes = useRef(false)
  const hasInitializedAnswers = useRef(false)
  const hasInitializedFiles = useRef(false)

  useEffect(() => {
    if (hasFetchedToolTypes.current) return
    hasFetchedToolTypes.current = true
    fetchToolTypes()
  }, [fetchToolTypes])

  // Initialize answers from existing responses - only once
  useEffect(() => {
    if (hasInitializedAnswers.current) return
    if (existingResponses && Object.keys(existingResponses).length > 0) {
      setAnswers(existingResponses)
      hasInitializedAnswers.current = true
    }
  }, [existingResponses])

  // Initialize existing files from assignment media - only once
  useEffect(() => {
    if (hasInitializedFiles.current) return
    if (assignment?.media && assignment.media.length > 0) {
      // Group files by response key from responses data
      const filesByKey: Record<string, string[]> = {}

      if (assignment.responses) {
        Object.entries(assignment.responses).forEach(([key, value]) => {
          if (typeof value === "string" && assignment.media?.includes(value)) {
            if (!filesByKey[key]) filesByKey[key] = []
            filesByKey[key].push(value)
          }
        })
      }

      // Also add files not yet mapped to any key (for attachment tool)
      const unmappedFiles = assignment.media.filter(
        (file) =>
          !Object.values(filesByKey).some((files) => files.includes(file))
      )
      if (unmappedFiles.length > 0) {
        filesByKey["_unmapped"] = unmappedFiles
      }

      setExistingFiles(filesByKey)
      hasInitializedFiles.current = true
    }
  }, [assignment?.media, assignment?.responses])

  if (isAssignmentsLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جاري التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  if (!assignment || !profile || !config) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الأداة غير موجودة" : "Tool not found"}
        </h2>
        <Link href="/dashboard/individual/cases">
          <Button>
            {lang === "ar" ? "العودة إلى الحالات" : "Back to Cases"}
          </Button>
        </Link>
      </div>
    )
  }

  if (profile.status && profile.status !== "active" && !isAdminOrExpert) {
    return <PaymentGate profile={profile} />
  }

  const handleAnswer = (questionId: string, value: unknown) => {
    setAnswers((prev) => ({ ...prev, [questionId]: value }))
    setErrors((prev) => prev.filter((e) => e !== questionId))
  }

  const validateRequired = (): boolean => {
    const missing: string[] = []

    if (isSurveyTool && surveyConfig) {
      surveyConfig.questions.forEach((q) => {
        if (q.required) {
          const answer = answers[q.id]
          if (
            answer === undefined ||
            answer === null ||
            (typeof answer === "string" && answer.trim() === "") ||
            (Array.isArray(answer) && answer.length === 0)
          ) {
            missing.push(q.id)
          }
        }
      })
    }

    if (isMultipleChoiceTool && mcConfig) {
      mcConfig.questions.forEach((q) => {
        if (q.required) {
          if (q.answerType === "media") {
            if (q.responseType === "text") {
              const answer = answers[q.id]
              if (
                !answer ||
                (typeof answer === "string" && answer.trim() === "")
              ) {
                missing.push(q.id)
              }
            } else if (
              q.responseType === "video" ||
              q.responseType === "audio"
            ) {
              const hasNewFile = uploadedFiles[q.id]
              const hasExistingFile =
                existingFiles[q.id] && existingFiles[q.id].length > 0
              if (!hasNewFile && !hasExistingFile) {
                missing.push(q.id)
              }
            }
          } else {
            const answer = answers[q.id]
            if (
              answer === undefined ||
              answer === null ||
              (typeof answer === "string" && answer.trim() === "") ||
              (typeof answer === "number" && isNaN(answer)) ||
              (Array.isArray(answer) && answer.length === 0)
            ) {
              missing.push(q.id)
            }
          }
        }
      })
    }

    if (isMediaTool && mediaConfig) {
      mediaConfig.items.forEach((item) => {
        if (item.responseType === "text") {
          const answer = mediaResponses[item.id]
          if (!answer || answer.trim() === "") {
            missing.push(item.id)
          }
        } else if (
          item.responseType === "video" ||
          item.responseType === "audio"
        ) {
          // Check if a file is uploaded for this media item
          const hasNewFile = uploadedFiles[item.id]
          const hasExistingFile =
            existingFiles[item.id] && existingFiles[item.id].length > 0
          if (!hasNewFile && !hasExistingFile) {
            missing.push(item.id)
          }
        }
      })
    }

    if (isAttachmentTool && attachmentConfig) {
      const totalFiles = Object.keys(uploadedFiles).length
      const totalExisting = existingFiles["_unmapped"]
        ? existingFiles["_unmapped"].filter((f) => !filesToRemove.includes(f))
            .length
        : 0

      if (attachmentConfig.required && totalFiles + totalExisting === 0) {
        missing.push("attachment")
      }
    }

    setErrors(missing)
    return missing.length === 0
  }

  const saveNotes = async () => {
    if (!assignment || !meetingConfig) return
    setIsSavingNotes(true)
    try {
      const updatedConfig = {
        ...meetingConfig,
        notes: localNotes || undefined,
        notesVisibleToUser: localNotesVisible,
      }
      await updateAssignment(assignmentId, {
        config: updatedConfig as OneToOneMeetingConfig,
      })
    } catch (error) {
      console.error("Failed to save notes:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSavingNotes(false)
    }
  }

  const handleSubmit = async () => {
    if (!validateRequired()) return

    setIsSubmitting(true)
    try {
      // Build responses with file references for media/attachment tools
      const finalResponses: Record<string, unknown> = { ...answers }

      if (isMediaTool && mediaConfig) {
        mediaConfig.items.forEach((item) => {
          if (item.responseType === "text") {
            finalResponses[item.id] = mediaResponses[item.id] || ""
          } else if (uploadedFiles[item.id]) {
            // File will be uploaded, reference will be added after upload
            finalResponses[item.id] = uploadedFiles[item.id].file.name
          }
        })
      }

      if (isMultipleChoiceTool && mcConfig) {
        mcConfig.questions.forEach((q) => {
          if (
            q.answerType === "media" &&
            (q.responseType === "video" || q.responseType === "audio")
          ) {
            if (uploadedFiles[q.id]) {
              finalResponses[q.id] = uploadedFiles[q.id].file.name
            }
          }
        })
      }

      if (isAttachmentTool) {
        // Add references for uploaded files
        Object.entries(uploadedFiles).forEach(([key, data]) => {
          finalResponses[key] = data.file.name
        })
      }

      // Upload files if any
      const filesToUpload = Object.values(uploadedFiles).map(
        (data) => data.file
      )

      if (filesToUpload.length > 0 || filesToRemove.length > 0) {
        await updateAssignmentWithFiles(
          assignmentId,
          {
            status: "completed",
            responses: finalResponses,
          },
          filesToUpload,
          filesToRemove.length > 0 ? filesToRemove : undefined
        )
      } else {
        await updateAssignment(assignmentId, {
          status: "completed",
          responses: finalResponses,
        })
      }

      router.push(`/dashboard/individual/cases/${profile.id}`)
    } catch (error) {
      console.error("Failed to submit:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleStart = async () => {
    if (assignment.status === "pending") {
      await updateAssignment(assignmentId, {
        status: "in_progress",
      })
    }
  }

  // File handling helpers
  const handleFileSelect = (
    key: string,
    e: React.ChangeEvent<HTMLInputElement>,
    allowedTypes?: AttachmentFileType[]
  ) => {
    const file = e.target.files?.[0]
    if (!file) return

    // Validate file type
    if (allowedTypes && allowedTypes.length > 0) {
      const isValidType = validateFileType(file, allowedTypes)
      if (!isValidType) {
        alert(
          lang === "ar" ? "نوع الملف غير مسموح به" : "File type not allowed"
        )
        return
      }
    }

    // Validate file size (default 20MB)
    const maxSize = attachmentConfig?.maxFileSize || 20
    if (file.size > maxSize * 1024 * 1024) {
      alert(
        lang === "ar"
          ? `حجم الملف كبير جداً. الحد الأقصى ${maxSize} ميجابايت`
          : `File too large. Max size is ${maxSize}MB`
      )
      return
    }

    // Create preview for media files
    let preview: string | undefined
    if (file.type.startsWith("image/") || file.type.startsWith("video/")) {
      preview = URL.createObjectURL(file)
    }

    setUploadedFiles((prev) => ({
      ...prev,
      [key]: { file, preview },
    }))
    setErrors((prev) => prev.filter((e) => e !== key))
  }

  const validateFileType = (
    file: File,
    allowedTypes: AttachmentFileType[]
  ): boolean => {
    if (allowedTypes.includes("any")) return true

    const typeMap: Record<AttachmentFileType, string[]> = {
      image: ["image/"],
      document: [
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument",
        "text/",
      ],
      video: ["video/"],
      audio: ["audio/"],
      any: [],
    }

    return allowedTypes.some((type) =>
      typeMap[type]?.some((prefix) => file.type.startsWith(prefix))
    )
  }

  const handleRemoveFile = (key: string) => {
    setUploadedFiles((prev) => {
      const newFiles = { ...prev }
      if (newFiles[key]?.preview) {
        URL.revokeObjectURL(newFiles[key].preview!)
      }
      delete newFiles[key]
      return newFiles
    })
  }

  const handleRemoveExistingFile = (filename: string) => {
    setFilesToRemove((prev) => [...prev, filename])
  }

  const getFileIcon = (filename: string) => {
    const ext = filename.split(".").pop()?.toLowerCase()
    if (["jpg", "jpeg", "png", "gif", "webp"].includes(ext || ""))
      return <Image className="h-5 w-5" />
    if (["mp4", "webm", "mov", "avi"].includes(ext || ""))
      return <Video className="h-5 w-5" />
    if (["mp3", "wav", "ogg", "m4a"].includes(ext || ""))
      return <Music className="h-5 w-5" />
    return <FileText className="h-5 w-5" />
  }

  const getFileUrl = (filename: string) => {
    return pb.files.getUrl(
      { collectionId: "case_tools", id: assignmentId },
      filename
    )
  }

  const renderQuestion = (question: SurveyQuestion) => {
    const value = answers[question.id] as string | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMultiple = surveyConfig?.answerType === "multiple_choice"
    const sortedOptions = [...(surveyConfig?.options || [])].sort(
      (a, b) => a.order - b.order
    )

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>
        {isMultiple ? (
          <div className="space-y-2">
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <Checkbox
                  id={`${question.id}-${opt.id}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{opt.label}</Label>
              </div>
            ))}
          </div>
        ) : (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`${question.id}-${opt.id}`}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{opt.label}</Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMCQuestion = (question: MCQuestion) => {
    const value = answers[question.id] as string | number | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMedia = question.answerType === "media"

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>

        {/* Media prompt */}
        {isMedia && question.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
            {question.mediaType === "image" && (
              <img
                src={question.mediaUrl}
                alt={lang === "ar" ? "الوسائط" : "Media"}
                className="h-full w-full object-contain"
              />
            )}
            {question.mediaType === "video" && (
              <video
                src={question.mediaUrl}
                controls
                className="h-full w-full object-contain"
              />
            )}
            {question.mediaType === "audio" && (
              <div className="p-4">
                <audio src={question.mediaUrl} controls className="w-full" />
              </div>
            )}
          </div>
        )}

        {question.answerType === "text" && (
          <Input
            placeholder={
              lang === "ar" ? "أدخل إجابتك..." : "Enter your answer..."
            }
            value={(value as string) || ""}
            onChange={(e) => handleAnswer(question.id, e.target.value)}
          />
        )}
        {question.answerType === "number" && (
          <Input
            type="number"
            placeholder="0"
            value={value as string | number | undefined}
            onChange={(e) => handleAnswer(question.id, Number(e.target.value))}
          />
        )}
        {question.answerType === "single_choice" && (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {question.options?.map((opt) => (
              <div key={opt.value} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`mc-${question.id}-${opt.value}`}
                />
                <Label htmlFor={`mc-${question.id}-${opt.value}`}>
                  {opt.label}
                </Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {question.answerType === "multiple_choice" && (
          <div className="space-y-2">
            {question.options?.map((opt) => (
              <div key={opt.value} className="flex items-center gap-2">
                <Checkbox
                  id={`mc-${question.id}-${opt.value}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`mc-${question.id}-${opt.value}`}>
                  {opt.label}
                </Label>
              </div>
            ))}
          </div>
        )}

        {/* Media question response */}
        {isMedia && question.responseType === "text" && (
          <Input
            placeholder={
              lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
            }
            value={(value as string) || ""}
            onChange={(e) => handleAnswer(question.id, e.target.value)}
          />
        )}
        {isMedia &&
          (question.responseType === "video" ||
            question.responseType === "audio") && (
            <div className="space-y-3">
              {(() => {
                const hasNewUpload = uploadedFiles[question.id]
                const hasExistingFile =
                  existingFiles[question.id] &&
                  existingFiles[question.id].length > 0 &&
                  !filesToRemove.includes(existingFiles[question.id][0])

                return (
                  <>
                    {/* Show existing uploaded file */}
                    {hasExistingFile && !hasNewUpload && (
                      <div className="rounded-lg border bg-muted/30 p-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {question.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="text-sm">
                              {existingFiles[question.id][0].split("_").pop()}
                            </span>
                          </div>
                          <div className="flex items-center gap-2">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(existingFiles[question.id][0]),
                                  "_blank"
                                )
                              }
                            >
                              <Play className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                handleRemoveExistingFile(
                                  existingFiles[question.id][0]
                                )
                              }
                            >
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          </div>
                        </div>
                        <div className="mt-2">
                          {question.responseType === "video" ? (
                            <video
                              src={getFileUrl(existingFiles[question.id][0])}
                              controls
                              className="w-full rounded"
                              style={{ maxHeight: "200px" }}
                            />
                          ) : (
                            <audio
                              src={getFileUrl(existingFiles[question.id][0])}
                              controls
                              className="w-full"
                            />
                          )}
                        </div>
                      </div>
                    )}

                    {/* Show new file being uploaded */}
                    {hasNewUpload && (
                      <div className="rounded-lg border bg-muted/30 p-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {question.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="text-sm">
                              {uploadedFiles[question.id].file.name}
                            </span>
                          </div>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleRemoveFile(question.id)}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        </div>
                        {uploadedFiles[question.id].preview && (
                          <div className="mt-2">
                            {question.responseType === "video" ? (
                              <video
                                src={uploadedFiles[question.id].preview}
                                controls
                                className="w-full rounded"
                                style={{ maxHeight: "200px" }}
                              />
                            ) : (
                              <audio
                                src={uploadedFiles[question.id].preview}
                                controls
                                className="w-full"
                              />
                            )}
                          </div>
                        )}
                      </div>
                    )}

                    {/* Upload button */}
                    {!hasExistingFile && !hasNewUpload && (
                      <div className="flex items-center gap-2">
                        <Input
                          type="file"
                          accept={
                            question.responseType === "video"
                              ? "video/*"
                              : "audio/*"
                          }
                          onChange={(e) => handleFileSelect(question.id, e)}
                          className="hidden"
                          id={`media-upload-${question.id}`}
                        />
                        <Button
                          variant="outline"
                          onClick={() =>
                            document
                              .getElementById(`media-upload-${question.id}`)
                              ?.click()
                          }
                        >
                          <Upload className="me-2 h-4 w-4" />
                          {lang === "ar" ? "اختيار ملف" : "Choose File"}
                        </Button>
                      </div>
                    )}
                  </>
                )
              })()}
            </div>
          )}

        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMediaItem = (item: MediaItem) => {
    const hasNewUpload = uploadedFiles[item.id]
    const hasExistingFile =
      existingFiles[item.id] &&
      existingFiles[item.id].length > 0 &&
      !filesToRemove.includes(existingFiles[item.id][0])
    const hasError = errors.includes(item.id)

    return (
      <div key={item.id} className="space-y-3 rounded-lg border bg-card p-4">
        <Label className="text-base font-medium">{item.question}</Label>

        {/* Display existing media (question media) */}
        {item.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
            {item.mediaType === "image" && (
              <img
                src={item.mediaUrl}
                alt={lang === "ar" ? "الوسائط" : "Media"}
                className="h-full w-full object-contain"
              />
            )}
            {item.mediaType === "video" && (
              <video
                src={item.mediaUrl}
                controls
                className="h-full w-full object-contain"
              />
            )}
            {item.mediaType === "audio" && (
              <div className="p-4">
                <audio src={item.mediaUrl} controls className="w-full" />
              </div>
            )}
          </div>
        )}

        {/* Response section */}
        {item.responseType === "text" && (
          <div>
            <Label className="text-sm text-muted-foreground">
              {lang === "ar" ? "إجابتك:" : "Your response:"}
            </Label>
            <Input
              placeholder={
                lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
              }
              value={mediaResponses[item.id] || ""}
              onChange={(e) => {
                setMediaResponses((prev) => ({
                  ...prev,
                  [item.id]: e.target.value,
                }))
                setErrors((prev) => prev.filter((e) => e !== item.id))
              }}
              className="mt-2"
            />
            {hasError && (
              <div className="flex items-center gap-1 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
              </div>
            )}
          </div>
        )}

        {/* Video/Audio response upload */}
        {(item.responseType === "video" || item.responseType === "audio") && (
          <div className="space-y-3">
            <Label className="text-sm text-muted-foreground">
              {lang === "ar"
                ? item.responseType === "video"
                  ? "رفع فيديو الرد:"
                  : "رفع صوت الرد:"
                : item.responseType === "video"
                  ? "Upload video response:"
                  : "Upload audio response:"}
            </Label>

            {/* Show existing uploaded file */}
            {hasExistingFile && !hasNewUpload && (
              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {item.responseType === "video" ? (
                      <Video className="h-5 w-5" />
                    ) : (
                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {existingFiles[item.id][0].split("_").pop()}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(
                          getFileUrl(existingFiles[item.id][0]),
                          "_blank"
                        )
                      }
                    >
                      <Play className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        handleRemoveExistingFile(existingFiles[item.id][0])
                      }
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
                {/* Preview player */}
                <div className="mt-2">
                  {item.responseType === "video" ? (
                    <video
                      src={getFileUrl(existingFiles[item.id][0])}
                      controls
                      className="w-full rounded"
                      style={{ maxHeight: "200px" }}
                    />
                  ) : (
                    <audio
                      src={getFileUrl(existingFiles[item.id][0])}
                      controls
                      className="w-full"
                    />
                  )}
                </div>
              </div>
            )}

            {/* Show new file being uploaded */}
            {hasNewUpload && (
              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {item.responseType === "video" ? (
                      <Video className="h-5 w-5" />
                    ) : (
                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {uploadedFiles[item.id].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(item.id)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
                {/* Preview player for new upload */}
                {uploadedFiles[item.id].preview && (
                  <div className="mt-2">
                    {item.responseType === "video" ? (
                      <video
                        src={uploadedFiles[item.id].preview}
                        controls
                        className="w-full rounded"
                        style={{ maxHeight: "200px" }}
                      />
                    ) : (
                      <audio
                        src={uploadedFiles[item.id].preview}
                        controls
                        className="w-full"
                      />
                    )}
                  </div>
                )}
              </div>
            )}

            {/* Upload button */}
            {!hasExistingFile && !hasNewUpload && (
              <div className="flex items-center gap-2">
                <Input
                  type="file"
                  accept={item.responseType === "video" ? "video/*" : "audio/*"}
                  onChange={(e) => handleFileSelect(item.id, e)}
                  className="hidden"
                  id={`media-upload-${item.id}`}
                />
                <Button
                  variant="outline"
                  onClick={() =>
                    document.getElementById(`media-upload-${item.id}`)?.click()
                  }
                >
                  <Upload className="me-2 h-4 w-4" />
                  {lang === "ar" ? "اختيار ملف" : "Choose File"}
                </Button>
              </div>
            )}

            {hasError && (
              <div className="flex items-center gap-1 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {lang === "ar" ? "الرد مطلوب" : "Response is required"}
              </div>
            )}
          </div>
        )}
      </div>
    )
  }

  const renderAttachment = () => {
    if (!attachmentConfig) return null

    const existingUnmapped = existingFiles["_unmapped"] || []
    const filteredExisting = existingUnmapped.filter(
      (f) => !filesToRemove.includes(f)
    )
    const newUploadKeys = Object.keys(uploadedFiles).filter((k) =>
      k.startsWith("attachment_")
    )
    const totalFiles = newUploadKeys.length + filteredExisting.length
    const hasError = errors.includes("attachment")

    return (
      <div className="space-y-4">
        <div className="rounded-lg border bg-card p-4">
          <h3 className="mb-2 text-lg font-semibold">
            {
              (attachmentConfig.title as unknown as { en: string; ar: string })[
                lang
              ]
            }
          </h3>
          <p className="text-sm text-muted-foreground">
            {lang === "ar"
              ? `الحد الأقصى: ${attachmentConfig.maxFiles} ملف(ات), ${attachmentConfig.maxFileSize}MB لكل ملف`
              : `Max files: ${attachmentConfig.maxFiles}, ${attachmentConfig.maxFileSize}MB each`}
          </p>
          <p className="text-sm text-muted-foreground">
            {lang === "ar" ? "أنواع الملفات المسموح بها: " : "Allowed types: "}
            {attachmentConfig.allowedTypes.join(", ")}
          </p>

          {/* Existing files */}
          {filteredExisting.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "الملفات المرفقة:" : "Attached files:"}
              </Label>
              {filteredExisting.map((filename, idx) => (
                <div
                  key={`existing-${idx}`}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(filename)}
                    <span className="text-sm">{filename.split("_").pop()}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(getFileUrl(filename), "_blank")
                      }
                    >
                      {lang === "ar" ? "عرض" : "View"}
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleRemoveExistingFile(filename)}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* New uploads */}
          {newUploadKeys.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "ملفات جديدة:" : "New files:"}
              </Label>
              {newUploadKeys.map((key) => (
                <div
                  key={key}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(uploadedFiles[key].file.name)}
                    <span className="text-sm">
                      {uploadedFiles[key].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(key)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          {/* Upload button */}
          {totalFiles < attachmentConfig.maxFiles && (
            <div className="mt-4">
              <Input
                type="file"
                accept={getAcceptTypes(attachmentConfig.allowedTypes)}
                onChange={(e) => {
                  const newKey = `attachment_${Date.now()}`
                  handleFileSelect(newKey, e, attachmentConfig.allowedTypes)
                }}
                className="hidden"
                id="attachment-upload"
              />
              <Button
                variant="outline"
                onClick={() =>
                  document.getElementById("attachment-upload")?.click()
                }
              >
                <Upload className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة ملف" : "Add File"}
              </Button>
            </div>
          )}

          {hasError && (
            <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
              <AlertCircle className="h-4 w-4" />
              {lang === "ar" ? "الملفات مطلوبة" : "Files are required"}
            </div>
          )}
        </div>
      </div>
    )
  }

  const getAcceptTypes = (allowedTypes: AttachmentFileType[]): string => {
    const typeMap: Record<AttachmentFileType, string> = {
      image: "image/*",
      document: ".pdf,.doc,.docx,.txt",
      video: "video/*",
      audio: "audio/*",
      any: "*/*",
    }
    return allowedTypes.map((t) => typeMap[t]).join(",")
  }

  const displayName =
    lang === "ar"
      ? assignment.name_ar || assignment.name_en
      : assignment.name_en

  if (isCompleted) {
    return (
      <div className="mx-auto max-w-2xl space-y-6">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="flex-1">
            <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
            <p className="text-muted-foreground">{profile.name}</p>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>{assignment.name_en}</CardTitle>
            <CardDescription>
              {lang === "ar" ? "تمت الإجابة" : "Completed"}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {isSurveyTool &&
              (() => {
                const sortedOptions = [...(surveyConfig?.options || [])].sort(
                  (a, b) => a.order - b.order
                )
                const isMultiple =
                  surveyConfig?.answerType === "multiple_choice"
                return (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                          <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                            {lang === "ar" ? "الأسئلة" : "Questions"}
                          </th>
                          {sortedOptions.map((opt) => (
                            <th
                              key={opt.id}
                              className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                            >
                              {opt.label}
                            </th>
                          ))}
                        </tr>
                      </thead>
                      <tbody className="divide-y">
                        {surveyConfig?.questions.map((question) => {
                          const value = answers[question.id] as
                            | string
                            | string[]
                            | undefined
                          return (
                            <tr
                              key={question.id}
                              className="text-muted-foreground"
                            >
                              <td className="py-3 pe-4 align-top font-medium">
                                {question.text}
                              </td>
                              {sortedOptions.map((opt) => (
                                <td
                                  key={opt.id}
                                  className="px-2 py-3 text-center"
                                >
                                  {isMultiple ? (
                                    ((value as string[]) || []).includes(
                                      opt.value
                                    ) ? (
                                      <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                    ) : null
                                  ) : (value as string) === opt.value ? (
                                    <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                  ) : null}
                                </td>
                              ))}
                            </tr>
                          )
                        })}
                      </tbody>
                    </table>
                  </div>
                )
              })()}

            {isMultipleChoiceTool &&
              mcConfig?.questions.map((question, idx) => (
                <div key={question.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {idx + 1}. {question.text}
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {question.answerType === "text" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "number" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "single_choice" && (
                      <span className="font-medium">
                        {question.options?.find(
                          (o) => o.value === answers[question.id]
                        )?.label || "-"}
                      </span>
                    )}
                    {question.answerType === "multiple_choice" && (
                      <div className="flex flex-wrap gap-2">
                        {((answers[question.id] as string[]) || []).map((v) => (
                          <span
                            key={v}
                            className="rounded-full bg-primary/10 px-3 py-1 text-sm"
                          >
                            {
                              question.options?.find((o) => o.value === v)
                                ?.label
                            }
                          </span>
                        ))}
                      </div>
                    )}
                    {question.answerType === "media" && (
                      <div>
                        {question.responseType === "text" ? (
                          <span className="font-medium">
                            {String(answers[question.id] || "-")}
                          </span>
                        ) : (
                          <div>
                            {assignment.responses?.[question.id] ? (
                              <div className="flex items-center gap-2">
                                {question.responseType === "video" ? (
                                  <Video className="h-5 w-5" />
                                ) : (
                                  <Music className="h-5 w-5" />
                                )}
                                <span className="font-medium">
                                  {(assignment.responses[question.id] as string)
                                    .split("_")
                                    .pop()}
                                </span>
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() =>
                                    window.open(
                                      getFileUrl(
                                        assignment.responses[
                                          question.id
                                        ] as string
                                      ),
                                      "_blank"
                                    )
                                  }
                                >
                                  {lang === "ar" ? "تشغيل" : "Play"}
                                </Button>
                              </div>
                            ) : (
                              <span className="text-muted-foreground">-</span>
                            )}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isMediaTool &&
              mediaConfig?.items.map((item) => (
                <div key={item.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {
                      (item.question as unknown as { en: string; ar: string })[
                        lang
                      ]
                    }
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {item.responseType === "text" ? (
                      <span className="font-medium">
                        {String(
                          answers[item.id] || mediaResponses[item.id] || "-"
                        )}
                      </span>
                    ) : (
                      <div>
                        {assignment.responses?.[item.id] ? (
                          <div className="flex items-center gap-2">
                            {item.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="font-medium">
                              {(assignment.responses[item.id] as string)
                                .split("_")
                                .pop()}
                            </span>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(
                                    assignment.responses[item.id] as string
                                  ),
                                  "_blank"
                                )
                              }
                            >
                              {lang === "ar" ? "تشغيل" : "Play"}
                            </Button>
                          </div>
                        ) : (
                          <span className="text-muted-foreground">-</span>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isAttachmentTool && (
              <div className="space-y-2">
                <Label className="text-base font-medium text-muted-foreground">
                  {(
                    attachmentConfig?.title as unknown as {
                      en: string
                      ar: string
                    }
                  )?.[lang] || (lang === "ar" ? "المرفقات" : "Attachments")}
                </Label>
                <div className="space-y-2">
                  {assignment.media && assignment.media.length > 0 ? (
                    assignment.media.map((file, idx) => (
                      <div
                        key={idx}
                        className="flex items-center justify-between rounded-lg bg-muted/30 p-3"
                      >
                        <div className="flex items-center gap-2">
                          {getFileIcon(file)}
                          <span className="font-medium">
                            {file.split("_").pop()}
                          </span>
                        </div>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() =>
                            window.open(getFileUrl(file), "_blank")
                          }
                        >
                          {lang === "ar" ? "عرض" : "View"}
                        </Button>
                      </div>
                    ))
                  ) : (
                    <p className="text-muted-foreground">
                      {lang === "ar" ? "لا توجد ملفات" : "No files"}
                    </p>
                  )}
                </div>
              </div>
            )}

            {isMeetingTool && meetingConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الوقت" : "Time"}
                    </Label>
                    <p className="font-medium">{meetingConfig.time || "—"}</p>
                  </div>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">
                    {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                  </Label>
                  <p className="font-medium">
                    {meetingConfig.meetingType === "online"
                      ? lang === "ar" ? "عن بُعد" : "Online"
                      : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                  </p>
                </div>
                {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الرابط" : "Meeting Link"}
                    </Label>
                    <div className="mt-1">
                      <a
                        href={meetingConfig.meetingLink}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <Button variant="default" size="sm">
                          {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                        </Button>
                      </a>
                    </div>
                  </div>
                )}
                {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الموقع" : "Location"}
                    </Label>
                    <p className="font-medium">{meetingConfig.location}</p>
                  </div>
                )}

                {isAdminOrExpert ? (
                  <div className="space-y-2 rounded-lg border p-3">
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                    </Label>
                    <textarea
                      value={localNotes}
                      onChange={(e) => setLocalNotes(e.target.value)}
                      placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                      className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                      rows={3}
                    />
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <input
                          type="checkbox"
                          id="notes-visible-completed"
                          checked={localNotesVisible}
                          onChange={(e) => setLocalNotesVisible(e.target.checked)}
                          className="h-4 w-4 rounded border-gray-300"
                        />
                        <Label htmlFor="notes-visible-completed" className="text-sm text-muted-foreground">
                          {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                        </Label>
                      </div>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={saveNotes}
                        disabled={isSavingNotes}
                      >
                        {isSavingNotes
                          ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                          : lang === "ar" ? "حفظ" : "Save"}
                      </Button>
                    </div>
                  </div>
                ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "ملاحظات" : "Notes"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                  </div>
                ) : null}
              </div>
            )}

            {isReportTool && reportConfig && (
              <div className="space-y-3">
                {reportConfig.date && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{formatDate(reportConfig.date)}</p>
                  </div>
                )}
                {reportConfig.assessment && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التقييم" : "Assessment"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                  </div>
                )}
                {reportConfig.suggestions && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                    </Label>
                    <p className="mt-1 whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                  </div>
                )}
              </div>
            )}

            {isPlanTool && planConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                    </Label>
                    <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                    </Label>
                    <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                  </div>
                </div>
                {planConfig.goals?.length > 0 && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الأهداف" : "Goals"}
                    </Label>
                    <div className="mt-1 space-y-2">
                      {planConfig.goals.map((goal) => (
                        <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                          <p className="font-medium">{goal.title}</p>
                          {goal.description && (
                            <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                {planConfig.steps?.length > 0 && (
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الخطوات" : "Steps"}
                    </Label>
                    <div className="mt-1 space-y-2">
                      {planConfig.steps.map((step) => (
                        <div key={step.id} className="rounded-lg border p-3">
                          <div className="flex items-start gap-2">
                            <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                            <div className="flex-1">
                              <p className="font-medium">{step.title}</p>
                              {step.description && (
                                <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                              )}
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {(isMeetingTool || isReportTool || isPlanTool) && (
              <div className="flex gap-2 pt-4">
                <Button
                  onClick={() => router.push(`/dashboard/individual/cases/${profile.id}`)}
                >
                  {lang === "ar" ? "العودة" : "Back"}
                </Button>
              </div>
            )}

            {!isMeetingTool && !isReportTool && !isPlanTool && (
            <div className="flex gap-2 pt-4">
              <Button
                variant="outline"
                onClick={() =>
                  updateAssignment(assignmentId, { status: "in_progress" })
                }
              >
                {lang === "ar" ? "تعديل الإجابات" : "Edit Answers"}
              </Button>
              <Button
                onClick={() => router.push(`/dashboard/individual/cases/${profile.id}`)}
              >
                {lang === "ar" ? "العودة" : "Back"}
              </Button>
            </div>
            )}
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
          <p className="text-muted-foreground">{profile.name}</p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>{assignment.name_en}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {isSurveyTool &&
            (() => {
              const sortedOptions = [...(surveyConfig?.options || [])].sort(
                (a, b) => a.order - b.order
              )
              const isMultiple = surveyConfig?.answerType === "multiple_choice"
              return (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                        <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                          {lang === "ar" ? "الأسئلة" : "Questions"}
                        </th>
                        {sortedOptions.map((opt) => (
                          <th
                            key={opt.id}
                            className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                          >
                            {opt.label}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {surveyConfig?.questions.map((question) => {
                        const value = answers[question.id] as
                          | string
                          | string[]
                          | undefined
                        const hasError = errors.includes(question.id)
                        return (
                          <tr key={question.id}>
                            <td className="py-3 pe-4 align-top">
                              <Label className="text-base font-medium">
                                {question.text}
                                {question.required && (
                                  <span className="ms-1 text-destructive">
                                    *
                                  </span>
                                )}
                              </Label>
                            </td>
                            {sortedOptions.map((opt) => (
                              <td
                                key={opt.id}
                                className="px-2 py-3 text-center"
                              >
                                {isMultiple ? (
                                  <Checkbox
                                    id={`${question.id}-${opt.id}`}
                                    checked={(
                                      (value as string[]) || []
                                    ).includes(opt.value)}
                                    onCheckedChange={(checked) => {
                                      if (checked) {
                                        handleAnswer(question.id, [
                                          ...((value as string[]) || []),
                                          opt.value,
                                        ])
                                      } else {
                                        handleAnswer(
                                          question.id,
                                          ((value as string[]) || []).filter(
                                            (v) => v !== opt.value
                                          )
                                        )
                                      }
                                    }}
                                    className="mx-auto"
                                  />
                                ) : (
                                  <button
                                    type="button"
                                    onClick={() =>
                                      handleAnswer(question.id, opt.value)
                                    }
                                    className={`mx-auto h-5 w-5 rounded-full border-2 transition-colors ${
                                      (value as string) === opt.value
                                        ? "border-primary bg-primary"
                                        : "border-muted-foreground hover:border-primary"
                                    }`}
                                  />
                                )}
                              </td>
                            ))}
                          </tr>
                        )
                      })}
                    </tbody>
                  </table>
                  {errors.some((errId) =>
                    surveyConfig?.questions.find((q) => q.id === errId)
                  ) && (
                    <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
                      <AlertCircle className="h-4 w-4" />
                      {lang === "ar"
                        ? "يرجى الإجابة على جميع الأسئلة المطلوبة"
                        : "Please answer all required questions"}
                    </div>
                  )}
                </div>
              )
            })()}

          {isMultipleChoiceTool &&
            mcConfig?.questions.map((question) => (
              <div key={question.id}>{renderMCQuestion(question)}</div>
            ))}

          {isMediaTool &&
            mediaConfig?.items.map((item) => renderMediaItem(item))}

          {isAttachmentTool && renderAttachment()}

          {isMeetingTool && meetingConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الوقت" : "Time"}
                  </Label>
                  <p className="font-medium">{meetingConfig.time || "—"}</p>
                </div>
              </div>
              <div className="space-y-1">
                <Label className="text-muted-foreground">
                  {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                </Label>
                <p className="font-medium">
                  {meetingConfig.meetingType === "online"
                    ? lang === "ar" ? "عن بُعد" : "Online"
                    : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                </p>
              </div>
              {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الرابط" : "Meeting Link"}
                  </Label>
                  <a
                    href={meetingConfig.meetingLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block"
                  >
                    <Button variant="default" className="w-full">
                      {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                    </Button>
                  </a>
                </div>
              )}
              {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الموقع" : "Location"}
                  </Label>
                  <p className="font-medium">{meetingConfig.location}</p>
                </div>
              )}

              {isAdminOrExpert ? (
                <div className="space-y-3 rounded-lg border p-4">
                  <Label className="text-sm font-medium">
                    {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                  </Label>
                  <textarea
                    value={localNotes}
                    onChange={(e) => setLocalNotes(e.target.value)}
                    placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                    className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                    rows={3}
                  />
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <input
                        type="checkbox"
                        id="notes-visible-task"
                        checked={localNotesVisible}
                        onChange={(e) => setLocalNotesVisible(e.target.checked)}
                        className="h-4 w-4 rounded border-gray-300"
                      />
                      <Label htmlFor="notes-visible-task" className="text-sm text-muted-foreground">
                        {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                      </Label>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={saveNotes}
                      disabled={isSavingNotes}
                    >
                      {isSavingNotes
                        ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                        : lang === "ar" ? "حفظ" : "Save"}
                    </Button>
                  </div>
                </div>
              ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "ملاحظات" : "Notes"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                </div>
              ) : null}
            </div>
          )}

          {isReportTool && reportConfig && (
            <div className="space-y-4">
              {reportConfig.date && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{formatDate(reportConfig.date)}</p>
                </div>
              )}
              {reportConfig.assessment && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التقييم" : "Assessment"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                </div>
              )}
              {reportConfig.suggestions && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                </div>
              )}
            </div>
          )}

          {isPlanTool && planConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                  </Label>
                  <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                  </Label>
                  <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                </div>
              </div>
              {planConfig.goals?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الأهداف" : "Goals"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.goals.map((goal) => (
                      <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                        <p className="font-medium">{goal.title}</p>
                        {goal.description && (
                          <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
              {planConfig.steps?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الخطوات" : "Steps"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.steps.map((step) => (
                      <div key={step.id} className="rounded-lg border p-3">
                        <div className="flex items-start gap-2">
                          <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                          <div className="flex-1">
                            <p className="font-medium">{step.title}</p>
                            {step.description && (
                              <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {(isMeetingTool || isReportTool || isPlanTool) ? (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الحفظ..."
                  : "Saving..."
                : lang === "ar"
                  ? "تأكيد الإتمام"
                  : "Mark as Completed"}
            </Button>
          ) : (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الإرسال..."
                  : "Submitting..."
                : lang === "ar"
                  ? "إرسال"
                  : "Submit"}
            </Button>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { useEffect } from "react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { ProfileCard } from "@/components/profiles/ProfileCard"
import { Card, CardContent } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { PageLoader } from "@/components/ui/page-loader"
import { FolderKanban, Plus } from "lucide-react"

export default function ProfilesPage() {
  const router = useRouter()
  const { currentUser } = useAuth()
  const { lang } = useLang()
  const { profiles, isLoading } = useProfiles()

  if (isLoading) {
    return <PageLoader text={lang === "ar" ? "جارٍ تحميل الحالات..." : "Loading cases..."} />
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-primary">
            {lang === "ar" ? "الحالات" : "Cases"}
          </h1>
          <p className="text-muted-foreground">
            {lang === "ar" ? "إدارة حالاتك" : "Manage your cases"}
          </p>
        </div>
        <Link href="/dashboard/individual/cases/new">
          <Button>
            <Plus className="me-2 h-4 w-4" />
            {lang === "ar" ? "حالة جديدة" : "New Case"}
          </Button>
        </Link>
      </div>

      {profiles.length === 0 ? (
        <Card>
          <CardContent className="flex flex-col items-center justify-center py-12">
            <FolderKanban className="mb-4 h-12 w-12 text-muted-foreground" />
            <h3 className="mb-2 text-lg font-medium">
              {lang === "ar" ? "لا توجد حالات بعد" : "No cases yet"}
            </h3>
            <p className="mb-4 text-center text-muted-foreground">
              {lang === "ar"
                ? "أنشئ حالتك الأولى للبدء"
                : "Create your first case to get started"}
            </p>
            <Link href="/dashboard/individual/cases/new">
              <Button>{lang === "ar" ? "إنشاء الحالة" : "Create Case"}</Button>
            </Link>
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {profiles.map((profile) => (
            <ProfileCard
              key={profile.id}
              profile={profile}
              hrefPrefix="/dashboard/individual/cases"
            />
          ))}
        </div>
      )}
    </div>
  )
}

"use client"

import { use, useState, useEffect, useMemo, useRef } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { formatDate } from "@/lib/format-date"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { Input } from "@/components/ui/input"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Checkbox } from "@/components/ui/checkbox"
import {
  ArrowLeft,
  CheckCircle,
  AlertCircle,
  Upload,
  X,
  FileText,
  Image,
  Video,
  Music,
  Play,
  Trash2,
  File,
} from "lucide-react"
import Link from "next/link"
import type {
  SurveyConfig,
  SurveyQuestion,
  MultipleChoiceConfig,
  MCQuestion,
  MediaConfig,
  MediaItem,
  AttachmentRequestConfig,
  AttachmentFileType,
  OneToOneMeetingConfig,
  ReportConfig,
  PlanConfig,
} from "@/types/tool"
import { cn } from "@/lib/utils"
import { toast } from "sonner"
import pb, { getErrorMessage } from "@/lib/pb"
import { PaymentGate } from "@/components/cases/PaymentGate"

const RATING_LABELS: Record<number, { en: string; ar: string }> = {
  1: { en: "Very Low", ar: "منخفض جداً" },
  2: { en: "Low", ar: "منخفض" },
  3: { en: "Medium", ar: "متوسط" },
  4: { en: "High", ar: "عالٍ" },
  5: { en: "Very High", ar: "عالٍ جداً" },
}

export default function TakeSurveyToolPage({
  params,
}: {
  params: Promise<{ id: string; toolId: string }>
}) {
  const params2 = use(params)
  const caseId = params2.id
  const assignmentId = params2.toolId
  const router = useRouter()
  const { lang } = useLang()
  const { getProfileById } = useProfiles()
  const {
    assignments,
    updateAssignment,
    updateAssignmentWithFiles,
    isLoading: isAssignmentsLoading,
  } = useAssignments(caseId)
  const { getToolTypeById, fetchToolTypes } = useToolTypes()
  const { currentUser } = useAuth()

  const assignment = assignments.find((a) => a.id === assignmentId) // Find by toolId
  const profile = getProfileById(caseId) // Get profile by case ID
  const toolType = assignment ? getToolTypeById(assignment.type) : undefined
  const toolTypeName = toolType?.key || "unknown"

  const isAdminOrExpert = currentUser?.role === "admin" || currentUser?.role === "super_admin" || currentUser?.role === "expert"

  const isSurveyTool = toolTypeName === "survey"
  const isMultipleChoiceTool = toolTypeName === "multiple_answer"
  const isMediaTool = toolTypeName === "media_question"
  const isAttachmentTool = toolTypeName === "attachment_request"
  const isMeetingTool = toolTypeName === "one_to_one_meeting"
  const isReportTool = toolTypeName === "report"
  const isPlanTool = toolTypeName === "plan"

  const surveyConfig = isSurveyTool
    ? (assignment?.config as SurveyConfig | undefined)
    : undefined
  const mcConfig = isMultipleChoiceTool
    ? (assignment?.config as MultipleChoiceConfig | undefined)
    : undefined
  const mediaConfig = isMediaTool
    ? (assignment?.config as MediaConfig | undefined)
    : undefined
  const attachmentConfig = isAttachmentTool
    ? (assignment?.config as AttachmentRequestConfig | undefined)
    : undefined
  const meetingConfig = isMeetingTool
    ? (assignment?.config as OneToOneMeetingConfig | undefined)
    : undefined
  const reportConfig = isReportTool
    ? (assignment?.config as ReportConfig | undefined)
    : undefined
  const planConfig = isPlanTool
    ? (assignment?.config as PlanConfig | undefined)
    : undefined

  const config = surveyConfig || mcConfig || mediaConfig || attachmentConfig || meetingConfig || reportConfig || planConfig

  const existingResponses = assignment?.responses as
    | Record<string, unknown>
    | undefined
  const [answers, setAnswers] = useState<Record<string, unknown>>({})
  const [mediaResponses, setMediaResponses] = useState<Record<string, string>>(
    {}
  )
  const [errors, setErrors] = useState<string[]>([])
  const [isSubmitting, setIsSubmitting] = useState(false)
  const isCompleted = assignment?.status === "completed"

  const [localNotes, setLocalNotes] = useState("")
  const [localNotesVisible, setLocalNotesVisible] = useState(false)
  const [isSavingNotes, setIsSavingNotes] = useState(false)

  useEffect(() => {
    if (meetingConfig) {
      setLocalNotes(meetingConfig.notes || "")
      setLocalNotesVisible(meetingConfig.notesVisibleToUser || false)
    }
  }, [meetingConfig])

  // File upload state for media and attachment tools
  const [uploadedFiles, setUploadedFiles] = useState<
    Record<string, { file: File; preview?: string }>
  >({})
  const [existingFiles, setExistingFiles] = useState<Record<string, string[]>>(
    {}
  )
  const [filesToRemove, setFilesToRemove] = useState<string[]>([])

  const hasFetchedToolTypes = useRef(false)
  const hasInitializedAnswers = useRef(false)
  const hasInitializedFiles = useRef(false)

  useEffect(() => {
    if (hasFetchedToolTypes.current) return
    hasFetchedToolTypes.current = true
    fetchToolTypes()
  }, [fetchToolTypes])

  // Initialize answers from existing responses - only once
  useEffect(() => {
    if (hasInitializedAnswers.current) return
    if (existingResponses && Object.keys(existingResponses).length > 0) {
      setAnswers(existingResponses)
      hasInitializedAnswers.current = true
    }
  }, [existingResponses])

  // Initialize existing files from assignment media - only once
  useEffect(() => {
    if (hasInitializedFiles.current) return
    if (assignment?.media && assignment.media.length > 0) {
      // Group files by response key from responses data
      const filesByKey: Record<string, string[]> = {}

      if (assignment.responses) {
        Object.entries(assignment.responses).forEach(([key, value]) => {
          if (typeof value === "string" && assignment.media?.includes(value)) {
            if (!filesByKey[key]) filesByKey[key] = []
            filesByKey[key].push(value)
          }
        })
      }

      // Also add files not yet mapped to any key (for attachment tool)
      const unmappedFiles = assignment.media.filter(
        (file) =>
          !Object.values(filesByKey).some((files) => files.includes(file))
      )
      if (unmappedFiles.length > 0) {
        filesByKey["_unmapped"] = unmappedFiles
      }

      setExistingFiles(filesByKey)
      hasInitializedFiles.current = true
    }
  }, [assignment?.media, assignment?.responses])

  if (isAssignmentsLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جاري التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  if (!assignment || !profile || !config) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الأداة غير موجودة" : "Tool not found"}
        </h2>
        <Link href="/dashboard/institution/projects">
          <Button>
            {lang === "ar" ? "العودة إلى المشاريع" : "Back to Projects"}
          </Button>
        </Link>
      </div>
    )
  }

  if (profile.status && profile.status !== "active" && !isAdminOrExpert) {
    return <PaymentGate profile={profile} noun="project" />
  }

  const handleAnswer = (questionId: string, value: unknown) => {
    setAnswers((prev) => ({ ...prev, [questionId]: value }))
    setErrors((prev) => prev.filter((e) => e !== questionId))
  }

  const validateRequired = (): boolean => {
    const missing: string[] = []

    if (isSurveyTool && surveyConfig) {
      surveyConfig.questions.forEach((q) => {
        if (q.required) {
          const answer = answers[q.id]
          if (
            answer === undefined ||
            answer === null ||
            (typeof answer === "string" && answer.trim() === "") ||
            (Array.isArray(answer) && answer.length === 0)
          ) {
            missing.push(q.id)
          }
        }
      })
    }

    if (isMultipleChoiceTool && mcConfig) {
      mcConfig.questions.forEach((q) => {
        if (q.required) {
          if (q.answerType === "media") {
            if (q.responseType === "text") {
              const answer = answers[q.id]
              if (
                !answer ||
                (typeof answer === "string" && answer.trim() === "")
              ) {
                missing.push(q.id)
              }
            } else if (
              q.responseType === "video" ||
              q.responseType === "audio"
            ) {
              const hasNewFile = uploadedFiles[q.id]
              const hasExistingFile =
                existingFiles[q.id] && existingFiles[q.id].length > 0
              if (!hasNewFile && !hasExistingFile) {
                missing.push(q.id)
              }
            }
          } else {
            const answer = answers[q.id]
            if (
              answer === undefined ||
              answer === null ||
              (typeof answer === "string" && answer.trim() === "") ||
              (typeof answer === "number" && isNaN(answer)) ||
              (Array.isArray(answer) && answer.length === 0)
            ) {
              missing.push(q.id)
            }
          }
        }
      })
    }

    if (isMediaTool && mediaConfig) {
      mediaConfig.items.forEach((item) => {
        if (item.responseType === "text") {
          const answer = mediaResponses[item.id]
          if (!answer || answer.trim() === "") {
            missing.push(item.id)
          }
        } else if (
          item.responseType === "video" ||
          item.responseType === "audio"
        ) {
          // Check if a file is uploaded for this media item
          const hasNewFile = uploadedFiles[item.id]
          const hasExistingFile =
            existingFiles[item.id] && existingFiles[item.id].length > 0
          if (!hasNewFile && !hasExistingFile) {
            missing.push(item.id)
          }
        }
      })
    }

    if (isAttachmentTool && attachmentConfig) {
      const totalFiles = Object.keys(uploadedFiles).length
      const totalExisting = existingFiles["_unmapped"]
        ? existingFiles["_unmapped"].filter((f) => !filesToRemove.includes(f))
            .length
        : 0

      if (attachmentConfig.required && totalFiles + totalExisting === 0) {
        missing.push("attachment")
      }
    }

    setErrors(missing)
    return missing.length === 0
  }

  const saveNotes = async () => {
    if (!assignment || !meetingConfig) return
    setIsSavingNotes(true)
    try {
      const updatedConfig = {
        ...meetingConfig,
        notes: localNotes || undefined,
        notesVisibleToUser: localNotesVisible,
      }
      await updateAssignment(assignmentId, {
        config: updatedConfig as OneToOneMeetingConfig,
      })
    } catch (error) {
      console.error("Failed to save notes:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSavingNotes(false)
    }
  }

  const handleSubmit = async () => {
    if (!validateRequired()) return

    setIsSubmitting(true)
    try {
      // Build responses with file references for media/attachment tools
      const finalResponses: Record<string, unknown> = { ...answers }

      if (isMediaTool && mediaConfig) {
        mediaConfig.items.forEach((item) => {
          if (item.responseType === "text") {
            finalResponses[item.id] = mediaResponses[item.id] || ""
          } else if (uploadedFiles[item.id]) {
            // File will be uploaded, reference will be added after upload
            finalResponses[item.id] = uploadedFiles[item.id].file.name
          }
        })
      }

      if (isMultipleChoiceTool && mcConfig) {
        mcConfig.questions.forEach((q) => {
          if (
            q.answerType === "media" &&
            (q.responseType === "video" || q.responseType === "audio")
          ) {
            if (uploadedFiles[q.id]) {
              finalResponses[q.id] = uploadedFiles[q.id].file.name
            }
          }
        })
      }

      if (isAttachmentTool) {
        // Add references for uploaded files
        Object.entries(uploadedFiles).forEach(([key, data]) => {
          finalResponses[key] = data.file.name
        })
      }

      // Upload files if any
      const filesToUpload = Object.values(uploadedFiles).map(
        (data) => data.file
      )

      if (filesToUpload.length > 0 || filesToRemove.length > 0) {
        await updateAssignmentWithFiles(
          assignmentId,
          {
            status: "completed",
            responses: finalResponses,
          },
          filesToUpload,
          filesToRemove.length > 0 ? filesToRemove : undefined
        )
      } else {
        await updateAssignment(assignmentId, {
          status: "completed",
          responses: finalResponses,
        })
      }

      router.push(`/dashboard/institution/projects/${profile.id}`)
    } catch (error) {
      console.error("Failed to submit:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleStart = async () => {
    if (assignment.status === "pending") {
      await updateAssignment(assignmentId, {
        status: "in_progress",
      })
    }
  }

  // File handling helpers
  const handleFileSelect = (
    key: string,
    e: React.ChangeEvent<HTMLInputElement>,
    allowedTypes?: AttachmentFileType[]
  ) => {
    const file = e.target.files?.[0]
    if (!file) return

    // Validate file type
    if (allowedTypes && allowedTypes.length > 0) {
      const isValidType = validateFileType(file, allowedTypes)
      if (!isValidType) {
        alert(
          lang === "ar" ? "نوع الملف غير مسموح به" : "File type not allowed"
        )
        return
      }
    }

    // Validate file size (default 20MB)
    const maxSize = attachmentConfig?.maxFileSize || 20
    if (file.size > maxSize * 1024 * 1024) {
      alert(
        lang === "ar"
          ? `حجم الملف كبير جداً. الحد الأقصى ${maxSize} ميجابايت`
          : `File too large. Max size is ${maxSize}MB`
      )
      return
    }

    // Create preview for media files
    let preview: string | undefined
    if (file.type.startsWith("image/") || file.type.startsWith("video/")) {
      preview = URL.createObjectURL(file)
    }

    setUploadedFiles((prev) => ({
      ...prev,
      [key]: { file, preview },
    }))
    setErrors((prev) => prev.filter((e) => e !== key))
  }

  const validateFileType = (
    file: File,
    allowedTypes: AttachmentFileType[]
  ): boolean => {
    if (allowedTypes.includes("any")) return true

    const typeMap: Record<AttachmentFileType, string[]> = {
      image: ["image/"],
      document: [
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument",
        "text/",
      ],
      video: ["video/"],
      audio: ["audio/"],
      any: [],
    }

    return allowedTypes.some((type) =>
      typeMap[type]?.some((prefix) => file.type.startsWith(prefix))
    )
  }

  const handleRemoveFile = (key: string) => {
    setUploadedFiles((prev) => {
      const newFiles = { ...prev }
      if (newFiles[key]?.preview) {
        URL.revokeObjectURL(newFiles[key].preview!)
      }
      delete newFiles[key]
      return newFiles
    })
  }

  const handleRemoveExistingFile = (filename: string) => {
    setFilesToRemove((prev) => [...prev, filename])
  }

  const getFileIcon = (filename: string) => {
    const ext = filename.split(".").pop()?.toLowerCase()
    if (["jpg", "jpeg", "png", "gif", "webp"].includes(ext || ""))
      return <Image className="h-5 w-5" />
    if (["mp4", "webm", "mov", "avi"].includes(ext || ""))
      return <Video className="h-5 w-5" />
    if (["mp3", "wav", "ogg", "m4a"].includes(ext || ""))
      return <Music className="h-5 w-5" />
    return <FileText className="h-5 w-5" />
  }

  const getFileUrl = (filename: string) => {
    return pb.files.getUrl(
      { collectionId: "case_tools", id: assignmentId },
      filename
    )
  }

  const renderQuestion = (question: SurveyQuestion) => {
    const value = answers[question.id] as string | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMultiple = surveyConfig?.answerType === "multiple_choice"
    const sortedOptions = [...(surveyConfig?.options || [])].sort(
      (a, b) => a.order - b.order
    )

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>
        {isMultiple ? (
          <div className="space-y-2">
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <Checkbox
                  id={`${question.id}-${opt.id}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{opt.label}</Label>
              </div>
            ))}
          </div>
        ) : (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`${question.id}-${opt.id}`}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{opt.label}</Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMCQuestion = (question: MCQuestion) => {
    const value = answers[question.id] as string | number | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMedia = question.answerType === "media"

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>

        {/* Media prompt */}
        {isMedia && question.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
            {question.mediaType === "image" && (
              <img
                src={question.mediaUrl}
                alt={lang === "ar" ? "الوسائط" : "Media"}
                className="h-full w-full object-contain"
              />
            )}
            {question.mediaType === "video" && (
              <video
                src={question.mediaUrl}
                controls
                className="h-full w-full object-contain"
              />
            )}
            {question.mediaType === "audio" && (
              <div className="p-4">
                <audio src={question.mediaUrl} controls className="w-full" />
              </div>
            )}
          </div>
        )}

        {question.answerType === "text" && (
          <Input
            placeholder={
              lang === "ar" ? "أدخل إجابتك..." : "Enter your answer..."
            }
            value={(value as string) || ""}
            onChange={(e) => handleAnswer(question.id, e.target.value)}
          />
        )}
        {question.answerType === "number" && (
          <Input
            type="number"
            placeholder="0"
            value={value as string | number | undefined}
            onChange={(e) => handleAnswer(question.id, Number(e.target.value))}
          />
        )}
        {question.answerType === "single_choice" && (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {question.options?.map((opt) => (
              <div key={opt.value} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`mc-${question.id}-${opt.value}`}
                />
                <Label htmlFor={`mc-${question.id}-${opt.value}`}>
                  {opt.label}
                </Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {question.answerType === "multiple_choice" && (
          <div className="space-y-2">
            {question.options?.map((opt) => (
              <div key={opt.value} className="flex items-center gap-2">
                <Checkbox
                  id={`mc-${question.id}-${opt.value}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`mc-${question.id}-${opt.value}`}>
                  {opt.label}
                </Label>
              </div>
            ))}
          </div>
        )}

        {/* Media question response */}
        {isMedia && question.responseType === "text" && (
          <Input
            placeholder={
              lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
            }
            value={(value as string) || ""}
            onChange={(e) => handleAnswer(question.id, e.target.value)}
          />
        )}
        {isMedia &&
          (question.responseType === "video" ||
            question.responseType === "audio") && (
            <div className="space-y-3">
              {(() => {
                const hasNewUpload = uploadedFiles[question.id]
                const hasExistingFile =
                  existingFiles[question.id] &&
                  existingFiles[question.id].length > 0 &&
                  !filesToRemove.includes(existingFiles[question.id][0])

                return (
                  <>
                    {/* Show existing uploaded file */}
                    {hasExistingFile && !hasNewUpload && (
                      <div className="rounded-lg border bg-muted/30 p-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {question.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="text-sm">
                              {existingFiles[question.id][0].split("_").pop()}
                            </span>
                          </div>
                          <div className="flex items-center gap-2">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(existingFiles[question.id][0]),
                                  "_blank"
                                )
                              }
                            >
                              <Play className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                handleRemoveExistingFile(
                                  existingFiles[question.id][0]
                                )
                              }
                            >
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          </div>
                        </div>
                        <div className="mt-2">
                          {question.responseType === "video" ? (
                            <video
                              src={getFileUrl(existingFiles[question.id][0])}
                              controls
                              className="w-full rounded"
                              style={{ maxHeight: "200px" }}
                            />
                          ) : (
                            <audio
                              src={getFileUrl(existingFiles[question.id][0])}
                              controls
                              className="w-full"
                            />
                          )}
                        </div>
                      </div>
                    )}

                    {/* Show new file being uploaded */}
                    {hasNewUpload && (
                      <div className="rounded-lg border bg-muted/30 p-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {question.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="text-sm">
                              {uploadedFiles[question.id].file.name}
                            </span>
                          </div>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleRemoveFile(question.id)}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        </div>
                        {uploadedFiles[question.id].preview && (
                          <div className="mt-2">
                            {question.responseType === "video" ? (
                              <video
                                src={uploadedFiles[question.id].preview}
                                controls
                                className="w-full rounded"
                                style={{ maxHeight: "200px" }}
                              />
                            ) : (
                              <audio
                                src={uploadedFiles[question.id].preview}
                                controls
                                className="w-full"
                              />
                            )}
                          </div>
                        )}
                      </div>
                    )}

                    {/* Upload button */}
                    {!hasExistingFile && !hasNewUpload && (
                      <div className="flex items-center gap-2">
                        <Input
                          type="file"
                          accept={
                            question.responseType === "video"
                              ? "video/*"
                              : "audio/*"
                          }
                          onChange={(e) => handleFileSelect(question.id, e)}
                          className="hidden"
                          id={`media-upload-${question.id}`}
                        />
                        <Button
                          variant="outline"
                          onClick={() =>
                            document
                              .getElementById(`media-upload-${question.id}`)
                              ?.click()
                          }
                        >
                          <Upload className="me-2 h-4 w-4" />
                          {lang === "ar" ? "اختيار ملف" : "Choose File"}
                        </Button>
                      </div>
                    )}
                  </>
                )
              })()}
            </div>
          )}

        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMediaItem = (item: MediaItem) => {
    const hasNewUpload = uploadedFiles[item.id]
    const hasExistingFile =
      existingFiles[item.id] &&
      existingFiles[item.id].length > 0 &&
      !filesToRemove.includes(existingFiles[item.id][0])
    const hasError = errors.includes(item.id)

    return (
      <div key={item.id} className="space-y-3 rounded-lg border bg-card p-4">
        <Label className="text-base font-medium">{item.question}</Label>

        {/* Display existing media (question media) */}
        {item.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
            {item.mediaType === "image" && (
              <img
                src={item.mediaUrl}
                alt={lang === "ar" ? "الوسائط" : "Media"}
                className="h-full w-full object-contain"
              />
            )}
            {item.mediaType === "video" && (
              <video
                src={item.mediaUrl}
                controls
                className="h-full w-full object-contain"
              />
            )}
            {item.mediaType === "audio" && (
              <div className="p-4">
                <audio src={item.mediaUrl} controls className="w-full" />
              </div>
            )}
          </div>
        )}

        {/* Response section */}
        {item.responseType === "text" && (
          <div>
            <Label className="text-sm text-muted-foreground">
              {lang === "ar" ? "إجابتك:" : "Your response:"}
            </Label>
            <Input
              placeholder={
                lang === "ar" ? "اكتب إجابتك..." : "Type your answer..."
              }
              value={mediaResponses[item.id] || ""}
              onChange={(e) => {
                setMediaResponses((prev) => ({
                  ...prev,
                  [item.id]: e.target.value,
                }))
                setErrors((prev) => prev.filter((e) => e !== item.id))
              }}
              className="mt-2"
            />
            {hasError && (
              <div className="flex items-center gap-1 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
              </div>
            )}
          </div>
        )}

        {/* Video/Audio response upload */}
        {(item.responseType === "video" || item.responseType === "audio") && (
          <div className="space-y-3">
            <Label className="text-sm text-muted-foreground">
              {lang === "ar"
                ? item.responseType === "video"
                  ? "رفع فيديو الرد:"
                  : "رفع صوت الرد:"
                : item.responseType === "video"
                  ? "Upload video response:"
                  : "Upload audio response:"}
            </Label>

            {/* Show existing uploaded file */}
            {hasExistingFile && !hasNewUpload && (
              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {item.responseType === "video" ? (
                      <Video className="h-5 w-5" />
                    ) : (
                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {existingFiles[item.id][0].split("_").pop()}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(
                          getFileUrl(existingFiles[item.id][0]),
                          "_blank"
                        )
                      }
                    >
                      <Play className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        handleRemoveExistingFile(existingFiles[item.id][0])
                      }
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
                {/* Preview player */}
                <div className="mt-2">
                  {item.responseType === "video" ? (
                    <video
                      src={getFileUrl(existingFiles[item.id][0])}
                      controls
                      className="w-full rounded"
                      style={{ maxHeight: "200px" }}
                    />
                  ) : (
                    <audio
                      src={getFileUrl(existingFiles[item.id][0])}
                      controls
                      className="w-full"
                    />
                  )}
                </div>
              </div>
            )}

            {/* Show new file being uploaded */}
            {hasNewUpload && (
              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {item.responseType === "video" ? (
                      <Video className="h-5 w-5" />
                    ) : (
                      <Music className="h-5 w-5" />
                    )}
                    <span className="text-sm">
                      {uploadedFiles[item.id].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(item.id)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
                {/* Preview player for new upload */}
                {uploadedFiles[item.id].preview && (
                  <div className="mt-2">
                    {item.responseType === "video" ? (
                      <video
                        src={uploadedFiles[item.id].preview}
                        controls
                        className="w-full rounded"
                        style={{ maxHeight: "200px" }}
                      />
                    ) : (
                      <audio
                        src={uploadedFiles[item.id].preview}
                        controls
                        className="w-full"
                      />
                    )}
                  </div>
                )}
              </div>
            )}

            {/* Upload button */}
            {!hasExistingFile && !hasNewUpload && (
              <div className="flex items-center gap-2">
                <Input
                  type="file"
                  accept={item.responseType === "video" ? "video/*" : "audio/*"}
                  onChange={(e) => handleFileSelect(item.id, e)}
                  className="hidden"
                  id={`media-upload-${item.id}`}
                />
                <Button
                  variant="outline"
                  onClick={() =>
                    document.getElementById(`media-upload-${item.id}`)?.click()
                  }
                >
                  <Upload className="me-2 h-4 w-4" />
                  {lang === "ar" ? "اختيار ملف" : "Choose File"}
                </Button>
              </div>
            )}

            {hasError && (
              <div className="flex items-center gap-1 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {lang === "ar" ? "الرد مطلوب" : "Response is required"}
              </div>
            )}
          </div>
        )}
      </div>
    )
  }

  const renderAttachment = () => {
    if (!attachmentConfig) return null

    const existingUnmapped = existingFiles["_unmapped"] || []
    const filteredExisting = existingUnmapped.filter(
      (f) => !filesToRemove.includes(f)
    )
    const newUploadKeys = Object.keys(uploadedFiles).filter((k) =>
      k.startsWith("attachment_")
    )
    const totalFiles = newUploadKeys.length + filteredExisting.length
    const hasError = errors.includes("attachment")

    return (
      <div className="space-y-4">
        <div className="rounded-lg border bg-card p-4">
          <h3 className="mb-2 text-lg font-semibold">
            {
              (attachmentConfig.title as unknown as { en: string; ar: string })[
                lang
              ]
            }
          </h3>
          <p className="text-sm text-muted-foreground">
            {lang === "ar"
              ? `الحد الأقصى: ${attachmentConfig.maxFiles} ملف(ات), ${attachmentConfig.maxFileSize}MB لكل ملف`
              : `Max files: ${attachmentConfig.maxFiles}, ${attachmentConfig.maxFileSize}MB each`}
          </p>
          <p className="text-sm text-muted-foreground">
            {lang === "ar" ? "أنواع الملفات المسموح بها: " : "Allowed types: "}
            {attachmentConfig.allowedTypes.join(", ")}
          </p>

          {/* Existing files */}
          {filteredExisting.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "الملفات المرفقة:" : "Attached files:"}
              </Label>
              {filteredExisting.map((filename, idx) => (
                <div
                  key={`existing-${idx}`}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(filename)}
                    <span className="text-sm">{filename.split("_").pop()}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        window.open(getFileUrl(filename), "_blank")
                      }
                    >
                      {lang === "ar" ? "عرض" : "View"}
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleRemoveExistingFile(filename)}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* New uploads */}
          {newUploadKeys.length > 0 && (
            <div className="mt-4 space-y-2">
              <Label className="text-sm text-muted-foreground">
                {lang === "ar" ? "ملفات جديدة:" : "New files:"}
              </Label>
              {newUploadKeys.map((key) => (
                <div
                  key={key}
                  className="flex items-center justify-between rounded-lg border bg-muted/30 p-2"
                >
                  <div className="flex items-center gap-2">
                    {getFileIcon(uploadedFiles[key].file.name)}
                    <span className="text-sm">
                      {uploadedFiles[key].file.name}
                    </span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveFile(key)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          {/* Upload button */}
          {totalFiles < attachmentConfig.maxFiles && (
            <div className="mt-4">
              <Input
                type="file"
                accept={getAcceptTypes(attachmentConfig.allowedTypes)}
                onChange={(e) => {
                  const newKey = `attachment_${Date.now()}`
                  handleFileSelect(newKey, e, attachmentConfig.allowedTypes)
                }}
                className="hidden"
                id="attachment-upload"
              />
              <Button
                variant="outline"
                onClick={() =>
                  document.getElementById("attachment-upload")?.click()
                }
              >
                <Upload className="me-2 h-4 w-4" />
                {lang === "ar" ? "إضافة ملف" : "Add File"}
              </Button>
            </div>
          )}

          {hasError && (
            <div className="mt-2 flex items-center gap-1 text-sm text-destructive">
              <AlertCircle className="h-4 w-4" />
              {lang === "ar" ? "الملفات مطلوبة" : "Files are required"}
            </div>
          )}
        </div>
      </div>
    )
  }

  const getAcceptTypes = (allowedTypes: AttachmentFileType[]): string => {
    const typeMap: Record<AttachmentFileType, string> = {
      image: "image/*",
      document: ".pdf,.doc,.docx,.txt",
      video: "video/*",
      audio: "audio/*",
      any: "*/*",
    }
    return allowedTypes.map((t) => typeMap[t]).join(",")
  }

  const displayName =
    lang === "ar"
      ? assignment.name_ar || assignment.name_en
      : assignment.name_en

  if (isCompleted) {
    return (
      <div className="mx-auto max-w-2xl space-y-6">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="flex-1">
            <h1 className="text-2xl font-bold text-primary">{displayName}</h1>
            <p className="text-muted-foreground">{profile.name}</p>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>{assignment.name_en}</CardTitle>
            <CardDescription>
              {lang === "ar" ? "تمت الإجابة" : "Completed"}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {isSurveyTool &&
              (() => {
                const sortedOptions = [...(surveyConfig?.options || [])].sort(
                  (a, b) => a.order - b.order
                )
                const isMultiple =
                  surveyConfig?.answerType === "multiple_choice"
                return (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b text-start text-xs tracking-wider text-muted-foreground uppercase">
                          <th className="min-w-[150px] pe-4 pb-2 text-start font-medium">
                            {lang === "ar" ? "الأسئلة" : "Questions"}
                          </th>
                          {sortedOptions.map((opt) => (
                            <th
                              key={opt.id}
                              className="px-2 pb-2 text-center font-medium whitespace-nowrap"
                            >
                              {opt.label}
                            </th>
                          ))}
                        </tr>
                      </thead>
                      <tbody className="divide-y">
                        {surveyConfig?.questions.map((question) => {
                          const value = answers[question.id] as
                            | string
                            | string[]
                            | undefined
                          return (
                            <tr
                              key={question.id}
                              className="text-muted-foreground"
                            >
                              <td className="py-3 pe-4 align-top font-medium">
                                {question.text}
                              </td>
                              {sortedOptions.map((opt) => (
                                <td
                                  key={opt.id}
                                  className="px-2 py-3 text-center"
                                >
                                  {isMultiple ? (
                                    ((value as string[]) || []).includes(
                                      opt.value
                                    ) ? (
                                      <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                    ) : null
                                  ) : (value as string) === opt.value ? (
                                    <div className="mx-auto h-4 w-4 rounded-full bg-primary" />
                                  ) : null}
                                </td>
                              ))}
                            </tr>
                          )
                        })}
                      </tbody>
                    </table>
                  </div>
                )
              })()}

            {isMultipleChoiceTool &&
              mcConfig?.questions.map((question, idx) => (
                <div key={question.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {idx + 1}. {question.text}
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {question.answerType === "text" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "number" && (
                      <span className="font-medium">
                        {String(answers[question.id] || "-")}
                      </span>
                    )}
                    {question.answerType === "single_choice" && (
                      <span className="font-medium">
                        {question.options?.find(
                          (o) => o.value === answers[question.id]
                        )?.label || "-"}
                      </span>
                    )}
                    {question.answerType === "multiple_choice" && (
                      <div className="flex flex-wrap gap-2">
                        {((answers[question.id] as string[]) || []).map((v) => (
                          <span
                            key={v}
                            className="rounded-full bg-primary/10 px-3 py-1 text-sm"
                          >
                            {
                              question.options?.find((o) => o.value === v)
                                ?.label
                            }
                          </span>
                        ))}
                      </div>
                    )}
                    {question.answerType === "media" && (
                      <div>
                        {question.responseType === "text" ? (
                          <span className="font-medium">
                            {String(answers[question.id] || "-")}
                          </span>
                        ) : (
                          <div>
                            {assignment.responses?.[question.id] ? (
                              <div className="flex items-center gap-2">
                                {question.responseType === "video" ? (
                                  <Video className="h-5 w-5" />
                                ) : (
                                  <Music className="h-5 w-5" />
                                )}
                                <span className="font-medium">
                                  {(assignment.responses[question.id] as string)
                                    .split("_")
                                    .pop()}
                                </span>
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() =>
                                    window.open(
                                      getFileUrl(
                                        assignment.responses[
                                          question.id
                                        ] as string
                                      ),
                                      "_blank"
                                    )
                                  }
                                >
                                  {lang === "ar" ? "تشغيل" : "Play"}
                                </Button>
                              </div>
                            ) : (
                              <span className="text-muted-foreground">-</span>
                            )}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isMediaTool &&
              mediaConfig?.items.map((item) => (
                <div key={item.id} className="space-y-2">
                  <Label className="text-base font-medium text-muted-foreground">
                    {
                      (item.question as unknown as { en: string; ar: string })[
                        lang
                      ]
                    }
                  </Label>
                  <div className="rounded-lg bg-muted/30 p-3">
                    {item.responseType === "text" ? (
                      <span className="font-medium">
                        {String(
                          answers[item.id] || mediaResponses[item.id] || "-"
                        )}
                      </span>
                    ) : (
                      <div>
                        {assignment.responses?.[item.id] ? (
                          <div className="flex items-center gap-2">
                            {item.responseType === "video" ? (
                              <Video className="h-5 w-5" />
                            ) : (
                              <Music className="h-5 w-5" />
                            )}
                            <span className="font-medium">
                              {(assignment.responses[item.id] as string)
                                .split("_")
                                .pop()}
                            </span>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                window.open(
                                  getFileUrl(
                                    assignment.responses[item.id] as string
                                  ),
                                  "_blank"
                                )
                              }
                            >
                              {lang === "ar" ? "تشغيل" : "Play"}
                            </Button>
                          </div>
                        ) : (
                          <span className="text-muted-foreground">-</span>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {isAttachmentTool && (
              <div className="space-y-2">
                <Label className="text-base font-medium text-muted-foreground">
                  {(
                    attachmentConfig?.title as unknown as {
                      en: string
                      ar: string
                    }
                  )?.[lang] || (lang === "ar" ? "المرفقات" : "Attachments")}
                </Label>
                <div className="space-y-2">
                  {assignment.media && assignment.media.length > 0 ? (
                    assignment.media.map((file, idx) => (
                      <div
                        key={idx}
                        className="flex items-center justify-between rounded-lg bg-muted/30 p-3"
                      >
                        <div className="flex items-center gap-2">
                          {getFileIcon(file)}
                          <span className="font-medium">
                            {file.split("_").pop()}
                          </span>
                        </div>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() =>
                            window.open(getFileUrl(file), "_blank")
                          }
                        >
                          {lang === "ar" ? "عرض" : "View"}
                        </Button>
                      </div>
                    ))
                  ) : (
                    <p className="text-muted-foreground">
                      {lang === "ar" ? "لا توجد ملفات" : "No files"}
                    </p>
                  )}
                </div>
              </div>
            )}

            {isMeetingTool && meetingConfig && (
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "التاريخ" : "Date"}
                    </Label>
                    <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                  </div>
                  <div>
                    <Label className="text-sm text-muted-foreground">
                      {lang === "ar" ? "الوقت" : "Time"}
                    </Label>
                    <p className="font-medium">{meetingConfig.time || "—"}</p>
                  </div>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">
                    {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                  </Label>
                  <p className="font-medium">
                    {meetingConfig.meetingType === "online"
                      ? lang === "ar" ? "عن بُعد" : "Online"
                      : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
