          {isMediaTool &&
            mediaConfig?.items.map((item) => renderMediaItem(item))}

          {isAttachmentTool && renderAttachment()}

          {isMeetingTool && meetingConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{meetingConfig.date ? formatDate(meetingConfig.date) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الوقت" : "Time"}
                  </Label>
                  <p className="font-medium">{meetingConfig.time || "—"}</p>
                </div>
              </div>
              <div className="space-y-1">
                <Label className="text-muted-foreground">
                  {lang === "ar" ? "نوع الاجتماع" : "Meeting Type"}
                </Label>
                <p className="font-medium">
                  {meetingConfig.meetingType === "online"
                    ? lang === "ar" ? "عن بُعد" : "Online"
                    : lang === "ar" ? "وجهاً لوجه" : "Face to Face"}
                </p>
              </div>
              {meetingConfig.meetingType === "online" && meetingConfig.meetingLink && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الرابط" : "Meeting Link"}
                  </Label>
                  <a
                    href={meetingConfig.meetingLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block"
                  >
                    <Button variant="default" className="w-full">
                      {lang === "ar" ? "انضمام للاجتماع" : "Join Meeting"}
                    </Button>
                  </a>
                </div>
              )}
              {meetingConfig.meetingType === "face_to_face" && meetingConfig.location && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الموقع" : "Location"}
                  </Label>
                  <p className="font-medium">{meetingConfig.location}</p>
                </div>
              )}

              {isAdminOrExpert ? (
                <div className="space-y-3 rounded-lg border p-4">
                  <Label className="text-sm font-medium">
                    {lang === "ar" ? "ملاحظات المشرف" : "Admin Notes"}
                  </Label>
                  <textarea
                    value={localNotes}
                    onChange={(e) => setLocalNotes(e.target.value)}
                    placeholder={lang === "ar" ? "أضف ملاحظات..." : "Add notes..."}
                    className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                    rows={3}
                  />
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <input
                        type="checkbox"
                        id="notes-visible-task"
                        checked={localNotesVisible}
                        onChange={(e) => setLocalNotesVisible(e.target.checked)}
                        className="h-4 w-4 rounded border-gray-300"
                      />
                      <Label htmlFor="notes-visible-task" className="text-sm text-muted-foreground">
                        {lang === "ar" ? "إظهار للمستخدم" : "Show to user"}
                      </Label>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={saveNotes}
                      disabled={isSavingNotes}
                    >
                      {isSavingNotes
                        ? lang === "ar" ? "جاري الحفظ..." : "Saving..."
                        : lang === "ar" ? "حفظ" : "Save"}
                    </Button>
                  </div>
                </div>
              ) : meetingConfig.notes && meetingConfig.notesVisibleToUser ? (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "ملاحظات" : "Notes"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{meetingConfig.notes}</p>
                </div>
              ) : null}
            </div>
          )}

          {isReportTool && reportConfig && (
            <div className="space-y-4">
              {reportConfig.date && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التاريخ" : "Date"}
                  </Label>
                  <p className="font-medium">{formatDate(reportConfig.date)}</p>
                </div>
              )}
              {reportConfig.assessment && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "التقييم" : "Assessment"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.assessment}</p>
                </div>
              )}
              {reportConfig.suggestions && (
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الاقتراحات" : "Suggestions"}
                  </Label>
                  <p className="whitespace-pre-wrap font-medium">{reportConfig.suggestions}</p>
                </div>
              )}
            </div>
          )}

          {isPlanTool && planConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ البداية" : "Start Date"}
                  </Label>
                  <p className="font-medium">{planConfig.startDate ? formatDate(planConfig.startDate) : "—"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "تاريخ النهاية" : "End Date"}
                  </Label>
                  <p className="font-medium">{planConfig.endDate ? formatDate(planConfig.endDate) : "—"}</p>
                </div>
              </div>
              {planConfig.goals?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الأهداف" : "Goals"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.goals.map((goal) => (
                      <div key={goal.id} className="rounded-lg bg-muted/30 p-3">
                        <p className="font-medium">{goal.title}</p>
                        {goal.description && (
                          <p className="mt-1 text-sm text-muted-foreground">{goal.description}</p>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
              {planConfig.steps?.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-muted-foreground">
                    {lang === "ar" ? "الخطوات" : "Steps"}
                  </Label>
                  <div className="space-y-2">
                    {planConfig.steps.map((step) => (
                      <div key={step.id} className="rounded-lg border p-3">
                        <div className="flex items-start gap-2">
                          <div className={`mt-1 h-3 w-3 shrink-0 rounded-full ${step.completed ? "bg-green-500" : "bg-muted-foreground/30"}`} />
                          <div className="flex-1">
                            <p className="font-medium">{step.title}</p>
                            {step.description && (
                              <p className="mt-1 text-sm text-muted-foreground">{step.description}</p>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {(isMeetingTool || isReportTool || isPlanTool) ? (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الحفظ..."
                  : "Saving..."
                : lang === "ar"
                  ? "تأكيد الإتمام"
                  : "Mark as Completed"}
            </Button>
          ) : (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full"
            >
              {isSubmitting
                ? lang === "ar"
                  ? "جاري الإرسال..."
                  : "Submitting..."
                : lang === "ar"
                  ? "إرسال"
                  : "Submit"}
            </Button>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { use, useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { getToolTypeLabel } from "@/lib/tool-types"
import { formatDate } from "@/lib/format-date"
import { caseExpertsCollection } from "@/lib/pb-collections"
import { getAllowedToolTypesForRole } from "@/lib/pb-collections"
import { PaymentGate } from "@/components/cases/PaymentGate"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  ArrowLeft,
  Calendar,
  Mail,
  Phone,
  User,
  ClipboardList,
  History,
  Eye,
  Pencil,
  Send,
} from "lucide-react"
import Link from "next/link"
import { toast } from "sonner"
import { getErrorMessage } from "@/lib/pb"

const assignmentStatusLabels: Record<
  string,
  { en: string; ar: string }
> = {
  pending: { en: "Pending", ar: "قيد الانتظار" },
  assigned: { en: "Assigned", ar: "تم التعيين" },
  in_progress: { en: "In Progress", ar: "قيد التنفيذ" },
  completed: { en: "Completed", ar: "مكتمل" },
}

export default function ProfileDetailPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = use(params)
  const router = useRouter()
  const { lang } = useLang()
  const { getProfileById } = useProfiles()
  const { getAssignmentsByCase, getVisibleAssignments } = useAssignments(id)
  const { toolTypes, fetchToolTypes } = useToolTypes()
  const { currentUser } = useAuth()

  const [expertRole, setExpertRole] = useState<string | null>(null)
  const [allowedToolTypeIds, setAllowedToolTypeIds] = useState<string[]>([])

  const profile = getProfileById(id)
  const assignments = getAssignmentsByCase(id)
  const visibleAssignments = getVisibleAssignments(id)

  // Filter visible assignments by role-based tool type permissions
  const roleFilteredAssignments =
    expertRole && allowedToolTypeIds.length > 0
      ? visibleAssignments.filter((a) => allowedToolTypeIds.includes(a.type))
      : visibleAssignments

  useEffect(() => {
    fetchToolTypes()
  }, [fetchToolTypes])

  useEffect(() => {
    async function fetchExpertRole() {
      if (!currentUser || !id) return
      try {
        const caseExpert = await caseExpertsCollection.getByCaseAndExpert(
          id,
          currentUser.id
        )
        if (caseExpert?.role) {
          setExpertRole(caseExpert.role)
          const allowed = await getAllowedToolTypesForRole(caseExpert.role)
          setAllowedToolTypeIds(allowed)
        }
      } catch (error) {
        console.error("Failed to fetch expert role:", error)
        toast.error(getErrorMessage(error))
      }
    }
    fetchExpertRole()
  }, [currentUser, id])

  if (!profile) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الحالة غير موجودة" : "Case not found"}
        </h2>
        <Link href="/dashboard/parent/cases">
          <Button>{lang === "ar" ? "العودة إلى الحالات" : "Back to Cases"}</Button>
        </Link>
      </div>
    )
  }

  return (
    <PaymentGate profile={profile}>
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-primary">{profile.name}</h1>
          <p className="text-muted-foreground">
            {lang === "ar" ? `أنشئت في ${formatDate(profile.created)}` : `Created ${formatDate(profile.created)}`}
          </p>
        </div>
      </div>

      <Tabs defaultValue="overview" className="space-y-4">
        <TabsList>
          <TabsTrigger value="overview">
            {lang === "ar" ? "نظرة عامة" : "Overview"}
          </TabsTrigger>
          <TabsTrigger value="tasks">
