        </TabsContent>

        <TabsContent value="tasks">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <ClipboardList className="h-5 w-5" />
                {lang === "ar" ? "المهام المكلف بها" : "Assigned Tasks"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "المهام المكلف بها لهذه الحالة"
                  : "Tasks assigned to this profile"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {roleFilteredAssignments.length === 0 ? (
                <div className="py-8 text-center">
                  <ClipboardList className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar" ? "لا توجد مهام مكلف بها" : "No tasks assigned"}
                  </h3>
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? "ستظهر المهام هنا بمجرد تكليفها من قبل المشرف"
                      : "Tasks will appear here once assigned by an admin"}
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {roleFilteredAssignments.map((assignment) => {
                    const toolType = toolTypes.find(
                      (t) => t.id === assignment.type
                    )
                    const toolTypeName = getToolTypeLabel(toolType, lang)
                    return (
                      <div
                        key={assignment.id}
                        className="flex items-center justify-between rounded-lg border p-4 transition-colors hover:bg-muted/50"
                      >
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <p className="font-medium">
                              {lang === "ar"
                                ? assignment.name_ar || assignment.name_en
                                : assignment.name_en}
                            </p>
                            <Badge
                              variant="outline"
                              className="text-xs capitalize"
                            >
                              {toolTypeName}
                            </Badge>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          {!assignment.is_not_template ? (
                            <Link
                              href={`/dashboard/parent/cases/${id}/tasks/${assignment.id}`}
                            >
                              <Button
                                variant="outline"
                                size="sm"
                                title={lang === "ar" ? "الإجابة" : "Respond"}
                              >
                                <Pencil className="h-4 w-4" />
                              </Button>
                            </Link>
                          ) : (
                            <Link
                              href={`/dashboard/parent/cases/${id}/tasks/${assignment.id}`}
                            >
                              <Button
                                variant="outline"
                                size="sm"
                                title={lang === "ar" ? "عرض" : "View"}
                              >
                                <Eye className="h-4 w-4" />
                              </Button>
                            </Link>
                          )}
                          {assignment.status === "completed" && !assignment.is_not_template && (
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => {
                                const responses = assignment.responses
                                if (
                                  responses &&
                                  Object.keys(responses).length > 0
                                ) {
                                  const printWindow = window.open(
                                    "",
                                    "_blank",
                                    "width=800,height=600"
                                  )
                                  if (printWindow) {
                                    printWindow.document.write(`
                                    <html>
                                      <head>
                                        <title>${assignment.name_en || (lang === "ar" ? "الردود" : "Responses")}</title>
                                        <style>
                                          body { font-family: system-ui, sans-serif; padding: 20px; }
                                          h1 { margin-bottom: 10px; }
                                          .meta { color: #666; margin-bottom: 20px; }
                                          .response { margin-bottom: 15px; padding: 10px; background: #f5f5f5; border-radius: 4px; }
                                          .question { font-weight: bold; margin-bottom: 5px; }
                                          @media print { .no-print { display: none; } }
                                        </style>
                                      </head>
                                      <body>
                                        <h1>${assignment.name_en || (lang === "ar" ? "الردود" : "Responses")}</h1>
                                        <p class="meta">${lang === "ar" ? "الحالة" : "Profile"}: ${profile.name} | ${lang === "ar" ? "التاريخ" : "Date"}: ${formatDate(assignment.updated)}</p>
                                        <pre style="white-space: pre-wrap; background: #f5f5f5; padding: 15px; border-radius: 4px;">${JSON.stringify(responses, null, 2)}</pre>
                                        <button class="no-print" onclick="window.print()" style="margin-top: 20px; padding: 10px 20px; cursor: pointer;">${lang === "ar" ? "طباعة / حفظ كـ PDF" : "Print / Save as PDF"}</button>
                                      </body>
                                    </html>
                                  `)
                                    printWindow.document.close()
                                  }
                                }
                              }}
                            >
                              <Eye className="h-4 w-4" />
                            </Button>
                          )}
                          <Badge
                            variant={
                              assignment.status === "completed"
                                ? "default"
                                : "secondary"
                            }
                          >
                            {assignmentStatusLabels[assignment.status]?.[lang] || assignment.status}
                          </Badge>
                        </div>
                      </div>
                    )
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="case-file">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <History className="h-5 w-5" />
                {lang === "ar" ? "السجل" : "History"}
              </CardTitle>
              <CardDescription>
                {lang === "ar"
                  ? "ستكون المهام المكتملة هنا"
                  : "Completed Tasks will be here"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {assignments.filter((a) => a.status === "completed").length ===
              0 ? (
                <div className="py-8 text-center">
                  <History className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
                  <h3 className="mb-2 text-lg font-medium">
                    {lang === "ar" ? "لا يوجد سجل بعد" : "No history yet"}
                  </h3>
                  <p className="text-muted-foreground">
                    {lang === "ar"
                      ? "ستظهر المهام المكتملة هنا"
                      : "Completed tasks will appear here"}
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {assignments
                    .filter((a) => a.status === "completed")
                    .map((assignment) => (
                      <div
                        key={assignment.id}
                        className="flex items-center justify-between rounded-lg border p-4"
                      >
                        <div>
                          <p className="font-medium">
                            {lang === "ar"
                              ? assignment.name_ar || assignment.name_en
                              : assignment.name_en}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            {lang === "ar" ? "أكملت في" : "Completed"}{" "}
                            {assignment.updated &&
                              formatDate(assignment.updated)}
                          </p>
                        </div>
                        <Badge variant="default">
                          {lang === "ar" ? "مكتمل" : "Completed"}
                        </Badge>
                      </div>
                    ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
    </PaymentGate>
  )
}

"use client"

import { use, useState, useEffect, useMemo, useRef } from "react"
import { useRouter } from "next/navigation"
import { useProfiles } from "@/hooks/useProfiles"
import { useAssignments } from "@/hooks/useAssignments"
import { useToolTypes } from "@/hooks/useToolTypes"
import { useAuth } from "@/hooks/useAuth"
import { useLang } from "@/lib/lang-context"
import { formatDate } from "@/lib/format-date"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { Input } from "@/components/ui/input"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Checkbox } from "@/components/ui/checkbox"
import {
  ArrowLeft,
  CheckCircle,
  AlertCircle,
  Upload,
  X,
  FileText,
  Image,
  Video,
  Music,
  Play,
  Trash2,
  File,
} from "lucide-react"
import Link from "next/link"
import type {
  SurveyConfig,
  SurveyQuestion,
  MultipleChoiceConfig,
  MCQuestion,
  MediaConfig,
  MediaItem,
  AttachmentRequestConfig,
  AttachmentFileType,
  OneToOneMeetingConfig,
  ReportConfig,
  PlanConfig,
} from "@/types/tool"
import { cn } from "@/lib/utils"
import { toast } from "sonner"
import pb, { getErrorMessage } from "@/lib/pb"
import { PaymentGate } from "@/components/cases/PaymentGate"

const RATING_LABELS: Record<number, { en: string; ar: string }> = {
  1: { en: "Very Low", ar: "منخفض جداً" },
  2: { en: "Low", ar: "منخفض" },
  3: { en: "Medium", ar: "متوسط" },
  4: { en: "High", ar: "عالٍ" },
  5: { en: "Very High", ar: "عالٍ جداً" },
}

export default function TakeSurveyToolPage({
  params,
}: {
  params: Promise<{ id: string; toolId: string }>
}) {
  const params2 = use(params)
  const caseId = params2.id
  const assignmentId = params2.toolId
  const router = useRouter()
  const { lang } = useLang()
  const { getProfileById } = useProfiles()
  const {
    assignments,
    updateAssignment,
    updateAssignmentWithFiles,
    isLoading: isAssignmentsLoading,
  } = useAssignments(caseId)
  const { getToolTypeById, fetchToolTypes } = useToolTypes()
  const { currentUser } = useAuth()

  const assignment = assignments.find((a) => a.id === assignmentId) // Find by toolId
  const profile = getProfileById(caseId) // Get profile by case ID
  const toolType = assignment ? getToolTypeById(assignment.type) : undefined
  const toolTypeName = toolType?.key || "unknown"

  const isAdminOrExpert = currentUser?.role === "admin" || currentUser?.role === "super_admin" || currentUser?.role === "expert"

  const isSurveyTool = toolTypeName === "survey"
  const isMultipleChoiceTool = toolTypeName === "multiple_answer"
  const isMediaTool = toolTypeName === "media_question"
  const isAttachmentTool = toolTypeName === "attachment_request"
  const isMeetingTool = toolTypeName === "one_to_one_meeting"
  const isReportTool = toolTypeName === "report"
  const isPlanTool = toolTypeName === "plan"

  const surveyConfig = isSurveyTool
    ? (assignment?.config as SurveyConfig | undefined)
    : undefined
  const mcConfig = isMultipleChoiceTool
    ? (assignment?.config as MultipleChoiceConfig | undefined)
    : undefined
  const mediaConfig = isMediaTool
    ? (assignment?.config as MediaConfig | undefined)
    : undefined
  const attachmentConfig = isAttachmentTool
    ? (assignment?.config as AttachmentRequestConfig | undefined)
    : undefined
  const meetingConfig = isMeetingTool
    ? (assignment?.config as OneToOneMeetingConfig | undefined)
    : undefined
  const reportConfig = isReportTool
    ? (assignment?.config as ReportConfig | undefined)
    : undefined
  const planConfig = isPlanTool
    ? (assignment?.config as PlanConfig | undefined)
    : undefined

  const config = surveyConfig || mcConfig || mediaConfig || attachmentConfig || meetingConfig || reportConfig || planConfig

  const existingResponses = assignment?.responses as
    | Record<string, unknown>
    | undefined
  const [answers, setAnswers] = useState<Record<string, unknown>>({})
  const [mediaResponses, setMediaResponses] = useState<Record<string, string>>(
    {}
  )
  const [errors, setErrors] = useState<string[]>([])
  const [isSubmitting, setIsSubmitting] = useState(false)
  const isCompleted = assignment?.status === "completed"

  const [localNotes, setLocalNotes] = useState("")
  const [localNotesVisible, setLocalNotesVisible] = useState(false)
  const [isSavingNotes, setIsSavingNotes] = useState(false)

  useEffect(() => {
    if (meetingConfig) {
      setLocalNotes(meetingConfig.notes || "")
      setLocalNotesVisible(meetingConfig.notesVisibleToUser || false)
    }
  }, [meetingConfig])

  // File upload state for media and attachment tools
  const [uploadedFiles, setUploadedFiles] = useState<
    Record<string, { file: File; preview?: string }>
  >({})
  const [existingFiles, setExistingFiles] = useState<Record<string, string[]>>(
    {}
  )
  const [filesToRemove, setFilesToRemove] = useState<string[]>([])

  const hasFetchedToolTypes = useRef(false)
  const hasInitializedAnswers = useRef(false)
  const hasInitializedFiles = useRef(false)

  useEffect(() => {
    if (hasFetchedToolTypes.current) return
    hasFetchedToolTypes.current = true
    fetchToolTypes()
  }, [fetchToolTypes])

  // Initialize answers from existing responses - only once
  useEffect(() => {
    if (hasInitializedAnswers.current) return
    if (existingResponses && Object.keys(existingResponses).length > 0) {
      setAnswers(existingResponses)
      hasInitializedAnswers.current = true
    }
  }, [existingResponses])

  // Initialize existing files from assignment media - only once
  useEffect(() => {
    if (hasInitializedFiles.current) return
    if (assignment?.media && assignment.media.length > 0) {
      // Group files by response key from responses data
      const filesByKey: Record<string, string[]> = {}

      if (assignment.responses) {
        Object.entries(assignment.responses).forEach(([key, value]) => {
          if (typeof value === "string" && assignment.media?.includes(value)) {
            if (!filesByKey[key]) filesByKey[key] = []
            filesByKey[key].push(value)
          }
        })
      }

      // Also add files not yet mapped to any key (for attachment tool)
      const unmappedFiles = assignment.media.filter(
        (file) =>
          !Object.values(filesByKey).some((files) => files.includes(file))
      )
      if (unmappedFiles.length > 0) {
        filesByKey["_unmapped"] = unmappedFiles
      }

      setExistingFiles(filesByKey)
      hasInitializedFiles.current = true
    }
  }, [assignment?.media, assignment?.responses])

  if (isAssignmentsLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">
          {lang === "ar" ? "جاري التحميل..." : "Loading..."}
        </p>
      </div>
    )
  }

  if (!assignment || !profile || !config) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <h2 className="mb-4 text-xl font-medium">
          {lang === "ar" ? "الأداة غير موجودة" : "Tool not found"}
        </h2>
        <Link href="/dashboard/parent/cases">
          <Button>
            {lang === "ar" ? "العودة إلى الحالات" : "Back to Cases"}
          </Button>
        </Link>
      </div>
    )
  }

  if (profile.status && profile.status !== "active" && !isAdminOrExpert) {
    return <PaymentGate profile={profile} />
  }

  const handleAnswer = (questionId: string, value: unknown) => {
    setAnswers((prev) => ({ ...prev, [questionId]: value }))
    setErrors((prev) => prev.filter((e) => e !== questionId))
  }

  const validateRequired = (): boolean => {
    const missing: string[] = []

    if (isSurveyTool && surveyConfig) {
      surveyConfig.questions.forEach((q) => {
        if (q.required) {
          const answer = answers[q.id]
          if (
            answer === undefined ||
            answer === null ||
            (typeof answer === "string" && answer.trim() === "") ||
            (Array.isArray(answer) && answer.length === 0)
          ) {
            missing.push(q.id)
          }
        }
      })
    }

    if (isMultipleChoiceTool && mcConfig) {
      mcConfig.questions.forEach((q) => {
        if (q.required) {
          if (q.answerType === "media") {
            if (q.responseType === "text") {
              const answer = answers[q.id]
              if (
                !answer ||
                (typeof answer === "string" && answer.trim() === "")
              ) {
                missing.push(q.id)
              }
            } else if (
              q.responseType === "video" ||
              q.responseType === "audio"
            ) {
              const hasNewFile = uploadedFiles[q.id]
              const hasExistingFile =
                existingFiles[q.id] && existingFiles[q.id].length > 0
              if (!hasNewFile && !hasExistingFile) {
                missing.push(q.id)
              }
            }
          } else {
            const answer = answers[q.id]
            if (
              answer === undefined ||
              answer === null ||
              (typeof answer === "string" && answer.trim() === "") ||
              (typeof answer === "number" && isNaN(answer)) ||
              (Array.isArray(answer) && answer.length === 0)
            ) {
              missing.push(q.id)
            }
          }
        }
      })
    }

    if (isMediaTool && mediaConfig) {
      mediaConfig.items.forEach((item) => {
        if (item.responseType === "text") {
          const answer = mediaResponses[item.id]
          if (!answer || answer.trim() === "") {
            missing.push(item.id)
          }
        } else if (
          item.responseType === "video" ||
          item.responseType === "audio"
        ) {
          // Check if a file is uploaded for this media item
          const hasNewFile = uploadedFiles[item.id]
          const hasExistingFile =
            existingFiles[item.id] && existingFiles[item.id].length > 0
          if (!hasNewFile && !hasExistingFile) {
            missing.push(item.id)
          }
        }
      })
    }

    if (isAttachmentTool && attachmentConfig) {
      const totalFiles = Object.keys(uploadedFiles).length
      const totalExisting = existingFiles["_unmapped"]
        ? existingFiles["_unmapped"].filter((f) => !filesToRemove.includes(f))
            .length
        : 0

      if (attachmentConfig.required && totalFiles + totalExisting === 0) {
        missing.push("attachment")
      }
    }

    setErrors(missing)
    return missing.length === 0
  }

  const saveNotes = async () => {
    if (!assignment || !meetingConfig) return
    setIsSavingNotes(true)
    try {
      const updatedConfig = {
        ...meetingConfig,
        notes: localNotes || undefined,
        notesVisibleToUser: localNotesVisible,
      }
      await updateAssignment(assignmentId, {
        config: updatedConfig as OneToOneMeetingConfig,
      })
    } catch (error) {
      console.error("Failed to save notes:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSavingNotes(false)
    }
  }

  const handleSubmit = async () => {
    if (!validateRequired()) return

    setIsSubmitting(true)
    try {
      // Build responses with file references for media/attachment tools
      const finalResponses: Record<string, unknown> = { ...answers }

      if (isMediaTool && mediaConfig) {
        mediaConfig.items.forEach((item) => {
          if (item.responseType === "text") {
            finalResponses[item.id] = mediaResponses[item.id] || ""
          } else if (uploadedFiles[item.id]) {
            // File will be uploaded, reference will be added after upload
            finalResponses[item.id] = uploadedFiles[item.id].file.name
          }
        })
      }

      if (isMultipleChoiceTool && mcConfig) {
        mcConfig.questions.forEach((q) => {
          if (
            q.answerType === "media" &&
            (q.responseType === "video" || q.responseType === "audio")
          ) {
            if (uploadedFiles[q.id]) {
              finalResponses[q.id] = uploadedFiles[q.id].file.name
            }
          }
        })
      }

      if (isAttachmentTool) {
        // Add references for uploaded files
        Object.entries(uploadedFiles).forEach(([key, data]) => {
          finalResponses[key] = data.file.name
        })
      }

      // Upload files if any
      const filesToUpload = Object.values(uploadedFiles).map(
        (data) => data.file
      )

      if (filesToUpload.length > 0 || filesToRemove.length > 0) {
        await updateAssignmentWithFiles(
          assignmentId,
          {
            status: "completed",
            responses: finalResponses,
          },
          filesToUpload,
          filesToRemove.length > 0 ? filesToRemove : undefined
        )
      } else {
        await updateAssignment(assignmentId, {
          status: "completed",
          responses: finalResponses,
        })
      }

      router.push(`/dashboard/parent/cases/${profile.id}`)
    } catch (error) {
      console.error("Failed to submit:", error)
      toast.error(getErrorMessage(error))
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleStart = async () => {
    if (assignment.status === "pending") {
      await updateAssignment(assignmentId, {
        status: "in_progress",
      })
    }
  }

  // File handling helpers
  const handleFileSelect = (
    key: string,
    e: React.ChangeEvent<HTMLInputElement>,
    allowedTypes?: AttachmentFileType[]
  ) => {
    const file = e.target.files?.[0]
    if (!file) return

    // Validate file type
    if (allowedTypes && allowedTypes.length > 0) {
      const isValidType = validateFileType(file, allowedTypes)
      if (!isValidType) {
        alert(
          lang === "ar" ? "نوع الملف غير مسموح به" : "File type not allowed"
        )
        return
      }
    }

    // Validate file size (default 20MB)
    const maxSize = attachmentConfig?.maxFileSize || 20
    if (file.size > maxSize * 1024 * 1024) {
      alert(
        lang === "ar"
          ? `حجم الملف كبير جداً. الحد الأقصى ${maxSize} ميجابايت`
          : `File too large. Max size is ${maxSize}MB`
      )
      return
    }

    // Create preview for media files
    let preview: string | undefined
    if (file.type.startsWith("image/") || file.type.startsWith("video/")) {
      preview = URL.createObjectURL(file)
    }

    setUploadedFiles((prev) => ({
      ...prev,
      [key]: { file, preview },
    }))
    setErrors((prev) => prev.filter((e) => e !== key))
  }

  const validateFileType = (
    file: File,
    allowedTypes: AttachmentFileType[]
  ): boolean => {
    if (allowedTypes.includes("any")) return true

    const typeMap: Record<AttachmentFileType, string[]> = {
      image: ["image/"],
      document: [
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument",
        "text/",
      ],
      video: ["video/"],
      audio: ["audio/"],
      any: [],
    }

    return allowedTypes.some((type) =>
      typeMap[type]?.some((prefix) => file.type.startsWith(prefix))
    )
  }

  const handleRemoveFile = (key: string) => {
    setUploadedFiles((prev) => {
      const newFiles = { ...prev }
      if (newFiles[key]?.preview) {
        URL.revokeObjectURL(newFiles[key].preview!)
      }
      delete newFiles[key]
      return newFiles
    })
  }

  const handleRemoveExistingFile = (filename: string) => {
    setFilesToRemove((prev) => [...prev, filename])
  }

  const getFileIcon = (filename: string) => {
    const ext = filename.split(".").pop()?.toLowerCase()
    if (["jpg", "jpeg", "png", "gif", "webp"].includes(ext || ""))
      return <Image className="h-5 w-5" />
    if (["mp4", "webm", "mov", "avi"].includes(ext || ""))
      return <Video className="h-5 w-5" />
    if (["mp3", "wav", "ogg", "m4a"].includes(ext || ""))
      return <Music className="h-5 w-5" />
    return <FileText className="h-5 w-5" />
  }

  const getFileUrl = (filename: string) => {
    return pb.files.getUrl(
      { collectionId: "case_tools", id: assignmentId },
      filename
    )
  }

  const renderQuestion = (question: SurveyQuestion) => {
    const value = answers[question.id] as string | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMultiple = surveyConfig?.answerType === "multiple_choice"
    const sortedOptions = [...(surveyConfig?.options || [])].sort(
      (a, b) => a.order - b.order
    )

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>
        {isMultiple ? (
          <div className="space-y-2">
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <Checkbox
                  id={`${question.id}-${opt.id}`}
                  checked={((value as string[]) || []).includes(opt.value)}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      handleAnswer(question.id, [
                        ...((value as string[]) || []),
                        opt.value,
                      ])
                    } else {
                      handleAnswer(
                        question.id,
                        ((value as string[]) || []).filter(
                          (v) => v !== opt.value
                        )
                      )
                    }
                  }}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{opt.label}</Label>
              </div>
            ))}
          </div>
        ) : (
          <RadioGroup
            value={(value as string) || ""}
            onValueChange={(v) => handleAnswer(question.id, v)}
          >
            {sortedOptions.map((opt) => (
              <div key={opt.id} className="flex items-center gap-2">
                <RadioGroupItem
                  value={opt.value}
                  id={`${question.id}-${opt.id}`}
                />
                <Label htmlFor={`${question.id}-${opt.id}`}>{opt.label}</Label>
              </div>
            ))}
          </RadioGroup>
        )}
        {hasError && (
          <div className="flex items-center gap-1 text-sm text-destructive">
            <AlertCircle className="h-4 w-4" />
            {lang === "ar" ? "إجابة مطلوبة" : "This field is required"}
          </div>
        )}
      </div>
    )
  }

  const renderMCQuestion = (question: MCQuestion) => {
    const value = answers[question.id] as string | number | string[] | undefined
    const hasError = errors.includes(question.id)
    const isMedia = question.answerType === "media"

    return (
      <div className="space-y-3">
        <Label className="text-base font-medium">
          {question.text}
          {question.required && (
            <span className="ms-1 text-destructive">*</span>
          )}
        </Label>

        {/* Media prompt */}
        {isMedia && question.mediaUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
