const MAX_SIZE_MB = 20
const MAX_SIZE_BYTES = MAX_SIZE_MB * 1024 * 1024

const MEDIA_TYPES: {
  value: MediaType
  label: { en: string; ar: string }
  icon: typeof Image
}[] = [
  { value: "image", label: { en: "Image", ar: "صورة" }, icon: Image },
  { value: "video", label: { en: "Video", ar: "فيديو" }, icon: Video },
  { value: "audio", label: { en: "Audio", ar: "صوت" }, icon: Music },
]

const RESPONSE_TYPES: { value: ResponseType; label: { en: string; ar: string } }[] = [
  { value: "text", label: { en: "Text Response", ar: "استجابة نصية" } },
  { value: "video", label: { en: "Video Response", ar: "استجابة فيديو" } },
  { value: "audio", label: { en: "Audio Response", ar: "استجابة صوتية" } },
]

interface MediaUploadProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onUpload: (data: {
    file: File
    mediaType: MediaType
    responseType: ResponseType
  }) => void
}

export function MediaUpload({
  open,
  onOpenChange,
  onUpload,
}: MediaUploadProps) {
  const { lang } = useLang()
  const [mediaType, setMediaType] = useState<MediaType>("image")
  const [responseType, setResponseType] = useState<ResponseType>("text")
  const [selectedFile, setSelectedFile] = useState<File | null>(null)
  const [previewUrl, setPreviewUrl] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setError(null)

    if (file.size > MAX_SIZE_BYTES) {
      setError(
        t(
          {
            en: `File too large. Max size is ${MAX_SIZE_MB}MB`,
            ar: `الملف كبير جداً. الحد الأقصى للحجم ${MAX_SIZE_MB} ميجابايت`,
          },
          lang
        )
      )
      return
    }

    setSelectedFile(file)
    setPreviewUrl(URL.createObjectURL(file))
  }

  const handleSave = () => {
    if (!selectedFile) return
    onUpload({ file: selectedFile, mediaType, responseType })
    handleClose()
  }

  const handleClose = () => {
    if (previewUrl) {
      URL.revokeObjectURL(previewUrl)
    }
    setSelectedFile(null)
    setPreviewUrl(null)
    setError(null)
    setMediaType("image")
    setResponseType("text")
    onOpenChange(false)
  }

  const renderPreview = () => {
    if (!previewUrl) return null

    if (mediaType === "image") {
      return (
        <div className="relative aspect-video w-full overflow-hidden rounded-lg border">
          <img
            src={previewUrl}
            alt={t({ en: "Preview", ar: "معاينة" }, lang)}
            className="h-full w-full object-contain"
          />
        </div>
      )
    }

    if (mediaType === "video") {
      return (
        <div className="relative aspect-video w-full overflow-hidden rounded-lg border bg-black">
          <video src={previewUrl} className="h-full w-full object-contain" />
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="flex h-16 w-16 items-center justify-center rounded-full bg-white/20 backdrop-blur-sm">
              <Play className="h-8 w-8 text-white" />
            </div>
          </div>
        </div>
      )
    }

    if (mediaType === "audio") {
      return (
        <div className="flex items-center justify-center rounded-lg border bg-muted/30 p-8">
          <div className="flex flex-col items-center gap-2">
            <Music className="h-12 w-12 text-muted-foreground" />
            <audio src={previewUrl} controls className="w-full" />
          </div>
        </div>
      )
    }

    return null
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>
            {t({ en: "Upload Media", ar: "رفع وسائط" }, lang)}
          </DialogTitle>
          <DialogDescription>
            {t(
              {
                en: `Add image, video, or audio (max ${MAX_SIZE_MB}MB)`,
                ar: `أضف صورة أو فيديو أو صوت (بحد أقصى ${MAX_SIZE_MB} ميجابايت)`,
              },
              lang
            )}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label>{t({ en: "Media Type", ar: "نوع الوسائط" }, lang)}</Label>
              <Select
                value={mediaType}
                onValueChange={(v) => setMediaType(v as MediaType)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {MEDIA_TYPES.map((type) => (
                    <SelectItem key={type.value} value={type.value}>
                      <div className="flex items-center gap-2">
                        <type.icon className="h-4 w-4" />
                        {t(type.label, lang)}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>
                {t({ en: "Response Type", ar: "نوع الاستجابة" }, lang)}
              </Label>
              <Select
                value={responseType}
                onValueChange={(v) => setResponseType(v as ResponseType)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {RESPONSE_TYPES.map((type) => (
                    <SelectItem key={type.value} value={type.value}>
                      {t(type.label, lang)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {!selectedFile && (
            <div className="space-y-2">
              <Input
                ref={fileInputRef}
                type="file"
                accept={
                  mediaType === "image"
                    ? "image/*"
                    : mediaType === "video"
                      ? "video/*"
                      : "audio/*"
                }
                onChange={handleFileSelect}
                className="cursor-pointer"
              />
              {error && <p className="text-sm text-destructive">{error}</p>}
            </div>
          )}

          {selectedFile && (
            <div className="space-y-3">
              {renderPreview()}
              <Button
                variant="outline"
                size="sm"
                onClick={() => {
                  if (previewUrl) {
                    URL.revokeObjectURL(previewUrl)
                  }
                  setSelectedFile(null)
                  setPreviewUrl(null)
                  if (fileInputRef.current) fileInputRef.current.value = ""
                }}
              >
                <X className="me-2 h-4 w-4" />
                {t(
                  {
                    en: "Remove & Upload Different",
                    ar: "إزالة ورفع ملف مختلف",
                  },
                  lang
                )}
              </Button>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose}>
            {t(UI_STRINGS.cancel, lang)}
          </Button>
          <Button onClick={handleSave} disabled={!selectedFile}>
            {t({ en: "Add Media", ar: "إضافة وسائط" }, lang)}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { useState, useEffect, useCallback } from "react"
import { caseExpertsCollection } from "@/lib/pb-collections"
import type { CaseExpert } from "@/types/allocation"
import { toast } from "sonner"
import { getErrorMessage } from "@/lib/pb"

export function useAllocations(caseId?: string) {
  const [allocations, setAllocations] = useState<CaseExpert[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState("")

  const fetchAllocations = useCallback(async () => {
    setIsLoading(true)
    setLoadError("")
    try {
      let data: CaseExpert[]
      if (caseId) {
        data = await caseExpertsCollection.getByCase(caseId)
      } else {
        data = await caseExpertsCollection.getAll()
      }
      setAllocations(data)
    } catch (error) {
      console.error("Failed to fetch allocations:", error)
      setLoadError(getErrorMessage(error))
      toast.error(getErrorMessage(error))
    } finally {
      setIsLoading(false)
    }
  }, [caseId])

  useEffect(() => {
    // Fetch external records when the selected scope changes.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchAllocations()
  }, [fetchAllocations])

  const addAllocation = async (data: {
    case_id: string
    expert_id: string
    role: CaseExpert["role"]
  }) => {
    try {
      const newAllocation = await caseExpertsCollection.create(data)
      setAllocations((prev) => [...prev, newAllocation])
      return newAllocation
    } catch (error) {
      console.error("Failed to create allocation:", error)
      throw error
    }
  }

  const updateAllocation = async (
    id: string,
    data: Partial<CaseExpert>
  ) => {
    try {
      const updated = await caseExpertsCollection.update(id, data)
      setAllocations((prev) =>
        prev.map((a) => (a.id === id ? updated : a))
      )
      return updated
    } catch (error) {
      console.error("Failed to update allocation:", error)
      throw error
    }
  }

  const removeAllocation = async (id: string) => {
    try {
      await caseExpertsCollection.delete(id)
      setAllocations((prev) => prev.filter((a) => a.id !== id))
    } catch (error) {
      console.error("Failed to delete allocation:", error)
      throw error
    }
  }

  const getAllocationsByCase = (caseId: string) =>
    allocations.filter((a) => a.case_id === caseId)

  return {
    allocations,
    isLoading,
    loadError,
    addAllocation,
    updateAllocation,
    removeAllocation,
    getAllocationsByCase,
    refresh: fetchAllocations,
  }
}

"use client"

import { useState, useEffect, useCallback } from "react"
import { caseToolsCollection } from "@/lib/pb-collections"
import type { CaseTool } from "@/types/assignment"
import type { ToolConfig } from "@/types/tool"
import { toast } from "sonner"
import { getErrorMessage } from "@/lib/pb"

export function useAssignments(caseId?: string) {
  const [assignments, setAssignments] = useState<CaseTool[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState("")

  const fetchAssignments = useCallback(async () => {
    setIsLoading(true)
    setLoadError("")
    try {
      let data: CaseTool[]
      if (caseId) {
        data = await caseToolsCollection.getByCase(caseId)
      } else {
        data = await caseToolsCollection.getAll()
      }
      setAssignments(data)
    } catch (error) {
      console.error("Failed to fetch assignments:", error)
      setLoadError(getErrorMessage(error))
      toast.error(getErrorMessage(error))
    } finally {
      setIsLoading(false)
    }
  }, [caseId])

  useEffect(() => {
    // Fetch external records when the selected scope changes.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchAssignments()
  }, [fetchAssignments])

  // Create assignment/document in case_tools
  // Works for both template-based (survey, etc.) and case-specific (plan, report, attachment)
  const assignTool = async (data: {
    case: string
    type: string // tool_type ID
    name_en?: string
    name_ar?: string
    is_not_template?: boolean
    config: ToolConfig
    is_visible_to_user?: boolean
    status?: CaseTool["status"]
  }) => {
    try {
      const newAssignment = await caseToolsCollection.create({
        case: data.case,
        type: data.type,
        name_en: data.name_en,
        name_ar: data.name_ar,
        is_not_template: data.is_not_template ?? false,
        config: data.config,
        status: data.status ?? "pending",
        is_visible_to_user: data.is_visible_to_user ?? true,
        responses: {},
        media: [],
      })
      setAssignments((prev) => [...prev, newAssignment])
      return newAssignment.id
    } catch (error) {
      console.error("Failed to create assignment:", error)
      throw error
    }
  }

  const updateAssignment = async (id: string, data: Partial<CaseTool>) => {
    try {
      const updated = await caseToolsCollection.update(id, data)
      setAssignments((prev) => prev.map((a) => (a.id === id ? updated : a)))
    } catch (error) {
      console.error("Failed to update assignment:", error)
      throw error
    }
  }

  const updateAssignmentWithFiles = async (
    id: string,
    data: Partial<CaseTool>,
    files: File[],
    filesToRemove?: string[]
  ) => {
    try {
      const updated = await caseToolsCollection.updateWithFiles(
        id,
        data,
        files,
        filesToRemove
      )
      setAssignments((prev) => prev.map((a) => (a.id === id ? updated : a)))
      return updated
    } catch (error) {
      console.error("Failed to update assignment with files:", error)
      throw error
    }
  }

  const deleteAssignment = async (id: string) => {
    try {
      await caseToolsCollection.delete(id)
      setAssignments((prev) => prev.filter((a) => a.id !== id))
    } catch (error) {
      console.error("Failed to delete assignment:", error)
      throw error
    }
  }

  const getAssignmentsByCase = (caseId: string) =>
    assignments.filter((a) => a.case === caseId)

  const getAssignmentsByType = (typeId: string) =>
    assignments.filter((a) => a.type === typeId)

  const getVisibleAssignments = (caseId: string) =>
    assignments.filter((a) => a.case === caseId && a.is_visible_to_user)

  return {
    assignments,
    isLoading,
    loadError,
    assignTool,
    updateAssignment,
    updateAssignmentWithFiles,
    deleteAssignment,
    getAssignmentsByCase,
    getAssignmentsByType,
    getVisibleAssignments,
    refresh: fetchAssignments,
  }
}

"use client"

import { useCallback, useEffect, useState } from "react"
import pb, { getErrorMessage } from "@/lib/pb"
import type { ExpertProfile, ExpertProfileDraft } from "@/types/expert"

function toText(value: unknown): string {
  if (typeof value === "string") return value
  if (typeof value === "number") return String(value)
  return ""
}

/**
 * Normalizes a PocketBase field that may hold an array, a single value, or a
 * comma separated string into a clean list of strings.
 */
export function toStringList(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value
      .map((item) => toText(item).trim())
      .filter((item) => item.length > 0)
  }
  const single = toText(value).trim()
  if (!single) return []
  return single
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean)
}

export function emptyDraft(name = ""): ExpertProfileDraft {
  return {
    name,
    countryOfResidence: "",
    city: "",
    whatsappCountryCode: "",
    whatsappNumber: "",
    highestAcademicDegree: "",
    degreeTitle: "",
    fieldOfStudy: "",
    ageGroup: [],
    specialization: [],
    consultationMode: "",
    fee: "",
    availability: "",
    bio: "",
    publicNameEn: "",
    publicNameAr: "",
    publicQualificationEn: "",
    publicQualificationAr: "",
    publicSpecialtyEn: "",
    publicSpecialtyAr: "",
    shortBioEn: "",
    shortBioAr: "",
    newPhoto: null,
    removePhoto: false,
    keptCv: [],
    newCv: [],
  }
}

/**
 * Builds an editable draft out of a stored profile record. A null record (an
 * expert with no profile row yet) yields an empty draft that save() creates.
 */
export function draftFromProfile(
  profile: ExpertProfile | null,
  name = ""
): ExpertProfileDraft {
  if (!profile) return emptyDraft(name)
  return {
    name,
    countryOfResidence: toText(profile.country_of_residence),
    city: toText(profile.city),
    whatsappCountryCode: toText(profile.whatsapp_country_code),
    whatsappNumber: toText(profile.whatsapp_number),
    highestAcademicDegree: toText(profile.highest_academic_degree),
    degreeTitle: toText(profile.degree_title),
    fieldOfStudy: toText(profile.field_of_study),
    ageGroup: toStringList(profile.age_group),
    specialization: toStringList(profile.specialization_type),
    consultationMode: toText(profile.consultation_mode),
    fee: toText(profile.fee),
    availability: toText(profile.availability),
    bio: toText(profile.bio),
    publicNameEn: toText(profile.public_name_en),
    publicNameAr: toText(profile.public_name_ar),
    publicQualificationEn: toText(profile.public_qualification_en),
    publicQualificationAr: toText(profile.public_qualification_ar),
    publicSpecialtyEn: toText(profile.public_specialty_en),
    publicSpecialtyAr: toText(profile.public_specialty_ar),
    shortBioEn: toText(profile.short_bio_en),
    shortBioAr: toText(profile.short_bio_ar),
    newPhoto: null,
    removePhoto: false,
    keptCv: toStringList(profile.cv),
    newCv: [],
  }
}

/**
 * Builds a private file URL using the short-lived PocketBase file token, which
 * is required when the file's collection is not publicly readable.
 */
export function profileFileUrl(
  profile: ExpertProfile | null,
  filename: string,
  fileToken: string
): string {
  if (!profile || !filename) return ""
  return pb.files.getURL(
    profile as never,
    filename,
    fileToken ? { token: fileToken } : {}
  )
}

/** The stored profile photo filename, or "" when none is set. */
export function profilePhotoName(profile: ExpertProfile | null): string {
  return toText(profile?.profile_photo)
}

/**
 * Builds the expert_profiles payload for a draft. Shared by the expert's own
 * save and the admin's editor so the two cannot drift on field names or the
 * multi-select encoding.
 */
function expertProfileFormData(
  draft: ExpertProfileDraft,
  userId: string,
  profileId?: string
): FormData {
  const formData = new FormData()
  formData.set("country_of_residence", draft.countryOfResidence.trim())
  formData.set("city", draft.city.trim())
  formData.set("whatsapp_country_code", draft.whatsappCountryCode.trim())
  formData.set("whatsapp_number", draft.whatsappNumber.trim())
  formData.set("highest_academic_degree", draft.highestAcademicDegree)
  formData.set("degree_title", draft.degreeTitle.trim())
  formData.set("field_of_study", draft.fieldOfStudy.trim())

  // Both are multi-select fields, so each value is appended separately. A
  // comma-joined string would be rejected by the server.
  formData.set("age_group", JSON.stringify(draft.ageGroup))
  formData.set("specialization_type", JSON.stringify(draft.specialization))

  formData.set("consultation_mode", draft.consultationMode)
  formData.set("fee", draft.fee.trim())
  formData.set("availability", draft.availability.trim())
  formData.set("public_name_en", draft.publicNameEn.trim())
  formData.set("public_name_ar", draft.publicNameAr.trim())
  formData.set("public_qualification_en", draft.publicQualificationEn.trim())
  formData.set("public_qualification_ar", draft.publicQualificationAr.trim())
  formData.set("public_specialty_en", draft.publicSpecialtyEn.trim())
  formData.set("public_specialty_ar", draft.publicSpecialtyAr.trim())
  formData.set("short_bio_en", draft.shortBioEn)
  formData.set("short_bio_ar", draft.shortBioAr)

  // An empty string clears a single-file field in PocketBase.
  if (draft.removePhoto) {
    formData.set("profile_photo", "")
  } else if (draft.newPhoto) {
    formData.append("profile_photo", draft.newPhoto)
  }

  // Re-sending stored filenames preserves the documents on the record;
  // anything removed is simply left out.
  draft.keptCv.forEach((filename) => formData.append("cv", filename))
  draft.newCv.forEach((file) => formData.append("cv", file))
  if (!draft.keptCv.length && !draft.newCv.length) formData.set("cv", "")

  if (!profileId) {
    formData.set("user", userId)
  }
  return formData
}

/**
 * Writes an expert profile on behalf of a user. Works for the signed-in expert
 * and for an admin editing someone else's application.
 */
export async function saveExpertProfileFor(
  draft: ExpertProfileDraft,
  userId: string,
  profileId?: string
): Promise<ExpertProfile> {
  if (draft.shortBioEn.length > 250 || draft.shortBioAr.length > 250)
    throw new Error("Each short biography must be at most 250 characters.")
  await pb.collection("users").update(userId, { name: draft.name.trim() })
  const formData = expertProfileFormData(draft, userId, profileId)
  const collection = pb.collection("expert_profiles")
  const saved = profileId
    ? await collection.update(profileId, formData)
    : await collection.create(formData)
  return saved as unknown as ExpertProfile
}

export function useExpertProfile(userId?: string) {
  const [profile, setProfile] = useState<ExpertProfile | null>(null)
  const [fileToken, setFileToken] = useState("")
  const [isLoading, setIsLoading] = useState(true)
  const [isSaving, setIsSaving] = useState(false)
  const [loadError, setLoadError] = useState("")

  const load = useCallback(async () => {
    if (!userId) {
      setIsLoading(false)
      return
    }
    setIsLoading(true)
    setLoadError("")
    try {
      const record = await pb
        .collection("expert_profiles")
        .getFirstListItem(pb.filter("user = {:value0}", { value0: userId }))
      setProfile(record as unknown as ExpertProfile)
    } catch (error) {
      // An expert without a profile row is a valid state, not a failure.
      const status = (error as { status?: number }).status
      if (status === 404) {
        setProfile(null)
      } else {
        setProfile(null)
        setLoadError(getErrorMessage(error))
      }
    } finally {
      setIsLoading(false)
    }
  }, [userId])

  useEffect(() => {
    // Begin the external profile fetch when the selected expert changes.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    load()
  }, [load])

  useEffect(() => {
    let cancelled = false
    pb.files
      .getToken()
      .then((token) => {
        if (!cancelled) setFileToken(token)
      })
      .catch(() => {
        if (!cancelled) setFileToken("")
      })
    return () => {
      cancelled = true
    }
  }, [])

  const save = useCallback(
    async (draft: ExpertProfileDraft) => {
      if (!userId) throw new Error("No signed-in expert")
      setIsSaving(true)
      try {
        // Updating users first syncs the PocketBase auth store on a self-update,
        // which keeps the sidebar name in step with the profile.
        const saved = await saveExpertProfileFor(draft, userId, profile?.id)
        setProfile(saved)
        return saved
      } finally {
        setIsSaving(false)
      }
    },
    [userId, profile?.id]
  )

  return {
    profile,
    fileToken,
    isLoading,
    isSaving,
    loadError,
    reload: load,
    save,
  }
}

"use client"

import { useState, useEffect, useCallback } from "react"
import { casesCollection, caseExpertsCollection } from "@/lib/pb-collections"
import type { Profile } from "@/types/profile"
import { toast } from "sonner"
import { getCurrentUser, getErrorMessage } from "@/lib/pb"

export function useProfiles() {
  const [profiles, setProfiles] = useState<Profile[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState("")
  const currentUser = getCurrentUser()
  const currentUserId: string | undefined = currentUser?.id
  const currentRole: string | undefined = currentUser?.role

  const fetchProfiles = useCallback(async () => {
    setIsLoading(true)
    setLoadError("")
    try {
      let data: Profile[]
      if (currentRole === "expert") {
        const expertCases = await caseExpertsCollection.getByExpert(
          currentUserId!
        )
        const caseIds = [
          ...new Set(
            expertCases.map((ce) => ce.case_id).filter(Boolean)
          ),
        ]
        data =
          caseIds.length > 0
            ? await casesCollection.getByIds(caseIds)
            : []
      } else if (
        currentUserId &&
        (currentRole === "individual" ||
          currentRole === "organization" ||
          currentRole === "parent")
      ) {
        data = await casesCollection.getByUser(currentUserId!)
      } else {
        data = await casesCollection.getAll()
      }
      setProfiles(data)
    } catch (error) {
      console.error("Failed to fetch profiles:", error)
      setLoadError(getErrorMessage(error))
      toast.error(getErrorMessage(error))
    } finally {
      setIsLoading(false)
    }
  }, [currentUserId, currentRole])

  useEffect(() => {
    // Fetch external records when the selected scope changes.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchProfiles()
  }, [fetchProfiles])

  const addProfile = async (data: Partial<Profile>, userId?: string) => {
    try {
      const ownerId = userId !== undefined ? userId : currentUser?.id
      const newProfile = await casesCollection.create({
        ...data,
        user: ownerId,
      })
      setProfiles((prev) => [...prev, newProfile])
      return newProfile.id
    } catch (error) {
      console.error("Failed to create profile:", error)
      throw error
    }
  }

  const updateProfile = async (id: string, data: Partial<Profile>) => {
    try {
      const updated = await casesCollection.update(id, data)
      setProfiles((prev) => prev.map((p) => (p.id === id ? updated : p)))
      return updated
    } catch (error) {
      console.error("Failed to update profile:", error)
      throw error
    }
  }

  const setPaymentAmount = async (id: string, amount: number) => {
    try {
      const updated = await casesCollection.update(id, {
        payment_amount: amount,
        status: "awaiting_payment",
      })
      setProfiles((prev) => prev.map((p) => (p.id === id ? updated : p)))
      return updated
    } catch (error) {
      console.error("Failed to set payment amount:", error)
      throw error
    }
  }

  const submitPaymentSlip = async (id: string, file: File) => {
    try {
      const updated = await casesCollection.updateWithFiles(
        id,
        { status: "under_review", payment_reject_reason: "" },
        [file]
      )
      setProfiles((prev) => prev.map((p) => (p.id === id ? updated : p)))
      return updated
    } catch (error) {
      console.error("Failed to submit payment slip:", error)
      throw error
    }
  }

  const approveCase = async (id: string) => {
    try {
      const updated = await casesCollection.update(id, {
        status: "active",
        is_paid: true,
        payment_reject_reason: "",
      })
      setProfiles((prev) => prev.map((p) => (p.id === id ? updated : p)))
      return updated
    } catch (error) {
      console.error("Failed to approve case:", error)
      throw error
    }
  }

  const rejectPayment = async (id: string, reason?: string) => {
    try {
      const updated = await casesCollection.update(id, {
        status: "awaiting_payment",
        payment_reject_reason: reason || "",
      })
      setProfiles((prev) => prev.map((p) => (p.id === id ? updated : p)))
      return updated
    } catch (error) {
      console.error("Failed to reject payment:", error)
      throw error
    }
  }

  const deleteProfile = async (id: string) => {
    try {
      await casesCollection.delete(id)
      setProfiles((prev) => prev.filter((p) => p.id !== id))
    } catch (error) {
      console.error("Failed to delete profile:", error)
      throw error
    }
  }

  const getProfileById = (id: string) => profiles.find((p) => p.id === id)

  const getProfilesByUser = (userId: string) =>
    profiles.filter((p) => p.user === userId)

  return {
    profiles,
    isLoading,
    loadError,
    addProfile,
    updateProfile,
    deleteProfile,
    getProfileById,
    getProfilesByUser,
    setPaymentAmount,
    submitPaymentSlip,
    approveCase,
    rejectPayment,
    refresh: fetchProfiles,
  }
}

